insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 1, '"നിങ്ങളെന്റെ പേരിടുക, എന്റെ ഓമനപ്പേരിടരുത്"', 'بَابٌ: قَوْلُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَسَمَّوْا باسمِي ولاَ تَكَنَّوْا بِكُنْيَتِي"', 401 from books where volume_id=2 and book_no=5 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
