insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَادَى رَجُلٌ رَجُلًا بالْبَقِيعِ يَا أَبَا الْقَاسِمِ، فَالْتَفَتَ إِلَيْهِ رَسُولُ اللَّهِ، فَقَالَ: يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنِّي لَمْ أَعْنِكَ، إِنَّمَا دَعَوْتُ فُلَانًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي". (م,ت,جه)', 'അനസ്(റ): ബഖീഇൽ വെച്ച് ഒരാൾ വേറൊരാളെ ''അബുൽ ഖാസിമേ'' എന്ന് വിളിച്ചു. അപ്പോൾ റസൂൽ(സ) തിരിഞ്ഞുനോക്കി. അപ്പോൾ വിളിച്ചയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ അങ്ങയെ ഉദ്ദേശിച്ചിട്ടില്ല. ഇന്നയാളെയാണ് ഞാൻ വിളിച്ചത്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളെന്റെ പേരിടുക, എന്റെ ഓമനപ്പേരിടരുത്." (മു,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا سَمَّيْتُمْ بِاسْمِي فَلَا تَكْتَنُوا بِي". حَسَنٌ. (د,ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളെന്റെ പേരിട്ടാൽ എന്റെ ഓമനപ്പേരിടരുത്." (ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ وُلِدَ لِي بَعْدَكَ، أُسَمِّيهِ مُحَمَّدًا، وَأُكَنِّيهِ بِكُنْيَتِكَ؟ قَالَ: "نَعَمْ". قَالَ: فَكَانَتْ رُخْصَةً لِي. صَحِيحٌ. (د,ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങേക്ക് ശേഷം എനിക്കൊരു കുട്ടി ജനിച്ചാൽ അവന് ''മുഹമ്മദെ''ന്ന് പേരിടുകയും അങ്ങയുടെ ഓമനപ്പേരിടുകയും ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." അലി(റ) പറയുന്നു: അത് എനിക്ക് മാത്രമുള്ള ഒരു ഇളവായിരുന്നു. (ദ,തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَسَمَّى بِاسْمِي فَلَا يَتَكَنَّى بِكُنْيَتِي، وَمَنْ تَكَنَّى بِكُنْيَتِي فَلَا يَتَسَمَّى بِاسْمِي". (د,ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും എന്റെ പേരിട്ടാൽ അവൻ എന്റെ ഓമനപ്പേരിടരുത്. ആരെങ്കിലും എന്റെ ഓമനപ്പേരിട്ടാൽ, അവനെന്റെ പേരിടുകയുമരുത്." (ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَجْمَعَ بَيْنَ اسْمِهِ وَكُنْيَتِهِ، وَيُسَمَّى مُحَمَّدًا أَبَا الْقَاسِمِ. حَسَنٌ صَحِيحٌ. (ت)', 'അബുഹുറൈറ(റ): നബി(സ)യുടെ പേരും ഓമനപ്പേരും ഒരുമിച്ച് ''മുഹമ്മദ് അബുൽഖാസിം'' എന്ന് പേരിടൽ അവിടുന്ന് നിരോധിച്ചിരിക്കുന്നു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: وُلِدَ لِرَجُلٍ مِنَّا غُلَامٌ فَسَمَّاهُ مُحَمَّدًا، فَقَالَ لَهُ قَوْمُهُ: لَا نَدَعُكَ تُسَمِّي باسْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقَ بابْنِهِ حامِلَهُ عَلَى ظَهْرِهِ، فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، وُلِدَ لِي غُلَامٌ فَسَمَّيْتُهُ مُحَمَّدًا، فَقَالَ لِي قَوْمِي: لَا نَدَعُكَ تُسَمِّي باسْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي، فَإِنَّمَا أَنَا قَاسِمٌ أَقْسِمُ بَيْنَكُمْ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങളിൽപ്പെട്ട ഒരാൾക്ക് ഒരു കുട്ടി ജനിച്ചു. അയാൾ അവന് ''മുഹമ്മദ്'' എന്ന് പേരിട്ടു. അദ്ദേഹത്തോട് തന്റെ സമൂഹം പറഞ്ഞു: നിന്നെ ഞങ്ങൾ റസൂൽ(സ)യുടെ പേരിടാൻ സമ്മതിക്കില്ല. അയാൾ തന്റെ മകനെ വാഹനപ്പുറത്ത് വഹിച്ച് നബി(സ)യുടെ അടുത്തു വന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊരു കുട്ടി ജനിച്ചു. അവന് ഞാൻ മുഹമ്മദെന്ന് പേരിട്ടു. അപ്പോൾ എന്നോടെന്റെ സമൂഹം പറഞ്ഞു: നിന്നെ ഞങ്ങൾ റസൂൽ(സ)യുടെ പേരിടാൻ സമ്മതിക്കില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ എന്റെ പേരിടുക. എന്റെ ഓമനപ്പേരിടരുത്. കാരണം ഞാൻ മാത്രമാണ് ഖാസിം (വീതിക്കുന്നവൻ). ഞാൻ നിങ്ങൾക്കിടയിൽ വീതിക്കും." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي قَدْ وَلَدْتُ غُلَامًا، فَسَمَّيْتُهُ مُحَمَّدًا وَكَنَّيْتُهُ أَبَا الْقَاسِمِ، فَذُكِرَ لِي أَنَّكَ تَكْرَهُ ذَلِكَ؟ فَقَالَ: "مَا الَّذِي أَحَلَّ اسْمِي وَحَرَّمَ كُنْيَتِي؟. أَوْ: مَا الَّذِي حَرَّمَ كُنْيَتِي وَأَحَلَّ اسْمِي". (د)', 'ആഇശ(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊരു കുഞ്ഞ് ജനിച്ചിട്ടുണ്ട്. അവന് ഞാൻ മുഹമ്മദെന്ന് പേരിടുകയും, അബുൽഖാസിമെന്ന് ഓമനപ്പേരിടുകയും ചെയ്തു. അവിടന്ന് അത് വെറുക്കുന്നുണ്ടെന്ന് എന്നോട് പറയപ്പെട്ടു? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ പേര് അനുവദനീയമാക്കുകയും എന്റെ ഓമനപ്പേര് നിഷിദ്ധമാക്കുകയും ചെയ്തത് എന്ത് കൊണ്ടാണ്. അല്ലെങ്കിൽ എന്റെ ഓമനപ്പേര് നിഷിദ്ധമാക്കുകയും പേര് അനുവദനീയമാക്കുകയും ചെയ്തത് എന്ത് കൊണ്ടാണ്?" (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِي أَسْمَاءً: أَنَا مُحَمَّدٌ، وَأَنَا أَحْمَدُ، وَأَنَا الْمَاحِي الَّذِي يَمْحُو اللَّهُ بِيَ الْكُفْرَ، وَأَنَا الْحَاشِرُ الَّذِي يُحْشَرُ النَّاسُ عَلَى قَدَمِي، وَأَنَا الْعَاقِبُ الَّذِي لَيْسَ بَعْدِي نَبِيٌّ". حَسَنٌ صَحِيحٌ. (ق,ن)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) പറഞ്ഞു: "എനിക്കൊരുപാട് പേരുകളുണ്ട്. ഞാൻ മുഹമ്മദാണ്. ഞാൻ അഹ്മദാണ്. ഞാൻ അൽമാഹിയാണ് (മായ്ച്ചുകളയുന്നവൻ) എന്നെക്കൊണ്ട് അല്ലാഹു കുഫ്റ് മായ്ച്ച് കളയും. ഞാൻ അൽഹാശിറാണ് (ഒരുമിച്ച് കൂട്ടുന്നവൻ) ജനങ്ങൾ എന്റെ കാൽക്കീഴിൽ ഒരുമിച്ച് കൂട്ടപ്പെടും. ഞാൻ ആഖിബാണ് എനിക്ക് ശേഷമൊരു പ്രവാചകനില്ല." (ബു,മു,ന)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 402, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحَبَّ أَسْمَائِكُمْ إِلَى اللَّهِ عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ". (م)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ നാമങ്ങളിൽ അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടത് ''അബ്ദുല്ല'' എന്നതും ''അബ്ദുർറഹ്മാൻ'' എന്നതുമാണ്." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: وُلِدَ لِرَجُلٍ مِنَّا غُلَامٌ فَسَمَّاهُ الْقَاسِمَ، فَقُلْنَا: لَا نَكْنِيكَ أَبَا الْقَاسِمِ وَلَا نُنْعِمُكَ عَيْنًا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ: "أَسْمِ ابْنَكَ عَبْدَ الرَّحْمَنِ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങളിലൊരാൾക്ക് ഒരു കുഞ്ഞ് ജനിച്ചു. അയാൾ അവന് ''ഖാസിം'' എന്ന് പേരിട്ടു. അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: നിന്നെ ഞങ്ങൾ ''അബുൽ ഖാസിം'' എന്ന ഓമനപ്പേര് വിളിക്കില്ല. അങ്ങനെ ഞങ്ങൾ നിന്നെ സുഖിപ്പിക്കുകയുമില്ല. അപ്പോൾ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് വിഷയം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിന്റെ മകന് നീ ''അബ്ദുർറഹ്മാൻ'' എന്ന് പേരിടുക." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: وُلِدَ لِي غُلَامٌ، فَأَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمَّاهُ: إِبْرَاهِيمَ، وَحَنَّكَهُ بِتَمْرَةٍ. (م)', 'അബുമൂസ(റ): എനിക്കൊരു കുട്ടി ജനിച്ചു. ഞാൻ അവനെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുപോയി. തിരുമേനി(സ) അവന് ''ഇബ്റാഹീം'' എന്ന് പേരിടുകയും കാരക്ക നൽകി മധുരം നൽകുകയും ചെയ്തു. (മു)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمْتُ نَجْرَانَ سَأَلُونِي فَقَالُوا: إِنَّكُمْ تَقْرَءُونَ {يَا أُخْتَ هَارُونَ} [مريم: ٢٨] وَمُوسَى قَبْلَ عِيسَى بِكَذَا وَكَذَا. فَلَمَّا قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ: "إِنَّهُمْ كَانُوا يُسَمُّونَ بِأَنْبِيَائِهِمْ وَالصَّالِحِينَ قَبْلَهُمْ". (م)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): ഞാൻ നജ്റാനിൽ ചെന്നപ്പോൾ അവരെന്നോട് ചോദിച്ചു: നിങ്ങൾ ''ഓ, ഹാറൂന്റെ സഹോദരീ'' (യാ ഉഖ്ത ഹാറൂൻ) (മർയം:28) എന്ന് ഓതുന്നുണ്ടല്ലോ, മൂസാനബി(അ) ഈസാനബി(അ)ന്റെ ഇത്ര വർഷങ്ങൾക്ക് മുമ്പല്ലേ? ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ ഇതിനെക്കുറിച്ച് അവിടത്തോട് ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർ തങ്ങൾക്ക് മുമ്പുള്ള അമ്പിയാക്കളുടെയും സ്വാലിഹീങ്ങളുടെയും പേരിടാറുണ്ടായിരുന്നു." (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], 'مريم: ٢٨', null, 403, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي وَهْبٍ الْجُشَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَسَمَّوْا بِأَسْمَاءِ الْأَنْبِيَاءِ، وَأَحَبُّ الْأَسْمَاءِ إِلَى اللَّهِ عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ، وَأَصْدَقُهَا حَارِثٌ وَهَمَّامٌ، وَأَقْبَحُهَا حَرْبٌ وَمُرَّةُ". (د)', 'അബു വഹബിൽ ജുശമി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അമ്പിയാക്കളുടെ പേരിടുക. അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട നാമങ്ങൾ ''അബ്ദുല്ലാഹി''യും അബ്ദുർറഹ്മാനുമാണ്. പേരുകളിൽ ഏറ്റവും സത്യസന്ധമായത് ഹാരിസും ഹമ്മാമുമാണ്. അതിൽ ഏറ്റവും മോശമായത് ഹർബും, മുർറയുമാണ്." (ദ)', 'أَبِي وَهْبٍ الْجُشَمِيِّ', 'അബു വഹബിൽ ജുശമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 404, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ وَفَاطِمَةَ بِنْتِ الْمُنْذِرِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهَا أَنَّهُمَا قَالَا: خَرَجَتْ أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ حِينَ هَاجَرَتْ وَهِيَ حُبْلَى بِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ، فَقَدِمَتْ قُبَاءً فَنُفِسَتْ بِعَبْدِ اللَّهِ بِقُبَاءٍ، ثُمَّ خَرَجَتْ حِينَ نُفِسَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُحَنِّكَهُ، فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا فَوَضَعَهُ فِي حَجْرِهِ، ثُمَّ دَعَا بِتَمْرَةٍ، [قَالَ]: قَالَتْ عَائِشَةُ: فَمَكَثْنَا سَاعَةً نَلْتَمِسُهَا قَبْلَ أَنْ نَجِدَهَا، فَمَضَغَهَا ثُمَّ بَصَقَهَا فِي فِيهِ، فَإِنَّ أَوَّلَ شَيْءٍ دَخَلَ بَطْنَهُ لَرِيقُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَتْ أَسْمَاءُ: ثُمَّ مَسَحَهُ وَصَلَّى عَلَيْهِ وَسَمَّاهُ عَبْدَ اللَّهِ، ثُمَّ جَاءَ وَهُوَ ابْنُ سَبْعِ سِنِينَ أَوْ ثَمَانٍ لِيُبَايِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَمَرَهُ بِذَلِكَ الزُّبَيْرُ رَضِيَ اللهُ عَنْهُ، فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَآهُ مُقْبِلًا إِلَيْهِ ثُمَّ بَايَعَهُ. (م)', 'ഉർവതുബ്നു സുബൈർ(റ), ഫാത്വിമതു ബിൻതുൽ മുൻദിറുബ്നു സുബൈർ(റ): അസ്മാഅ് ബിൻത് അബീബക്കർ(റ) എന്നവർ ഹിജ്റ പുറപ്പെട്ടു. അപ്പോൾ അവർ അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)വിനെ ഗർഭം ചുമന്നിരുന്നു. അവർ ഖുബായിലെത്തി. ഖുബായിൽ വെച്ച് അബ്ദുല്ലയെ പ്രസവിച്ചു. ഉടനെ അവർ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് കുട്ടിക്ക് മധുരം നൽകാൻ വേണ്ടി പുറപ്പെട്ടു. റസൂൽ(സ) കുട്ടിയെ വാങ്ങി മടിയിൽ വെച്ചു. പിന്നെ അവിടന്ന് ഒരു കാരക്ക കൊണ്ടുവരാൻ പറഞ്ഞു. ആഇശ(റ) പറയുന്നു: കാരക്ക കിട്ടുന്നതിന് മുമ്പ് അത് അന്വേഷിച്ച് കൊണ്ട് ഞങ്ങൾ കുറച്ച് നേരം തങ്ങി. റസൂൽ(സ) കാരക്ക ചവച്ചു. പിന്നെ കുട്ടിയുടെ വായിലേക്ക് അത് തുപ്പിക്കൊടുത്തു. കുട്ടിയുടെ വയറ്റിൽ ആദ്യമായി പ്രവേശിച്ചത് റസൂൽ(സ)യുടെ ഉമിനീരാണ്. അസ്മാഅ്(റ) പറയുന്നു: പിന്നെ റസൂൽ(സ) കുട്ടിയെ തടവുകയും അവന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ''അബ്ദുല്ലാഹ്'' എന്ന് പേരിടുകയും ചെയ്തു. പിന്നീട് ഏഴോ എട്ടോ വയസ്സുള്ളപ്പോൾ അവൻ റസൂൽ(സ)യെ ബൈഅത്ത് ചെയ്യാൻ വേണ്ടി വന്നു. സുബൈർ(റ) ആണ് ഇത് അവനോട് കൽപ്പിച്ചത്. അബ്ദുല്ല(റ) തന്നിലേക്ക് വരുന്നത് കണ്ട റസൂൽ പുഞ്ചിരിച്ചു. പിന്നെ അദ്ദേഹം റസൂൽ(സ)യെ ബൈഅത്ത് ചെയ്തു. (മു)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവതുബ്നു സുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 404, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ ابْنٌ لِأَبِي طَلْحَةَ يَشْتَكِي، فَخَرَجَ أَبُو طَلْحَةَ فَقُبِضَ الصَّبِيُّ، فَلَمَّا رَجَعَ أَبُو طَلْحَةَ قَالَ: مَا فَعَلَ ابْنِي؟ قَالَتْ أُمُّ سُلَيْمٍ: هُوَ أَسْكَنُ مِمَّا كَانَ. فَقَرَّبَتْ إِلَيْهِ الْعَشَاءَ فَتَعَشَّى، ثُمَّ أَصَابَ مِنْهَا، فَلَمَّا فَرَغَ قَالَتْ: وَارُوا الصَّبِيَّ، فَلَمَّا أَصْبَحَ أَبُو طَلْحَةَ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ: "أَعْرَسْتُمُ اللَّيْلَةَ". قَالَ: نَعَمْ، قَالَ: "اللَّهُمَّ بَارِكْ لَهُمَا". فَوَلَدَتْ غُلَامًا، فَقَالَ لِي أَبُو طَلْحَةَ: احْمِلْهُ حَتَّى تَأْتِيَ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَعَثَتْ مَعَهُ بِتَمَرَاتٍ، فَأَخَذَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَمَعَهُ شَيْءٌ". قَالُوا: نَعَمْ تَمَرَاتٌ، فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَضَغَهَا، ثُمَّ أَخَذَهَا مِنْ فِيهِ فَجَعَلَهَا فِي فِي الصَّبِيِّ، ثُمَّ حَنَّكَهُ وَسَمَّاهُ: عَبْدَ اللَّهِ. (م)', 'അനസുബ്നു മാലിക്(റ): അബൂത്വൽഹ(റ)വിന് രോഗിയായ ഒരു മകനുണ്ടായിരുന്നു. അബൂത്വൽഹ(റ) പുറത്ത് പോയ സമയത്ത് ആ കുട്ടി മരിച്ചു. തിരിച്ചു വന്നപ്പോൾ അബൂത്വൽഹ(റ) ചോദിച്ചു: എന്റെ കുട്ടിക്ക് എങ്ങനെയുണ്ട്? ഉമ്മു സുലൈം(റ) പറഞ്ഞു: അവൻ മുമ്പുള്ളതിനേക്കാൾ ശാന്തനാണ്. അവർ അബൂത്വൽഹ(റ)വിന് അത്താഴം കൊണ്ടുവന്നുകൊടുത്തു. അബൂത്വൽഹ(റ) അത്താഴം കഴിച്ചു. പിന്നെ അബൂത്വൽഹ(റ) ഉമ്മുസുലൈം(റ)വുമായി ബന്ധപ്പെട്ടു. എല്ലാം കഴിഞ്ഞപ്പോൾ അബൂത്വൽഹ(റ)വിനോട് ഉമ്മുസുലൈം(റ) പറഞ്ഞു: നിങ്ങൾ കുട്ടിയെ മറമാടുക. പ്രഭാതമായപ്പോൾ അബൂത്വൽഹ(റ) റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഇന്നലെ രാത്രി നിങ്ങൾ ബന്ധപ്പെട്ടിരുന്നോ?" അദ്ദേഹം ''അതെ''യെന്ന് മറുപടി പറഞ്ഞു. നബി(സ) പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, അവർക്ക് രണ്ടുപേർക്കും നീ അനുഗ്രഹം ചെയ്യേണമേ." ശേഷം ഉമ്മു സുലൈം(റ) ഒരു കുട്ടിയെ പ്രസവിച്ചു. അപ്പോൾ എന്നോട് അബൂത്വൽഹ(റ) പറഞ്ഞു. നീ കുട്ടിയെ എടുത്ത് നബി(സ)യുടെ അടുത്ത് കൊണ്ടുപോകുക. അങ്ങനെ കുട്ടിയെ നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവരപ്പെട്ടു. ഉമ്മുസുലൈം(റ) അവന്റെ കൂടെ കാരക്കകളും കൊടുത്തയച്ചിരുന്നു. നബി(സ) കുട്ടിയെ എടുത്ത് കൊണ്ടുചോദിച്ചു: "അവന്റെ കൂടെ എന്തെങ്കിലുമുണ്ടോ?" അവർ പറഞ്ഞു: കാരക്കകൾ ഉണ്ട്. നബി(സ) കാരക്കയെടുത്ത് ചവച്ചു. പിന്നെ അത് അവിടത്തെ വായിൽ നിന്നെടുത്ത് കുട്ടിയുടെ വായിൽ വെച്ചു. പിന്നെ നബി(സ) അവന് മധുരം നൽകുകയും ''അബ്ദുല്ല'' എന്ന് പേരിടുകയും ചെയ്തു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 404, 405, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: ذَهَبْتُ بِعَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ وُلِدَ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عَبَاءَةٍ يَهْنَأُ بَعِيرًا لَهُ، قَالَ: "هَلْ مَعَكَ تَمْرٌ". قُلْتُ: نَعَمْ، قَالَ: فَنَاوَلْتُهُ تَمَرَاتٍ، فَأَلْقَاهُنَّ فِي فِيهِ، فَلَاكَهُنَّ، ثُمَّ فَغَرَ فَاهُ فَأَوْجَرَهُنَّ إِيَّاهُ، فَجَعَلَ الصَّبِيُّ يَتَلَمَّظُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "حُبُّ الْأَنْصَار التَّمْرَ". وَسَمَّاهُ: عَبْدَ اللَّهِ. (م,د)', 'അനസ്(റ): അബ്ദുല്ലാഹിബ്നു അബീത്വൽഹ(റ) പ്രസവിക്കപ്പെട്ടപ്പോൾ ഞാനവനെയുമെടുത്ത് നബി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ നബി(സ) രോമവസ്ത്രം ധരിച്ച് അവിടത്തെ ഒട്ടകത്തിന് തീറ്റകൊടുക്കുകയായിരുന്നു. അവിടന്ന് ചോദിച്ചു: "നിങ്ങളുടെ കൂടെ കാരക്കയുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, ഞാൻ നബി(സ)ക്ക് കാരക്കകൾ നൽകി. നബി(സ) അത് വായിലിട്ടു ചവച്ചു. തിരുനബി(സ) കുട്ടിയുടെ വാ തുറന്നു. ചവച്ച കാരക്കകൾ കുട്ടിയുടെ വായിൽ ഇട്ടുകൊടുത്തു. കുട്ടി വായ ചലിപ്പിക്കാൻ തുടങ്ങി. നബി(സ) പറഞ്ഞു: "അൻസാറുകൾക്ക് കാരക്കയോടുള്ള ഇഷ്ടമാണിത്." അവന് റസൂൽ(സ) ''അബ്ദുല്ല''യെന്ന് പേരിടുകയും ചെയ്തു. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 405, 405, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ بِالْمُنْذِرِ بْنِ أَبِي أُسَيْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ وُلِدَ، فَوَضَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى فَخِذِهِ، وَأَبُو أُسَيْدٍ جَالِسٌ، فَلَهِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَيْءٍ بَيْنَ يَدَيْهِ، فَأَمَرَ أَبُو أُسَيْدٍ بِابْنِهِ، فَاحْتُمِلَ مِنْ عَلَى فَخِذِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَقْلَبُوهُ، فَاسْتَفَاقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَيْنَ الصَّبِيُّ". فَقَالَ أَبُو أُسَيْدٍ: قَلَبْنَاهُ يَا رَسُولَ اللَّهِ، قَالَ: "مَا اسْمُهُ". قَالَ: فُلَانٌ يَا رَسُولَ اللَّهِ، قَالَ: "لَا، وَلَكِنِ اسْمُهُ الْمُنْذِرُ". فَسَمَّاهُ يَوْمَئِذٍ: الْمُنْذِرَ. (م)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): മുൻദിറുബ്നു അബീ ഉസൈദ്(റ)വിനെ പ്രസവിച്ചപ്പോൾ റസൂൽ(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. നബി(സ) കുട്ടിയെ അവിടത്തെ തുടയിൽ വെച്ചു. അബൂ ഉസൈദ് ഇരിക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ) തന്റെ മുമ്പിലുള്ള എന്തോ വിഷയത്തിൽ വ്യാപൃതനായി. അപ്പോൾ അബൂ ഉസൈദ്(റ) കുട്ടിയെ എടുക്കാൻ പറഞ്ഞു. അപ്പോൾ അവർ കുട്ടിയെ റസൂൽ(സ)യുടെ തുടയിൽ നിന്ന് കൊണ്ടുപോയി. ഉടനെ നബി(സ) വിഷയത്തിൽ നിന്നുണർന്നു. അവിടന്ന് ചോദിച്ചു: "കുട്ടിയെവിടെ." അബൂ ഉസൈദ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവനെ ഞങ്ങൾ കൊണ്ടുപോയി. നബി(സ) ചോദിച്ചു: "അവന്റെ പേരെന്താണ്?" അബൂ ഉസൈദ്(റ) പറഞ്ഞു: ഇന്ന പേരാണ്, അല്ലാഹുവിന്റെ റസൂലേ. നബി(സ) പറഞ്ഞു: "അല്ല, അവന്റെ പേര് മുൻദിർ എന്നാണ്." അങ്ങനെ ആ ദിവസം റസൂൽ(സ) അവന് ''മുൻദിർ'' എന്ന് പേരിട്ടു. (മു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 405, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّه عَنْه ضَرَبَ ابْنًا لَهُ تَكَنَّى أَبَا عِيسَى، وَأَنَّ الْمُغِيرَةَ بْنَ شُعْبَةَ تَكَنَّى بِأَبِي عِيسَى، فَقَالَ لَهُ عُمَرُ: أَمَا يَكْفِيكَ أَنْ تُكْنَى بِأَبِي عَبْدِ اللَّهِ؟ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَنَّانِي، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ، وَإِنَّا فِي جَلْجَتِنَا، فَلَمْ يَزَلْ يُكْنَى بِأَبِي عَبْدِ اللَّهِ حَتَّى هَلَكَ. (د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): അദ്ദേഹം ''അബൂ ഈസാ''യെന്ന് ഓമനപ്പേരുള്ള തന്റെ മകനെയടിച്ചു. മുഗീറതുബ്നു ശുഅ്ബ(റ)വിന്നും അബൂഈസയെന്ന് ഓമനപ്പേര് ഉണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തോട് ഉമർ(റ) പറഞ്ഞു: നിനക്ക് അബൂ അബ്ദില്ലാഹി എന്ന് ഓമനപ്പേര് വെച്ചാൽ പോരേ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) എന്റെ ഓമനപ്പേര് വിളിച്ചിട്ടുണ്ട്. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ)ക്ക് മുൻകഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ ദോഷങ്ങൾ പൊറുക്കപ്പെട്ടിരിക്കുന്നു. നാം സാധാരണ മുസ്ലിംകളുടെ കൂട്ടത്തിലാണ്. ശേഷം മുഗീറതുബ്നു ശുഅ്ബ(റ) മരിക്കുന്നത് വരെ ''അബൂ അബ്ദില്ലാഹ്'' എന്ന് ഓമനപ്പേരായിരുന്നു വിളിക്കപ്പെട്ടിരുന്നത്. (ദ)', 'عُمَرَ بْنَ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَخْنَعَ اسْمٍ عِنْدَ اللَّهِ رَجُلٌ تَسَمَّى مَلِكَ الْأَمْلَاكِ". فِي رِوَايَةٍ: "لَا مَالِكَ إِلَّا اللَّهُ". قَالَ سُفْيَانُ – يَعْنِي ابْنَ عُيَيْنَةَ – مِثْلُ شَاهَانْ شَاهْ. و قَالَ أَحْمَدُ بْنُ حَنْبَلٍ: سَأَلْتُ أَبَا عَمْرٍو عَنْ ''أَخْنَعُ'' فَقَالَ: أَوْضَعُ. (ق,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിങ്കൽ ഏറ്റവും ദുഷിച്ച പേര് ''മലികുൽ അംലാക്'' (രാജാധിരാജൻ) എന്നതാണ്." മറ്റൊരു നിവേദനം: "അല്ലാഹുവല്ലാതെ ഒരു ഉടമസ്ഥനുമില്ല." സുഫ്യാനുബ്നു ഉയൈന(റ) പറയുന്നു: ശാഹാൻശാഹ് (രാജാധിരാജൻ) പോലെത്തന്നെയാണത്. അഹ്മദുബ്നു ഹൻബൽ(റ) പറയുന്നു: ഞാൻ അബൂഅംറ്(റ)വിനോട് ''അഖ്നഅ്'' എന്ന വാക്കിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഏറ്റവും മോശമായത് എന്നാണർത്ഥം. (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 406, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=19), 1, null, 'മറ്റൊരു നിവേദനം: "അല്ലാഹുവല്ലാതെ ഒരു ഉടമസ്ഥനുമില്ല." സുഫ്യാനുബ്നു ഉയൈന(റ) പറയുന്നു: ശാഹാൻശാഹ് (രാജാധിരാജൻ) പോലെത്തന്നെയാണത്. അഹ്മദുബ്നു ഹൻബൽ(റ) പറയുന്നു: ഞാൻ അബൂഅംറ്(റ)വിനോട് ''അഖ്നഅ്'' എന്ന വാക്കിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഏറ്റവും മോശമായത് എന്നാണർത്ഥം. (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ سَمُرَةَ بْنِ جُنْدَب رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحَبُّ الْكَلَامِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ، وَلَا تُسَمِّيَنَّ غُلَامَكَ يَسَارًا وَلَا رَبَاحًا وَلَا نَجِيحًا وَلَا أَفْلَحَ، فَإِنَّكَ تَقُولُ أَثَمَّ هُوَ؟ فَلَا يَكُونُ، فَيَقُولُ: لَا. إِنَّمَا هُنَّ أَرْبَعٌ فَلَا تَزِيدُنَّ عَلَيَّ". (د,ت,جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട സംസാരം നാലെണ്ണമാണ്: സുബ്ഹാനല്ലാഹി, അൽഹംദുലില്ലാഹി, ലാഇലാഹ ഇല്ലല്ലാഹു, അല്ലാഹു അക്ബർ. അതിൽ ഏത് കൊണ്ട് തുടങ്ങിയാലും നിനക്ക് പ്രശ്നമില്ല. നിന്റെ കുട്ടിക്ക് യസാറെന്നോ, റബാഹെന്നോ, നജീഹെന്നോ അഫ്ലഹെന്നോ നീ പേരിടരുത്. കാരണം നീ ചോദിക്കും: അവൻ അവിടെയുണ്ടോ? അവൻ ഉണ്ടാകില്ല. അപ്പോൾ അവൻ ഇല്ലെന്ന് പറയും. അത് നാലെണ്ണം മാത്രമാണ്. നിങ്ങളെന്റെ മേൽ അധികമായി പറയരുത്." (ദ,തു,ജ)', 'سَمُرَةَ بْنِ جُنْدَب', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَئِنْ عِشْتُ – إِنْ شَاءَ اللَّهُ – لَأَنْهَيَنَّ أَنْ يُسَمَّى: رَبَاحٌ، وَنَجِيحٌ، وَأَفْلَحُ، وَنَافِعٌ، وَيَسَارٌ". (ت,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇൻശാ അല്ലാഹ് ഞാൻ ജീവിക്കുകയാണെങ്കിൽ റബാഹ്, നജീഹ്, അഫ്ലഹ്, നാഫിഅ്, യസാർ എന്നീ പേരുകൾ ഇട്ടുകൊടുക്കുന്നത് ഞാൻ നിരോധിക്കും. (തു,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُسَمِّيَ رَقِيقَنَا أَرْبَعَةَ أَسْمَاءٍ: أَفْلَحُ، وَنَافِعٌ، وَرَبَاحٌ، وَيَسَارٌ. (م,د,ت,جه)', 'സമുറ(റ): നാലുപേരുകൾ അടിമകൾക്ക് ഇട്ടുകൊടുക്കുന്നതിൽ നിന്ന് അല്ലാഹുവിന്റെ റസൂൽ(സ) ഞങ്ങളെ വിലക്കിയിരിക്കുന്നു. അഫ്ലഹ്, നാഫിഅ്, റബാഹ്, യസാർ. (മു,ദ,തു,ജ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ عِشْتُ – إِنْ شَاءَ اللَّهُ – أَنْهَى أُمَّتِي أَنْ يُسَمُّوا نَافِعًا وَأَفْلَحَ وَبَرَكَةَ فَإِنَّ الرَّجُلَ يَقُولُ إِذَا جَاءَ: أَثَمَّ بَرَكَةُ؟ فَيَقُولُونَ: لَا". (د,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇൻശാഅല്ലാഹ്, ഞാൻ ജീവിക്കുകയാണെങ്കിൽ എന്റെ സമൂഹത്തെ നാഫിഅ്, അഫ്ലഹ്, ബറകത് എന്നീ പേരുകളിടുന്നതിൽ നിന്ന് വിലക്കുമായിരുന്നു. ഏതെങ്കിലും ഒരാൾ വന്ന് ചോദിക്കും: അവിടെ ബർക്കത്തുണ്ടോ? അപ്പോൾ അവർ ഇല്ലെന്ന് പറയും." (ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَابِرٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْهَيَنَّ أَنْ يُسَمَّى: رَافِعٌ وَبَرَكَةُ وَيَسَارٌ". (م,ت,جه)', 'ജാബിർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ)വിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: റസൂൽ(സ) പറഞ്ഞു: "നാഫിഅ്, ബറകത്ത്, യസാർ എന്നീ പേരുകൾ നൽകപ്പെടുന്നത് ഞാൻ നിരോധിക്കുക തന്നെ ചെയ്യും." (മു,തു,ജ)*', 'جَابِرٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ –', 'ജാബിർ(റ)', '*ഈ പേരുകൾ നിരോധിക്കപ്പെടാൻ കാരണം ഇത്തരത്തിലുള്ള പേരുകളുള്ളവർ വല്ല സമയത്തും വീട്ടിൽ നിന്നോ മറ്റോ പുറത് പോയാൽ ചിലപ്പോൾ അവരുടെ പേര് വിളിച്ച് അവരവിടെയുണ്ടോയെന്ന് ചോദിക്കും. (ഉദാഹരണം ''ബറകത്'' അവിടെയുണ്ടോ എന്ന് ചോദിക്കപ്പെടുമ്പോൾ ഇല്ല എന്ന മറുപടി വ്യംഗ്യമായി ആ വീട്ടിൽ അല്ലാഹുവിന്റെ ബറകത് ഇല്ല എന്ന് സൂചിപ്പിക്കപ്പെടുന്നത് കൊണ്ടാണ്.', null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 407, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَنْهَى [عَنْ] أَنْ يُسَمَّى بِمُقْبِلٍ وَبِبَرَكَةَ وَبِأَفْلَحَ وَبِيَسَارٍ وَبِنَافِعٍ، وَبِنَحْوِ ذَلِكَ، ثُمَّ رَأَيْتُهُ سَكَتَ بَعْدُ عَنْهَا فَلَمْ يَقُلْ شَيْئًا، ثُمَّ قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَنْهَ عَنْ ذَلِكَ، ثُمَّ أَرَادَ عُمَرُ رَضِيَ اللهُ عَنْهُ أَنْ يَنْهَى عَنْ ذَلِكَ ثُمَّ تَرَكَهُ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): മുഖ്ബിൽ, ബറകത്, അഫ്ലഹ്, യസാർ, നാഫിഅ് എന്നിവയും അതിനോട് സമാനമായ പേരുകളും ഇടുന്നത് നിരോധിക്കാൻ റസൂൽ(സ) ഉദ്ദേശിച്ചിരുന്നു. പിന്നീട് അവിടന്ന് അതിനെ സംബന്ധിച്ച് മൗനമവലംബിച്ചതായി ഞാൻ കണ്ടു. അവിടന്നൊന്നും പറഞ്ഞതുമില്ല. പിന്നെ റസൂൽ(സ) വഫാത്തായി. അവിടന്നത് വിരോധിക്കുകയും ചെയ്തില്ല. ശേഷം ഉമർ(റ) അത് നിരോധിക്കാനുദ്ദേശിച്ചു. പിന്നീട് അദ്ദേഹമത് ഉപേക്ഷിച്ചു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'عَنْ', null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ هَانِئِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ لَمَّا وَفَدَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ قَوْمِهِ سَمِعَهُمْ يَكْنُونَهُ بِأَبِي الْحَكَمِ، فَدَعَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ اللَّهَ هُوَ الْحَكَمُ، وَإِلَيْهِ الْحُكْمُ، فَلِمَ تُكْنَى أَبَا الْحَكَمِ". فَقَالَ: إِنَّ قَوْمِي إِذَا اخْتَلَفُوا فِي شَيْءٍ أَتَوْنِي فَحَكَمْتُ بَيْنَهُمْ، فَرَضِيَ كِلَا الْفَرِيقَيْنِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَحْسَنَ هَذَا فَمَا لَكَ مِنَ الْوَلَدِ". قَالَ: لِي شُرَيْحٌ وَمُسْلِمٌ وَعَبْدُ اللَّهِ، قَالَ: "فَمَنْ أَكْبَرُهُمْ". قُلْتُ: شُرَيْحٌ، قَالَ: "فَأَنْتَ أَبُو شُرَيْحٍ". (د,ن)', 'ഹാനിഉബ്നു യസീദ്(റ): അദ്ദഹേം തന്റെ സമൂഹത്തോടു കൂടെ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവർ അദ്ദേഹത്തെ ''അബുൽ ഹകം'' എന്ന ഓമനപ്പേര് വിളിക്കുന്നത് റസൂൽ(സ) കേട്ടു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ വിളിച്ചിട്ട് പറഞ്ഞു: "അല്ലാഹുവാണ് ഹകം(വിധികർത്താവ്), വിധിക്കാനുള്ള അധികാരം അവന്നാണുള്ളത്. പിന്നെയെന്തിനാണ് നിങ്ങൾ ''അബുൽഹകം'' എന്ന ഓമനപ്പേരിടുന്നത്?" അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ സമൂഹം വല്ല കാര്യത്തിലും തർക്കിച്ചാൽ അവർ എന്റെയടുത്ത് വരും, ഞാനവർക്കിടയിൽ വിധി കൽപിക്കും. അങ്ങനെ രണ്ട് വിഭാഗവും തൃപ്തിപ്പെടും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇതെത്ര നല്ലതാണ്. നിങ്ങൾക്ക് കുട്ടികളൊന്നുമില്ലേ?" അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ശുറൈഹ്, മുസ്ലിം, അബ്ദുല്ല എന്നീ മക്കളുണ്ട്. നബി(സ) ചോദിച്ചു: "അതിൽ ഏറ്റവും വലിയവൻ ആരാണ്?" ഞാൻ പറഞ്ഞു: ശുറൈഹ്. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ അബൂശുറൈഹാണ്." (ദ,ന)', 'هَانِئِ بْنِ يَزِيدَ', 'ഹാനിഉബ്നു യസീദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "مَا اسْمُكَ". قَالَ: حَزْنٌ، قَالَ: "أَنْتَ سَهْلٌ". قَالَ: لَا، السَّهْلُ يُوطَأُ وَيُمْتَهَنُ. قَالَ سَعِيدٌ: فَظَنَنْتُ أَنَّهُ سَيُصِيبُنَا بَعْدَهُ حُزُونَةٌ. (خ,د)', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ): നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "നിങ്ങളുടെ പേരെന്താണ്?" അദ്ദേഹം പറഞ്ഞു: ഹസ്ൻ(ദു:ഖം എന്നർത്ഥം). നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സഹ്ലാണ്." അദ്ദേഹം പറഞ്ഞു: അല്ല, സഹ്ലിന് കുത്തേൽക്കുകയും അവൻ പരീക്ഷിക്കപ്പെടുകയും ചെയ്യും. സഈദ്(റ) പറയുന്നു: അതിന് ശേഷം ഞങ്ങൾക്ക് കാഠിന്യം ബാധിക്കുമെന്ന് ഞാൻ വിചാരിച്ചു. (ബു,ദ)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 408, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ مَسْرُوقٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقِيتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ فَقَالَ: مَنْ أَنْتَ؟ قُلْتُ: مَسْرُوقُ بْنُ الْأَجْدَعِ، فَقَالَ عُمَرُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْأَجْدَعُ شَيْطَانٌ". (د,جه)', 'മസ്റുഖ്(റ): ഞാൻ ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനെ കണ്ടുമുട്ടി. അദ്ദേഹം ചോദിച്ചു: നിങ്ങളാരാണ്? ഞാൻ പറഞ്ഞു: മസ്റൂഖുബ്നുൽ അജ്ദഅ്. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അജ്ദഅ് എന്നത് ഒരു പിശാചാണ്." (ദ,ജ)', 'مَسْرُوقٍ', 'മസ്റുഖ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقُولَنَّ أَحَدُكُمْ لِلْعِنَبِ الْكَرْمَ، إِنَّمَا الْكَرْمُ الرَّجُلُ الْمُسْلِمُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരും മുന്തിരിക്ക് ''കർമ്'' (വള്ളി) എന്ന് പറയരുത്. കർമ് മുസ്ലിമായ മനുഷ്യൻ മാത്രമാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُسَمُّوا الْعِنَبَ الْكَرْمَ، إِنَّمَا الْكَرْمُ قَلْبُ الْمُؤْمِنِ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മുന്തിരിയെ ''കർമെ''ന്ന് വിളിക്കരുത്. ''കർമ്'' വിശ്വാസിയുടെ ഹൃദയം മാത്രമാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ وَائِلِ بْنِ حِجْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُولُوا الْكَرْمُ، وَلَكِنْ قُولُوا الْعِنَبُ وَالْحَبَلَةُ". (م)', 'വാഇലുബ്നു ഹിജ്ർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ''കർമെ''ന്ന് പറയരുത്. മറിച്ച് ഇനബ്(മുന്തിരി)യെന്നും ഹബ്ല(മുന്തിരിത്തടി)യെന്നും പറഞ്ഞുകൊള്ളുക." (മു)', 'وَائِلِ بْنِ حِجْرٍ', 'വാഇലുബ്നു ഹിജ്ർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقُلْ أَحَدُكُمْ: اسْقِ رَبَّكَ، وَأَطْعِمْ رَبَّكَ، وَضِّئْ رَبَّكَ، وَلَا يَقُلْ أَحَدُكُمْ: رَبِّي، وَلْيَقُلْ: سَيِّدِي وَمَوْلَايَ، وَلَا يَقُلْ أَحَدُكُمْ: عَبْدِي، أَمَتِي، وَلْيَقُلْ: فَتَايَ، فَتَاتِي، غُلَامِي". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ രക്ഷിതാവിനെ കുടിപ്പിക്കുക, നിന്റെ രക്ഷിതാവിനെ ഭക്ഷിപ്പിക്കുക, നിന്റെ രക്ഷിതാവിന് വുളൂ ചെയ്ത് കൊടുക്കുക എന്നിങ്ങനെ പറയരുത്. ''എന്റെ രക്ഷിതാവ്'' എന്ന് നിങ്ങൾ പറയരുത്. എന്റെ നേതാവ്, എന്റെ യജമാനൻ എന്ന് പറയുക. എന്റെ അടിമ, എന്റെ അടിമസ്ത്രീ എന്ന് നിങ്ങൾ പറയരുത്. എന്റെ യുവാവ്, എന്റെ യുവതി, എന്റെ വേലക്കാരൻ എന്നെല്ലാം പറഞ്ഞു കൊള്ളട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 409, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُغَيِّرُ الِاسْمَ الْقَبِيحَ. (ت)', 'ആഇശ(റ): മോശമായ പേര് നബി(സ) മാറ്റുമായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَيَّرَ اسْمَ عَاصِيَةَ، وَقَالَ: "أَنْتِ جَمِيلَةٌ". حَسَنٌ. (م,د,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ''ആസിയ'' (ദോഷി) എന്ന പേര് മാറ്റിയിട്ട് പറഞ്ഞു: "നീ ജമീലയാണ്." ഹദീസ് ഹസനാണ്. (മു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ ابْنَةً لِعُمَرَ رَضِيَ اللهُ عَنْهُ كَانَتْ يُقَالُ لَهَا عَاصِيَةُ، فَسَمَّاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمِيلَةَ. (م,جه)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ)വിന്റെ ഒരു കുട്ടിയുടെ പേര് ''ആസിയ'' (ദോഷി) എന്നായിരുന്നു. റസൂൽ(സ) അവൾക്ക് ''ജമീല''യെന്ന് പേരിട്ടു. (മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمَّيْتُ ابْنَتِي بَرَّةَ، فَقَالَتْ لِي زَيْنَبُ بِنْتُ أَبِي سَلَمَةَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ هَذَا الِاسْمِ، وَسُمِّيتُ بَرَّةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُزَكُّوا أَنْفُسَكُمْ، اللَّهُ أَعْلَمُ بِأَهْلِ الْبِرِّ مِنْكُمْ". فَقَالُوا: بِمَ نُسَمِّيهَا؟ قَالَ: "سَمُّوهَا زَيْنَبَ". (م,د)', 'മുഹമ്മദുബ്നു അംരിബ്നി അത്വാഅ്(റ): ഞാനെന്റെ മകൾക്ക് ''ബർറ'' (പുണ്യവതി) എന്ന് പേരിട്ടു. എന്നോട് സൈനബ് ബിൻത് അബീസലമ(റ) പറഞ്ഞു: എനിക്ക് ''ബർറ'' എന്ന് പേരിട്ടിരിക്കെ, റസൂൽ(സ) ഈ പേര് നിരോധിച്ചിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളെ നിങ്ങൾ പരിശുദ്ധരായി വാഴ്ത്തരുത്. നിങ്ങളിൽ നിന്ന് നന്മ ചെയ്യുന്നവരെ അല്ലാഹു അറിയും." അപ്പോൾ അവർ ചോദിച്ചു: ഞങ്ങൾ എന്താണ് അവൾക്ക് പേരിടുക? അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ അവൾക്ക് സൈനബ് എന്ന് പേരിടുക." (മു,ദ)', 'مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ', 'മുഹമ്മദുബ്നു അംരിബ്നി അത്വാഅ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ زَيْنَبَ كَانَ اسْمُهَا بَرَّةَ، فَقِيلَ لَهَا تُزَكِّي نَفْسَهَا، فَسَمَّاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: زَيْنَبَ. (ق)', 'അബൂഹുറൈറ(റ): സൈനബ(റ)യുടെ ആദ്യത്തെ പേര് ''ബർറ'' എന്നായിരുന്നു. അപ്പോൾ അവരോട് ''നീ സ്വയം പരിശുദ്ധയാക്കുകയാണോ? എന്ന് ചോദിക്കപ്പെട്ടു. അങ്ങനെ റസൂൽ(സ) അവർക്ക് സൈനബ് എന്ന് പേരിട്ടു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ أُمُّ سُلَيْمٍ فِي الثَّقَلِ، وَأَنْجَشَةُ غُلَامُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسُوقُ بِهِنَّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَنْجَشُ رُوَيْدَكَ سَوْقَكَ بِالْقَوَارِيرِ". (خ)', 'അനസ്(റ): ഉമ്മു സുലൈം(റ) ഒരു കൂട്ടം സ്ത്രീകളുടെ കൂടെ യാത്ര ചെയ്യുകയായിരുന്നു. റസൂൽ(സ)യുടെ അടിമ അൻജഷയാണ് അവരുടെ ഒട്ടകങ്ങളെ തെളിച്ചിരുന്നത്. തിരുമേനി(സ) പറഞ്ഞു: "അൻജഷേ, പതുക്കെ തെളിക്കുക. നീ വാഹനത്തിൽ ചുമന്നുകൊണ്ട് പോകുന്നത് സ്ഫടിക പാത്രങ്ങളാണ്." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ جُوَيْرِيَةُ اسْمُهَا بَرَّةَ، فَحَوَّلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْمَهَا جُوَيْرِيَةَ، وَكَانَ يَكْرَهُ أَنْ يُقَالَ: خَرَجَ مِنْ عِنْدِ بَرَّةَ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ജുവൈരിയ(റ)യുടെ പേര് ''ബർറ'' എന്നായിരുന്നു. റസൂൽ(സ) അവളുടെ പേര് ജുവൈരിയ എന്നാക്കി. ബർറ (പുണ്യവതി)യുടെ അടുത്ത് നിന്ന് പുറപ്പെട്ടു എന്ന് പറയപ്പെടുന്നത് അവിടന്ന് വെറുത്തിരുന്നു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَيْسَ اسْمِي عَبْدَ اللَّهِ بْنَ سَلَامٍ، فَسَمَّانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَبْدَ اللَّهِ بْنَ سَلَامٍ. [ز: فيه رَاوٍ مجهول] (جه)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ എന്റെ പേര് ''അബ്ദുല്ലാഹിബ്നു സലാം'' എന്നായിരുന്നില്ല. റസൂൽ(സ) എനിക്ക് അബ്ദുല്ലാഹിബ്നു സലാം എന്ന് പേരിട്ടു. (പരമ്പരയിൽ അറിയപ്പെടാത്ത നിവേദകനുണ്ട്.) (ജ)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه رَاوٍ مجهول', null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أُسَامَةَ بْنِ أَخْدَرِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا يُقَالُ لَهُ أَصْرَمُ، كَانَ فِي النَّفَرِ الَّذِينَ أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا اسْمُكَ". قَالَ: أَنَا أَصْرَمُ، قَالَ: "بَلْ أَنْتَ زُرْعَةُ". (د)', 'ഉസാമതുബ്നു അഖ്ദരി(റ): റസൂൽ(സ)യുടെ അടുത്ത് വന്ന സംഘത്തിൽ ''അസ്റം'' എന്ന് പേരുള്ള ഒരാളുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളുടെ പേരെന്താണ്?". ഞാൻ അസ്റമാണ് എന്ന് അദ്ദേഹം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ല, നിങ്ങൾ ''സുർഅ''യാണ്." (ദ)', 'أُسَامَةَ بْنِ أَخْدَرِيٍّ', 'ഉസാമതുബ്നു അഖ്ദരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكُمْ تُدْعَوْنَ يَوْمَ الْقِيَامَةِ بِأَسْمَائِكُمْ وَأَسْمَاءِ آبَائِكُمْ، فَأَحْسِنُوا أَسْمَاءَكُمْ". (م,د)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യദിനത്തിൽ നിങ്ങളുടെ പേരിലും നിങ്ങളുടെ പിതാക്കളുടെ പേരിലും നിങ്ങൾ വിളിക്കപ്പെടും. അത് കൊണ്ട് നിങ്ങൾ നിങ്ങളുടെ പേരുകൾ നന്നാക്കുക." (മു,ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ حَمْزَةَ بْنِ صُهَيْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عُمَرَ قَالَ لِصُهَيْبٍ، رَضِيَ اللهُ عَنْهُمَا: مَا لَكَ تَكْتَنِي بِأَبِي يَحْيَى، وَلَيْسَ لَكَ وَلَدٌ؟ قَالَ: كَنَّانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَبِي يَحْيَى. (جه)', 'ഹംസതുബ്നു സുഹൈബ്(റ): നിശ്ചയം ഉമർ(റ) സുഹൈബ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെന്താ അബു യഹ്യായെന്ന് ഓമനപ്പേരിട്ടിരിക്കുന്നത്. നിങ്ങൾക്ക് കുട്ടിയില്ലല്ലോ? സുഹൈബ്(റ) പറഞ്ഞു: എനിക്ക് റസൂൽ(സ)യാണ് അബു യഹ്യായെന്ന ഓമനപ്പേരിട്ടത്. (ജ)', 'حَمْزَةَ بْنِ صُهَيْبٍ', 'ഹംസതുബ്നു സുഹൈബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا قَالَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ أَزْوَاجِكَ كَنَّيْتَهُ غَيْرِي. قَالَ: "فَأَنْتِ أُمُّ عَبْدِ اللَّهِ". (جه)', 'ആഇശ(റ): അവർ നബി(സ)യോട് പറഞ്ഞു: ഞാനല്ലാത്ത, അങ്ങയുടെ എല്ലാ ഭാര്യമാർക്കും അങ്ങ് ഓമനപ്പേരിട്ടിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ഉമ്മു അബ്ദില്ലയാണ്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينَا فَيَقُولُ لِأَخٍ لِي، وَكَانَ صَغِيرًا: "يَا أَبَا عُمَيْرٍ". (جه)', 'അനസ്(റ): നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്നിരുന്നു. അപ്പോൾ എന്റെ ചെറിയ സഹോദരനോട് അവിടന്ന് പറയും: "ഓ, അബൂ ഉമൈർ." (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ عَلَيْنَا وَلِي أَخٌ صَغِيرٌ يُكْنَى أَبَا عُمَيْرٍ، وَكَانَ لَهُ نُغَرٌ يَلْعَبُ بِهِ، فَمَاتَ، فَدَخَلَ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَرَآهُ حَزِينًا، فَقَالَ: "مَا شَأْنُهُ". قَالُوا: مَاتَ نُغَرُهُ، فَقَالَ: "يَا أَبَا عُمَيْرٍ، مَا فَعَلَ النُّغَيْرُ". (ق,د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഞങ്ങളുടെയടുത്ത് വരാറുണ്ടായിരുന്നു. അബൂ ഉമൈർ എന്ന് ഓമനപ്പേരുള്ള ഒരു ഇളയ സഹോദരനുണ്ടായിരുന്നു എനിക്ക്. അവന് കളിക്കാൻ കുരുവി പോലുള്ള ഒരു കിളിയുണ്ടായിരുന്നു. ഒരുവേള അത് ചത്തുപോയി. പിന്നീടൊരു ദിവസം റസൂൽ(സ) അവന്റെയടുത്ത് വന്നപ്പോൾ അവനെ ദുഃഖിതനായി കണ്ടു. നബി(സ) ചോദിച്ചു: "എന്താണ് അവന് പറ്റിയത്." അവർ പറഞ്ഞു. അവന്റെ കിളി ചത്തു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഓ അബൂ ഉമൈർ, കുഞ്ഞിക്കിളിക്കെന്ത് പറ്റി." (ബു,മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي جَبِيرَةَ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ قَالَ: فِينَا نَزَلَتْ هَذِهِ الْآيَةُ فِي بَنِي سَلَمَةَ: {وَلَا تَنَابَزُوا بِالْأَلْقَابِ بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ} [الْحُجُرَات: ١١]. قَالَ: قَدِمَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَيْسَ مِنَّا رَجُلٌ إِلَّا وَلَهُ اسْمَانِ أَوْ ثَلَاثَةٌ، فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَا فُلَانُ". فَيَقُولُونَ: مَهْ يَا رَسُولَ اللَّهِ، إِنَّهُ يَغْضَبُ مِنْ هَذَا الِاسْمِ. فَأُنْزِلَتْ هَذِهِ الْآيَةُ: {وَلَا تَنَابَزُوا بِالْأَلْقَابِ}. (د,ت,جه)', 'അബൂ ജബീറതുബ്നു ളഹ്ഹാക്(റ): ഞങ്ങൾ ബനുസലമക്കാരിലാണ് ഈ സൂക്തമിറങ്ങിയത്: ''നിങ്ങൾ പരസ്പരം പരിഹാസപ്പേര് വിളിക്കരുത്, ഈമാന് ശേഷം തെമ്മാടിത്തം എത്ര മോശമായ പേരാണ്.'' (അൽഹുജറാത്: 11). അബൂ ജബീറ(റ) പറയുന്നു: റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. ആ സമയത്ത് ഞങ്ങളിലോരോരുത്തർക്കും രണ്ടോ മൂന്നോ പേരുണ്ട്. നബി(സ) ഓരോരുത്തരുടെ പേര് വിളിക്കാൻ തുടങ്ങി. അപ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിർത്തിയാലും. ഈ പേര് അയാളെ ദേഷ്യം പിടിപ്പിക്കും. അപ്പോൾ ''നിങ്ങൾ പരസ്പരം പരിഹാസപ്പേരുകൾ വിളിക്കരുത്'' എന്ന സൂക്തമിറങ്ങി. (ദ,തു,ജ)', 'أَبِي جَبِيرَةَ بْنِ الضَّحَّاكِ', 'അബൂ ജബീറതുബ്നു ളഹ്ഹാക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'الْحُجُرَات: ١١', null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: يَا رَسُولَ اللَّهِ، كُلُّ صَوَاحِبِي لَهُنَّ كُنًى؟ قَالَ: "فَاكْتَنِي بِابْنِكِ عَبْدِ اللَّهِ". يَعْنِي ابْنَ أُخْتِهَا عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ، قَالَ: فَكَانَتْ تُكَنَّى بِأُمِّ عَبْدِ اللَّهِ. (د)', 'ആഇശ(റ): മഹതി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ എല്ലാ കൂട്ടുകാരികൾക്കും ഓമനപ്പേരുകളുണ്ട്. നബി(സ) പറഞ്ഞു: "നിന്റെ മകനായ അബ്ദുല്ലയുടെ പേര് ചേർത്തി നീ ഓമനപ്പേര് വെക്കുക." അതായത് ആഇശ(റ)യുടെ സഹോദരീപുത്രനായ അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ). ശേഷം അവർ ''ഉമ്മു അബ്ദില്ല'' എന്ന ഓമനപ്പേരിൽ വിളിക്കപ്പെട്ടിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 412, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِتَسْمِيَةِ الْمَوْلُودِ يَوْمَ سَابِعِهِ، وَوَضْعِ الْأَذَى عَنْهُ، وَالْعَقِّ. حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) കുട്ടിക്ക് ഏഴാം ദിവസം പേരിടാനും അവന്റെ തലമുടി നീക്കാനും അവന് അഖീഖ അറുക്കാനും കൽപിച്ചു. (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدٌ عَنِ الدَّجَّالِ أَكْثَرَ مِمَّا سَأَلْتُهُ عَنْهُ، فَقَالَ لِي: "أَيْ بُنَيَّ، وَمَا يُنْصِبُكَ مِنْهُ؟ إِنَّهُ لَنْ يَضُرَّكَ". قَالَ: قُلْتُ: إِنَّهُمْ يَزْعُمُونَ أَنَّ مَعَهُ أَنْهَارَ الْمَاءِ وَجِبَالَ الْخُبْزِ؟ قَالَ: "هُوَ أَهْوَنُ عَلَى اللَّهِ مِنْ ذَلِكَ". (م)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): ദജ്ജാലിനെക്കുറിച്ച് റസൂൽ(സ)യോട് ഞാൻ ചോദിച്ചതിനേക്കാൾ കൂടുതൽ ആരും ചോദിച്ചിട്ടുണ്ടാകില്ല. അവിടന്നെന്നോട് പറഞ്ഞു: "എന്റെ കുഞ്ഞിമോനേ, അവൻ നിനക്ക് എന്ത് ബുദ്ധിമുട്ട് വരുത്താനാണ്! അവൻ നിന്നെ ഒരിക്കലും ഉപദ്രവിക്കില്ല." അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: അവന്റെ കൂടെ വെള്ളത്തിന്റെ പുഴകളും, പത്തിരിയുടെ പർവ്വതങ്ങളുമുണ്ടെന്ന് അവർ പറയുന്നുണ്ടല്ലോ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന് അവൻ അതിനേക്കാൾ നിസ്സാരമാണ്." (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "يَا بُنَيَّ". (م,د,ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) അദ്ദേഹത്തെ "എന്റെ കുഞ്ഞിമോനെ"യെന്ന് വിളിച്ചു. (മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَنَّ رَجُلًا اطَّلَعَ عَلَيْكَ بِغَيْرِ إِذْنٍ فَخَذَفْتَهُ بِحَصَاةٍ فَفَقَأْتَ عَيْنَهُ، مَا كَانَ عَلَيْكَ مِنْ جُنَاحٍ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ സമ്മതം കൂടാതെ നിന്നിലേക്ക് എത്തിനോക്കിയപ്പോൾ നീ കല്ലെറിഞ്ഞ് അവന്റെ കണ്ണ് ചൂഴ്ന്നെടുത്താലും നിന്റെ മേൽ യാതൊരു കുറ്റവുമില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ اطَّلَعَ فِي دَارِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ، فَفَقَئُوا عَيْنَهُ، فَقَدْ هَدَرَتْ عَيْنُهُ". (د)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "വീട്ടുകാരുടെ സമ്മതമില്ലാതെ ഒരാൾ വീട്ടിലേക്ക് എത്തിനോക്കിയപ്പോൾ അവർ അവന്റെ കണ്ണെറിഞ്ഞുവീഴ്ത്തിയാൽ, അവന്റെ കണ്ണിന്റെ സംരക്ഷണം നഷ്ടപ്പെട്ടിരിക്കുന്നു." (അതിൽ നഷ്ടപരിഹാരമില്ല.) (ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، هَذَا السَّلَامُ، فَمَا الِاسْتِئْذَانُ؟ قَالَ: "يَتَكَلَّمُ الرَّجُلُ تَسْبِيحَةً وَتَكْبِيرَةً وَتَحْمِيدَةً، وَيَتَنَحْنَحُ، وَيُؤْذِنُ أَهْلَ الْبَيْتِ". [ز: فِي سَنَدِهِ رَاوٍ مُنْكَرُ الْحَدِيثِ] (جه)', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ): ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സലാം ഇപ്രകാരമാണ്. എങ്കിൽ സമ്മതം ചോദിക്കൽ എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തസ്ബീഹായിട്ടും, തക്ബീറായിട്ടും, തഹ്മീദായിട്ടും സംസാരിക്കുകയും, അവൻ തൊണ്ടയനക്കി ശബ്ദമുണ്ടാക്കുകയും വീട്ടുകാരോട് സമ്മതം ചോദിക്കുകയും ചെയ്യൽ." (ജ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سَنَدِهِ رَاوٍ مُنْكَرُ الْحَدِيثِ', null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِي مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُدْخَلَانِ: مُدْخَلٌ بِاللَّيْلِ، وَمُدْخَلٌ بِالنَّهَارِ، فَكُنْتُ إِذَا أَتَيْتُهُ وَهُوَ يُصَلِّي يَتَنَحْنَحُ لِي. (ن)', 'അലി(റ): എനിക്ക് റസൂൽ(സ)യുടെ അടുക്കലേക്ക് രണ്ട് പ്രവേശനസമയമുണ്ട്. ഒന്ന് രാത്രിയിലെ പ്രവേശന സമയം, മറ്റേത് പകലിലെ പ്രവേശന സമയം. നബി(സ) നിസ്കരിക്കുന്ന സമയത്ത് ഞാൻ തിരുസന്നിധിയിൽ വന്നാൽ എനിക്ക് വേണ്ടി അവിടന്ന് തൊണ്ടയനക്കും. (പ്രവേശിക്കാനുള്ള സമ്മതമെന്ന നിലക്ക്) (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَشَفَ سِتْرًا، فَأَدْخَلَ بَصَرَهُ فِي الْبَيْتِ قَبْلَ أَنْ يُؤْذَنَ لَهُ، فَرَأَى عَوْرَةَ أَهْلِهِ، فَقَدْ أَتَى حَدًّا لَا يَحِلُّ لَهُ أَنْ يَأْتِيَهُ. لَوْ أَنَّهُ حِينَ أَدْخَلَ بَصَرَهُ اسْتَقْبَلَهُ رَجُلٌ، فَفَقَأَ عَيْنَيْهِ، مَا غَيَّرْتُ عَلَيْهِ. وَإِنْ مَرَّ الرَّجُلُ عَلَى بَابٍ لَا سِتْرَ لَهُ غَيْرِ مُغْلَقٍ، فَنَظَرَ، فَلَا خَطِيئَةَ عَلَيْهِ، إِنَّمَا الْخَطِيئَةُ عَلَى أَهْلِ الْبَيْتِ". (ت)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ സമ്മതം നൽകപ്പെടുന്നതിന് മുമ്പ് മറ തുറന്ന് വീട്ടിനകത്തേക്ക് നോക്കി വീട്ടുകാരുടെ ഔറത്ത് കണ്ടാൽ തനിക്ക് അനുവദനീയമല്ലാത്ത ശിക്ഷാർഹമായ കാര്യമാണ് അവൻ ചെയ്തത്. അവൻ നോക്കിയ സമയത്ത് ഒരാൾ വന്ന് അവന്റെ കണ്ണെറിഞ്ഞ് വീഴ്ത്തിയാൽ ഞാനതിന് എതിര് പറയില്ല. താഴില്ലാത്ത, മറയില്ലാത്ത ഒരു വാതിലിനരികിലൂടെ ഒരാൾ നടന്നു പോകുമ്പോൾ നോക്കിയാൽ അവന് കുറ്റമില്ല. കുറ്റം വീട്ടുകാർക്കാണ്." (തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا اطَّلَعَ مِنْ بَعْضِ حُجَرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ إِلَيْهِ بِمِشْقَصٍ – أَوْ: مَشَاقِصَ – قَالَ: فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْتِلُهُ لِيَطْعَنَهُ. (ق,د,ت)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യുടെ മുറിയിലേക്ക് (വാതിൽപ്പഴുതിലൂടെ) എത്തിനോക്കി. നബി(സ) അയാളുടെ അടുത്തേക്ക് അമ്പും മുനയുമായി ചെന്നു. അനസുബ്നു മാലിക്(റ) പറയുന്നു: റസുൽ(സ) രഹസ്യമായി അയാളെ കുത്താൻ പോകുന്നത് ഞാനിപ്പോൾ നോക്കുന്നത് പോലെയുണ്ട്. (ബു,മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي بَيْتِهِ، فَاطَّلَعَ عَلَيْهِ رَجُلٌ، فَأَهْوَى إِلَيْهِ بِمِشْقَصٍ، فَتَأَخَّرَ الرَّجُلُ. حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അനസ്(റ): നബി(സ) വീട്ടിലായിരുന്നു. അപ്പോൾ ഒരാൾ നബി(സ)യെ എത്തിനോക്കി. നബി(സ) അയാളുടെ അടുത്തേക്ക് അമ്പിന്റെ മുനയുമായി ചെന്നു. അപ്പോൾ അയാൾ പിന്തിരിഞ്ഞു പോയി. (ബു,മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 414, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَظَرِ الْفُجَاءَةِ، فَأَمَرَنِي أَنْ أَصْرِفَ بَصَرِي. (م,ت)', 'ജരീറുബ്നു അബ്ദില്ല(റ): ഞാൻ റസൂൽ(സ)യോട് പെട്ടെന്നുള്ള നോട്ടത്തെക്കുറിച്ച് ചോദിച്ചു: അപ്പോൾ അവിടുന്നെന്നോട് കണ്ണ് തിരിക്കാൻ പറഞ്ഞു. (മു,തു)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ –رَفَعَهُ– قَالَ: "يَا عَلِيُّ، لَا تُتْبِعِ النَّظْرَةَ النَّظْرَةَ، فَإِنَّ لَكَ الْأُولَى وَلَيْسَتْ لَكَ الْآخِرَةُ". حَسَنٌ. (د,ت)', 'അബു ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓ അലി, നിങ്ങൾ വീണ്ടും വീണ്ടും നോക്കരുത്, ആദ്യത്തേത് നിങ്ങൾക്കനുവദനീയമാണ്, അതിന് ശേഷമുള്ളത് നിങ്ങൾക്കനുവദനീയമല്ല." (ദ,തു)', 'بُرَيْدَةَ', 'അബു ബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا اطَّلَعَ فِي جُحْرٍ فِي بَابٌ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِدْرًى يَحُكُّ بِهِ رَأْسَهُ، فَلَمَّا رَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَعْلَمُ أَنَّكَ تَنْتَظِرُنِي لَطَعَنْتُ بِهِ فِي عَيْنِكَ". وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا جُعِلَ الْإِذْنُ مِنْ أَجْلِ الْبَصَرِ". (ق,ت,ن)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): ഒരാൾ റസൂൽ(സ)യുടെ വാതിൽ ദ്വാരത്തിലൂടെ എത്തിനോക്കി. നബി(സ)യുടെ പക്കൽ തല ചൊറിയാനുപയോഗിച്ചിരുന്ന ഒരു കൊള്ളിയുണ്ടായിരുന്നു. അയാളെ കണ്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ എന്നെ നോക്കുന്നുണ്ടെന്ന് അറിഞ്ഞിരുന്നെങ്കിൽ, നിന്റെ കണ്ണിൽ ഞാൻ കുത്തുമായിരുന്നു." റസൂൽ(സ) വീണ്ടും പറഞ്ഞു: "നോട്ടം കാരണമാണ് സമ്മതം ചോദിക്കൽ വെച്ചത്." (ബു,മു,തു,ന)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دَخَلَ الْبَصَرُ فَلَا إِذْنَ". (د)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അകത്തേക്ക് നോക്കിയാൽ, പിന്നെ സമ്മതം ലഭിക്കില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ هُزَيْلِ بْنِ شُرَحْبِيلِ الْأَوْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ وفي رواية: سَعْدٌ –فَوَقَفَ عَلَى بَابٌ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْذِنُ، فَقَامَ عَلَى الْبَابِ –وفي رواية: مُسْتَقْبِلَ الْبَابُ– فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَكَذَا عَنْكَ– أَوْ: هَكَذَا، فَإِنَّمَا الِاسْتِئْذَانُ مِنَ النَّظَرِ". (د)', 'ഹുദൈലുബ്നു ഷുറഹ്ബീലുൽ ഔദി(റ): ഒരാൾ വന്ന്കൊണ്ട് - ഒരു നിവേദനത്തിൽ: സഅ്ദ്(റ) - നബി(സ)യുടെ വാതിൽക്കൽ സമ്മതം ചോദിച്ചുകൊണ്ട് നിന്നു. അയാൾ വാതിൽക്കലാണ് നിന്നത്. -മറ്റൊരു നിവേദനത്തിൽ: വാതിലിന്റെ മുമ്പിലാണ്- അപ്പോൾ അദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "ഇത് പോലെത്തന്നെ, നോക്കാതിരിക്കാനാണ് സമ്മതം ചോദിക്കൽ വെച്ചത്." (ദ)', 'هُزَيْلِ بْنِ شُرَحْبِيلِ الْأَوْدِيِّ', 'ഹുദൈലുബ്നു ഷുറഹ്ബീലുൽ ഔദി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=63), 1, 'وَفِي رِوَايَةٍ: سَعْدٌ –فَوَقَفَ عَلَى بَابٌ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْذِنُ، فَقَامَ عَلَى الْبَابِ –', 'മറ്റൊരു നിവേദനത്തിൽ: വാതിലിന്റെ മുമ്പിലാണ്- അപ്പോൾ അദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "ഇത് പോലെത്തന്നെ, നോക്കാതിരിക്കാനാണ് സമ്മതം ചോദിക്കൽ വെച്ചത്." (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=63), 2, 'وَفِي رِوَايَةٍ: مُسْتَقْبِلَ الْبَابُ– فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَكَذَا عَنْكَ– أَوْ: هَكَذَا، فَإِنَّمَا الِاسْتِئْذَانُ مِنَ النَّظَرِ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ كَتَبَ عَلَى ابْنِ آدَمَ حَظَّهُ مِنَ الزِّنَا، أَدْرَكَ ذَلِكَ لَا مَحَالَةَ، فَزِنَا الْعَيْنِ النَّظَرُ، وَزِنَا اللِّسَانِ الْمَنْطِقُ، وَالنَّفْسُ تَمَنَّى وَتَشْتَهِي، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ، أَوْ يُكَذِّبُهُ". (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ആദം സന്തതിക്ക് വ്യഭിചാരത്തിന്റെ ഒരു വിഹിതം നിശ്ചയിച്ച് വെച്ചിരിക്കുന്നു. നിസ്സംശയം അവനത് കിട്ടുകതന്നെ ചെയ്യും. കണ്ണിന്റെ വ്യഭിചാരം ദൃഷ്ടിയാണ്. നാവിന്റെ വ്യഭിചാരം സംസാരമാണ്. മനസ്സ് ആഗ്രഹിക്കുകയും മോഹിക്കുകയും ചെയ്യും. ഗുഹ്യസ്ഥാനമാണ് ഇതിനെ യാഥാർത്ഥ്യമാക്കുകയോ കളവാക്കുകയോ ചെയ്യുന്നത്." (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 416, 416, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا فِي مَجْلِسٍ مِنْ مَجَالِسِ الْأَنْصَارِ، فَجَاءَ أَبُو مُوسَى فَزِعًا، فَقُلْنَا لَهُ: مَا أَفْزَعَكَ؟ قَالَ: أَمَرَنِي عُمَرُ أَنْ آتِيَهُ، فَأَتَيْتُهُ، فَاسْتَأْذَنْتُ ثَلَاثًا فَلَمْ يُؤْذَنْ لِي، فَرَجَعْتُ، فَقَالَ: مَا مَنَعَكَ أَنْ تَأْتِيَنِي؟ قُلْتُ: قَدْ جِئْتُ فَاسْتَأْذَنْتُ ثَلَاثًا فَلَمْ يُؤْذَنْ لِي، وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَأْذَنَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ". قَالَ: لَتَأْتِيَنَّ عَلَى هَذَا بِالْبَيِّنَةِ. فَقَالَ أَبُو سَعِيدٍ: لَا يَقُومُ مَعَكَ إِلَّا أَصْغَرُ الْقَوْمِ، قَالَ: فَقَامَ أَبُو سَعِيدٍ مَعَهُ فَشَهِدَ لَهُ. (ق,د)', 'അബൂ സഈദുൽ ഖുദ്രി(റ): ഞാൻ അൻസാറുകളുടെ ഒരു വേദിയിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അബൂമൂസ(റ) പേടിച്ച് വന്നു. ഞങ്ങൾ ചോദിച്ചു: എന്താണ് നീ പേടിക്കാൻ കാരണം? അദ്ദേഹം പറഞ്ഞു: ഉമർ(റ) എന്നോട് ചെല്ലാൻ പറഞ്ഞു: ഞാൻ അദ്ദേഹത്തിന്റെയടുത്ത് ചെന്ന് മൂന്ന് പ്രാവശ്യം സമ്മതം തേടി. എനിക്ക് സമ്മതം ലഭിച്ചില്ല. അങ്ങനെ ഞാൻ മടങ്ങിപ്പോന്നു. പിന്നെ ഉമർ(റ) ചോദിച്ചു: എന്റെയടുത്ത് നീ വരാതിരിക്കാൻ കാരണമെന്താണ്? ഞാൻ പറഞ്ഞു: ഞാൻ വന്ന് മൂന്ന് പ്രാവശ്യം സമ്മതം ചോദിച്ചു. എനിക്ക് സമ്മതം കിട്ടിയില്ല. റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നിങ്ങളിലൊരാൾ മൂന്ന് പ്രാവശ്യം സമ്മതം ചോദിച്ചിട്ട് സമ്മതം കിട്ടിയില്ലെങ്കിൽ അവൻ തിരിച്ച് പോയിക്കൊള്ളട്ടെ." ഉമർ(റ) പറഞ്ഞു: നീ ഇതിന് തെളിവ് കൊണ്ടുവരണം. അബൂ സഈദ്(റ) പറഞ്ഞു: നിന്റെ കുടെ ഏറ്റവും ചെറിയ ആളേ വരികയുള്ളു. അങ്ങനെ അബൂ സഈദ്(റ) പോയി അദ്ദേഹത്തിന് സാക്ഷി നിന്നു. (ബു,മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂ സഈദുൽ ഖുദ്രി(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 416, 416, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا مُوسَى اسْتَأْذَنَ عَلَى عُمَرَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ، فَانْصَرَفَ، فَأَرْسَلَ إِلَيْهِ عُمَرُ: مَا رَدَّكَ؟ قَالَ: اسْتَأْذَنْتُ الِاسْتِئْذَانَ الَّذِي أَمَرَنَا بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثًا، فَإِنْ أُذِنَ لَنَا دَخَلْنَا، وَإِنْ لَمْ يُؤْذَنْ لَنَا رَجَعْنَا. قَالَ: فَقَالَ: لَتَأْتِيَنِّي عَلَى هَذَا بِبَيِّنَةٍ، أَوْ لَأَفْعَلَنَّ. فَأَتَى مَجْلِسَ قَوْمِهِ فَنَاشَدَهُمْ، فَشَهِدُوا لَهُ، فَخَلَّى سَبِيلَهُ. (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): അബൂമൂസാ(റ) ഉമർ(റ)വിനോട് മൂന്ന് പ്രാവശ്യം സമ്മതം തേടി. അദ്ദേഹത്തിന് സമ്മതം കിട്ടിയില്ല. അദ്ദേഹം തിരിച്ച് പോയി. അബൂമൂസ(റ)വിന്റെ അടുക്കലേക്ക് ഉമർ(റ) ആളെ അയച്ചു ഇപ്രകാരം ചോദിച്ചു: നീ എന്തിനാണ് മടങ്ങിയത്? അപ്പോൾ അബൂമൂസ(റ) പറഞ്ഞു: റസൂൽ(സ) ഞങ്ങളോട് കൽപ്പിച്ച പ്രകാരമുള്ള മുന്ന് പ്രാവശ്യം, ഞാൻ സമ്മതം ചോദിച്ചു. ഞങ്ങൾക്ക് സമ്മതം നൽകപ്പെട്ടാൽ ഞങ്ങൾ പ്രവേശിക്കും. സമ്മതം നൽകപ്പെട്ടിട്ടില്ലെങ്കിൽ ഞങ്ങൾ പ്രവേശിക്കില്ല. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നീ അതിന് എനിക്ക് തെളിവ് കൊണ്ടുവന്ന് തരണം. അല്ലെങ്കിൽ നിനക്ക് ഞാൻ കാണിച്ച് തരാം. അങ്ങനെ അബൂ മൂസ(റ) തന്റെ സമൂഹത്തിന്റെയടുത്ത് ചെന്ന് സത്യം ചെയ്ത് കാര്യം പറഞ്ഞു. അങ്ങനെ അവർ അദ്ദേഹത്തിന് സാക്ഷി നിന്നു. അപ്പോൾ ഉമർ(റ) അദ്ദേഹത്തെ വിട്ടയച്ചു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 416, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى عُمَرَ فَاسْتَأْذَنَ ثَلَاثًا، فَقَالَ: يَسْتَأْذِنُ أَبُو مُوسَى، يَسْتَأْذِنُ الْأَشْعَرِيُّ، يَسْتَأْذِنُ عَبْدُ اللَّهِ بْنُ قَيْسٍ، فَلَمْ يُؤْذَنْ لَهُ، فَرَجَعَ، فَبَعَثَ إِلَيْهِ عُمَرُ: مَا رَدَّكَ؟ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَسْتَأْذِنُ أَحَدُكُمْ ثَلَاثًا، فَإِنْ أُذِنَ لَهُ، وَإِلَّا فَلْيَرْجِعْ". قَالَ: ائْتِنِي بِبَيِّنَةٍ عَلَى هَذَا. فَذَهَبَ ثُمَّ رَجَعَ، فَقَالَ: هَذَا أُبَيٌّ، فَقَالَ أُبَيٌّ: يَا عُمَرُ، لَا تَكُنْ عَذَابًا عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ عُمَرُ: لَا أَكُونُ عَذَابًا عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=67), 1, 'وَفِي رِوَايَةٍ: أَنَّ أَبَا مُوسَى رَضِيَ اللهُ عَنْهُ اسْتَأْذَنَ عَلَى عُمَرَ، بِهَذِهِ الْقِصَّةِ، قَالَ فِيهِ: فَانْطَلَقَ بِأَبِي سَعِيدٍ، فَشَهِدَ لَهُ، فَقَالَ: أَخَفِيَ عَلَيَّ هَذَا مِنْ أَمْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ أَلْهَانى السَّفْقُ بالْأَسْوَاق، وَلَكِنْ سَلِّمْ مَا شِئْتَ وَلَا تَسْتَأْذِنْ. (ق)', 'മറ്റൊരു നിവേദനം: അബൂമൂസ(റ) ഉമർ(റ)വിനോട് സമ്മതം ചോദിച്ചു. (ഈ സംഭവത്തിൽ) അദ്ദേഹം അബൂ സഈദ്(റ)വുമായി ചെന്നു. അബൂ സഈദ്(റ) അദ്ദേഹത്തിന് സാക്ഷി നിന്നു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു. റസൂൽ(സ)യുടെ കൽപ്പനകളിൽ ഇതെനിക്ക് അവ്യക്തമായോ? അങ്ങാടികളിലെ കച്ചവടം എന്നെ അശ്രദ്ധമാക്കി. എങ്കിലും നീ ഉദ്ദേശിച്ചത്ര സലാം ചൊല്ലുക. നീ സമ്മതം ചോദിക്കേണ്ടതില്ല. (ബു,മു)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=67), 2, 'وَفِي رِوَايَةٍ: فَقَالَ عُمَرُ لِأَبِي مُوسَى رَضِيَ اللهُ عَنْهُمَا: إِنِّي لَمْ أَتَّهِمْكَ، وَلَكِنَّ الْحَدِيثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَدِيدٌ.', 'മറ്റൊരു നിവേദനം: അപ്പോൾ ഉമർ(റ) അബൂമൂസ(റ)വിനോട് പറഞ്ഞു: നിന്നെ ഞാൻ തെറ്റിദ്ധരിച്ചതല്ല. റസൂൽ(സ)യിൽ നിന്നുള്ള ഹദീസ് ഗൗരവമുള്ള വിഷയമാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=67), 3, 'وَفِي رِوَايَةٍ: أَمَا إِنِّي لَمْ أَتَّهِمْكَ، وَلَكِنْ خَشِيتُ أَنْ يَتَقَوَّلَ النَّاسُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ. (د)', 'മറ്റൊരു നിവേദനം: ഞാൻ നിന്നെ തെറ്റിദ്ധരിച്ചതല്ല. എങ്കിലും, ജനങ്ങൾ റസൂൽ(സ)യുടെ മേൽ ജൽപനങ്ങൾ നടത്തുന്നത് ഞാൻ ഭയപ്പെട്ടു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَأْذَنَ أَبُو مُوسَى عَلَى عُمَرَ –رَضِيَ اللهُ عَنْهُمَا– فَقَالَ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ؟ قَالَ عُمَرُ: وَاحِدَةٌ. ثُمَّ سَكَتَ سَاعَةً، ثُمَّ قَالَ: السَّلَامُ عَلَيْكُمْ أَأَدْخُلُ؟ قَالَ عُمَرُ: ثِنْتَانِ. ثُمَّ سَكَتَ سَاعَةً، فَقَالَ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ؟ فَقَالَ عُمَرُ: ثَلَاثٌ. ثُمَّ رَجَعَ، فَقَالَ عُمَرُ لِلْبَوَّابِ: مَا صَنَعَ؟ قَالَ: رَجَعَ. قَالَ: عَلَيَّ بِهِ. فَلَمَّا جَاءَهُ قَالَ: مَا هَذَا الَّذِي صَنَعْتَ؟ قَالَ: السُّنَّةُ قَالَ: آلسُّنَّةُ؟ وَاللَّهِ لَتَأْتِيَنِّي عَلَى هَذَا بِبُرْهَانٍ –أَوْ بِبَيِّنَةٍ– أَوْ لَأَفْعَلَنَّ بِكَ. قَالَ: فَأَتَانَا وَنَحْنُ رُفْقَةٌ مِنَ الْأَنْصَارِ، فَقَالَ: يَا مَعْشَرَ الْأَنْصَارِ، أَلَسْتُمْ أَعْلَمَ النَّاسِ بِحَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الِاسْتِئْذَانُ ثَلَاثٌ، فَإِنْ أُذِنَ لَكَ وَإِلَّا فَارْجِعْ". فَجَعَلَ الْقَوْمُ يُمَازِحُونَهُ. قَالَ أَبُو سَعِيدٍ: ثُمَّ رَفَعْتُ رَأْسِي إِلَيْهِ فَقُلْتُ: فَمَا أَصَابَكَ فِي هَذَا مِنَ الْعُقُوبَةِ فَأَنَا شَرِيكُكَ. قَالَ: فَأَتَى عُمَرَ فَأَخْبَرَهُ بِذَلِكَ، فَقَالَ عُمَرُ: مَا كُنْتُ عَلِمْتُ بِهَذَا. حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബൂസഈദ്(റ): അബൂമൂസാ(റ) ഉമർ(റ)വിനോട് പ്രവേശനാനുമതി തേടി. അബൂമൂസ(റ) ചോദിച്ചു: അസ്സലാമു അലൈകും, ഞാൻ പ്രവേശിക്കട്ടെ? ഉമർ(റ) പറഞ്ഞു: ഒന്ന്. പിന്നെ അദ്ദേഹം അൽപനേരം മിണ്ടാതിരുന്നു. അബൂമൂസാ(റ) വീണ്ടും ചോദിച്ചു. അസ്സലാമു അലൈക്കും, ഞാൻ പ്രവേശിക്കട്ടെ? ഉമർ(റ) പറഞ്ഞു: രണ്ട്. പിന്നെ അദ്ദേഹം അൽപനേരം മിണ്ടാതിരുന്നു. അബൂമൂസ(റ) വീണ്ടും ചോദിച്ചു: അസ്സലാമു അലൈക്കും, ഞാൻ പ്രവേശിക്കട്ടെയോ? അപ്പോൾ ഉമർ(റ) മൂന്നെന്ന് പറഞ്ഞു: പിന്നെ അബൂ മൂസ(റ) മടങ്ങിപ്പോയി. കാവൽക്കാരനോട് ഉമർ(റ) ചോദിച്ചു: അദ്ദേഹം എന്ത് ചെയ്തു. കാവൽക്കാരൻ പറഞ്ഞു: അയാൾ മടങ്ങിപ്പോയി. ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹത്തെ എന്റെ അടുത്തെത്തിക്കുക, അങ്ങനെ അബൂമൂസ(റ) ഉമർ(റ)വിന്റെ അടുത്തെത്തിയപ്പോൾ ഉമർ(റ) ചോദിച്ചു: നീ എന്താണ് ചെയ്തത്? അബൂമൂസ(റ) പറഞ്ഞു: അത് നബിചര്യയാണ്. ഉമർ(റ) ചോദിച്ചു: അത് നബിചര്യയാണോ? താങ്കൾ ഇതിനെനിക്ക് തെളിവ് നൽകണം, അല്ലെങ്കിൽ നിന്നെ ഞാൻ പാഠം പഠിപ്പിക്കും. അപ്പോൾ അദ്ദേഹം ഞങ്ങൾ അൻസാരി സുഹൃത്തുക്കളുടെയടുത്ത് വന്നു. അദ്ദേഹം ചോദിച്ചു: ഓ, അൻസാരീ സമൂഹമേ, ഏറ്റവും കൂടുതൽ ഹദീസ് അറിയുന്നവർ നിങ്ങളല്ലേ? റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ. "സമ്മതം തേടൽ മൂന്ന് പ്രാവശ്യമാണ്. നിനക്ക് സമ്മതം നൽകപ്പെട്ടാൽ, പ്രവേശിക്കുക, അല്ലങ്കിൽ തിരിച്ച് പോകുക." ആളുകൾ അദ്ദേഹത്തെ പരിഹസിക്കാൻ തുടങ്ങി. അബൂസഈദ്(റ) പറയുന്നു: ഞാൻ അദ്ദേഹത്തിന്റെയടുത്ത് ചെന്ന് പറഞ്ഞു: നിങ്ങൾക്ക് പറ്റിയ ഈ പരീക്ഷണത്തിൽ ഞാനും പങ്കാളിയാകും. അങ്ങനെ അദ്ദേഹം ഉമർ(റ)വിന്റെ അടുത്ത് ചെന്ന് ഈ വിവരം പറഞ്ഞു: അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഇത് ഞാൻ അറിഞ്ഞിരുന്നില്ല. (ബു,മു,ദ,തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 417, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: حَدَّثَنِي عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَأْذَنْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثًا، فَأَذِنَ لِي. حَسَنٌ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): എന്നോട് ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോട് മൂന്ന് പ്രാവശ്യം സമ്മതം ചോദിച്ചു. അവിടന്നെനിക്ക് സമ്മതം നൽകി. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ كَلَدَةَ بْنِ حَنْبَلٍ: أَنَّ صَفْوَانَ بْنَ أُمَيَّةَ –رَضِيَ اللهُ عَنْهُ– بَعَثَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَبَنٍ وَجِدَايَةٍ وَضَغَابِيسَ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَعْلَى مَكَّةَ، فَدَخَلْتُ وَلَمْ أُسَلِّمْ، فَقَالَ: "ارْجِعْ فَقُلِ: السَّلَامُ عَلَيْكُمْ". وَذَلِكَ بَعْدَمَا أَسْلَمَ صَفْوَانُ بْنُ أُمَيَّةَ. (د,ت)', 'കൽദതുബ്നു ഹൻബൽ(റ): സ്വഫ്വാനുബ്നു ഉമയ്യ(റ) അദ്ദേഹത്തെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് പാൽ, ആട്, കക്കരിക്ക എന്നിവയുമായി പറഞ്ഞയച്ചു. നബി(സ) മക്കയിലെ ഉയർന്ന ഭാഗത്തായിരുന്നു. ഞാൻ സലാം ചൊല്ലാതെ പ്രവേശിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ മടങ്ങിപ്പോയിട്ട് സലാം പറയുക." ഇത് സ്വഫ്വാനുബ്നു ഉമയ്യ(റ) മുസ്ലിമായതിന് ശേഷമാണ്. (ദ,തു)', 'كَلَدَةَ بْنِ حَنْبَلٍ', 'കൽദതുബ്നു ഹൻബൽ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 418, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ كَلَدَةَ بْنِ حَنْبَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ صَفْوَانَ بْنَ أُمَيَّةَ بَعَثَهُ بِلَبَنٍ وَلِبًا وَضَغَابِيسَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بأَعْلَى الْوَادِي، قَالَ: فَدَخَلْتُ عَلَيْهِ وَلَمْ أُسَلِّمْ وَلَمْ أَسْتَأْذِنْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ارْجِعْ فَقُلِ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ". حَسَنٌ. (د,ت)', 'കൽദതുബ്നു ഹൻബൽ(റ): സ്വഫ്വാനുബ്നു ഉമയ്യ(റ) അദ്ദേഹത്തെ പാൽ, ആട്, കക്കരിക്ക എന്നിവയുമായി നബി(സ)യുടെ അടുക്കലേക്കയച്ചു. ആ സമയത്ത് നബി(സ) ഉയർന്ന ഒരു മലഞ്ചെരുവിലായിരുന്നു. ഞാൻ സലാം പറയാതെ, സമ്മതം ചോദിക്കാതെ തിരുസന്നിധിയിൽ പ്രവേശിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ തിരിച്ചുപോയി സലാം പറയുകയും പ്രവേശിക്കട്ടെയോ എന്ന് പറയുകയും ചെയ്യുക." (ദ,തു)', 'كَلَدَةَ بْنِ حَنْبَلٍ', 'കൽദതുബ്നു ഹൻബൽ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 419, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ، قَالَ: جَاءَ أَبُو مُوسَى رَضِيَ اللهُ عَنْهُ إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: السَّلَامُ عَلَيْكُمْ، هَذَا عَبْدُ اللَّهِ بْنُ قَيْسٍ. فَلَمْ يَأْذَنْ لَهُ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، هَذَا أَبُو مُوسَى، السَّلَامُ عَلَيْكُمْ، هَذَا الْأَشْعَرِيُّ. ثُمَّ انْصَرَفَ، فَقَالَ: رُدُّوا عَلَيَّ، رُدُّوا عَلَيَّ. فَجَاءَ، فَقَالَ: يَا أَبَا مُوسَى مَا رَدَّكَ، كُنَّا فِي شُغْلٍ؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الِاسْتِئْذَانُ ثَلَاثٌ، فَإِنْ أُذِنَ لَكَ وَإِلَّا فَارْجِعْ". قَالَ: لَتَأْتِيَنِّي عَلَى هَذَا بِبَيِّنَةٍ، وَإِلَّا فَعَلْتُ وَفَعَلْتُ. فَذَهَبَ أَبُو مُوسَى، قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: إِنْ وَجَدَ بَيِّنَةً تَجدُوهُ عِنْدَ الْمِنْبَرِ عَشِيَّةً، وَإِنْ لَمْ يَجدْ بَيِّنَةً فَلَمْ تَجدُوهُ. فَلَمَّا أَنْ جَاءَ بالْعَشِيِّ وَجَدُوهُ، قَالَ: يَا أَبَا مُوسَى مَا تَقُولُ، أَقَدْ وَجَدْتَ؟ قَالَ: نَعَمْ، أُبَيَّ بْنَ كَعْبٍ، قَالَ: عَدْلٌ، قَالَ: يَا أَبَا الطُّفَيْلِ مَا يَقُولُ هَذَا؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ ذَلِكَ، يَا ابْنَ الْخَطَّابِ، فَلَا تَكُونَنَّ عَذَابًا عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: سُبْحَانَ اللَّهِ، إِنَّمَا سَمِعْتُ شَيْئًا فَأَحْبَبْتُ أَنْ أَتَثَبَّتَ. (م)', 'അബൂമൂസ(റ)വിൽ നിന്ന് അബൂബുർദ(റ): അബൂമൂസ(റ) ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെ അടുത്ത് ചെന്നിട്ട് പറഞ്ഞു. അസ്സലാമു അലൈക്കും, ഇത് അബ്ദുല്ലാഹിബ്നു ഖൈസാണ്. അദ്ദേഹത്തിന് സമ്മതം കിട്ടിയില്ല. അദ്ദേഹം പറഞ്ഞു: അസ്സലാമു അലൈക്കും. ഇത് അബൂ മൂസയാണ്. അസ്സലാമു അലൈക്കും. ഇത് അശ്അരിയാണ്. പിന്നെ അദ്ദേഹം തിരിച്ച് പോയി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹത്തെ എന്റെയടുത്തേക്ക് കൊണ്ട് വരിക. അദ്ദേഹത്തെ എന്റെയടുത്തേക്ക് കൊണ്ടുവരിക. അങ്ങനെ അബുമൂസ(റ) വന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അബു മൂസ, താങ്കൾ എന്ത് കൊണ്ടാണ് തിരിച്ച് പോയത്? ഞങ്ങൾ ഒരു പണിയിലായിരുന്നു. അബുമൂസ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് കേട്ടു: "സമ്മതം ചോദിക്കൽ മൂന്ന് പ്രാവശ്യമാണ്. താങ്കൾക്ക് സമ്മതം നൽകപ്പെട്ടാൽ പ്രവേശിക്കുക, അതല്ലെങ്കിൽ നീ മടങ്ങുക." ഉമർ(റ) പറഞ്ഞു: ഇതിന് നീയെനിക്ക് തെളിവ് കൊണ്ടുവന്ന് തരണം. അല്ലെങ്കിൽ ഞാൻ വേണ്ടത് ചെയ്യും. ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹം തെളിവ് കണ്ടെത്തിയാൽ വൈകുന്നേരം നിങ്ങൾക്ക് അദ്ദേഹത്തെ മിമ്പറിന്റെയടുത്ത് കാണാം, തെളിവ് കിട്ടിയിട്ടില്ലെങ്കിൽ നിങ്ങൾക്കദ്ദേഹത്തെ അവിടെ കാണാനാകില്ല. അബുമൂസ(റ) വൈകുന്നേരം വന്നപ്പോൾ ജനങ്ങൾ അദ്ദേഹത്തെ കണ്ടു. ഉമർ(റ) ചോദിച്ചു: നിനക്ക് തെളിവ് കിട്ടിയോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനെ കിട്ടിയിരിക്കുന്നു. ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹം നീതിമാനാണ്. ശേഷം ഉമർ(റ) ചോദിച്ചു: ഓ അബുഥുഫൈൽ, ഇദ്ദേഹമെന്താണ് പറയുന്നത്? അബു ഉബയ്യ്(റ) പറഞ്ഞു: ഇത് റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. ഓ, ഖത്താബിന്റെ പുത്രാ, നിങ്ങൾ റസൂൽ(സ)യുടെ അനുചരർക്ക് ഒരു ശിക്ഷയാകരുത്. ഉമർ(റ) പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്, ഞാൻ ഒരുകാര്യം കേൾക്കുകയും അത് സ്ഥിരീകരിക്കാൻ ആഗ്രഹിക്കുകയും മാത്രമാണ് ചെയ്തത്. (മു)', 'أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 419, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ رِبعِي بنِ حِرَاشٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَجُلٌ مَنْ بَنِي عَامِرٍ: أَنَّهُ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي بَيْتٍ، فَقَالَ: أَلِجُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَادِمِهِ: "اخْرُجْ إِلَى هَذَا فَعَلِّمْهُ الِاسْتِئْذَانَ، فَقُلْ لَهُ: قُلِ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ". فَسَمِعَهُ الرَّجُلُ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ؟ فَأَذِنَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَخَلَ. وفي رواية: قَالَ: حُدِّثْتُ أَنَّ رَجُلًا مَنْ بَنِي عَامِرٍ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ. وفي رواية: عَنْ رِبْعِيٍّ رَضِيَ اللهُ عَنْهُ، عَنْ رَجُلٍ مَنْ بَنِي عَامِرٍ: أَنَّهُ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَعْنَاهُ، قَالَ: فَسَمِعْتُهُ فَقُلْتُ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ؟ (د)', 'രിബ്ഇയ്യിബ്നു ഹിറാഷ്(റ): ബനൂ ആമിറിൽ പെട്ട ഒരാൾ ഞങ്ങളോട് ഹദീസ് പറഞ്ഞു: നബി(സ) ഒരു വീട്ടിലായിരിക്കെ അദ്ദേഹം നബി(സ)യോട് പ്രവേശനാനുമതി തേടി. അദ്ദേഹം പറഞ്ഞു: ഞാൻ പ്രവേശിക്കട്ടെയോ? അപ്പോൾ നബി(സ) അവിടത്തെ സേവകനോട് പറഞ്ഞു: "നീ അയാളുടെ അടുത്ത് ചെന്ന് അയാൾക്ക് പ്രവേശനാനുമതി തേടുന്ന വിധം പഠിപ്പിക്കുക. നീയദ്ദേഹത്തോട് അസ്സലാമു അലൈക്കും, ഞാൻ പ്രവേശിക്കട്ടെയോ, എന്ന് പറയാൻ പറയുക." അപ്പോൾ അദ്ദേഹമത് കേട്ടു. അദ്ദേഹം അസ്സലാമു അലൈക്കും, ഞാൻ പ്രവേശിക്കട്ടെയോ? എന്ന് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹത്തിന് റസൂൽ(സ) പ്രവേശനാനുമതി നൽകി. അങ്ങനെ അദ്ദേഹം പ്രവേശിച്ചു. മറ്റൊരു നിവേദനം: ബനൂ ആമിറിൽ പെട്ട ഒരാൾ നബി(സ)യോട് സമ്മതം ചോദിച്ചെന്ന് എന്നോട് ഹദീസ് പറയപ്പെട്ടു. (മുമ്പ് പറഞ്ഞ ഹദീസിന്റെ അർത്ഥത്തിൽ)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=73), 1, 'وَفِي رِوَايَةٍ: قَالَ: حُدِّثْتُ أَنَّ رَجُلًا مَنْ بَنِي عَامِرٍ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ.', 'മറ്റൊരു നിവേദനം: ബനൂ ആമിറിൽ പെട്ട ഒരാൾ നബി(സ)യോട് സമ്മതം ചോദിച്ചെന്ന് എന്നോട് ഹദീസ് പറയപ്പെട്ടു. (മുമ്പ് പറഞ്ഞ ഹദീസിന്റെ അർത്ഥത്തിൽ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=73), 2, 'وَفِي رِوَايَةٍ: عَنْ رِبْعِيٍّ رَضِيَ اللهُ عَنْهُ، عَنْ رَجُلٍ مَنْ بَنِي عَامِرٍ: أَنَّهُ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَعْنَاهُ، قَالَ: فَسَمِعْتُهُ فَقُلْتُ: السَّلَامُ عَلَيْكُمْ، أَأَدْخُلُ؟ (د)', 'മറ്റൊരു നിവേദനം: ബനൂആമിറിൽ പെട്ട ഒരാളിൽ നിന്ന് രിബ്ഇയ്യ്(റ): അദ്ദേഹം നബി(സ)യോട് സമ്മതം ചോദിച്ചു. (മുമ്പ് പറഞ്ഞ ഹദീസിന്റെ അതേ അർത്ഥത്തിൽ). അദ്ദേഹം പറഞ്ഞു. ഞാനത് കേട്ടു. അപ്പോൾ ഞാൻ ചോദിച്ചു. അസ്സലാമു അലൈകും. ഞാൻ പ്രവേശിക്കട്ടെയോ? (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ قَيْسِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: زَارَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَنْزِلِنَا فَقَالَ: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ". فَرَدَّ سَعْدٌ رَدًّا خَفِيًّا، قَالَ قَيْسٌ: فَقُلْتُ: أَلَا تَأْذَنُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: ذَرْهُ يُكْثِرْ عَلَيْنَا مِنَ السَّلَامِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ". فَرَدَّ سَعْدٌ رَدًّا خَفِيًّا، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ". ثُمَّ رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَاتَّبَعَهُ سَعْدٌ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ أَسْمَعُ تَسْلِيمَكَ، وَأَرُدُّ عَلَيْكَ رَدًّا خَفِيًّا لِتُكْثِرَ عَلَيْنَا مِنَ السَّلَامِ، قَالَ: فَانْصَرَفَ مَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ لَهُ سَعْدٌ بِغُسْلٍ، فَاغْتَسَلَ، ثُمَّ نَاوَلَهُ مِلْحَفَةً مَصْبُوغَةً بِزَعْفَرَانٍ، أَوْ وَرْسٍ، فَاشْتَمَلَ بِهَا، ثُمَّ رَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ وَهُوَ يَقُولُ: "اللَّهُمَّ اجْعَلْ صَلَوَاتِكَ وَرَحْمَتَكَ عَلَى آلِ سَعْدِ بْنِ عُبَادَةَ". قَالَ: ثُمَّ أَصَابَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الطَّعَامِ، فَلَمَّا أَرَادَ الِانْصِرَافَ قَرَّبَ لَهُ سَعْدٌ حِمَارًا قَدْ وَطَّأَ عَلَيْهِ بِقَطِيفَةٍ، فَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ سَعْدٌ: يَا قَيْسُ، اصْحَبْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ قَيْسٌ: فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ارْكَبْ". فَأَبَيْتُ، ثُمَّ قَالَ: "إِمَّا أَنْ تَرْكَبَ وَإِمَّا أَنْ تَنْصَرِفَ". قَالَ: فَانْصَرَفْتُ. (د,ن)', 'ഖൈസുബ്നു സഅ്ദ്(റ): റസൂൽ(സ) ഞങ്ങളെ ഞങ്ങളുടെ വീട്ടിൽ വന്ന് സന്ദർശിച്ചു. അവിടന്ന് "അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി" എന്ന് പറഞ്ഞു: സഅ്ദ്(റ) സലാം പതുക്കെ മടക്കി. ഖൈസ്(റ) പറയുന്നു: ഞാൻ ചോദിച്ചു: നിങ്ങൾ റസൂൽ(സ)ക്ക് സമ്മതം നൽകുന്നില്ലേ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) നമ്മുടെ മേൽ കൂടുതൽ സലാം പറയട്ടെ, അപ്പോൾ റസൂൽ(സ) വീണ്ടും പറഞ്ഞു: "അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി" സഅ്ദ്(റ) സലാം പതുക്കെ മടക്കി. റസൂൽ(സ) വീണ്ടും പറഞ്ഞു: "അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി" പിന്നെ നബി(സ) മടങ്ങിപ്പോയി. സഅ്ദ്(റ) നബി(സ)യെ പിന്തുടർന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ അങ്ങയുടെ സലാം കേൾക്കുകയായിരുന്നു. അവിടന്ന് സലാം അധികരിപ്പിക്കാൻ വേണ്ടി ഞാൻ പതുക്കെ മടക്കുകയായിരുന്നു. ഖൈസുബ്നു സഅ്ദ്(റ) പറയുന്നു: അദ്ദേഹത്തോടൊപ്പം റസൂൽ(സ)യും തിരിച്ച് ചെന്നു. ഖൈസിനോട് സഅ്ദ്(റ) നബി(സ)ക്ക് കുളിക്കാനുള്ള വെള്ളം കൊടുക്കാൻ കൽപ്പിക്കുകയും റസൂൽ(സ) കുളിക്കുകയും ചെയ്തു. പിന്നെ അദ്ദേഹം നബി(സ)ക്ക് കുങ്കുമം കൊണ്ടോ വർസ് കൊണ്ടോ ചായം കൊടുക്കപ്പെട്ട ഒരു മേൽവസ്ത്രം നൽകി. നബി(സ) അത് പുതച്ചു. പിന്നെ അവിടന്ന് ഇരു കരങ്ങളുമുയർത്തിക്കൊണ്ട് പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, സഅ്ദുബ്നു ഉബാദയുടെ കുടുംബത്തിൽ നിന്റെ നന്മകളും അനുഗ്രഹങ്ങളും ചൊരിയണേ." പിന്നെ നബി(സ) ഭക്ഷണം കഴിച്ചു. നബി(സ) മടങ്ങാൻ ഉദ്ദേശിച്ചപ്പോൾ തൊങ്കലുള്ള പുതപ്പ് വിരിച്ച ഒരു കഴുതയെ നബി(സ)യുടെ അടുക്കലേക്ക് കൊണ്ടു വന്നു. അങ്ങനെ റസൂൽ(സ) അതിന്റെ പുറത്ത് കയറി. അപ്പോൾ സഅ്ദ്(റ) പറഞ്ഞു: ഖൈസേ, താങ്കൾ റസുൽ(സ)യുടെ കൂടെ പോകുക. ഖൈസ്(റ) പറയുന്നു. അപ്പോൾ എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ കയറുക." അപ്പോൾ ഞാൻ കുട്ടാക്കിയില്ല. പിന്നെ നബി(സ) പറഞ്ഞു: "ഒന്നുകിൽ താങ്കൾ കയറുക, അല്ലെങ്കിൽ തിരിച്ച് പോവുക." അങ്ങനെ ഞാൻ തിരിച്ച് പോയി. (ദ,ന)', 'قَيْسِ بْنِ سَعْدٍ', 'ഖൈസുബ്നു സഅ്ദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 420, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَى بَابٌ قَوْمٍ لَمْ يَسْتَقْبِلِ الْبَابٌ مِنْ تِلْقَاءِ وَجْهِهِ، وَلَكِنْ مِنْ رُكْنِهِ الْأَيْمَنِ أَوِ الْأَيْسَرِ، وَيَقُولُ: "السَّلَامُ عَلَيْكُمْ، السَّلَامُ عَلَيْكُمْ". وَذَلِكَ أَنَّ الدُّورَ لَمْ يَكُنْ عَلَيْهَا يَوْمَئِذٍ سُتُورٌ. (د)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): റസൂൽ(സ) ഒരു സമൂഹത്തിന്റെ വാതിൽക്കൽ ചെന്നാൽ, അവിടന്ന് വാതിലിന് നേരെ മുന്നിടുകയില്ല. വലതു ഭാഗത്തുകുടെയോ ഇടതു ഭാഗത്തു കൂടെയോ ആണ് അവിടന്ന് മുന്നിടുക. അവിടന്ന് "അസ്സലാമു അലൈക്കും, അസ്സലാമു അലൈക്കും" എന്ന് പറയും. ഇതിന് കാരണം അക്കാലങ്ങളിൽ വീടിന് മറകളുണ്ടായിരുന്നില്ല. (ദ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ نَافِعِ بْنِ عَبْدِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى دَخَلْتُ حَائِطًا، فَقَالَ لِي: "أَمْسِكِ الْبَابٌ". فَضُرِبَ الْبَابُ، فَقُلْتُ: مَنْ هَذَا؟ وَسَاقَ الْحَدِيثَ. (د)', 'നാഫിഉബ്നു അബ്ദിൽ ഹാരിസ്(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെ പുറപ്പെട്ടു. അങ്ങനെ ഞാനൊരു തോട്ടത്തിൽ പ്രവേശിച്ചു. അപ്പോൾ അവിടന്ന് എന്നോട് പറഞ്ഞു: "വാതിൽ പിടിച്ച് വെക്കൂ." അപ്പോൾ വാതിൽ അടക്കപ്പെട്ടു. ഞാൻ ചോദിച്ചു. ഇതാരാണ്? ശേഷം ഹദീസ് പൂർത്തിയാക്കിപ്പറഞ്ഞു. (ദ)', 'نَافِعِ بْنِ عَبْدِ الْحَارِثِ', 'നാഫിഉബ്നു അബ്ദിൽ ഹാരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَسُولُ الرَّجُلِ إِلَى الرَّجُلِ إِذْنُهُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാളുടെ അടുത്തേക്ക് വന്ന വേറൊരാളുടെ ദൂതൻ, അയാളുടെ സമ്മതമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دُعِيَ أَحَدُكُمْ إِلَى طَعَامٍ، فَجَاءَ مَعَ الرَّسُولِ، فَإِنَّ ذَلِكَ لَهُ إِذْنٌ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ ഭക്ഷണത്തിലേക്ക് ക്ഷണിക്കപ്പെടുകയും, അവൻ ദൂതന്റെ കൂടെ വരികയും ചെയ്താൽ, അത് അവന് സമ്മതമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذَهَبَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَيْنِ أَبِيهِ، فَدَقَقْتُ الْبَابٌ، فَقَالَ: "مَنْ هَذَا". قُلْتُ: أَنَا، قَالَ: "أَنَا أَنَا". كَأَنَّهُ كَرِهَهُ. (ق,د,ت,جه)', 'ജാബിർ(റ): ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് തന്റെ പിതാവിന്റെ കടത്തെ സംബന്ധിച്ച വിഷയത്തിൽ ചെന്നു. അപ്പോൾ ഞാൻ വാതിൽക്കൽ മുട്ടി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ഇതാരാണ്." ഞാൻ പറഞ്ഞു: ഞാനാണ്. നബി(സ) പറഞ്ഞു: "ഞാൻ! ഞാൻ!" നബി(സ) അത് വെറുത്തത് പോലെയുണ്ട്. (ബു,മു,ദ,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ يُؤْمَرْ بِهَا أَكْثَرُ النَّاسِ: آيَةَ الْإِذْنِ، وَإِنِّي لَآمُرُ جَارِيَتِي هَذِهِ تَسْتَأْذِنُ عَلَيَّ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): സമ്മതത്തിന്റെ സൂക്തം കൊണ്ട് അധികമാളുകളും കൽപ്പിക്കപ്പെട്ടിട്ടില്ല. ഞാനെന്റെ ഈ അടിമസ്ത്രീയോട്, അവളെന്നോട് സമ്മതം ചോദിക്കാൻ കൽപ്പിക്കുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عِكْرِمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ نَفَرًا مِنْ أَهْلِ الْعِرَاقِ قَالُوا: يَا ابْنَ عَبَّاسٍ، كَيْفَ تَرَى فِي هَذِهِ الْآيَةِ الَّتِي أُمِرْنَا فِيهَا بمَا أُمِرْنَا، وَلَا يَعْمَلُ بِهَا أَحَدٌ؟ قَوْلُ اللَّهِ عَزَّ وَجَلَّ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمِ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلَاثَ مَرَّاتٍ مِنْ قَبْلِ صَلَاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلَاةِ الْعِشَاءِ ثَلَاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ} إِلَى {عَلِيمٌ حَكِيمٌ} قَالَ ابْنُ عَبَّاسٍ: إِنَّ اللَّهَ حَلِيمٌ رَحِيمٌ بالْمُؤْمِنِينَ يُحِبُّ السَّتْرَ، وَكَانَ النَّاسُ لَيْسَ لِبُيُوتِهِمْ سُتُورٌ وَلَا حِجَالٌ، فَرُبَّمَا دَخَلَ الْخَادِمُ أَوِ الْوَلَدُ أَوْ يَتِيمَةُ الرَّجُلِ وَالرَّجُلُ عَلَى أَهْلِهِ، فَأَمَرَهُمُ اللَّهُ بالِاسْتِئْذَانِ فِي تِلْكَ الْعَوْرَاتِ، فَجَاءَهُمُ اللَّهُ بالسُّتُورِ وَالْخَيْرِ، فَلَمْ أَرَ أَحَدًا يَعْمَلُ بذَلِكَ بَعْدُ. (د)', 'ഇക്രിമ(റ): ഇറാഖികളിൽ പെട്ട ഒരു കൂട്ടമാളുകൾ ചോദിച്ചു: ഓ, ഇബ്നുഅബ്ബാസ്, അല്ലാഹു നമ്മോട് കൽപ്പിക്കേണ്ടത് കൽപ്പിക്കുകയും ഒരാളും അത് കൊണ്ട് പ്രവർത്തിക്കുകയും ചെയ്യാത്ത ഈ ആയത്തിനെക്കുറിച്ച് (''ഓ, സത്യവിശ്വാസികളേ, നിങ്ങളുടെ അടിമകളും നിങ്ങളിലെ പ്രായപൂർത്തിയാകാത്തവരും, പ്രഭാത നിസ്കാരത്തിന് മുമ്പും, നിങ്ങൾ വസ്ത്രങ്ങൾ അഴിച്ചു വെക്കുന്ന ഉച്ച സമയത്തും ഇഷാ നമസ്കാരത്തിന്റെ ശേഷവും നിങ്ങളുടെ ഈ മൂന്ന് സമയങ്ങളിൽ മൂന്ന് പ്രാവശ്യം സമ്മതം ചോദിക്കട്ടെ. ആ സമയങ്ങൾക്ക് ശേഷം അവർ നിങ്ങളിൽ ചുറ്റുന്നത് അവർക്കോ നിങ്ങൾക്കോ പ്രശ്നമില്ല.'' എന്നത് മുതൽ ''അല്ലാഹു ജ്ഞാനിയും തന്ത്രജ്ഞനുമാണ്.'' എന്നത് വരെയുള്ള ആയതിനെക്കുറിച്ച്) നിങ്ങളുടെ അഭിപ്രായമെന്താണ്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ലാഹു സഹനതയുള്ളവനും വിശ്വാസികളോട് കരുണയുള്ളവനും മറ ഇഷ്ടപ്പെടുന്നവനുമാണ്. ജനങ്ങളുടെ വീടുകൾക്ക് മറകളോ, വിരികളോ ഉണ്ടായിരുന്നില്ല. സേവകനോ കുട്ടിയോ, അയാളുടെ പ്രായപൂർത്തിയാകാത്ത പെൺകുട്ടിയോ ചിലപ്പോൾ അയാൾ ഭാര്യയുമായി വേഴ്ച നടത്തുന്ന സമയത്ത് പ്രവേശിക്കാറുണ്ടായിരുന്നു. ഈ സമയങ്ങളിൽ അല്ലാഹു അവരോട് സമ്മതം ചോദിക്കാൻ കൽപ്പിച്ചു. ശേഷം അല്ലാഹു അവർക്ക് സമ്പത്തും മറകളും നൽകി., പിന്നീട് ഇത് ചെയ്യുന്ന ആരെയും ഞാൻ കണ്ടിട്ടില്ല. (ദ)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 422, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذْنُكَ عَلَيَّ أَنْ يُرْفَعَ الْحِجَابُ، وَأَنْ تَسْتَمِعَ سِوَادِي، حَتَّى أَنْهَاكَ". (م)', 'ഇബ്നു മസ്ഊദ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "മറയുയർത്തലും നീയെന്റെ ശബ്ദം കേൾക്കലും ഞാൻ നിന്നെ തടയുന്നത് വരെ എന്റെയടുത്ത് പ്രവേശിക്കാൻ നിനക്കുള്ള സമ്മതമാണ്." (മു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بيَدِهِ، لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَفَلَا أَدُلُّكُمْ عَلَى أَمْرٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ നിയന്ത്രണത്തിലാണോ അവൻ തന്നെ സത്യം, മുഅ്മിനാകുന്നത് വരെ, നിങ്ങൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല. പരസ്പരം സ്നേഹിക്കുന്നത് വരെ നിങ്ങൾ മുഅ്മിനുകളാവുകയില്ല. ഞാൻ നിങ്ങൾക്കൊരു കാര്യം അറിയിച്ച് തരട്ടെയോ, അത് ചെയ്താൽ നിങ്ങൾ പരസ്പരം സ്നേഹിക്കും? നിങ്ങൾക്കിടയിൽ സലാം വ്യാപിപ്പിക്കുക." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا نَبِيُّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُفْشِيَ السَّلَامَ. (جه)', 'അബൂ ഉമാമ(റ): ഞങ്ങളുടെ നബി(സ) ഞങ്ങളോട് സലാം വ്യാപിപ്പിക്കാൻ കൽപ്പിച്ചു. (ജ)', 'أَبِي أُمَامَةَ', 'അബൂ ഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اعْبُدُوا الرَّحْمَنَ، وَأَفْشُوا السَّلَامَ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): "റഹ്മാനെ (പരമകാരുണികനെ) നിങ്ങൾ ആരാധിക്കുക, സലാം വ്യാപിപ്പിക്കുക." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 423, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: "تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ". (ق,د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: ഇസ്ലാമിൽ ഏറ്റവും ഉത്തമമായ കാര്യമേതാണ്? റസുൽ(സ) പറഞ്ഞു: "നീ ഭക്ഷണം നൽകുക, നീ അറിയുന്നവനും അറിയാത്തവനും സലാം പറയുക." (ബു,മു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: السَّلَامُ عَلَيْكُمْ. قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَشْرٌ". ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عِشْرُونَ". ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثُونَ". حَسَنٌ صَحِيحٌ (د,ت,ن)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് കൊണ്ട് പറഞ്ഞു: അസ്സലാമു അലൈക്കും. നബി(സ) പറഞ്ഞു: "പത്ത്". വേറൊരാൾ വന്ന് കൊണ്ട് പറഞ്ഞു: അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇരുപത്". പിന്നെ വേറൊരാൾ വന്ന് കൊണ്ട് അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി വബറകാതുഹു എന്ന് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മുപ്പത്." (ദ,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّلَامُ قَبْلَ الْكَلَامِ". وَقَالَ: "لَا تَدْعُوا أَحَدًا إِلَى الطَّعَامِ حَتَّى يُسَلِّمَ". (ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "സലാം സംസാരത്തിന് മുമ്പാണ്." അവിടന്ന് പറഞ്ഞു: "സലാം പറയുന്നത് വരെ, ആരെയും നിങ്ങൾ ഭക്ഷണത്തിലേക്ക് ക്ഷണിക്കരുത്." (തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا بُنَيَّ، إِذَا دَخَلْتَ عَلَى أَهْلِكَ فَسَلِّمْ، يَكُونُ بَرَكَةً عَلَيْكَ وَعَلَى أَهْلِ بَيْتِكَ". حَسَنٌ صَحِيحٌ (ت)', 'അനസുബ്നു മാലിക്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "എന്റെ കുഞ്ഞിമോനേ, നീ നിന്റെ വീട്ടുകാരുടെയടുത്ത് ചെല്ലുമ്പോൾ, സലാം പറയുക, അത് നിനക്കും നിന്റെ വീട്ടുകാർക്കും അനുഗ്രഹമാകും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَرَدَّ عَلَيْهِ السَّلَامَ، ثُمَّ جَلَسَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَشْرٌ". ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، فَرَدَّ عَلَيْهِ، فَجَلَسَ، فَقَالَ: "عِشْرُونَ". ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، فَرَدَّ عَلَيْهِ، فَجَلَسَ، فَقَالَ: "ثَلَاثُونَ". وفي رواية: عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ، زَادَ: ثُمَّ أَتَى آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ وَمَغْفِرَتُهُ، فَقَالَ: "أَرْبَعُونَ". قَالَ: "هَكَذَا تَكُونُ الْفَضَائِلُ". (د,ت)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): നബി(സ)യുടെ അടുത്ത് ഒരാൾ വന്ന് ''അസ്സലാമു അലൈക്കും'' എന്നു പറഞ്ഞപ്പോൾ നബി(സ) അവനോട് സലാം മടക്കി. ആഗതൻ ഇരുന്നു. അപ്പോൾ നബി(സ) "പത്ത്" എന്ന് പറഞ്ഞു. പിന്നെ മറ്റൊരാൾ വന്നു പറഞ്ഞു: ''അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി''. അവനോട് സലാം മടക്കി. ശേഷം ആഗതൻ ഇരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇരുപത്." പിന്നെ മറ്റൊരാൾ വന്നു പറഞ്ഞു: ''അസ്സലാമു അലൈക്കും വറഹ്മതുല്ലാഹി വബറകാതുഹു''. അവനോട് സലാം മടക്കി. പിന്നെ ആഗതൻ ഇരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മുപ്പത്".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ: عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ، زَادَ: ثُمَّ أَتَى آخَرُ فَقَالَ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ وَمَغْفِرَتُهُ، فَقَالَ: "أَرْبَعُونَ". قَالَ: "هَكَذَا تَكُونُ الْفَضَائِلُ". (د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: അനസ്(റ) നബി(സ)യെത്തൊട്ട് ഇതേ ആശയത്തിൽ നിവേദനം ചെയ്യുന്നു. അതിൽ ഇത് കൂടി അധികരിപ്പിച്ചു: ശേഷം ഒരാൾ വന്നുപറഞ്ഞു: അസ്സലാമു അലൈകും വറഹ്മതുല്ലാഹി വബറകാതുഹു വമഗ്ഫിറതുഹു'' അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നാൽപ്പത്" പിന്നെ പറഞ്ഞു: "ഇങ്ങനെയാണ് ശ്രേഷ്ഠതകൾ ഉണ്ടാകുന്നത്." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْتُ أَنَا وَصَاحِبَانِ لِي، قَدْ ذَهَبَتْ أَسْمَاعُنَا وَأَبْصَارُنَا مِنَ الْجَهْدِ، فَجَعَلْنَا نَعْرِضُ أَنْفُسَنَا عَلَى أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَيْسَ أَحَدٌ يَقْبَلُنَا، فَأَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَى بِنَا أَهْلَهُ، فَإِذَا ثَلَاثَةُ أَعْنُزٍ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "احْتَلِبُوا هَذَا اللَّبَنَ بَيْنَنَا". فَكُنَّا نَحْتَلِبُهُ فَيَشْرَبُ كُلُّ إِنْسَانٍ نَصِيبَهُ، وَنَرْفَعُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَصِيبَهُ، فَيَجِيءُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ، فَيُسَلِّمُ تَسْلِيمًا لَا يُوقِظُ النَّائِمَ وَيُسْمِعُ الْيَقْظَانَ، ثُمَّ يَأْتِي الْمَسْجِدَ فَيُصَلِّي، ثُمَّ يَأْتِي شَرَابَهُ فَيَشْرَبُهُ. حَسَنٌ صَحِيحٌ. (م,ت)', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ): ഞാനും തന്റെ രണ്ട് സുഹൃത്തുക്കളും പുറപ്പെട്ടു. ശക്തമായ ക്ഷീണം കാരണം ഞങ്ങളുടെ കേൾവിയും കാഴ്ചയും നഷ്ടപ്പെട്ട പോലെയുണ്ടായിരുന്നു. അങ്ങനെ ഞങ്ങൾ നബി(സ)യുടെ അനുചരന്മാരുടെയടുത്ത് ചെന്നു നിന്നു. ആരും ഞങ്ങളെ സ്വീകരിക്കുന്നില്ല. അപ്പോൾ ഞങ്ങൾ നബി(സ) യുടെയടുത്ത് ചെന്നു. ഞങ്ങളെ അവിടത്തെ കുടുംബത്തിൽ കൊണ്ടുപോയി, അപ്പോൾ അവിടെ മൂന്നാടുകളുണ്ടായിരുന്നു. അങ്ങനെ നബി(സ) പറഞ്ഞു: "നമുക്കിടയിൽ ഇവയുടെ പാൽ കറന്നെടുക്കുക." ഞങ്ങൾ പാൽ കറന്നെടുത്ത് എല്ലാവരും അവരുടെ ഓഹരി കുടിച്ചു. റസൂൽ(സ)ക്ക് അവിടത്തെ വിഹിതം വെച്ചുകൊടുത്തു. അങ്ങനെ റസൂൽ(സ) രാത്രി വരികയും സലാം ചൊല്ലുകയും ചെയ്യാറുണ്ടായിരുന്നു. അത് ഉറങ്ങുന്നവനെ ഉണർത്തുകയില്ല, ഉറങ്ങാത്തവനെ കേൾപ്പിക്കുകയും ചെയ്യുമായിരുന്നു, പിന്നെ പള്ളിയിൽ പോയി നിസ്കരിച്ച് വന്ന് അവിടന്ന് പാലെടുത്ത് കുടിക്കും. (മു,തു)', 'الْمِقْدَادِ بْنِ الْأَسْوَدِ', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 425, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، الرَّجُلَانِ يَلْتَقِيَانِ، أَيُّهُمَا يَبْدَأُ بالسَّلَامِ؟ فَقَالَ: "أَوْلَاهُمَا باللَّهِ". حَسَنٌ. (د,ت)', 'അബൂഉമാമ(റ): റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: തിരുദൂതരേ, രണ്ടാളുകൾ കണ്ടുമുട്ടിയാൽ ആരാണ് ആദ്യം സലാം പറയേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "അവരിൽ നിന്ന് അല്ലാഹുവിനോട് ഏറ്റവും അടുത്തവൻ" (ദ,തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَوْلَى النَّاسِ باللَّهِ مَنْ بَدَأَهُمْ بالسَّلَامِ". (د)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിൽ നിന്ന് അല്ലാഹുവിനോട് ഏറ്റവും അടുത്തവൻ അവരിൽ സലാം കൊണ്ടു തുടങ്ങുന്നവനാകുന്നു." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَجُلٌ الْمَسْجِدَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ فِي نَاحِيَةِ الْمَسْجِدِ، فَصَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَعَلَيْكَ، ارْجِعْ فَصَلِّ..." فَذَكَرَ الْحَدِيثَ بِطُولِهِ (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പള്ളിയുടെ ഒരു മൂലയിൽ ഇരിക്കുകയാരുന്നപ്പോൾ ഒരാൾ പള്ളിയിൽ പ്രവേശിച്ചു. അദ്ദേഹം നിസ്കരിച്ചു. പിന്നെ തിരുമേനി(സ)യുടെ അടുത്ത് വന്നു. സലാം പറഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "വഅലൈക(താങ്കളുടെ മേലിലുമുണ്ടായിരിക്കട്ടെ), നീ പോയി നിസ്കരിക്കുക." ശേഷം ഹദീസ് മുഴുവനായി പറഞ്ഞു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا دَخَلَ الْمَسْجِدَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ فِي نَاحِيَةِ الْمَسْجِدِ، فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ، فَقَالَ: "وَعَلَيْكَ السَّلَامُ". (جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ പള്ളിയിൽ വന്നു. അന്നേരം റസൂൽ(സ) ഒരു മൂലയിൽ ഇരിക്കുകയായിരുന്നു. അങ്ങനെ അയാൾ നിസ്കരിച്ച് വന്നു സലാം പറഞ്ഞു. റസൂൽ പറഞ്ഞു: "വഅലൈകുമുസ്സലാം. (താങ്കളുടെ മേലിലും സലാമുണ്ടായിരിക്കട്ടെ.)" (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "إِنَّ جِبْرِيلَ يَقْرَأُ عَلَيْكِ السَّلَامَ". قَالَتْ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ. (ق,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) അവരോട് പറഞ്ഞു: "ജിബ്രീൽ(അ) നിന്നോട് സലാം പറയുന്നു." അവർ പറഞ്ഞു: വഅലൈഹിസ്സലാം വറഹ്മതുല്ലാഹി(ജിബ്രീലിന്റെ മേലിലും അല്ലാഹുവിന്റെ സലാമും അനുഗ്രഹവുമുണ്ടായിരിക്കട്ടെ). (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُسَلِّمُ الصَّغِيرُ عَلَى الْكَبِيرِ، وَالْمَارُّ عَلَى الْقَاعِدِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ". وفي رواية: "يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي..." ثُمَّ ذَكَرَ الحديث. (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ചെറിയവൻ വലിയവനോടും, നടക്കുന്നവൻ ഇരിക്കുന്നവനോടും ചെറിയ കൂട്ടം വലിയ കൂട്ടത്തോടും സലാം പറയണം." മറ്റൊരു നിവേദനത്തിൽ: "വാഹനം കേറിയവൻ നടക്കുന്നവനോടും സലാം പറയണം." ശേഷം ബാക്കി ഹദീസ് പറഞ്ഞു. (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=97), 1, 'وَفِي رِوَايَةٍ: "يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي..." ثُمَّ ذَكَرَ الحديث. (ق,د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: "വാഹനം കേറിയവൻ നടക്കുന്നവനോടും സലാം പറയണം." ശേഷം ബാക്കി ഹദീസ് പറഞ്ഞു. (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُسَلِّمُ الْفَارِسُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْقَائِمِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ". حَسَنٌ صَحِيحٌ. (ت)', 'ഫളാലതുബ്നു ഉബൈദ്(റ): റസൂൽ(സ) പറയുന്നു: "കുതിര സവാരിക്കാരൻ നടക്കുന്നവനോടും, നടക്കുന്നവൻ നിൽക്കുന്നവനോടും കുറച്ചാളുകൾ കൂടുതലാളുകളോടും സലാം പറയണം." (തു)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا لَقِيَ أَحَدُكُمْ أَخَاهُ فَلْيُسَلِّمْ عَلَيْهِ، فَإِنْ حَالَتْ بَيْنَهُمَا شَجَرَةٌ أَوْ جِدَارٌ أَوْ حَجَرٌ ثُمَّ لَقِيَهُ فَلْيُسَلِّمْ عَلَيْهِ أَيْضًا. (د)', 'അബൂഹുറൈറ(റ): നിങ്ങളിലൊരാൾ തന്റെ സഹോദരനെ കണ്ടാൽ അവനോട് സലാം പറയുക. പിന്നെ നിങ്ങൾ രണ്ട് പേരുടെ ഇടയിൽ ഒരു മരമോ, ചുമരോ, കല്ലോ മറയായി വരികയും വീണ്ടും അവനെ കണ്ട് മുട്ടുകയും ചെയ്താൽ അവനോട് വീണ്ടും സലാം പറയുക. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ عُمَرَ، رَضِيَ اللهُ عَنْهُمْ أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي مَشْرُبَةٍ لَهُ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ، السَّلَامُ عَلَيْكُمْ أَيَدْخُلُ عُمَرُ؟ (د)', 'ഉമർ(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) അവിടത്തെ ചെറിയ റൂമിൽ ആയിരിക്കുമ്പോൾ ഉമർ(റ) പറഞ്ഞു: അസ്സലാമു അലൈക്കും തിരുദൂതരേ, അസ്സലാമു അലൈകും. ഉമർ പ്രവേശിക്കട്ടെയോ? (ദ)', 'ابْنِ عَبَّاسٍ، عَنْ عُمَرَ،', 'ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى غِلْمَانٍ يَلْعَبُونَ، فَسَلَّمَ عَلَيْهِمْ. (ق,د,ت,ن,جه)', 'അനസ്(റ): റസൂൽ(സ) കളിച്ച് കൊണ്ടിരിക്കുന്ന ചില കുട്ടികളുടെയടുത്ത് ചെന്നു. അവരോട് സലാം പറഞ്ഞു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 427, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: انْتَهَى إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا غُلَامٌ فِي الْغِلْمَانِ، فَسَلَّمَ عَلَيْنَا، ثُمَّ أَخَذَ بِيَدِي فَأَرْسَلَنِي برِسَالَةٍ، وَقَعَدَ فِي ظِلِّ جِدَارٍ، أَوْ قَالَ: إِلَى جِدَارٍ، حَتَّى رَجَعْتُ إِلَيْهِ. (د)', 'അനസ്(റ): ധാരാളം കുട്ടികൾക്കിടയിൽ ഒരുവനായി ഞാൻ നിൽക്കുമ്പോൾ റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അവിടന്ന് ഞങ്ങളോട് സലാം പറഞ്ഞു, പിന്നെ എന്റെ കൈ പിടിച്ച് എന്നെ ഒരു സന്ദേശവുമായി അയച്ചു. ഞാൻ തിരിച്ചു വരുന്നത് വരെ അവിടന്ന് ഒരു മതിലിന്റെ തണലിൽ ഇരിക്കുകയും ചെയ്തു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ سَيَّارٍ قَالَ: كُنْتُ أَمْشِي مَعَ ثَابِتٍ الْبُنَانِيِّ، فَمَرَّ عَلَى صِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ، فَقَالَ ثَابِتٌ: كُنْتُ مَعَ أَنَسٍ فَمَرَّ عَلَى صِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ، وَقَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرَّ عَلَى صِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ. صَحِيحٌ. (ق,د,ت,ن)', 'സയ്യാർ(റ): ഞാൻ സാബിതുൽ ബുനാനി(റ)വിന്റെ കൂടെ നടക്കുകയായിരുന്നു. അദ്ദേഹം കുറച്ച് കുട്ടികളുടെ അരികിലൂടെ നടന്നു പോയി. അപ്പോൾ അവർക്ക് സലാം പറഞ്ഞു. എന്നിട്ട് സാബിത്(റ) പറഞ്ഞു. ഞാൻ അനസ്(റ)വിന്റെ കൂടെയായിരുന്നപ്പോൾ അദ്ദേഹം കുറച്ച് കുട്ടികളുടെയടുത്ത് കൂടെ നടന്നു പോവുകയും അവരോട് സലാം പറയുകയും ചെയ്തു. ശേഷം ഇങ്ങനെ പറയുകയും ചെയ്തു: ഞാൻ റസൂൽ(സ)യുടെ കൂടെയായിരുന്നപ്പോൾ അവിടന്ന് കുറച്ച് കുട്ടികളുടെയരികിലൂടെ നടന്നു പോയി. അപ്പോൾ അവിടന്ന് അവരോട് സലാം പറഞ്ഞു. (ബു,മു,ദ,തു,ന)', 'سَيَّارٍ قَالَ', 'സയ്യാർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ صِبْيَانٌ، فَسَلَّمَ عَلَيْنَا. (ق,جه)', 'അനസ്(റ): ഞങ്ങൾ കുട്ടികളായിരിക്കെ റസൂൽ(സ) ഞങ്ങളുടെയടുത്ത് വന്നു. അവിടന്ന് ഞങ്ങളോട് സലാം പറഞ്ഞു. (ബു,മു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، أَنَّهُ مَرَّ عَلَى صِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ، وَقَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ. (خ)', 'അനസുബ്നു മാലിക്(റ): അവർ കുറച്ച് കുട്ടികളുടെയടുത്ത് കൂടെ നടന്നു പോയപ്പോൾ അവരോട് സലാം പറഞ്ഞു. എന്നിട്ട് പറഞ്ഞു. നബി(സ) അത് ചെയ്യാറുണ്ടായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَرَّ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نِسْوَةٍ، فَسَلَّمَ عَلَيْنَا. (د,ت,جه)', 'അസ്മാഉബിൻത് യസീദ്(റ): നബി(സ) ഭാര്യമാരോടൊപ്പം ഞങ്ങളുടെ അരികിലൂടെ നടന്നു പോയപ്പോൾ അവിടന്ന് ഞങ്ങളോട് സലാം പറഞ്ഞു. (ദ,തു,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഉബിൻത് യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ فِي الْمَسْجِدِ يَوْمًا وَعُصْبَةٌ مِنَ النِّسَاءِ قُعُودٌ، فَأَلْوَى بِيَدِهِ بالتَّسْلِيمِ. حَسَنٌ. (د,ت,جه)', 'അസ്മാഉബിൻത് യസീദ്(റ): ഒരു കൂട്ടം സ്ത്രീകൾ ഇരിക്കെ, റസൂൽ(സ) പള്ളിയിലൂടെ നടന്നു പോയി. അപ്പോൾ അവിടന്ന് തിരുകൈകൾ കൊണ്ട് സലാം ചൊല്ലുന്നതായി ആംഗ്യം കാണിച്ചു. (ദ,തു,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഉബിൻത് യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 428, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا انْتَهَى أَحَدُكُمْ إِلَى مَجْلِسٍ فَلْيُسَلِّمْ، فَإِنْ بَدَا لَهُ أَنْ يَجْلِسَ فَلْيَجْلِسْ، ثُمَّ إِذَا قَامَ فَلْيُسَلِّمْ، فَلَيْسَتِ الْأُولَى بِأَحَقَّ مِنَ الْآخِرَةِ". حَسَنٌ. (د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളിലൊരാൾ ഒരു സദസ്സിൽ ചെന്നാൽ അവൻ സലാം ചൊല്ലട്ടെ, ഇരിക്കണമെന്ന് തോന്നിയാൽ അവൻ ഇരിക്കട്ടെ, ഇനി അവൻ എഴുന്നേൽക്കാൻ ഉദ്ദേശിച്ചാൽ സലാം പറയണം. ആദ്യത്തെ സലാം രണ്ടാമത്തേതിനെക്കാൾ ബന്ധപ്പെട്ടതല്ല. (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا انْتَهَى أَحَدُكُمْ إِلَى الْمَجْلِسِ فَلْيُسَلِّمْ، فَإِذَا أَرَادَ أَنْ يَقُومَ فَلْيُسَلِّمْ، فَلَيْسَتِ الْأُولَى بِأَحَقَّ مِنَ الْآخِرَةِ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ ഒരു സദസ്സിൽ ചെന്നാൽ അവൻ സലാം ചൊല്ലട്ടെ. എഴുന്നേറ്റ് പോകണമെന്ന് അവൻ ആഗ്രഹിച്ചാൽ അപ്പോഴും സലാം ചൊല്ലട്ടെ. ആദ്യത്തെ സലാം രണ്ടാമത്തേതിനേക്കാൾ അനുയോജ്യമായതല്ല." (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ وَالنَّاسُ مَعَهُ إِذْ أَقْبَلَ نَفَرٌ ثَلَاثَةٌ، فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَ وَاحِدٌ، قَالَ: فَوَقَفَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَّا أَحَدُهُمَا فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ فِيهَا، وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ، وَأَمَّا الثَّالِثُ فَأَدْبَرَ ذَاهِبًا، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلَاثَةِ؟ أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ فَآوَاهُ اللَّهُ، وَأَمَّا الْآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ، وَأَمَّا الْآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ". (م)', 'അബൂ വാഖിദുല്ലൈസി(റ): റസൂൽ(സ) ജനങ്ങളുടെ കൂടെ പള്ളിയിൽ ഇരിക്കവെ മൂന്ന് ആളുകൾ വന്നു. രണ്ടുപേർ റസൂൽ(സ)യുടെ അടുത്ത് വരികയും ഒരാൾ പോകുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ രണ്ടുപേരും റസൂൽ(സ)യുടെ അടുത്ത് നിന്നു. സദസ്സിലെ ചെറിയ ഒരു വിടവ് കണ്ടപ്പോൾ അവരിലൊരാൾ അവിടെ ഇരുന്നു. രണ്ടാമത്തെയാൾ അവരുടെ പിന്നിലുമിരുന്നു. മൂന്നാമത്തവൻ തിരിച്ചുപോയി. അങ്ങനെ മജ്ലിസ് പിരിഞ്ഞപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ആ മൂന്ന് ആളുകളെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ? അതിൽ ഒരാൾ അല്ലാഹുവിലേക്ക് ചെന്നു. അപ്പോൾ അല്ലാഹു അവന് അഭയം നൽകി. മറ്റൊരാൾ ലജ്ജ കാണിച്ചു. അപ്പോൾ അവനിൽ നിന്ന് അല്ലാഹു ലജ്ജിച്ചു. മറ്റെയാൾ പിന്തിരിഞ്ഞു. അപ്പോൾ അല്ലാഹു അവനിൽ നിന്നും പിന്തിരിഞ്ഞു." (മു)', 'أَبِي وَاقِدٍ اللَّيْثِيِّ', 'അബൂ വാഖിദുല്ലൈസി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِمَجْلِسٍ، وَفِيهِ أَخْلَاطٌ مِنَ الْمُسْلِمِينَ وَالْيَهُودِ، فَسَلَّمَ عَلَيْهِمْ. حَسَنٌ صَحِيحٌ. (ت)', 'ഉസാമതുബ്നു സൈദ്(റ): മുസ്ലിംകളും യഹൂദികളും കൂടി കലർന്നിരിക്കുന്ന ഒരു മജ്ലിസിനരികിലൂടെ നടന്നു പോയപ്പോൾ തിരുമേനി(സ) അവരുടെ മേൽ സലാം പറഞ്ഞു. (തു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبُولُ، فَلَمْ يَرُدَّ عَلَيْهِ السَّلَامَ. حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) മൂത്രമൊഴിച്ചു കൊണ്ടിരിക്കുമ്പോൾ ഒരാൾ സലാം പറഞ്ഞു. അവിടന്ന് സലാം മടക്കിയില്ല. (മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي تَمِيمَةَ الْهُجَيْمِيِّ، عَنْ رَجُلٍ مِنْ قَوْمِهِ، قَالَ: طَلَبْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ أَقْدِرْ عَلَيْهِ، فَجَلَسْتُ فَإِذَا نَفَرٌ هُوَ فِيهِمْ وَلَا أَعْرِفُهُ، وَهُوَ يُصْلِحُ بَيْنَهُمْ، فَلَمَّا فَرَغَ قَامَ مَعَهُ بَعْضُهُمْ، فَقَالُوا: يَا رَسُولَ اللَّهِ، فَلَمَّا رَأَيْتُ ذَلِكَ قُلْتُ: عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ، عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ، عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ. قَالَ: "إِنَّ عَلَيْكَ السَّلَامُ تَحِيَّةُ الْمَيِّتِ، إِنَّ عَلَيْكَ السَّلَامُ تَحِيَّةُ الْمَيِّتِ". ثَلَاثًا، ثُمَّ أَقْبَلَ عَلَيَّ فَقَالَ: "إِذَا لَقِيَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ فَلْيَقُلْ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ". ثُمَّ رَدَّ عَلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ، وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ، وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ". (د,ت)', 'തന്റെ സമുദായത്തിൽ പെട്ട ഒരാളിൽ നിന്ന് അബൂ തമീമതുൽ ഹുജൈമിയ്യ്(റ): ഞാൻ നബി(സ)യെ അന്വേഷിച്ചു, പക്ഷെ എനിക്ക് കിട്ടിയില്ല. അങ്ങനെ ഞാനിങ്ങനെ ഇരിക്കുമ്പോൾ ഒരു സംഘം വന്നു. അതിൽ റസൂൽ(സ)യുണ്ടായിരുന്നു. പക്ഷെ ഞാൻ അവിടത്തെ അറിയുമായിരുന്നില്ല. അവിടന്ന് അവർക്കിടയിലെ പ്രശ്നം തീർക്കുകയായിരുന്നു. അത് കഴിഞ്ഞപ്പോൾ അവരിൽ കുറച്ച് പേർ അവിടത്തോട് കൂടെ എഴുന്നേറ്റു, എന്നിട്ട് പറഞ്ഞു: തിരുദൂതരേ. ഇത് കണ്ടപ്പോൾ ഞാൻ പറഞ്ഞു: തിരുദൂതരേ അലൈകസ്സലാം, തിരുദൂതരേ അലൈകസ്സലാം, തിരുദൂതരേ, അലൈകസ്സലാം. അവിടന്ന് പറഞ്ഞു: "അലൈക്കസ്സലാം എന്നത് ശവത്തിന്റെ സ്വാഗതവാക്കാകുന്നു, അലൈക്കസ്സലാം എന്നത് ശവത്തിന്റെ സ്വാഗതവാക്കാകുന്നു." ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം പറഞ്ഞു: ശേഷം എന്റെയടുത്ത് വന്നു പറഞ്ഞു: "ഒരാൾ തന്റെ മുസ്ലിമായ സഹോദരനെ കണ്ടുമുട്ടിയാൽ അവൻ പറയട്ടെ, അസ്സലാമു അലൈകും വറഹ്മതുല്ലാഹി" ശേഷം നബി(സ) എന്നോട് സലാം മടക്കി: "വഅലൈക്കസ്സലാം വറഹ്മതുല്ലാഹി, വഅലൈക്കസ്സലാം വറഹ്മതുല്ലാഹി, വഅലൈക്കസ്സലാം വറഹ്മതുല്ലാഹി." (ദ,തു)', 'أَبِي تَمِيمَةَ الْهُجَيْمِيِّ، عَنْ رَجُلٍ مِنْ قَوْمِهِ، قَالَ', 'തന്റെ സമുദായത്തിൽ പെട്ട ഒരാളിൽ നിന്ന് അബൂ തമീമതുൽ ഹുജൈമിയ്യ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ جَابِرِ بْنِ سُلَيْمٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: عَلَيْكَ السَّلَامُ. فَقَالَ: "لَا تَقُلْ عَلَيْكَ السَّلَامُ، وَلَكِنْ قُلِ: السَّلَامُ عَلَيْكَ". حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിറുബ്നു സുലൈം(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു പറഞ്ഞു: അലൈക്കസ്സലാം. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അലൈക്കസ്സലാം എന്ന് പറയരുത്, മറിച്ച് അസ്സലാമു അലൈക എന്ന് നിങ്ങൾ പറയുക." (തു)', 'جَابِرِ بْنِ سُلَيْمٍ', 'ജാബിറുബ്നു സുലൈം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَلَّمَ سَلَّمَ ثَلَاثًا، وَإِذَا تَكَلَّمَ بِكَلِمَةٍ أَعَادَهَا ثَلَاثًا. حَسَنٌ صَحِيحٌ. (خ,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) സലാം ചൊല്ലിയാൽ മൂന്ന് പ്രാവശ്യം സലാം ചൊല്ലുമായിരുന്നു. ഒരു വാക്യം പറഞ്ഞാൽ അത് മൂന്ന് പ്രാവശ്യം മടക്കുമായിരുന്നു. (ബു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي جُرَيٍّ الْهُجَيْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ، قَالَ: "لَا تَقُلْ عَلَيْكَ السَّلَامُ، فَإِنَّ عَلَيْكَ السَّلَامُ تَحِيَّةُ الْمَوْتَى". (د,ت)', 'അബൂജുറയ്യിൽ ഹുജൈമിയ്യ(റ): ഞാൻ നബി(സ)യുടെ തിരുസന്നിധിയിൽ ചെന്ന് പറഞ്ഞു: തിരുദൂതരേ, അലൈക്കസ്സലാം. അവിടന്ന് പറഞ്ഞു: "അലൈക്കസ്സലാം എന്ന് നിങ്ങൾ പറയരുത്, കാരണം അത് മരിച്ചവരുടെ സ്വാഗതവാക്കാകുന്നു." (ദ,തു)', 'أَبِي جُرَيٍّ الْهُجَيْمِيِّ', 'അബൂജുറയ്യിൽ ഹുജൈമിയ്യ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ غَالِبِ بْنِ خِطَافٍ الْبَصْرِي رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّا لَجُلُوسٌ ببَابٌ الْحَسَنِ إِذْ جَاءَ رَجُلٌ فَقَالَ: حَدَّثَنِي أَبِي، عَنْ جَدِّي قَالَ: بَعَثَنِي أَبِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: ائْتِهِ فَأَقْرِئْهُ السَّلَامَ، قَالَ: فَأَتَيْتُهُ، قُلْتُ: إِنَّ أَبِي يُقْرِئُكَ السَّلَامَ، فَقَالَ: "عَلَيْكَ السَّلَامُ وَعَلَى أَبِيكَ السَّلَامُ". (د)', 'ഗാലിബുബ്നു ഖിതാഫിൽ ബസ്വരി(റ): ഞങ്ങൾ ബാബുൽ ഹസന്റെയടുത്ത് ഇരിക്കുമ്പോൾ ഒരാൾ വന്നു പറഞ്ഞു: എന്റെ പിതാവ് എന്റെ പിതാമഹനെക്കുറിച്ച് എന്നോട് പറഞ്ഞു: എന്റെ പിതാവ് എന്നെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് പറഞ്ഞയച്ചു. എന്നിട്ട് പറഞ്ഞു: അവിടത്തെ തിരുസന്നിധിയിൽ ചെന്ന് സലാം പറയുക. അദ്ദേഹം പറയുന്നു: ഞാൻ ചെന്ന് ഇപ്രകാരം പറഞ്ഞു: നിശ്ചയം എന്റെ പിതാവ് അവിടത്തോട് സലാം പറയുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അലൈകസ്സലാം വഅലാ അബീകസ്സലാം (താങ്കളുടെയും താങ്കളുടെ പിതാവിന്റയും മേൽ രക്ഷയുണ്ടായിരിക്കട്ടെ)" (ദ)', 'غَالِبِ بْنِ خِطَافٍ الْبَصْرِي', 'ഗാലിബുബ്നു ഖിതാഫിൽ ബസ്വരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "إِنَّ جِبْرِيلَ يَقْرَأُ عَلَيْكِ السَّلَامَ". فَقَالَتْ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ. (ق,د,ت,جه)', 'ആഇശ(റ): നബി(സ) അവരോട് പറഞ്ഞു: "ജിബ്രീൽ നിന്നോട് സലാം പറയുന്നു." അപ്പോൾ അവർ പറഞ്ഞു: വഅലൈഹിസ്സലാം വറഹ്മതുല്ലാഹി (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّه عَنْه -رَفَعَهُ الْحَسَنُ بْنُ عَلِيٍّ- قَالَ: "يُجْزِئُ عَنِ الْجَمَاعَةِ -إِذَا مَرُّوا- أَنْ يُسَلِّمَ أَحَدُهُمْ، وَيُجْزِئُ عَنِ الْجُلُوسِ أَنْ يَرُدَّ أَحَدُهُمْ". (د)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): - ഇത് ഹസനുബ്നു അലിയ്യ്(റ) മർഫൂആക്കി പറഞ്ഞതാണ് - "ഒരു സംഘത്തിൽ നിന്ന് - അവർ നടക്കുകയാണെങ്കിൽ - ഒരാൾ സലാം പറയലും, അവർ ഇരിക്കുകയാണെങ്കിൽ അവരിൽ നിന്നൊരാൾ സലാം മടക്കലും അവർക്ക് മതിയാകും." (ദ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 431, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ مِنَّا مَنْ تَشَبَّهَ بِغَيْرِنَا، لَا تَشَبَّهُوا بِالْيَهُودِ وَلَا بِالنَّصَارَى، فَإِنَّ تَسْلِيمَ الْيَهُودِ الْإِشَارَةُ بِالْأَصَابِعِ، وَتَسْلِيمَ النَّصَارَى الْإِشَارَةُ بِالْأَكُفِّ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നു: "നാമല്ലാത്തവരോട് സാമ്യം പുലർത്തിയവർ നമ്മിൽ പെട്ടവരല്ല. നിങ്ങൾ ജൂതൻമാരോടും ക്രിസ്ത്യാനികളോടും സാമ്യം പുലർത്തരുത്. ജൂതന്മാർ വിരലുകൾ കൊണ്ടും, നസാറാക്കൾ കൈപ്പടം കൊണ്ടുമാണ് സലാം ചൊല്ലുക." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَبْدَءُوا الْيَهُودَ وَالنَّصَارَى بِالسَّلَامِ، وَإِذَا لَقِيتُمْ أَحَدَهُمْ فِي الطَّرِيقِ فَاضْطَرُّوهُ إِلَى أَضْيَقِهِ". حَسَنٌ صَحِيحٌ (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജൂതരോടും കൃസ്ത്യാനികളോടും നിങ്ങൾ അങ്ങോട്ട് സലാം പറയരുത്. നിങ്ങൾ അവരെ വഴിയിൽ കണ്ടുമുട്ടിയാൽ അതിന്റെ കുടുസ്സായ ഭാഗത്തേക്ക് അവരെ ആക്കുക." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ رَهْطًا مِنَ الْيَهُودِ دَخَلُوا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ". فَقَالَتْ عَائِشَةُ: بَلْ عَلَيْكُمُ السَّامُ وَاللَّعْنَةُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، إِنَّ اللَّهَ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ". قَالَتْ عَائِشَةُ: أَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: "قَدْ قُلْتُ: عَلَيْكُمْ". حَسَنٌ صَحِيحٌ. (م)', 'ആഇശ(റ): യഹൂദികളിൽ പെട്ട ഒരു സംഘം നബി(സ)യുടെ സന്നിധിയിൽ വന്നു പറഞ്ഞു: അസ്സാമു അലൈക (താങ്കൾക്ക് മരണം സംഭവിക്കട്ടെ) അപ്പോൾ നബി(സ) പറഞ്ഞു: "അലൈകും" (നിങ്ങളുടെ മേലിലും). അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: അല്ല, ശാപവും മരണവും നിങ്ങളുടെ മേലിലുണ്ടാവട്ടെ. (ബൽ അലൈകുമുസ്സാമ വല്ലഅ്ന:) അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആഇശാ, അല്ലാഹു എല്ലാ കാര്യത്തിലും സൗമ്യത ഇഷ്ടപ്പെടുന്നു". ആഇശ(റ) ചോദിച്ചു: അവർ പറഞ്ഞത് അവിടന്ന് കേട്ടില്ലേ? തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ പറഞ്ഞത് ''അലൈക്കും'' (നിങ്ങളുടെ മേലിലും) എന്നാണ്." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ أَبِي إِلَى الشَّامِ، فَجَعَلُوا يَمُرُّونَ بِصَوَامِعَ فِيهَا نَصَارَى فَيُسَلِّمُونَ عَلَيْهِمْ، فَقَالَ أَبِي: لَا تَبْدَءُوهُمْ بِالسَّلَامِ، فَإِنَّ أَبَا هُرَيْرَةَ حَدَّثَنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَبْدَءُوهُمْ بِالسَّلَامِ، وَإِذَا لَقِيتُمُوهُمْ فِي الطَّرِيقِ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِ الطَّرِيقِ". (م,د,ت)', 'സുഹൈലുബ്നു അബീസ്വാലിഹ്(റ): ഞാൻ എന്റെ പിതാവിന്റെ കൂടെ ശാമിലേക്ക് പുറപ്പെട്ടു. അങ്ങനെ അവർ ക്രിസ്ത്യാനികളുടെ ആശ്രമത്തിനരികിലൂടെ നടന്നുപോയപ്പോൾ അവർക്ക് സലാം പറഞ്ഞു. അപ്പോൾ എന്റെ പിതാവ് പറഞ്ഞു: നിങ്ങൾ അവരോട് സലാം ആദ്യം പറയരുത്. കാരണം അബൂഹുറൈറ(റ) ഞങ്ങൾക്ക് ഇപ്രകാരം പറഞ്ഞു തന്നിട്ടുണ്ട്: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവരോട് സലാം പറഞ്ഞു തുടങ്ങരുത്, ഇനി വഴിമദ്ധ്യേ അവരെ കണ്ടുമുട്ടിയാൽ അതിന്റെ ഏറ്റവും കുടുസ്സായ ഭാഗത്തേക്ക് അവരെ ആക്കുക." (മു,ദ,തു)', 'سُهَيْلِ بْنِ أَبِي صَالِحٍ', 'സുഹൈലുബ്നു അബീസ്വാലിഹ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 432, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْيَهُودَ إِذَا سَلَّمَ عَلَيْكُمْ أَحَدُهُمْ فَإِنَّمَا يَقُولُ: السَّامُ عَلَيْكُمْ، فَقُولُوا: وَعَلَيْكُمْ". (م,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജൂതന്മാർ നിങ്ങളോട് സലാം പറയുമ്പോൾ അവർ പറയുന്നത് ''അസ്സാമു അലൈക്കും'' (നിങ്ങൾക്ക് മരണം വരട്ടെ) എന്നാണ്. അത് കൊണ്ട് നിങ്ങൾ ''വഅലൈകും''(നിങ്ങൾക്കും വരട്ടെ) എന്ന് മടക്കുക." (മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَصْحَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَهْلَ الْكِتَابِ يُسَلِّمُونَ عَلَيْنَا، فَكَيْفَ نَرُدُّ عَلَيْهِمْ؟ قَالَ: "قُولُوا وَعَلَيْكُمْ". (ق,د,جه)', 'അനസ്(റ): നബി(സ)യുടെ അനുചരൻമാർ അവിടത്തോട് ചോദിച്ചു: അഹ്ലുൽ കിതാബ്(ജൂതരും ക്രിസ്ത്യാനികളും) ഞങ്ങളോട് സലാം പറയുന്നു, അപ്പോൾ ഞങ്ങൾ എങ്ങനെയാണ് തിരിച്ച് പറയേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ വഅലൈക്കും. (നിങ്ങൾക്കും വരട്ടെ) എന്ന് പറയുക". (ബു,മു,ദ,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: سَلَّمَ نَاسٌ مِنْ يَهُودَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: السَّامُ عَلَيْكَ يَا أَبَا الْقَاسِمِ، فَقَالَ: "وَعَلَيْكُمْ". فَقَالَتْ عَائِشَةُ -وَغَضِبَتْ-: أَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: "بَلَى قَدْ سَمِعْتُ، فَرَدَدْتُ عَلَيْهِمْ، وَإِنَّا نُجَابُ عَلَيْهِمْ وَلَا يُجَابُونَ عَلَيْنَا". (م)', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ): റസൂൽ(സ)യോട് ജൂതരിലെ ഒരു സംഘം ആളുകൾ ഇപ്രകാരം സലാം പറഞ്ഞു: അസ്സാമു അലൈകും (നിങ്ങൾക്ക് മരണം വരട്ടെ), ഓ അബുൽഖാസിം. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "വഅലൈകും (നിങ്ങൾക്കും വരട്ടെ)" അപ്പോൾ ആഇശ(റ) ദേശ്യപ്പെട്ടുകൊണ്ട് പറഞ്ഞു: അവർ പറഞ്ഞത് അങ്ങ് കേട്ടില്ലേ? തിരുമേനി(സ) പറഞ്ഞു: "അതെ, ഞാൻ കേട്ടിട്ടുണ്ട്, അത് കൊണ്ടാണ് ഞാൻ മടക്കിയത്, അവർക്കെതിരിൽ നമ്മുടേത് സ്വീകരിക്കപ്പെടും. എന്നാൽ നമുക്കെതിരിൽ അവരുടേത് സ്വീകരിക്കപ്പെടുകയില്ല." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا سَلَّمَ عَلَيْكُمْ أَحَدٌ مِنْ أَهْلِ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ". (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അഹ്ലുൽ കിതാബിൽ നിന്നാരെങ്കിലും നിങ്ങളോട് സലാം പറഞ്ഞാൽ നിങ്ങൾ വഅലൈക്കും (നിങ്ങൾക്കും) എന്ന് മാത്രം പറയുക." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي رَاكِبٌ غَدًا إِلَى الْيَهُودِ، فَلَا تَبْدَءُوهُمْ بِالسَّلَامِ، فَإِذَا سَلَّمُوا عَلَيْكُمْ فَقُولُوا: وَعَلَيْكُمْ". [ز: في سنده مدلس عنعنه] (جه)', 'അബ്ദുൽറഹ്മാനുൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നാളെ ജൂതരുടെയടുത്തേക്ക് പോകുകയാണ്. അപ്പോൾ നിങ്ങൾ ആരും അവരോട് സലാം പറഞ്ഞ് തുടങ്ങരുത്. ഇനി നിങ്ങളോട് അവർ സലാം പറഞ്ഞാൽ നിങ്ങൾ വഅലൈകും (നിങ്ങൾക്കും) എന്ന് പറയുക." (പരമ്പരയിൽ ഹദീസ് അൻഅനാക്കിപ്പറഞ്ഞ മുദല്ലിസുണ്ട്.) (ബു)', 'أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ', 'അബ്ദുൽറഹ്മാനുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ബു']::text[], 'ز: في سنده مدلس عنعنه', null, 433, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ مُسْلِمَيْنِ يَلْتَقِيَانِ فَيَتَصَافَحَانِ إِلَّا غُفِرَ لَهُمَا قَبْلَ أَنْ يَفْتَرِقَا". حَسَنٌ. (د,ت,جه)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് മുസ്ലിം സഹോദരങ്ങൾ കണ്ടുമുട്ടുകയും അങ്ങനെ അവർ ഹസ്തദാനം ചെയ്യുകയും ചെയ്താൽ അവർ വേർപിരിയുന്നതിനു മുമ്പ് തന്നെ അവരുടെ ദോശങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." (ദ,തു,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، الرَّجُلُ مِنَّا يَلْقَى أَخَاهُ أَوْ صَدِيقَهُ، أَيَنْحَنِي لَهُ؟ قَالَ: "لَا". قَالَ: أَفَيَلْتَزِمُهُ وَيُقَبِّلُهُ؟ قَالَ: "لَا". قَالَ: أَفَيَأْخُذُ بِيَدِهِ وَيُصَافِحُهُ؟ قَالَ: "نَعَمْ". حَسَنٌ (ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യോട് ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഞങ്ങളിൽ നിന്നൊരാൾ തന്റെ സഹോദരനെ അല്ലെങ്കിൽ സ്നേഹിതനെ കണ്ടുമുട്ടുമ്പോൾ അവന് വേണ്ടി കുനിയണോ? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട." അയാൾ ചോദിച്ചു: അവനെ ആലിംഗനം ചെയ്ത് ചുംബിക്കണോ? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട." അയാൾ ചോദിച്ചു: അവന്റെ കൈ പിടിച്ച് ഹസ്തദാനം ചെയ്യണോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِأَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: هَلْ كَانَتِ الْمُصَافَحَةُ فِي أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. حَسَنٌ صَحِيحٌ. (خ,ت)', 'ഖതാദ(റ): ഞാൻ അനസുബ്നു മാലിക്(റ)വിനോട് ചോദിച്ചു: ഹസ്തദാനം ചെയ്യൽ റസൂൽ(സ)യുടെ സ്വഹാബാക്കൾക്കിടയിലുണ്ടായിരുന്നോ? അനസ്(റ) പറഞ്ഞു: അതെ. (ബു,തു)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مِنْ تَمَامِ التَّحِيَّةِ الْأَخْذُ بِالْيَدِ". (ت)', 'ഇബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹസ്തദാനം ചെയ്യൽ അഭിവാദ്യത്തിന്റെ പൂർണ്ണതയാണ്." (തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَمَامُ عِيَادَةِ الْمَرِيضِ أَنْ يَضَعَ أَحَدُكُمْ يَدَهُ عَلَى جَبْهَتِهِ -أَوْ قَالَ: عَلَى يَدِهِ- فَيَسْأَلُهُ كَيْفَ هُوَ؟ وَتَمَامُ تَحِيَّاتِكُمْ بَيْنَكُمُ الْمُصَافَحَةُ". (ت)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "രോഗിയെ സന്ദർശിക്കുന്നതിന്റെ പൂർണ്ണത തന്റെ കൈ ആ രോഗിയുടെ നെറ്റിയിൽ അല്ലെങ്കിൽ കയ്യിന്റെ മേൽ വെച്ച് ''എങ്ങനെയുണ്ട്?'' എന്നന്വേഷിക്കലാണ്. നിങ്ങൾക്കിടയിലുള്ള അഭിവാദ്യങ്ങളുടെ പൂർണ്ണത ഹസ്തദാനമാണ്." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا الْتَقَى الْمُسْلِمَانِ فَتَصَافَحَا، وَحَمِدَا اللَّهَ عَزَّ وَجَلَّ وَاسْتَغْفَرَاهُ، غُفِرَ لَهُمَا". (د)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് മുസ്ലിം സഹോദരന്മാർ കണ്ടുമുട്ടി ഹസ്തദാനം ചെയ്യുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും പൊറുക്കലിനെ തേടുകയും ചെയ്താൽ അവർക്ക് രണ്ടുപേർക്കും പൊറുക്കപ്പെടും." (ദ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا جَاءَ أَهْلُ الْيَمَنِ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ جَاءَكُمْ أَهْلُ الْيَمَنِ، وَهُمْ أَوَّلُ مَنْ جَاءَ بِالْمُصَافَحَةِ". (خ,د)', 'അനസുബ്നു മാലിക്(റ): യമൻ നിവാസികൾ വന്നപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "യമൻ നിവാസികളിതാ നിങ്ങളിലേക്ക് വന്നിരിക്കുന്നു. അവരാണ് ആദ്യമായി ഹസ്തദാനം കൊണ്ടുവന്നവർ." (ബു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، وَسُئِلَ: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَافِحُكُمْ إِذَا لَقِيتُمُوهُ؟ قَالَ: مَا لَقِيتُهُ قَطُّ إِلَّا صَافَحَنِي، وَبَعَثَ إِلَيَّ ذَاتَ يَوْمٍ وَلَمْ أَكُنْ فِي أَهْلِي، فَلَمَّا جِئْتُ أُخْبِرْتُ أَنَّهُ أَرْسَلَ لِي، فَأَتَيْتُهُ وَهُوَ عَلَى سَرِيرِهِ، فَالْتَزَمَنِي، فَكَانَتْ تِلْكَ أَجْوَدَ وَأَجْوَدَ. (د)', 'അബൂദർറ്(റ): അവരോട് ഇപ്രകാരം ചോദിക്കപ്പെട്ടു: നിങ്ങൾ തിരുദൂതർ(സ)യെ കണ്ടുമുട്ടുമ്പോൾ അവിടന്ന് നിങ്ങൾക്ക് ഹസ്തദാനം ചെയ്യാറുണ്ടോ?. അബൂദർറ്(റ) പറഞ്ഞു: ഇന്നുവരെ എനിക്ക് ഹസ്തദാനം ചെയ്തിട്ടല്ലാതെ റസൂൽ(സ)യെ ഞാൻ കണ്ടുമുട്ടിയിട്ടില്ല. ഒരു ദിവസം ഞാൻ വീട്ടിലില്ലാത്ത സമയത്ത് റസൂൽ(സ) എന്റെ അടുത്തേക്ക് ആളെ വിട്ടു. ഞാൻ വന്നപ്പോൾ റസൂൽ(സ) എന്റെ അടുത്തേക്ക് ആളെ വിട്ടിരുന്നു എന്നറിയാൻ കഴിഞ്ഞു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. റസൂൽ(സ) തന്റെ കട്ടിലിലായിരുന്നു. അങ്ങനെ അവിടന്ന് എന്നെ വാരിപ്പുണർന്നു. അത് എല്ലാറ്റിനെക്കാളും നല്ലൊരു അനുഭവമായിരുന്നു. (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَدِمَ زَيْدُ بْنُ حَارِثَةَ الْمَدِينَةَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي، فَأَتَاهُ فَقَرَعَ الْبَابٌ، فَقَامَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُرْيَانًا يَجُرُّ ثَوْبَهُ، وَاللَّهِ مَا رَأَيْتُهُ عُرْيَانًا قَبْلَهُ وَلَا بَعْدَهُ، فَاعْتَنَقَهُ وَقَبَّلَهُ. حَسَنٌ (ت)', 'ആഇശ(റ): റസൂൽ(സ) എന്റെ വീട്ടിലായിരിക്കെ സൈദുബ്നു ഹാരിസ(റ) മദീനയിൽ വന്നു. അങ്ങനെ സൈദ്(റ) റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് വാതിൽ മുട്ടി. അവിടന്ന് സൈദ്(റ)വിന്റടുത്തേക്ക് നഗ്നനായി വസ്ത്രങ്ങൾ വലിച്ചുകൊണ്ട് എണീറ്റു ചെന്നു. അല്ലാഹുവാണ് സത്യം, അതിനുമുമ്പോ ശേഷമോ റസൂൽ(സ)യെ നഗ്നനായി ഞാൻ കണ്ടിട്ടില്ല. അങ്ങനെ സൈദ്(റ)വിനെ അവിടന്ന് ആലിംഗനം ചെയ്ത് ചുംബിച്ചു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ صَفْوَانَ بْنِ عَسَّالٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ يَهُودِيٌّ لِصَاحِبِهِ: اذْهَبْ بِنَا إِلَى هَذَا النَّبِيِّ، فَقَالَ صَاحِبُهُ: لَا تَقُلْ نَبِيٌّ، إِنَّهُ لَوْ سَمِعَكَ كَانَ لَهُ أَرْبَعَةُ أَعْيُنٍ. فَأَتَيَا رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَاهُ عَنْ تِسْعِ آيَاتٍ بَيِّنَاتٍ، فَقَالَ لَهُمْ: "لَا تُشْرِكُوا بِاللَّهِ شَيْئًا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا، وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ، وَلَا تَمْشُوا بِبَرِيءٍ إِلَى ذِي سُلْطَانٍ لِيَقْتُلَهُ، وَلَا تَسْحَرُوا، وَلَا تَأْكُلُوا الرِّبَا، وَلَا تَقْذِفُوا مُحْصَنَةً، وَلَا تُوَلُّوا الْفِرَارَ يَوْمَ الزَّحْفِ. وَعَلَيْكُمْ خَاصَّةً الْيَهُودَ: أَنْ لَا تَعْتَدُوا فِي السَّبْتِ". قَالَ: فَقَبَّلُوا يَدَهُ وَرِجْلَهُ، فَقَالَا: نَشْهَدُ أَنَّكَ نَبِيٌّ. قَالَ: "فَمَا يَمْنَعُكُمْ أَنْ تَتَّبِعُونِي". قَالُوا: إِنَّ دَاوُدَ دَعَا رَبَّهُ أَنْ لَا يَزَالَ فِي ذُرِّيَّتِهِ نَبِيٌّ، وَإِنَّا نَخَافُ إِنْ تَبِعْنَاكَ أَنْ تَقْتُلَنَا الْيَهُودُ. حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'സ്വഫ്വാനുബ്നു അസ്സാൽ(റ): ഒരു ജൂതൻ തന്റെ കൂട്ടുകാരനോട് പറഞ്ഞു: എന്നെ ഈ നബിയുടെ അടുത്തേക്ക് കൊണ്ടുപോകുക. കൂട്ടുകാരൻ പറഞ്ഞു: നീ ''നബി'' എന്ന് പറയരുത്. അദ്ദേഹം നീ പറയുന്നത് കേട്ടാൽ അദ്ദേഹത്തിന് നാല് കണ്ണുകളുണ്ടാകും (നിന്നെ കൂടുതൽ വീക്ഷിക്കും). അങ്ങനെ രണ്ടുപേരും റസൂൽ(സ)യുടെ അടുത്തേക്ക് പോവുകയും വ്യക്തമായ ഒമ്പത് ദൃഷ്ടാന്തങ്ങളെക്കുറിച്ച് ചോദിക്കുകയും ചെയ്തു. റസൂൽ(സ) അവരോട് പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കുചേർക്കരുത്, കളവ് നടത്തരുത്, വ്യഭിചരിക്കരുത്, അല്ലാഹു നിഷിദ്ധമാക്കിയ ശരീരത്തെ ഒരു ന്യായം കൂടാതെ കൊല്ലരുത്, വധിക്കുന്നതിന് വേണ്ടി നിരപരാധികളെ അധികാരികളുടെ അടുത്തേക്ക് കൊണ്ട് പോകരുത്, മാരണം ചെയ്യരുത്, പലിശ തിന്നരുത്, സച്ചരിതയായ സ്ത്രീക്കെതിരിൽ ആരോപണമുന്നയിക്കരുത്, യുദ്ധദിവസം പിന്തിരിഞ്ഞോടരുത്. പ്രത്യേകിച്ച് യഹൂദികളായ നിങ്ങൾക്ക് ശനിയാഴ്ച പരിധി ലംഘിക്കാതിരിക്കൽ നിർബന്ധമാണ്." അപ്പോൾ അവർ തിരുദൂതർ(സ)യുടെ കൈകാലുകൾ ചുംബിച്ചു. അവർ രണ്ടുപേരും പറഞ്ഞു: അങ്ങ് നബിയാണെന്ന് ഞങ്ങൾ സാക്ഷ്യം വഹിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "പിന്നെയെന്താണ് എന്നെ പിന്തുടരുന്നതിൽ നിന്ന് നിങ്ങളെ തടയുന്നത്?" അവർ പറഞ്ഞു: ദാവുദ്(അ) തന്റെ സന്തതികളിൽ ഒരു പ്രവാചകൻ ഉണ്ടായിക്കൊണ്ടിരിക്കണമെന്ന് തന്റെ രക്ഷിതാവിനോട് പ്രാർത്ഥിച്ചു. ഞങ്ങൾ അങ്ങയെ പിൻപറ്റിയാൽ യഹൂദികൾ ഞങ്ങളെ വധിക്കുമെന്ന് ഞങ്ങൾ ഭയക്കുന്നു. (തു,ന,ജ)', 'صَفْوَانَ بْنِ عَسَّالٍ', 'സ്വഫ്വാനുബ്നു അസ്സാൽ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 435, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَبَّلْنَا يَدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ت,جه)', 'ഇബ്നുഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കരം ചുംബിച്ചു. (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 436, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ زَارِعِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ -وَكَانَ فِي وَفْدِ عَبْدِ الْقَيْسِ- قَالَ: لَمَّا قَدِمْنَا الْمَدِينَةَ فَجَعَلْنَا نَتَبَادَرُ مِنْ رَوَاحِلِنَا، فَنُقَبِّلُ يَدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرِجْلَهُ، قَالَ: وَانْتَظَرَ الْمُنْذِرُ الْأَشَجُّ حَتَّى أَتَى عَيْبَتَهُ فَلَبِسَ ثَوْبَيْهِ، ثُمَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: "إِنَّ فِيكَ خَلَّتَيْنِ يُحِبُّهُمَا اللَّهُ: الْحِلْمُ وَالْأَنَاةُ". قَالَ: يَا رَسُولَ اللَّهِ، أَنَا أَتَخَلَّقُ بِهِمَا، أَمِ اللَّهُ جَبَلَنِي عَلَيْهِمَا؟ قَالَ: "بَلِ اللَّهُ جَبَلَكَ عَلَيْهِمَا". قَالَ: الْحَمْدُ لِلَّهِ الَّذِي جَبَلَنِي عَلَى خَلَّتَيْنِ يُحِبُّهُمَا اللَّهُ وَرَسُولُهُ. (د)', 'സാരിഉബ്നു ആമിർ(റ): - അദ്ദേഹം അബ്ദുൽ ഖൈസ്(റ)വിന്റെ സംഘത്തിൽ ഉണ്ടായിരുന്നു - ഞങ്ങൾ മദീനയിൽ ചെന്നപ്പോൾ ഓരോരുത്തരും വേഗത്തിൽ തങ്ങളുടെ വാഹനങ്ങളിൽ നിന്നിറങ്ങി റസൂൽ(സ)യുടെ കൈയും കാലും ചുംബിച്ചു കൊണ്ടിരുന്നു. മുൻദിറുൽ അശജ്ജ്(റ) കുറച്ച് കാത്ത് നിന്ന് തന്റെ ബാഗെടുത്ത് രണ്ട് വസ്ത്രങ്ങൾ ധരിച്ച് റസൂലിനടുത്തേക്ക് ചെന്നു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "അല്ലാഹു ഇഷ്ടപ്പെടുന്ന രണ്ട് കാര്യങ്ങൾ നിന്നിലുണ്ട്: സഹനവും സാവകാശവും." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനത് കൊണ്ട് സ്വഭാവം സിദ്ധിച്ചതാണോ അതോ അല്ലാഹു എന്നിൽ അത് സൃഷ്ടിച്ചതാണോ? റസൂൽ(സ) പറഞ്ഞു: "അത് നിന്നിൽ അല്ലാഹു ജന്മവാസനയായി തന്നതാണ്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവും അവന്റെ തിരുദൂതരും ഇഷ്ടപ്പെടുന്ന രണ്ട് കാര്യങ്ങൾ എനിക്ക് സൃഷ്ടിപ്പിൽ തന്നെ നൽകിയ അല്ലാഹുവിന് സർവസ്തോത്രങ്ങളും. (ദ)', 'زَارِعِ بْنِ عَامِرٍ', 'സാരിഉബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 436, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ الْأَقْرَعَ بْنَ حَابِسٍ أَبْصَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُقَبِّلُ حُسَيْنًا فَقَالَ: إِنَّ لِي عَشَرَةً مِنَ الْوَلَدِ مَا فَعَلْتُ هَذَا بِوَاحِدٍ مِنْهُمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَا يَرْحَمُ لَا يُرْحَمُ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഹുസൈൻ(റ)വിനെ ചുംബിക്കുന്നത് അഖ്റഉബ്നു ഹാബിസ്(റ) കണ്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എനിക്ക് പത്ത് കുട്ടികളുണ്ടായിട്ടും ഇന്നുവരെ ഒരാളെയും ഞാനിങ്ങനെ ചെയ്തിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "കരുണ കാണിക്കാത്തവനോട് കരുണ കാണിക്കപ്പെടുകയില്ല." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ثُمَّ قَالَ: -تَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- "أَبْشِرِي يَا عَائِشَةُ، فَإِنَّ اللَّهَ قَدْ أَنْزَلَ عُذْرَكِ". وَقَرَأَ عَلَيْهَا الْقُرْآنَ، فَقَالَ أَبَوَايَ: قُومِي فَقَبِّلِي رَأْسَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: أَحْمَدُ اللَّهَ -عَزَّ وَجَلَّ- لَا إِيَّاكُمَا. (ق,د)', 'ആഇശ(റ): മഹതി പറയുന്നു: (മഹതിക്കെതിരെ ആരോപണമുണ്ടായ പശ്ചാത്തലം) റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, നീ സന്തോഷിക്കുക, നിശ്ചയമായും അല്ലാഹു നിന്റെ നിരപരാധിത്വം തെളിയിച്ച് സൂക്തം ഇറക്കിയിരിക്കുന്നു." എന്നിട്ട് അവിടന്ന് എനിക്ക് ഖുർആൻ ഓതിത്തന്നു. അപ്പോൾ എന്റെ മാതാപിതാക്കൾ പറഞ്ഞു: നീ എഴുന്നേറ്റ് റസൂൽ(സ)യുടെ തല ചുംബിക്കൂ. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ അല്ലാഹുവിനെ സ്തുതിക്കുന്നു. നിങ്ങളെ രണ്ടാളെയുമല്ല. (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنِ الشَّعْبِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَلَقَّى جَعْفَرَ بْنَ أَبِي طَالِبٍ، فَالْتَزَمَهُ وَقَبَّلَ مَا بَيْنَ عَيْنَيْهِ. (مرسل) (د)', 'ശഅ്ബീ(റ): നബി(സ) ജഅ്ഫറുബ്നു അബീഥാലിബ്(റ)വിനെ കണ്ടപ്പോൾ ആലിംഗനം ചെയ്ത് കൺതടത്തിൽ ചുംബിച്ചു. (ഹദീസ് മുർസലാണ്.) (ദ)', 'الشَّعْبِيِّ', 'ശഅ്ബീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ إِيَاسِ بْنِ دَغْفَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ أَبَا نَضْرَةَ قَبَّلَ خَدَّ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا. (د)', 'ഇയാസുബ്നു ദഗ്ഫൽ(റ): അബൂനള്റ(റ) ഹസനുബ്നു അലി(റ)വിന്റെ കവിളിൽ ചുംബിക്കുന്നത് ഞാൻ കണ്ടു. (ദ)', 'إِيَاسِ بْنِ دَغْفَلٍ', 'ഇയാസുബ്നു ദഗ്ഫൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ مَعَ أَبِي بَكْرٍ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ، فَإِذَا عَائِشَةُ ابْنَتُهُ مُضْطَجِعَةٌ قَدْ أَصَابَتْهَا حُمَّى، فَأَتَاهَا أَبُو بَكْرٍ فَقَالَ لَهَا: كَيْفَ أَنْتِ يَا بُنَيَّةُ؟ وَقَبَّلَ خَدَّهَا. (د)', 'ബറാഅ്(റ): അബൂബക്കർ(റ) മദീനയിൽ വന്ന ആദ്യകാലത്ത് അവരോട് കൂടെ ഞാൻ ചെന്നു. അപ്പോൾ അവരുടെ മകൾ ആഇശ(റ) പനി ബാധിച്ച് അവിടെ കിടക്കുകയായിരുന്നു. അബൂബക്ർ(റ) മഹതിയുടെ അടുത്തേക്ക് ചെന്ന് ''പൊന്നു മകളേ, എങ്ങനെയുണ്ട്?'' എന്ന് ചോദിക്കുകയും മഹതിയുടെ കവിൾതടം ചുംബിക്കുകയും ചെയ്തു. (ദ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 437, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا هُوَ يُحَدِّثُ الْقَوْمَ -وَكَانَ فِيهِ مِزَاحٌ- بَيْنَا يُضْحِكُهُمْ فَطَعَنَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خَاصِرَتِهِ بِعُودٍ، فَقَالَ: أَصْبِرْنِي، فَقَالَ: "اصْطَبِرْ". قَالَ: إِنَّ عَلَيْكَ قَمِيصًا وَلَيْسَ عَلَيَّ قَمِيصٌ، فَرَفَعَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ قَمِيصِهِ، فَاحْتَضَنَهُ وَجَعَلَ يُقَبِّلُ كَشْحَهُ، قَالَ: إِنَّمَا أَرَدْتُ هَذَا يَا رَسُولَ اللَّهِ. (د)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): അദ്ദേഹം കുറച്ചാളുകളോട് സംസാരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അദ്ദേഹം നല്ല തമാശക്കാരനായിരുന്നു. അങ്ങനെ അവരെ ചിരിപ്പിക്കുന്നതിനിടയിൽ റസൂൽ(സ) അദ്ദേഹത്തിന്റെ ഊരയുടെ ഭാഗത്ത് ഒരു വടി കൊണ്ട് കുത്തി. ഉസൈദ്(റ) പറഞ്ഞു: എനിക്ക് പ്രതികാരം ചെയ്യാൻ അവസരം തരണം. റസൂൽ(സ) പറഞ്ഞു: "നീ പ്രതികാരം ചെയ്യുക." ഉസൈദ്(റ) പറഞ്ഞു: അങ്ങയുടെ ശരീരത്തിൽ ഖമീസ് (നീളക്കുപ്പായം) ഉണ്ട്. എന്റെ ശരീരത്തിലില്ല. അങ്ങനെ റസൂൽ(സ) തന്റെ ഖമീസുയർത്തിയപ്പോൾ ഉസൈദ്(റ) റസൂൽ(സ)യെ വാരിപ്പുണർന്ന് അവിടുത്തെ ഊരയുടെ ഭാഗത്ത് ചുംബിക്കാൻ തുടങ്ങി. എന്നിട്ട് പറഞ്ഞു: തിരുദൂതരേ, ഞാൻ ഇത് മാത്രമാണ് ഉദ്ദേശിച്ചിരുന്നത്. (ദ)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْن حُنَيْفٍ رَضِيَ اللهُ عَنْهُ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَهْلَ قُرَيْظَةَ لَمَّا نَزَلُوا عَلَى حُكْمِ سَعْدٍ أَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ عَلَى حِمَارٍ أَقْمَرَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قُومُوا إِلَى سَيِّدِكُمْ". أَوْ: "إِلَى خَيْرِكُمْ". فَجَاءَ حَتَّى قَعَدَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وفي رواية: قَالَ: فَلَمَّا كَانَ قَرِيبًا مِنَ الْمَسْجِدِ قَالَ لِلْأَنْصَارِ: "قُومُوا إِلَى سَيِّدِكُمْ". (ق,د)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)വിൽ നിന്ന് അബൂ ഉമാമതുബ്നു സഹ്ലുബ്നു ഹുനൈഫ്(റ): സഅ്ദ്(റ)വിന്റെ വിധി പ്രകാരം ഖുറൈള ഗോത്രക്കാർ കീഴടങ്ങിയപ്പോൾ നബി(സ) അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് ആളെവിട്ടു. അപ്പോൾ സഅ്ദ്(റ) കറുപ്പ് കലർന്ന വെള്ളനിറമുള്ള ഒരു കഴുതപ്പുറത്ത് വന്നു. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളുടെ നേതാവിന് വേണ്ടി നിങ്ങൾ എഴുന്നേറ്റ് നിൽക്കുക." അല്ലെങ്കിൽ "നിങ്ങളിൽ നിന്നേറ്റവും ഉത്തമന് വേണ്ടി." അങ്ങനെ സഅ്ദ്(റ) വന്ന് റസൂൽ(സ)യുടെ അടുത്തിരുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=147), 1, 'وَفِي رِوَايَةٍ: قَالَ: فَلَمَّا كَانَ قَرِيبًا مِنَ الْمَسْجِدِ قَالَ لِلْأَنْصَارِ: "قُومُوا إِلَى سَيِّدِكُمْ". (ق,د)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പള്ളിയോടടുത്തപ്പോൾ റസൂൽ(സ) അൻസാരികളോട് പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ നേതാവിന് വേണ്ടി എഴുന്നേൽക്കുക." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أُمِّ الْمُؤْمِنِينَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: مَا رَأَيْتُ أَحَدًا كَانَ أَشْبَهَ سَمْتًا وَهَدْيًا وَدَلًّا وَحَدِيثًا وَكَلَامًا بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ فَاطِمَةَ كَرَّمَ اللَّهُ وَجْهَهَا، كَانَتْ إِذَا دَخَلَتْ عَلَيْهِ قَامَ إِلَيْهَا، فَأَخَذَ بِيَدِهَا وَقَبَّلَهَا وَأَجْلَسَهَا فِي مَجْلِسِهِ، وَكَانَ إِذَا دَخَلَ عَلَيْهَا قَامَتْ إِلَيْهِ فَأَخَذَتْ بِيَدِهِ فَقَبَّلَتْهُ وَأَجْلَسَتْهُ فِي مَجْلِسِهَا. (د,ت)', 'ആഇശ(റ): രൂപത്തിലും പെരുമാറ്റത്തിലും സ്വഭാവത്തിലും ചിട്ടയിലും സംസാരത്തിലും ഫാത്തിമ(റ)യെക്കാൾ റസൂൽ(സ)യോട് സാദൃശ്യമുള്ള ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. ഫാത്തിമ(റ) തിരുദൂതർ(സ)യുടെ അടുത്തേക്ക് ചെന്നാൽ റസൂൽ(സ) എഴുന്നേറ്റ് നിൽക്കുകയും മഹതിയുടെ കൈപിടിച്ച് അവരെ ഉമ്മവെക്കുകയും തന്റെ ഇരിപ്പിടത്തിൽ ഇരുത്തുകയും ചെയ്യുമായിരുന്നു. റസൂൽ(സ) മഹതിയുടെ അടുത്തേക്ക് വരുമ്പോൾ മഹതി എഴുന്നേറ്റ് നിന്ന് തിരുദൂതർ(സ)യുടെ കൈപിടിച്ച് ചുംബിക്കുകയും തന്റെ ഇരിപ്പിടത്തിൽ ഇരുത്തുകയും ചെയ്യുമായിരുന്നു. (ദ,തു)', 'أُمِّ الْمُؤْمِنِينَ عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 438, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي مِجْلَزٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ مُعَاوِيَةُ عَلَى ابْنِ الزُّبَيْرِ وَابْنِ عَامِرٍ، فَقَامَ ابْنُ عَامِرٍ وَجَلَسَ ابْنُ الزُّبَيْرِ، فَقَالَ مُعَاوِيَةُ لِابْنِ عَامِرٍ: اجْلِسْ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَحَبَّ أَنْ يَمْثُلَ لَهُ الرِّجَالُ قِيَامًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (د)', 'അബൂമിജ്‌ലസ്(റ): മുആവിയ(റ) ഇബ്നുആമിർ(റ)വിന്റെയും ഇബ്നുസുബൈർ(റ)വിന്റെയും അടുത്തേക്ക് ചെന്നപ്പോൾ ഇബ്നുആമിർ(റ) എഴുന്നേറ്റ് നിൽക്കുകയും ഇബ്നുസുബൈർ(റ) ഇരിക്കുകയും ചെയ്തു. അപ്പോൾ മുആവിയ(റ) ഇബ്നുആമിർ(റ)വിനോട് പറഞ്ഞു: താങ്കൾ ഇരിക്കുക, കാരണം തിരുദൂതർ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും തനിക്ക് വേണ്ടി ആളുകൾ എഴുന്നേറ്റ് നിൽക്കുന്നത് ഇഷ്ടപ്പെട്ടാൽ നരകത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ദ)', 'أَبِي مِجْلَزٍ', 'അബൂമിജ്‌ലസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُتَوَكِّئًا عَلَى عَصًا، فَقُمْنَا إِلَيْهِ، فَقَالَ: "لَا تَقُومُوا كَمَا تَقُومُ الْأَعَاجِمُ، يُعَظِّمُ بَعْضُهَا بَعْضًا". (د,جه)', 'അബൂഉമാമ(റ): റസൂൽ(സ) ഒരു വടി കുത്തിപ്പിടിച്ച് ഞങ്ങളുടെ അടുത്തേക്ക് വന്നപ്പോൾ ഞങ്ങളെല്ലാവരും എഴുന്നേറ്റ് നിന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ചിലർ ചിലരെ വന്ദിക്കാൻ വേണ്ടി, അനറബികൾ എഴുന്നേറ്റ് നിൽക്കും പോലെ നിങ്ങൾ എഴുന്നേറ്റ് നിൽക്കരുത്." (ദ,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمْ يَكُنْ شَخْصٌ أَحَبَّ إِلَيْهِمْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: وَكَانُوا إِذَا رَأَوْهُ لَمْ يَقُومُوا، لِمَا يَعْلَمُونَ مِنْ كَرَاهِيَتِهِ لِذَلِكَ. حَسَنٌ صَحِيحٌ. (ت)', 'അനസ്(റ): തിരുദൂതർ(സ)യേക്കാളും അവർ(സ്വഹാബികൾ)ക്കിഷ്ടപ്പെട്ട ഒരാളും ഉണ്ടായിരുന്നില്ല. അദ്ദേഹം പറഞ്ഞു: അവർ റസൂൽ(സ)യെ കണ്ടാൽ എഴുന്നേറ്റ് നിൽക്കുമായിരുന്നില്ല. കാരണം റസൂൽ(സ)ക്ക് അത് വെറുപ്പാണെന്നവർക്കറിയാം. (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي مِجْلَزٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ مُعَاوِيَةُ رَضِيَ اللهُ عَنْهُ، فَقَامَ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ وَابْنُ صَفْوَانَ حِينَ رَأَوْهُ، فَقَالَ: اجْلِسَا، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سَرَّهُ أَنْ يَتَمَثَّلَ لَهُ الرِّجَالُ قِيَامًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". حَسَنٌ. (د,ت,ن)', 'അബൂമിജ്‌ലസ്(റ): മുആവിയ(റ) വന്നപ്പോൾ ഇബ്നുസുബൈർ(റ)വും ഇബ്നുസ്വഫ്‌വാൻ(റ)വും എഴുന്നേറ്റുനിന്നു. അപ്പോൾ മുആവിയ(റ) പറഞ്ഞു: നിങ്ങൾ രണ്ടുപേരും ഇരിക്കുക. കാരണം, റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: "ആരെങ്കിലും ആളുകൾ എഴുന്നേറ്റ് നിന്ന് തന്നെ വന്ദിക്കുന്നത് ഇഷ്ടപ്പെട്ടാൽ നരകത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ദ,തു,ന)', 'أَبِي مِجْلَزٍ', 'അബൂമിജ്‌ലസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ الْفِهْرِيَّ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُنَيْنًا، فَسِرْنَا فِي يَوْمٍ قَائِظٍ شَدِيدِ الْحَرِّ، فَنَزَلْنَا تَحْتَ ظِلِّ الشَّجَرَةِ، فَلَمَّا زَالَتِ الشَّمْسُ لَبِسْتُ لَأْمَتِي وَرَكِبْتُ فَرَسِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي فُسْطَاطِهِ، فَقُلْتُ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، قَدْ حَانَ الرَّوَاحُ. قَالَ: "أَجَلْ". ثُمَّ قَالَ: "يَا بِلَالُ قُمْ". فَثَارَ مِنْ تَحْتِ سَمُرَةٍ كَأَنَّ ظِلَّهُ ظِلُّ طَائِرٍ، فَقَالَ: لَبَّيْكَ وَسَعْدَيْكَ وَأَنَا فِدَاؤُكَ، فَقَالَ: "أَسْرِجْ لِي الْفَرَسَ". فَأَخْرَجَ سَرْجًا دَفَّتَاهُ مِنْ لِيفٍ، لَيْسَ فِيهِ أَشَرٌ وَلَا بَطَرٌ، فَرَكِبَ وَرَكِبْنَا. (د)', 'അബൂ അബ്ദുർറഹ്മാനുൽ ഫിഹ്‌രീ(റ): റസൂൽ(സ)യോട് കൂടെ ഹുനൈനിൽ ഞാൻ പങ്കെടുത്തു. അങ്ങനെ കഠിനമായി ചൂടുള്ള ഒരു ദിവസം യാത്രചെയ്ത് ഞങ്ങൾ ഒരു മരത്തണലിൽ ഇറങ്ങി. അങ്ങനെ ഉച്ചക്ക് ശേഷം ഞാനെന്റെ പടയങ്കി ധരിച്ച് കുതിരപ്പുറത്ത് കയറി റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. തിരുദൂതർ(സ) തന്റെ തമ്പിലിരിക്കുകയായിരുന്നു. ഞാൻ തിരുദൂതർ(സ)യോട് ''അസ്സലാമു അലൈക്ക യാറസൂലല്ലാഹി വറഹ്മത്തുല്ലാഹി വബറകാത്തുഹു'' എന്ന് സലാം പറയുകയും പോകാൻ സമയമായെന്ന് പറയുകയും ചെയ്തു. തിരുദൂതർ(സ) പറഞ്ഞു: "അതെ." എന്നിട്ട് പറഞ്ഞു: "ബിലാൽ, എഴുന്നേൽക്കുക." ബിലാൽ(റ) മുള്ള് മരത്തിന്റെ ചുവട്ടിൽ നിന്നും എഴുന്നേറ്റു. ആ മരത്തിന്റെ നിഴൽ ഒരു പക്ഷിയുടെ നിഴൽ പോലെയുണ്ടായിരുന്നു. ബിലാൽ(റ) പറഞ്ഞു: ''ലബ്ബൈക വ സഅദൈക വഅന ഫിദാഉക'' (അങ്ങേക്ക് ഞാനുത്തരം ചെയ്യുന്നു. അങ്ങേക്ക് ഞാൻ ദണ്ഡമാണ്). റസൂൽ(സ) പറഞ്ഞു: "എന്റെ കുതിരക്ക് ജീനി ധരിപ്പിക്കുക." ബിലാൽ(റ) അഹങ്കാരമോ അനുസരണക്കേടോ ഇല്ലാതെ ജീനിയെടുത്തു. അതിന്റെ ഇരു ഭാഗങ്ങളും ചകിരിനാര് കൊണ്ടുള്ളതായിരുന്നു. അങ്ങനെ റസൂൽ(സ)യും ഞങ്ങളും വാഹനം കയറി. (ദ)', 'أَبِي عَبْدِ الرَّحْمَنِ الْفِهْرِيَّ', 'അബൂ അബ്ദുർറഹ്മാനുൽ ഫിഹ്‌രീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 440, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ مِرْدَاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ أَبُو بَكْرٍ أَوْ عُمَرُ: أَضْحَكَ اللَّهُ سِنَّكَ. (د,جه)', 'മിർദാസ്(റ): റസൂൽ(സ) ചിരിച്ചപ്പോൾ അബൂബക്ർ സിദ്ദീഖ്(റ) - അല്ലെങ്കിൽ ഉമർ(റ) പറഞ്ഞു: ''അള്ഹകല്ലാഹു സിന്നക'' (അല്ലാഹു നിങ്ങളുടെ പല്ലിനെ ചിരിപ്പിക്കട്ടെ). (ദ,ജ)', 'مِرْدَاسٍ', 'മിർദാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 440, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ". فَقُلْتُ: لَبَّيْكَ وَسَعْدَيْكَ يَا رَسُولَ اللَّهِ، وَأَنَا فِدَاكَ. (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) "അബൂദർറേ" എന്ന് വിളിച്ചു. ഞാൻ പറഞ്ഞു: ''ലബ്ബൈക വ സഅദൈക യാറസൂലല്ലാ, (അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഞാനിതാ അങ്ങേക്ക് ഉത്തരം നൽകുന്നു.) ഞാനങ്ങേക്ക് ബലിയാണ്. (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 440, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: مَا سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَمَعَ أَبَوَيْهِ لِأَحَدٍ غَيْرَ سَعْدِ بْن أَبِي وَقَّاصٍ. وفي رواية: مَا جَمَعَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبَاهُ وَأُمَّهُ لِأَحَدٍ إِلَّا لِسَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ لَهُ يَوْمَ أُحُدٍ: "ارْمِ فِدَاكَ أَبِي وَأُمِّي". وَقَالَ لَهُ: "ارْمِ أَيُّهَا الْغُلَامُ الْحَزَوَّرُ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അലി(റ): തിരുദൂതർ(സ), സഅ്ദുബ്നു അബീവഖാസ്(റ)വിനോടൊഴികെ വേറൊരാളോടും ഉമ്മയെയും ഉപ്പയെയും ഒരുമിച്ച് (ഫിദാക അബീ വഉമ്മീ എന്ന്) പറയുന്നതായി ഞാൻ കേട്ടിട്ടില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=156), 1, 'وَفِي رِوَايَةٍ: مَا جَمَعَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبَاهُ وَأُمَّهُ لِأَحَدٍ إِلَّا لِسَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ لَهُ يَوْمَ أُحُدٍ: "ارْمِ فِدَاكَ أَبِي وَأُمِّي". وَقَالَ لَهُ: "ارْمِ أَيُّهَا الْغُلَامُ الْحَزَوَّرُ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: സഅ്ദുബ്നു അബീവഖാസ്(റ)വിനോടല്ലാതെ ആരോടും റസൂൽ(സ) തന്റെ ഉമ്മയേയും ഉപ്പയേയും ഒരുമിച്ച് പറഞ്ഞിട്ടില്ല. റസൂൽ(സ) ഉഹ്ദ് ദിവസം സഅ്ദ്(റ)വിനോട് പറഞ്ഞു: "എന്റെ ഉമ്മയും ഉപ്പയും നിനക്ക് ബലിയാണ്, നീ അമ്പെറിയുക." പിന്നെ പറഞ്ഞു: "ശക്തനായ ചെറുപ്പക്കാരാ, നീ അമ്പെറിയുക." (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَمَعَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبَوَيْهِ يَوْمَ أُحُدٍ، قَالَ: "ارْمِ فِدَاكَ أَبِي وَأُمِّي". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): തിരുദൂതർ(സ) ഉഹ്ദ് ദിവസം തന്റെ മാതാവിനെയും പിതാവിനെയും എനിക്ക് ഒരുമിച്ച് പറഞ്ഞു: "നീ എറിയുക, എന്റെ മാതാവും പിതാവും നിനക്ക് ബലിയാണ്." (ബു,മു,തു,ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عِمْرَانِ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَقُولُ فِي الْجَاهِلِيَّةِ: أَنْعَمَ اللَّهُ بِكَ عَيْنًا، وَأَنْعِمْ صَبَاحًا، فَلَمَّا كَانَ الْإِسْلَامُ نُهِينَا عَنْ ذَلِكَ. (د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ഞങ്ങൾ ജാഹിലിയ്യാ കാലത്ത് ''അൻഅമല്ലാഹു ബിക ഐനൻ'' (അല്ലാഹു നിന്നെ അനുഗ്രഹിക്കട്ടെ) എന്നും ''അൻഇം സ്വബാഹൻ'' (നിനക്ക് നല്ല പ്രഭാതം ആശംസിക്കുന്നു) എന്നും പറയാറുണ്ടായിരുന്നു. പിന്നെ ഇസ്‌ലാം വന്നപ്പോൾ ഞങ്ങൾക്ക് അത് നിരോധിക്കപ്പെട്ടു. (ദ)', 'عِمْرَانِ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي سَفَرٍ لَهُ فَعَطِشُوا، فَانْطَلَقَ سَرْعَانُ النَّاسِ، فَلَزِمْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِلْكَ اللَّيْلَةَ، فَقَالَ: "حَفِظَكَ اللَّهُ بِمَا حَفِظْتَ بِهِ نَبِيَّهُ". (م,د,ت,ن)', 'അബൂഖതാദ(റ): ഒരു യാത്രക്കിടയിൽ നബി(സ)ക്കും കൂടെയുള്ളവർക്കും ദാഹം അനുഭവപ്പെട്ടു. ജനങ്ങളെല്ലാം പെട്ടെന്ന് പോയി. ഞാൻ ആ രാത്രി മുഴുവൻ റസൂൽ(സ)യുടെ കൂടെ കൂടി. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു തന്റെ പ്രവാചകനെ സംരക്ഷിച്ചതു കൊണ്ട് അല്ലാഹു നിന്നെയും സംരക്ഷിക്കട്ടെ". (മു,ദ,തു,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: ذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ فَوَجَدْتُهُ يَغْتَسِلُ، وَفَاطِمَةُ تَسْتُرُهُ بِثَوْبٍ، قَالَتْ: فَسَلَّمْتُ، فَقَالَ: "مَنْ هَذِهِ". قُلْتُ: أَنَا أُمُّ هَانِئٍ، فَقَالَ: "مَرْحَبًا بِأُمِّ هَانِئٍ". حَسَنٌ صَحِيحٌ. (ت,ن)', 'ഉമ്മുഹാനിഅ്(റ): മക്കാവിജയം നടന്ന വർഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നപ്പോൾ റസൂൽ(സ) കുളിക്കുകയായിരുന്നു. ഫാത്തിമ ബീവി(റ) ഒരു വസ്ത്രം കൊണ്ട് റസൂൽ(സ)യെ മറച്ചുപിടിക്കുന്നുണ്ട്. മഹതി പറയുന്നു: ഞാൻ സലാം പറഞ്ഞു. റസൂൽ(സ) ചോദിച്ചു: "ആരാണിത്?" ഞാൻ പറഞ്ഞു: ഉമ്മുഹാനിഅ്. റസൂൽ(സ) പറഞ്ഞു: "മർഹബൻ ബി ഉമ്മിഹാനിഅ്" (ഉമ്മുഹാനിഇന് സ്വാഗതം). (തു,ന)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عِكْرِمَةَ بْنِ أَبِي جَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ جِئْتُهُ: "مَرْحَبًا بِالرَّاكِبِ الْمُهَاجِرِ". (ت)', 'ഇക്‌രിമതുബ്നു അബീജഹ്ൽ(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്ന ദിവസം എന്നോട് പറഞ്ഞു: "മർഹബൻ ബിർറാകിബിൽ മുഹാജിർ. (പലായനം ചെയ്ത യാത്രക്കാരന് സ്വാഗതം)". (തു)', 'عِكْرِمَةَ بْنِ أَبِي جَهْلٍ', 'ഇക്‌രിമതുബ്നു അബീജഹ്ൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: كَيْفَ أَصْبَحْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: "بِخَيْرٍ، مِنْ رَجُلٍ لَمْ يُصْبِحْ صَائِمًا، وَلَمْ يَعُدْ سَقِيمًا". [ز: فِي سَنَدِهِ ضَعِيفٌ] (جه)', 'ജാബിർ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എപ്രകാരമാണ് നേരം പുലർന്നത്? റസൂൽ(സ) പറഞ്ഞു: "നന്മയോടെ, നോമ്പുകാരനായി പ്രഭാതത്തിൽ പ്രവേശിക്കുകയോ രോഗിയെ സന്ദർശിക്കുകയോ ചെയ്യാത്ത (അതിന് സാധിക്കാത്ത) എത്ര ആളുകളുണ്ട്." (ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബ്ബലനുണ്ട്). (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سَنَدِهِ ضَعِيفٌ', 'ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബ്ബലനുണ്ട്', 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَبِي أُسَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، وَدَخَلَ عَلَيْهِمْ، فَقَالَ: "السَّلَامُ عَلَيْكُمْ". قَالُوا: وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. قَالَ: "كَيْفَ أَصْبَحْتُمْ". قَالُوا: بِخَيْرٍ، نَحْمَدُ اللَّهَ، فَكَيْفَ أَصْبَحْتَ؟ بِأَبِينَا وَأُمِّنَا، يَا رَسُولَ اللَّهِ؟ قَالَ: "أَصْبَحْتُ بِخَيْرٍ، أَحْمَدُ اللَّهَ". (جه)', 'അബൂ ഉസൈദുസ്സാഇദീ(റ): റസൂൽ(സ) അബ്ബാസുബ്നു അബ്ദിൽ മുത്തലിബിന്റെ അടുത്ത് ചെന്ന് അവിടെയുള്ളവരോട് "അസ്സലാമു അലൈക്കും" എന്ന് പറഞ്ഞു. അവർ മറുപടി പറഞ്ഞു: ''വഅലൈക്കുമുസ്സലാം വറഹ്മതുല്ലാഹി വബറകാത്തുഹു'' എന്നിട്ട് റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളെങ്ങനെയാണ് പ്രഭാതത്തിൽ പ്രവേശിച്ചത്?" അവർ പറഞ്ഞു: വളരെ നന്മയോടെ, ഞങ്ങൾ അല്ലാഹുവിനെ സ്തുതിക്കുന്നു. ഞങ്ങളുടെ മാതാപിതാക്കൾ അങ്ങേക്ക് ബലിയാണ്, അല്ലാഹുവിന്റെ തിരുദൂതരേ, അങ്ങ് എങ്ങനെയാണ് പ്രഭാതത്തിൽ പ്രവേശിച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ വളരെ നന്മയോടുകൂടെയാണ് നേരം പുലർന്നത്. ഞാൻ അല്ലാഹുവിനെ സ്തുതിക്കുന്നു." (ജ)', 'أَبِي أُسَيْدٍ السَّاعِدِيِّ', 'അബൂ ഉസൈദുസ്സാഇദീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 442, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَمْسٌ تَجِبُ لِلْمُسْلِمِ عَلَى أَخِيهِ: رَدُّ السَّلَامِ، وَتَشْمِيتُ الْعَاطِسِ، وَإِجَابَةُ الدَّعْوَةِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്‌ലിമിന് തന്റെ കൂട്ടുകാരനോട് ബന്ധപ്പെട്ട അഞ്ച് കാര്യങ്ങൾ നിർബന്ധമാണ്: സലാം മടക്കൽ, തുമ്മിയവനെ അനുമോദിക്കൽ, ക്ഷണം സ്വീകരിക്കൽ, രോഗിയെ സന്ദർശിക്കൽ, ജനാസയെ അനുഗമിക്കൽ." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ". قِيلَ: مَا هُنَّ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِذَا لَقِيتَهُ فَسَلِّمْ عَلَيْهِ، وَإِذَا دَعَاكَ فَأَجِبْهُ، وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ - وفي رواية عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: "وَيَجِبُ لَهُ مَا يَجِبُ لِنَفْسِهِ". ، وفي رواية: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: "وَيَنْصَحُ لَهُ إِذَا غَابَ أَوْ شَهِدَ". - وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ فَشَمِّتْهُ، وَإِذَا مَرِضَ فَعُدْهُ، وَإِذَا مَاتَ فَاتَّبِعْهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്‌ലിമിന് മറ്റൊരു മുസ്‌ലിമിനോടുള്ള ബാധ്യതകൾ ആറെണ്ണമാണ്." അപ്പോൾ തിരുമേനി(സ)യോട് ചോദിക്കപ്പെട്ടു: അത് ഏതൊക്കെയാണ് റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "നീ അവനെ കണ്ടുമുട്ടിയാൽ സലാം പറയുക, ക്ഷണിച്ചാൽ ക്ഷണത്തിന് ഉത്തരം നൽകുക, നിന്നോട് ഉപദേശം തേടിയാൽ നീ അവനെ ഉപദേശിക്കുക, - അലി(റ)വിൽ നിന്നുള്ള നിവേദനത്തിൽ ''ഉപദേശം തേടിയാൽ ഉപദേശം നൽകുക'' എന്നതിനു പകരം ''താനിഷ്ടപ്പെടുന്നത് അവന് വേണ്ടി ഇഷ്ടപ്പെടുക'' എന്നാണ്. അബൂഹുറൈറ(റ)വിൽനിന്നുള്ള മറ്റൊരു നിവേദനത്തിൽ: ''അവൻ സന്നിഹിതനായാലും അപ്രത്യക്ഷനായാലും അവനെ ഉപദേശിക്കുക എന്നുമാണ്. - അവൻ തുമ്മിയിട്ട് ''അൽഹംദു ലില്ലാ'' (അല്ലാഹുവിനു സ്തുതി) എന്ന് പറഞ്ഞാൽ ''യർഹമുകല്ലാ'' (അല്ലാഹു നിനക്ക് കരുണ ചെയ്യട്ടെ) എന്ന് പറയുക, അവൻ രോഗിയായാൽ പോയി സന്ദർശിക്കുക, അവൻ മരിച്ചാൽ അവനെ അനുഗമിക്കുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=165), 1, 'وَفِي رِوَايَةٍ عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: "وَيَجِبُ لَهُ مَا يَجِبُ لِنَفْسِهِ". ،', 'മറ്റൊരു നിവേദനത്തിൽ: ''അവൻ സന്നിഹിതനായാലും അപ്രത്യക്ഷനായാലും അവനെ ഉപദേശിക്കുക എന്നുമാണ്. - അവൻ തുമ്മിയിട്ട് ''അൽഹംദു ലില്ലാ'' (അല്ലാഹുവിനു സ്തുതി) എന്ന് പറഞ്ഞാൽ ''യർഹമുകല്ലാ'' (അല്ലാഹു നിനക്ക് കരുണ ചെയ്യട്ടെ) എന്ന് പറയുക, അവൻ രോഗിയായാൽ പോയി സന്ദർശിക്കുക, അവൻ മരിച്ചാൽ അവനെ അനുഗമിക്കുക." (മു)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=165), 2, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: "وَيَنْصَحُ لَهُ إِذَا غَابَ أَوْ شَهِدَ". - وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ فَشَمِّتْهُ، وَإِذَا مَرِضَ فَعُدْهُ، وَإِذَا مَاتَ فَاتَّبِعْهُ". (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْعُطَاسُ مِنَ اللَّهِ وَالتَّثَاؤُبُ مِنَ الشَّيْطَانِ، فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَضَعْ يَدَهُ عَلَى فِيهِ، وَإِذَا قَالَ: آهْ آهْ، فَإِنَّ الشَّيْطَانَ يَضْحَكُ مِنْ جَوْفِهِ، وَإِنَّ اللَّهَ يُحِبُّ الْعُطَاسَ وَيَكْرَهُ التَّثَاؤُبَ، فَإِذَا قَالَ الرَّجُلُ: آهْ آهْ، إِذَا تَثَاءَبَ فَإِنَّ الشَّيْطَانَ يَضْحَكُ فِي جَوْفِهِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തുമ്മൽ അല്ലാഹുവിൽ നിന്നും കോട്ടുവായ ശൈത്വാനിൽ നിന്നുമാണ്. നിങ്ങളിൽനിന്നാരെങ്കിലും കോട്ടുവായയിട്ടാൽ കൈ വായക്കുമീതെ വെക്കട്ടെ. അവൻ ''ആഹ്, ആഹ്'' എന്ന് പറയുമ്പോൾ ശൈത്വാൻ അവന്റെ ഉള്ളിൽ നിന്ന് ചിരിക്കും. നിശ്ചയമായും അല്ലാഹു തുമ്മൽ ഇഷ്ടപ്പെടുകയും കോട്ടുവായ വെറുക്കുകയും ചെയ്യുന്നു. ഒരുവൻ കോട്ടുവായയിടുന്ന സമയത്ത് ''ആഹ്, ആഹ്'' എന്ന് പറഞ്ഞാൽ നിശ്ചയമായും ശൈത്വാൻ അവന്റെയുള്ളിൽ നിന്ന് ചിരിക്കും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 443, 444, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يُحِبُّ الْعُطَاسَ وَيَكْرَهُ التَّثَاؤُبَ، فَإِذَا عَطَسَ أَحَدُكُمْ فَقَالَ: الْحَمْدُ لِلَّهِ، فَحَقٌّ عَلَى كُلِّ مَنْ سَمِعَهُ أَنْ يَقُولَ: يَرْحَمُكَ اللَّهُ. وَأَمَّا التَّثَاؤُبُ: فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَرُدَّهُ مَا اسْتَطَاعَ، وَلَا يَقُولُ: هَاهْ هَاهْ، فَإِنَّمَا ذَلِكَ مِنَ الشَّيْطَانِ، يَضْحَكُ مِنْهُ". صَحِيحٌ (خ,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയമായും അല്ലാഹു തുമ്മൽ ഇഷ്ടപ്പെടുകയും കോട്ടുവായ വെറുക്കുകയും ചെയ്യുന്നു. നിങ്ങളിൽനിന്നാരെങ്കിലും തുമ്മിയാൽ അവൻ ''അൽഹംദു ലില്ലാ'' (സർവ്വ സ്തുതിയും അല്ലാഹുവിനാണ്) എന്ന് പറയട്ടെ. അത് കേട്ട ഓരോരുത്തരും ''യർഹമുകല്ലാ'' (നിനക്ക് അല്ലാഹു റഹ്മത് ചെയ്യട്ടെ) എന്ന് പറയൽ നിർബന്ധമാണ്. നിങ്ങളിലാരെങ്കിലും കോട്ടുവായയിട്ടാൽ കഴിവിന്റെ പരമാവധി അവൻ അതിനെ മടക്കിയയക്കട്ടെ. അവൻ ''ആഹ് ആഹ്'' എന്ന് പറയരുത്. കാരണം അത് ശൈത്വാനിൽ നിന്നുള്ളതാണ്. അതുകാരണം ശൈത്വാൻ ചിരിക്കുന്നതാണ്." (ബു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 444, 444, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ عَلَى فِيهِ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ". وَفِي رِوَايَةٍ: "فِي الصَّلَاةِ... فَلْيَكْظِمْ مَا اسْتَطَاعَ". (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽനിന്നാരെങ്കിലും കോട്ടുവായിടുകയാണെങ്കിൽ അവന്റെ വായക്ക് മീതെ അവൻ പിടിച്ചുകൊള്ളട്ടെ. കാരണം ശൈത്വാൻ പ്രവേശിക്കും." മറ്റൊരു നിവേദനത്തിൽ: "നിസ്കാരത്തിലാണെങ്കിൽ, അവന്റെ കഴിവിന്റെ പരമാവധി അവൻ ഒതുക്കിക്കൊള്ളട്ടെ." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 444, 444, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=168), 1, 'وَفِي رِوَايَةٍ: "فِي الصَّلَاةِ... فَلْيَكْظِمْ مَا اسْتَطَاعَ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "നിസ്കാരത്തിലാണെങ്കിൽ, അവന്റെ കഴിവിന്റെ പരമാവധി അവൻ ഒതുക്കിക്കൊള്ളട്ടെ." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الْيَهُودُ يَتَعَاطَسُونَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَرْجُونَ أَنْ يَقُولَ لَهُمْ: يَرْحَمُكُمُ اللَّهُ، فَيَقُولُ: "يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബൂമൂസാ(റ): റസൂൽ(സ) ''യർഹമുകല്ലാ'' (നിങ്ങൾക്ക് അല്ലാഹു അനുഗ്രഹം ചെയ്യട്ടെ) എന്ന പറയുന്നതും പ്രതീക്ഷിച്ച് യഹൂദികൾ തിരുമേനി(സ)യുടെ അടുക്കൽ വെച്ച് പരസ്പരം തുമ്മാറുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) അവരോട് ഇപ്രകാരമാണ് പറഞ്ഞിരുന്നത്: "യഹ്ദീകുമുല്ലാഹു വയുസ്‌ലിഹ് ബാലകും." (അല്ലാഹു നിങ്ങളെ സന്മാർഗത്തിലാക്കുകയും നിങ്ങളുടെ അവസ്ഥ നന്നാക്കുകയും ചെയ്യട്ടെ). (ദ,തു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 444, 444, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ سَالِمِ بْنِ عُبَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ مَعَ الْقَوْمِ فِي سَفَرٍ، فَعَطَسَ رَجُلٌ مِنَ الْقَوْمِ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَقَالَ: وَعَلَيْكَ وَعَلَى أُمِّكَ. ثُمَّ قَالَ بَعْدُ: لَعَلَّكَ وَجَدْتَ مِمَّا قُلْتُ لَكَ، قَالَ: لَوَدِدْتُ أَنَّكَ لَمْ تَذْكُرْ أُمِّي بِخَيْرٍ وَلَا بِشَرٍّ؟ قَالَ: إِنَّمَا قُلْتُ لَكَ كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّا بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ عَطَسَ رَجُلٌ مِنَ الْقَوْمِ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَعَلَيْكَ وَعَلَى أُمِّكَ". ثُمَّ قَالَ: "إِذَا عَطَسَ أَحَدُكُمْ فَلْيَحْمَدِ اللَّهَ". قَالَ: فَذَكَرَ بَعْضَ الْمَحَامِدِ "وَلْيَقُلْ لَهُ مَنْ عِنْدَهُ: يَرْحَمُكَ اللَّهُ، وَلْيَرُدَّ -يَعْنِي عَلَيْهِمْ- يَغْفِرُ اللَّهُ لَنَا وَلَكُمْ". (د,ت)', 'സാലിമുബ്നു ഉബൈദ്(റ): അദ്ദേഹം കുറച്ചാളുകളോട് കൂടെ ഒരു യാത്രയിലായിരിക്കെ അവരിലൊരാൾ തുമ്മുകയും ''അസ്സലാമുഅലൈക്കും'' എന്ന് പറയുകയും ചെയ്തു. അപ്പോൾ സാലിം(റ) പറഞ്ഞു: നിനക്കും നിന്റെ ഉമ്മാക്കും രക്ഷയുണ്ടാകട്ടെ. ശേഷം സാലിം(റ) പറഞ്ഞു: ഞാൻ പറഞ്ഞത് നിനക്ക് മനോവിശമമുണ്ടാക്കിയിട്ടുണ്ടാകും. അയാൾ പറഞ്ഞു: താങ്കൾ എന്റെ ഉമ്മയെക്കുറിച്ച് നന്മയോ തിന്മയോ പറയാതിരിക്കണമെന്നാണ് എന്റെ ആഗ്രഹം. സാലിം(റ) പറഞ്ഞു: നബി(സ) തങ്ങൾ പറഞ്ഞതല്ലാതെ ഞൻ പറഞ്ഞിട്ടില്ല. തിരുമേനി(സ)യുടെ അടുക്കൽവെച്ച് ഒരുത്തൻ തുമ്മുകയും ''അസ്സലാമു അലൈക്കും'' എന്ന് പറയുകയും ചെയ്തപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അലയ്ക്ക വഅലാ ഉമ്മിക'' (നിനക്കും നിന്റെ മാതാവിനും രക്ഷയുണ്ടാവട്ടെ), തുടർന്ന് അവിടന്ന് പറഞ്ഞു: "നിങ്ങളിൽ നിന്നൊരാൾ തുമ്മിയാൽ അവൻ ''അൽഹംദുലില്ലാഹ്'' (അല്ലാഹുവിനാണ് സർവസ്തുതിയും) എന്ന് പറയട്ടെ." നിവേദകൻ പറയുന്നു: അവിടന്ന് ചില പ്രകീർത്തന വചനം ഉരുവിട്ടു. (തുടർന്ന് പറഞ്ഞു): "അവന്റെയടുത്തുള്ളവൻ ''യർഹമുകല്ലാഹ്'' (നിനക്കല്ലാഹു റഹ്മത്ത് ചെയ്യട്ടെ) എന്നും, തുമ്മിയവൻ ''യഗ്ഫിറുല്ലാഹു ലനാ വലകും'' (അല്ലാഹു നിങ്ങൾക്കും നമുക്കും പൊറുത്തുതരട്ടെ) എന്നും പറയണം. (ദ,തു)', 'سَالِمِ بْنِ عُبَيْدٍ', 'സാലിമുബ്നു ഉബൈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 444, 445, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلِ: الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، وَلْيَقُلِ الَّذِي يَرُدُّ عَلَيْهِ: يَرْحَمُكَ اللَّهُ، وَلْيَقُلْ هُوَ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ". (خ,د,ت)', 'അബൂഅയ്യൂബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും തുമ്മിയാൽ അവൻ ''അൽഹംദുലില്ലാഹി അലാ കുല്ലിഹാൽ'' (എല്ലാ അവസ്ഥയിലും അല്ലാഹുവിനാണ് സർവസ്തുതിയും) എന്ന് പറയട്ടെ. അവന് മടക്കുന്നവൻ ''യർഹമുകല്ലാഹ്'' (അല്ലാഹു താങ്കൾക്ക് കരുണ ചെയ്യട്ടെ) എന്നും അപ്പോൾ തുമ്മിയവൻ ''യഹ്ദീകുമുല്ലാഹു വയുസ്‌ലിഹ് ബാലകും'' (അല്ലാഹു നിങ്ങളെ സന്മാർഗത്തിലാക്കുകയും നിങ്ങളുടെ അവസ്ഥ നന്നാക്കുകയും ചെയ്യട്ടെ) എന്നും പറയട്ടെ." (ബു,ദ,തു)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 445, 445, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: عَطَسَ رَجُلٌ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا شَاهِدٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَرْحَمُكَ اللَّهُ". ثُمَّ عَطَسَ الثَّانِيَةَ وَالثَّالِثَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا رَجُلٌ مَزْكُومٌ". حَسَنٌ صَحِيحٌ. وَفِي رِوَايَةٍ عَنْهُ: أَنَّ رَجُلًا عَطَسَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَرْحَمُكَ اللهُ". ثُمَّ عَطَسَ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرَّجُلُ مَزْكُومٌ". (م,د,ت,ن,جه)', 'സലമതുബ്നുൽ അക്‌വഅ്(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെയുണ്ടായിരിക്കെ ഒരാൾ തുമ്മി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "യർഹമുകല്ലാഹ്." അയാൾ രണ്ടാം പ്രാവശ്യവും മൂന്നാം പ്രാവശ്യവും തുമ്മി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇയാൾ ജലദോശം ബാധിച്ചവനാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=172), 1, 'وَفِي رِوَايَةٍ عَنْهُ: أَنَّ رَجُلًا عَطَسَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَرْحَمُكَ اللهُ". ثُمَّ عَطَسَ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرَّجُلُ مَزْكُومٌ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)യുടെ അടുത്ത് വെച്ച് ഒരാൾ തുമ്മുകയുണ്ടായി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "യർഹമുകല്ലാ" വീണ്ടും അയാൾ തുമ്മിയപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഇയാൾ ജലദോഷം പിടിച്ചവനാണ്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عُبَيْدِ بْنِ رِفَاعَةَ الْأَنْصَارِي رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُشَمَّتُ الْعَاطِسُ ثَلَاثًا، فَإِنْ زَادَ: فَإِنْ شِئْتَ فَشَمِّتْهُ، وَإِنْ شِئْتَ فَلَا". مرسل (د,ت)', 'ഉബൈദുബ്നു രിഫാഅതൽ അൻസാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "തുമ്മിയവനെ മൂന്ന് പ്രാവശ്യം അനുമോദിക്കണം. അതിൽ അധികമായി തുമ്മിയാൽ നിനക്ക് അനുമോദിക്കുകയോ അനുമോദിക്കാതിരിക്കുകയോ ചെയ്യാം." (ഹദീസ് മുർസലാണ്.) (ദ,തു)', 'عُبَيْدِ بْنِ رِفَاعَةَ الْأَنْصَارِي', 'ഉബൈദുബ്നു രിഫാഅതൽ അൻസാരി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 445, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلَيْنِ عَطَسَا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَشَمَّتَ أَحَدَهُمَا وَلَمْ يُشَمِّتِ الْآخَرَ، فَقَالَ الَّذِي لَمْ يُشَمِّتْهُ: يَا رَسُولَ اللَّهِ، شَمَّتَّ هَذَا وَلَمْ تُشَمِّتْنِي؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ حَمِدَ اللَّهَ، وَإِنَّكَ لَمْ تَحْمَدِ اللَّهَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ അടുക്കൽ വെച്ച് രണ്ടാളുകൾ തുമ്മിയപ്പോൾ റസൂൽ(സ) ഒരാളെ അനുമോദിച്ചു. രണ്ടാമത്തെയാളെ അനുമോദിച്ചില്ല. അപ്പോൾ അയാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഇയാളെ അനുമോദിച്ചു, എന്നെ അനുമോദിച്ചില്ല? റസൂൽ(സ) പറഞ്ഞു: "അയാൾ അല്ലാഹുവിനെ സ്തുതിച്ചു. നീ സ്തുതിച്ചില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ نَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا عَطَسَ إِلَى جَنْبِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: الْحَمْدُ لِلَّهِ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ ابْنُ عُمَرَ: وَأَنَا أَقُولُ: الْحَمْدُ لِلَّهِ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، وَلَيْسَ هَكَذَا عَلَّمَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَلَّمَنَا أَنْ نَقُولَ: "الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ". (ت)', 'നാഫിഅ്(റ): ഒരാൾ ഇബ്നുഉമർ(റ)വിന്റെ അരികിൽ വെച്ച് തുമ്മുകയും അൽഹംദുലില്ലാഹി വസ്സലാമു അലാ റസൂലില്ലാഹി (സർവ്വസ്തുതിയും അല്ലാഹുവിന്നാണ്. അല്ലാഹുവിന്റെ ദൂതർക്ക് മേൽ രക്ഷയുണ്ടാവട്ടെ.) എന്ന് പറയുകയും ചെയ്തു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഞാൻ പറയുന്നു: ''അൽഹംദുലില്ലാഹി വസ്സലാമുഅലാ റസൂലില്ലാഹ് (സർവ്വസ്തുതിയും അല്ലാഹുവിന്നാണ്. അല്ലാഹുവിന്റെ റസൂലിന്റെമേൽ രക്ഷയുണ്ടാവട്ടെ.)'' ഇങ്ങനെയല്ല റസൂൽ(സ) ഞങ്ങളെ പഠിപ്പിച്ചത്." ''അൽഹംദുലില്ലാഹി അലാ കുല്ലിഹാൽ'' (സർവ അവസ്ഥയിലും അല്ലാഹുവിനാണ് സ്തുതി) എന്ന് പറയാനാണ് അവിടന്ന് ഞങ്ങളെ പഠിപ്പിച്ചത്. (തു)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا عَطَسَ غَطَّى وَجْهَهُ بِيَدِهِ أَوْ بِثَوْبِهِ، وَغَضَّ بِهَا صَوْتَهُ. حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) തുമ്മിയാൽ തന്റെ കരം കൊണ്ടോ വസ്ത്രം കൊണ്ടോ മുഖം പൊത്തുകയും അത് കൊണ്ട് (കൈ അല്ലെങ്കിൽ വസ്ത്രം) ശബ്ദം താഴ്ത്താറുമുണ്ടായിരുന്നു. (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُم عَلَيْهِ وَسَلَّمَ إِذَا عَطَسَ وَضَعَ يَدَهُ - أَوْ ثَوْبَهُ- عَلَى فِيهِ، وَخَفَضَ -أَوْ غَضَّ- بِهَا صَوْتَهُ. (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) തുമ്മിയാൽ തന്റെ കൈ - അല്ലെങ്കിൽ വസ്ത്രം - വായമേൽ വെക്കുകയും ശബ്ദം കുറക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 446, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عَدِيِّ بْنِ ثَابِتِ الْأَنْصَارِي عَنْ أَبِيهِ عَنْ جَدِّهِ - رَفَعَهُ - قَالَ: "الْعُطَاسُ وَالنُّعَاسُ وَالتَّثَاؤُبُ فِي الصَّلَاةِ، وَالْحَيْضُ وَالْقَيْءُ وَالرُّعَافُ، مِنَ الشَّيْطَانِ". (ت,جه)', 'അദിയ്യുബ്നു സാബിതിൽ അൻസാരി(റ) തന്റെ പിതാവിൽ നിന്ന്, അദ്ദേഹം തന്റെ പിതാവിൽ നിന്നും മർഫൂആക്കി നിവേദനം ചെയ്യുന്നു: "നിസ്കാരത്തിൽ തുമ്മലും തൂങ്ങിയുറങ്ങലും, കോട്ടുവായിടലും, ആർത്തവവും ഛർദ്ദിയും മൂക്കിൽ നിന്ന് രക്തം വരലും പിശാചിൽ നിന്നുള്ളതാണ്." (തു,ജ)', 'عَدِيِّ بْنِ ثَابِتِ الْأَنْصَارِي عَنْ أَبِيهِ عَنْ جَدِّهِ - رَفَعَهُ - قَالَ', 'അദിയ്യുബ്നു സാബിതിൽ അൻസാരി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي بُرْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتِ الْيَهُودُ تَعَاطَسُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَاءَ أَنْ يَقُولَ لَهَا: يَرْحَمُكُمُ اللَّهُ، فَكَانَ يَقُولُ: "يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ". (د,ت)', 'അബൂബുർദ(റ): തങ്ങളോട് ''അല്ലാഹു നിങ്ങൾക്ക് കരുണ ചെയ്യട്ടെ'' എന്ന് പറയാൻ വേണ്ടി ജൂതന്മാർ നബി(സ)യുടെ അടുക്കൽ തുമ്മാറുണ്ടായിരുന്നു. എന്നാൽ അവിടന്ന് "അല്ലാഹു നിങ്ങളെ നേർമാർഗത്തിലാക്കുകയും നിങ്ങളുടെ അവസ്ഥ നന്നാക്കുകയും ചെയ്യട്ടെ" എന്നാണ് പറഞ്ഞിരുന്നത്. (ദ,തു)', 'أَبِي بُرْدَةَ', 'അബൂബുർദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ سَعِيدِ بْنِ أَبِي الْحَسَنِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَنَا أَبُو بَكْرَةَ فِي شَهَادَةٍ، فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ، فَأَبَى أَنْ يَجْلِسَ فِيهِ، وَقَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ذَا، وَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمْسَحَ الرَّجُلُ يَدَهُ بِثَوْبِ مَنْ لَمْ يَكْسُهُ. (د)', 'സഈദുബ്നു അബിൽ ഹസൻ(റ): അബൂബക്റത്(റ) ചില തെളിവുകൾ നൽകാൻ ഞങ്ങളുടെ അടുക്കൽ വന്നപ്പോൾ അദ്ദേഹത്തിന് ഒരാൾ തന്റെ ഇരിപ്പിടത്തിൽ നിന്ന് എഴുന്നേറ്റുകൊടുത്തു. അപ്പോൾ അദ്ദേഹമവിടെ ഇരിക്കാൻ വിസമ്മതിച്ച് പറഞ്ഞു: നിശ്ചയം നബി(സ) ഇത് നിരോധിച്ചിരിക്കുന്നു. ഒരാളുടെ വസ്ത്രം അയാൾ നൽകിയിട്ടില്ലെങ്കിൽ അത് കൊണ്ട് മറ്റൊരാൾ തന്റെ കൈ തുടക്കുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ)', 'سَعِيدِ بْنِ أَبِي الْحَسَنِ', 'സഈദുബ്നു അബിൽ ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ، فَذَهَبَ لِيَجْلِسَ فِيهِ، فَنَهَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ت)', 'ഇബ്നുഉമർ(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് വന്നു. അപ്പോൾ അയാൾക്കായി ഒരാൾ തന്റെ ഇരിപ്പിടത്തിൽ നിന്നെഴുന്നേറ്റുകൊടുത്തു. ഉടൻ അയാളവിടെ ഇരിക്കാനൊരുങ്ങിയപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ വിലക്കി. (ബു,മു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ مَثَلُ الْأُتْرُجَّةِ: رِيحُهَا طَيِّبٌ وَطَعْمُهَا طَيِّبٌ، وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ: طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا، وَمَثَلُ الْفَاجِرِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ: رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ، وَمَثَلُ الْفَاجِرِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ الْحَنْظَلَةِ: طَعْمُهَا مُرٌّ وَلَا رِيحَ لَهَا. وَمَثَلُ الْجَلِيس الصَّالِح كَمَثَل صَاحِب الْمِسْكِ: إِنْ لَمْ يُصِبْكَ مِنْهُ شَيْءٌ أَصَابَكَ مِنْ رِيحِهِ، وَمَثَلُ جَلِيسِ السُّوءِ كَمَثَلِ صَاحِبِ الْكِيرِ: إِنْ لَمْ يُصِبْكَ مِنْ سَوَادِهِ أَصَابَكَ مِنْ دُخَانِهِ". (د)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=182), 1, 'وَفِي رِوَايَةٍ: عَنْ أَنَسٍ، عَنْ أَبِي مُوسَى، رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بِهَذَا الْكَلَامِ الْأَوَّلِ إِلَى قَوْلِهِ: "وَطَعْمُهَا مُرٌّ".', 'മറ്റൊരു നിവേദനത്തിൽ: അനസ്(റ) അബൂമൂസ(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: മുകളിലുദ്ധരിച്ച ഹദീസിലെ ''അതിന്റെ രുചി കൈപാണ്'' എന്നത് വരെ റസൂൽ(സ) പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=182), 2, 'وَفِي رِوَايَةٍ: قَالَ أَنَسٌ رَضِيَ اللهُ عَنْهُ: وَكُنَّا نَتَحَدَّثُ أَنَّ مَثَلَ جَلِيسِ الصَّالِحِ، وَسَاقَ بَقِيَّةَ الْحَدِيثِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: അനസ്(റ) പറഞ്ഞു: ഞങ്ങൾ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: നിശ്ചയം നല്ല കൂട്ടുകാരന്റെ ഉപമ... ശേഷം മുൻ പ്രസ്താവ്യങ്ങൾതന്നെ. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، عَنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "لَا تُصَاحِبْ إِلَّا مُؤْمِنًا، وَلَا يَأْكُلْ طَعَامَكَ إِلَّا تَقِيٌّ". (د,ت)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിനിനോടല്ലാതെ നീ കൂട്ടുകൂടരുത്. തഖ്‌വയുള്ളവനൊഴികെ നിന്റെ ഭക്ഷണം കഴിക്കരുത്." (ദ,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرَّجُلُ عَلَى دِينِ خَلِيلِهِ، فَلْيَنْظُرْ أَحَدُكُمْ مَنْ يُخَالِلُ". (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മനുഷ്യൻ തന്റെ കൂട്ടുകാരന്റെ ദീനിലാണ്. അതിനാൽ നിങ്ങളിലോരോരുത്തരും താൻ ആരോട് കൂട്ടുകൂടുന്നുവെന്ന് നോക്കട്ടെ." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: يَرْفَعُهُ قَالَ: "الْأَرْوَاحُ جُنُودٌ مُجَنَّدَةٌ، فَمَا تَعَارَفَ مِنْهَا ائْتَلَفَ، وَمَا تَنَاكَرَ مِنْهَا اخْتَلَفَ". (م,د)', 'അബൂഹുറൈറ(റ) - മർഫൂആക്കി നിവേദനം ചെയ്യുന്നു: "ആത്മാക്കൾ ഒരുമിച്ചുകൂട്ടപ്പെട്ട കൂട്ടങ്ങളാകുന്നു. അവയിൽ പരസ്പരം തിരിച്ചറിഞ്ഞവർ ഇണങ്ങി, തിരിച്ചറിയാത്തവർ ഭിന്നിക്കുകയും ചെയ്തു." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 448, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَامَ أَحَدُكُمْ - وَفِي حَدِيثِ أَبِي عَوَانَةَ: مَنْ قَامَ - مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ". (م,د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരുവൻ തന്റെ ഇരിപ്പിടത്തിൽ നിന്ന് എഴുൽക്കുകയും - അബൂ അവാനയുടെ ഹദീസിൽ: ആരെങ്കിലും തന്റെ ഇരിപ്പിടത്തിൽ നിന്ന് എഴുന്നേൽക്കുകയും - പിന്നീടങ്ങോട്ട് തന്നെ മടങ്ങി വരികയും ചെയ്താൽ അവനാണതിന്റെ അവകാശി." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ وَهْبِ بْنِ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الرَّجُلُ أَحَقُّ بِمَجْلِسِهِ، وَإِنْ خَرَجَ لِحَاجَتِهِ ثُمَّ عَادَ فَهُوَ أَحَقُّ بِمَجْلِسِهِ". حَسَنٌ صَحِيحٌ. (ت)', 'വഹ്ബുബ്നു ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരുത്തൻ തന്റെ ഇരിപ്പിടത്തിന്റെ അവകാശിയാണ്. അവൻ തന്റെ ആവശ്യത്തിന് പുറത്തുപോയി പിന്നീട് മടങ്ങിവന്നാലും അവൻ തന്നെയാണ് തന്റെ ഇരിപ്പിടത്തിന്റെ വകാശി." (തു)', 'وَهْبِ بْنِ حُذَيْفَةَ', 'വഹ്ബുബ്നു ഹുദൈഫ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا جَلَسَ وَجَلَسْنَا حَوْلَهُ، فَقَامَ فَأَرَادَ الرُّجُوعَ نَزَعَ نَعْلَيْهِ أَوْ بَعْضَ مَا يَكُونُ عَلَيْهِ، فَيَعْرِفُ ذَلِكَ أَصْحَابُهُ، فَيَثْبُتُونَ. (د)', 'അബൂദ്ദർദാഅ്(റ): റസൂൽ(സ)യുടെ ചുറ്റും ഞങ്ങളിരുന്ന് അവിടന്ന് എണീക്കുകയും മടങ്ങിവരാൻ ഉദ്ദേശിക്കുകയും ചെയ്താൽ തന്റെ ചെരുപ്പോ അല്ലെങ്കിൽ മറ്റുവല്ലതുമോ ഊരിവെക്കാറുണ്ടായിരുന്നു. അങ്ങനെ അത് തന്റെ അനുചരർ മനസ്സിലാക്കുകയും അവർ ആ സ്ഥലം (തിരുമേനി(സ)ക്ക് വേണ്ടി) സ്ഥിരപ്പെടുത്തുകയും ചെയ്തിരുന്നു. (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ قَوْمٍ يَقُومُونَ مِنْ مَجْلِسٍ لَا يَذْكُرُونَ اللَّهَ فِيهِ إِلَّا قَامُوا عَنْ مِثْلِ جِيفَةِ حِمَارٍ. وَكَانَ لَهُمْ حَسْرَةً". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ സ്മരിക്കാത്ത സദസ്സിൽ നിന്ന് ഒരു കൂട്ടരും എഴുന്നേറ്റിട്ടില്ല, അവർ ചത്ത കഴുതയുടെ പക്കൽ നിന്നെന്ന പോലെ എഴുന്നേറ്റിട്ടല്ലാതെ. അവർക്ക് അത് ഒരു ഖേദം ആയിത്തീരുന്നു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَعَدَ مَقْعَدًا لَمْ يَذْكُرِ اللَّهَ فِيهِ كَانَتْ عَلَيْهِ مِنَ اللَّهِ تِرَةٌ، وَمَنِ اضْطَجَعَ مَضْجَعًا لَا يَذْكُرُ اللَّهَ فِيهِ كَانَتْ عَلَيْهِ مِنَ اللَّهِ تِرَةٌ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനെ സ്മരിക്കാതെ ഒരു സദസ്സിലിരുന്നാൽ അവന്ന് അല്ലാഹുവിൽ നിന്ന് ഒരു കോപം ഉണ്ടാകുന്നു. അല്ലാഹുവിനെ സ്മരിക്കാതെ ആരെങ്കിലും ഒരു കിടപ്പറയിൽ കിടന്നാൽ അവന്റെ മേൽ അല്ലാഹുവിങ്കൽ നിന്ന് ഒരു കോപം ഉണ്ടാകുന്നു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 449, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: كَلِمَاتٌ لَا يَتَكَلَّمُ بِهِنَّ أَحَدٌ فِي مَجْلِسِهِ عِنْدَ قِيَامِهِ ثَلَاث مَرَّاتٍ إِلَّا كُفِّرَ بِهِنَّ عَنْهُ، وَلَا يَقُولُهُنَّ فِي مَجْلِسِ خَيْرٍ وَمَجْلِسِ ذِكْرٍ إِلَّا خُتِمَ لَهُ بِهِنَّ عَلَيْهِ، كَمَا يُخْتَمُ بِالْخَاتَمِ عَلَى الصَّحِيفَةِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. وفي رواية: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِثْلَهُ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മൂന്ന് വചനങ്ങളുണ്ട്, ആരെങ്കിലും സദസ്സിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ അത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞാൽ അവകാരണം അവന് പാപമോചനം ലഭിക്കുകതന്നെ ചെയ്യും. ഒരു നന്മയുടെ സദസ്സിലോ ദിക്റിന്റെ സദസ്സിലോ അവൻ അത് പറഞ്ഞാൽ എഴുത്തുകടലാസ് സീൽ കൊണ്ട് സീൽ ചെയ്യുന്നതുപോലെ അത് കൊണ്ട് ആ സദസ്സ് സീൽ ചെയ്യപ്പെടുന്നതാണ്. അത് സുബ്ഹാനകല്ലാഹുമ്മ വബിഹംദിക, ലാഇലാഹ ഇല്ലാ അൻത, അസ്തഗ്ഫിറുക വ അതൂബു ഇലൈക. (അല്ലാഹുവേ, നീ എത്ര പരിശുദ്ധൻ! ഞാൻ നിന്നെ വാഴ്ത്തുന്നു. നീയല്ലാതെ ആരാധ്യനില്ല. ഞാൻ നിന്നോട് പൊറുക്കൽ തേടുകയും നിന്നിലേക്ക് ഖേദിച്ച്മടങ്ങുകയും ചെയ്യുന്നു). എന്നിവയാണ്
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=191), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِثْلَهُ. (د,ت,ن)', 'മറ്റൊരു നിവേദനം: അബൂഹുറൈറ(റ): നബി(സ)യിൽ നിന്ന് മുമ്പത്തെ പോലെ (ഹദീസ്) നിവേദനം ചെയ്യുന്നു. (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ بِأَخَرَةٍ إِذَا أَرَادَ أَنْ يَقُومَ مِنَ الْمَجْلِس: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ". فَقَالَ رَجُلٌ: إِنَّكَ لَتَقُولُ قَوْلًا مَا كُنْتَ تَقُولُهُ فِيمَا مَضَى يَا رَسُولَ اللَّهِ؟ فَقَالَ: "كَفَّارَةٌ لِمَا يَكُونُ فِي الْمَجْلِسِ". (د)', 'അബൂബർസതിൽ അസ്‌ലമി(റ): റസൂൽ(സ) സദസ്സിൽ നിന്ന് എഴുന്നേൽക്കാൻ ഉദ്ദേശിച്ചാൽ അവസാനമായി ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "സുബ്ഹാനകല്ലാഹുമ്മ വബിഹംദിക, അശ്ഹദു അൻലാഇലാഹ ഇല്ലാ അൻത, അസ്തഗ്ഫിറുക വഅതൂബു ഇലൈക". (അല്ലാഹുവേ, നീ എത്ര പരിശുദ്ധൻ! ഞാൻ നിന്നെ വാഴ്ത്തുന്നു. നീയല്ലാതെ ആരാധ്യനില്ല. ഞാൻ നിന്നോട് പൊറുക്കൽ തേടുകയും നിന്നിലേക്ക് ഖേദിച്ച്മടങ്ങുകയും ചെയ്യുന്നു). അപ്പോൾ ഒരാൾ ചോദിച്ചു: അവിടന്ന് മുമ്പൊന്നും പറഞ്ഞിട്ടില്ലാത്ത വചനങ്ങൾ പറയുന്നു, അല്ലാഹുവിന്റെ ദൂതരേ? അപ്പോൾ അവിടന്നരുളി: "സദസ്സിൽ ഉണ്ടായ കാര്യങ്ങൾക്കുള്ള പ്രായശ്ചിത്തമാണത്." (ദ)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസതിൽ അസ്‌ലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُبَلِّغْنِي أَحَدٌ مِنْ أَصْحَابِي عَنْ أَحَدٍ شَيْئًا، فَإِنِّي أُحِبُّ أَنْ أَخْرُجَ إِلَيْكُمْ وَأَنَا سَلِيمُ الصَّدْرِ". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അനുചരരിൽ ഒരാളും മറ്റൊരാളെക്കുറിച്ച് ഒരു പരാതിയും എന്നെ ബോധിപ്പിക്കരുത്. കാരണം ഞാൻ സുരക്ഷിതഹൃദയത്തോടെ നിങ്ങളിലേക്കിറങ്ങി വരാനാണ് കൊതിക്കുന്നത്." (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 450, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَقْعَدِهِ ثُمَّ يَجْلِسُ فِيهِ، وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا". وفي رواية: قُلْتُ: فِي يَوْمِ الْجُمُعَةِ؟ قَالَ: فِي يَوْمِ الْجُمُعَةِ وَغَيْرِهَا. وَكَانَ ابْنُ عُمَرَ إِذَا قَامَ لَهُ رَجُلٌ عَنْ مَجْلِسِهِ لَمْ يَجْلِسْ فِيهِ. (ق)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളും മറ്റൊരാളെ അവന്റെ ഇരിപ്പിടത്തിൽനിന്ന് എഴുന്നേൽപിച്ച് അവിടെ ഇരിക്കാൻ പാടില്ല. എങ്കിലും നിങ്ങൾ വിശാലമാക്കുകയും സൗകര്യപ്പെടുത്തുകയും ചെയ്യുവിൻ."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=194), 1, 'وَفِي رِوَايَةٍ: قُلْتُ: فِي يَوْمِ الْجُمُعَةِ؟ قَالَ: فِي يَوْمِ الْجُمُعَةِ وَغَيْرِهَا. وَكَانَ ابْنُ عُمَرَ إِذَا قَامَ لَهُ رَجُلٌ عَنْ مَجْلِسِهِ لَمْ يَجْلِسْ فِيهِ. (ق)', 'മറ്റൊരു നിവേദനത്തിൽ: ഞാൻ ചോദിച്ചു: ജുമുഅ ദിവസത്തിലോ? അവിടന്ന് പറഞ്ഞു: ജുമുഅ ദിവസവും അല്ലാത്ത ദിവസവും. ഇബ്നുഉമർ(റ)വിന് വേണ്ടി ആരെങ്കിലും ഇരിപ്പിടം ഒഴിഞ്ഞുകെടുത്താൽ അദ്ദേഹം അവിടെ ഇരിക്കാറില്ലായിരുന്നു. (ബു,മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُقِمْ أَحَدُكُمْ أَخَاهُ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ". قَالَ: وَكَانَ الرَّجُلُ يَقُومُ لِابْنِ عُمَرَ، فَمَا يَجْلِسُ فِيهِ. حَسَنٌ صَحِيحٌ. (م,ت)', 'ഇബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളും തന്റെ സഹോദരനെ അവന്റെ ഇരിപ്പിടത്തിൽ നിന്ന് എഴുന്നേൽപിച്ച് അവിടെ ഇരിക്കരുത്." നിവേദകൻ പറഞ്ഞു: ആളുകൾ ഇബ്നുഉമർ(റ)വിന് വേണ്ടി എഴുന്നേറ്റുകൊടുക്കാറുണ്ടായിരുന്നു. പക്ഷേ, അദ്ദേഹമവിടെ ഇരിക്കാറില്ലായിരുന്നു. (മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُجْلَسْ بَيْنَ رَجُلَيْنِ إِلَّا بِإِذْنِهِمَا". وفي رواية: "لَا يَحِلُّ لِلرَّجُلِ أَنْ يُفَرِّقَ بَيْنَ اثْنَيْنِ إِلَّا بِإِذْنِهِمَا". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടാളുകൾക്കിടയിൽ അവരുടെ സമ്മതമില്ലാതെ ഇരിക്കപ്പെടരുത്." മറ്റൊരു നിവേദനം: "രണ്ടാളുകൾക്കിടയിൽ അവരുടെ സമ്മതമില്ലാതെ വേർപിരിക്കൽ ഒരാൾക്കും അനുവദനീയമല്ല." (ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=196), 1, 'وَفِي رِوَايَةٍ: "لَا يَحِلُّ لِلرَّجُلِ أَنْ يُفَرِّقَ بَيْنَ اثْنَيْنِ إِلَّا بِإِذْنِهِمَا". (د,ت)', 'മറ്റൊരു നിവേദനം: "രണ്ടാളുകൾക്കിടയിൽ അവരുടെ സമ്മതമില്ലാതെ വേർപിരിക്കൽ ഒരാൾക്കും അനുവദനീയമല്ല." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا جَلَسَ احْتَبَى بِيَدَيْهِ. (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) ഇരിക്കുമ്പോൾ തന്റെ രണ്ട് കരങ്ങൾ കൊണ്ട് കാൽമുട്ട് കെട്ടിയിരിക്കുമായിരുന്നു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ قَيْلَةَ بِنْتِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا رَأَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ قَاعِدٌ الْقُرْفُصَاء، قَالَتْ: فَلَمَّا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُخْتَشِعَ -وفي رواية: الْمُتَخَشِّعَ- فِي الْجِلْسَةِ أُرْعِدْتُ مِنَ الْفَرَقِ. (د,ت)', 'ഖൈലതു ബിൻത് മഖ്റമ(റ): നബി(സ) മുട്ട് കെട്ടിയിരിക്കുന്നത് അവർ കണ്ടു. അവർ പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യെ താഴ്മയോടെയുള്ള ഇരുത്തത്തിൽ കണ്ടപ്പോൾ ഭയന്നു വിറച്ചുപോയി. (ദ,തു)', 'قَيْلَةَ بِنْتِ مَخْرَمَةَ', 'ഖൈലതു ബിൻത് മഖ്റമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 451, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=198), 1, 'وَفِي رِوَايَةٍ: الْمُتَخَشِّعَ- فِي الْجِلْسَةِ أُرْعِدْتُ مِنَ الْفَرَقِ. (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنِ الشَّرِيدِ بْنِ سُوَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا جَالِسٌ هَكَذَا، وَقَدْ وَضَعْتُ يَدِيَ الْيُسْرَى خَلْفَ ظَهْرِي، وَاتَّكَأْتُ عَلَى أَلْيَةِ يَدِي، فَقَالَ: "أَتَقْعُدُ قَعْدَةَ الْمَغْضُوبِ عَلَيْهِمْ". (د)', 'ശരീദുബ്നു സുവൈദ്(റ): ഞാൻ ഇങ്ങനെ ഇരിക്കുമ്പോൾ നബി(സ) എന്റെ അടുക്കലൂടെ കടന്നുപോയി. എന്റെ ഇടത്കൈ മുതുകിന്റെ പിന്നിലൂടെ വെച്ച് തന്റെ കൈയിന്റെ താഴ്ഭാഗത്തിന്മേൽ ചാരിയിരിക്കുകയായിരുന്നു ഞാൻ. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ കോപത്തിനിരയായവരുടെ (ജൂതന്മാരുടെ) ഇരുത്തം ഇരിക്കുകയാണോ താങ്കൾ?" (ദ)', 'الشَّرِيدِ بْنِ سُوَيْدٍ', 'ശരീദുബ്നു സുവൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النَّوْمِ قَبْلَهَا وَالْحَدِيثِ بَعْدَهَا. (ق,د,ت,ن,جه)', 'അബൂബർസ(റ): അതിന്റെ (ഇശാഇന്റെ) മുമ്പ് ഉറങ്ങലും ഇശാഇന്ന് ശേഷം സംസാരിക്കലും നബി(സ) നിരോധിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي بَرْزَةَ', 'അബൂബർസ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْفَجْرَ تَرَبَّعَ فِي مَجْلِسِهِ حَتَّى تَطْلُعَ الشَّمْسُ حَسْنَاء. (م,د,ت,ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) പ്രഭാതനമസ്കാരത്തിന് ശേഷം തന്റെ സദസ്സിൽ സൂര്യൻ തെളിഞ്ഞുദിക്കും വരെ ചമ്രം പടിഞ്ഞിരിക്കുമായിരുന്നു. (മു,ദ,തു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "خَيْرُ الْمَجَالِسِ أَوْسَعُهَا". (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സദസ്സുകളിൽ ഏറ്റവും നല്ലത് കൂടുതൽ വിശാലമായതാണ്." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ أَحَدُكُمْ فِي الشَّمْسِ - وفي رواية: فِي الْفَيْءِ - فَقَلَصَ عَنْهُ الظِّلُّ، وَصَارَ بَعْضُهُ فِي الشَّمْسِ وَبَعْضُهُ فِي الظِّلِّ، فَلْيَقُمْ". (د)', 'അബൂഹുറൈറ(റ): അബുൽ ഖാസിം(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും വെയിലത്ത് -മറ്റൊരു നിവേദനത്തിൽ: തണലിൽ - നിൽക്കുകയും ശേഷം തണൽ നീങ്ങി അയാളുടെ ചില ഭാഗം വെയിലത്തും ചില ഭാഗം തണലിലുമായാൽ അവൻ (അവിടെ നിന്നും) എഴുന്നേൽക്കട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=203), 1, 'وَفِي رِوَايَةٍ: فِي الْفَيْءِ - فَقَلَصَ عَنْهُ الظِّلُّ، وَصَارَ بَعْضُهُ فِي الشَّمْسِ وَبَعْضُهُ فِي الظِّلِّ، فَلْيَقُمْ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: തണലിൽ - നിൽക്കുകയും ശേഷം തണൽ നീങ്ങി അയാളുടെ ചില ഭാഗം വെയിലത്തും ചില ഭാഗം തണലിലുമായാൽ അവൻ (അവിടെ നിന്നും) എഴുന്നേൽക്കട്ടെ." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ عَبْدِ عَوْفِ بْنِ الْحَارِثِ الْبَجَلِي رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ جَاءَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَقَامَ فِي الشَّمْسِ، فَأَمَرَ بِهِ فَحُوِّلَ إِلَى الظِّلِّ. (د)', 'അബ്ദുഔഫിബ്നിൽ ഹാരിസിൽ ബജലി(റ): റസൂൽ(സ) പ്രസംഗിച്ചുകൊണ്ടിരിക്കുന്ന സമയത്ത് അദ്ദേഹം വരികയും വെയിലത്ത് നിൽക്കുകയും ചെയ്തു. അപ്പോൾ അവിടന്ന് അദ്ദേഹത്തോട് കൽപിക്കുകയും അദ്ദേഹത്തെ തണലത്തേക്ക് മാറ്റപ്പെടുകയും ചെയ്തു. (ദ)', 'عَبْدِ عَوْفِ بْنِ الْحَارِثِ الْبَجَلِي', 'അബ്ദുഔഫിബ്നിൽ ഹാരിസിൽ ബജലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُقْعَدَ بَيْنَ الظِّلِّ وَالشَّمْسِ. (جه)', 'ബുറൈദ(റ): വെയിലിനും തണലിനും ഇടയിലായി ഇരിക്കൽ നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ وَهُمْ حِلَقٌ، فَقَالَ: "مَالِي أَرَاكُمْ عِزِينَ". وفي رواية: كَأَنَّهُ يُحِبُّ الْجَمَاعَةَ. (م,د)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പള്ളിയിൽ കടന്നുവന്നു. അവർ (സ്വഹാബികൾ) വ്യത്യസ്ത കൂട്ടങ്ങളായി ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "എന്താണ് നിങ്ങളെ ഞാൻ വ്യത്യസ്ത കൂട്ടങ്ങളായി കാണുന്നത്?" ഒരു നിവേദനത്തിൽ: അവിടന്ന് സംഘമായിരിക്കൽ ഇഷ്ടപ്പെടുന്നതു പോലെയുണ്ട്. (മു,ദ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=206), 1, 'وَفِي رِوَايَةٍ: كَأَنَّهُ يُحِبُّ الْجَمَاعَةَ. (م,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَلَسَ أَحَدُنَا حَيْثُ يَنْتَهِي. (د,ت)', 'ജാബിറുബ്നു സമുറ(റ): ഞങ്ങളാരെങ്കിലും നബി(സ)യുടെ അടുക്കൽ വന്നാൽ അവസാനഭാഗത്ത് ഇരിക്കുമായിരുന്നു. (ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الْأَيَّامِ، مَخَافَةَ السَّآمَةِ عَلَيْنَا. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): തിരുദൂതർ(സ) ഞങ്ങൾക്ക് മടുപ്പ് വരുമെന്ന് കരുതി ഉപദേശം നടത്തുന്ന ദിവസങ്ങളിൽ സമയം പാലിക്കാറുണ്ടായിരുന്നു. (ബു,മു,തു)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَعَنَ مَنْ جَلَسَ وَسْطَ الْحَلْقَةِ. (ت)', 'ഹുദൈഫ(റ): വട്ടമിട്ടിരിക്കുന്ന സദസ്സിന്റെ മധ്യത്തിലിരിക്കുന്നവനെ റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. (തു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ أَبِي مِجْلَزٍ لَاحِقِ بْنِ حُمَيْدٍ: أَنَّ رَجُلًا قَعَدَ وَسْطَ حَلْقَةٍ، فَقَالَ حُذَيْفَةُ رَضِيَ اللهُ عَنْهُ: مَلْعُونٌ عَلَى لِسَانِ مُحَمَّدٍ - أَوْ: لَعَنَ اللَّهُ عَلَى لِسَانِ مُحَمَّدٍ - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَنْ قَعَدَ وَسْطَ الْحَلْقَةِ. حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂ മിജ്‌ലസിൻ ലാഹിഖുബ്നു ഹുമൈദ്(റ): ഒരാൾ വട്ടമിട്ട സദസ്സിന്റെ മധ്യത്തിൽ ഇരുന്നു. അപ്പോൾ ഹുദൈഫ(റ) പറഞ്ഞു: സദസ്സിന്റെ മധ്യത്തിലിരിക്കുന്നവൻ മുഹമ്മദ്(സ)യുടെ നാവിലൂടെ ശപിക്കപ്പെട്ടവനാണ് - അല്ലെങ്കിൽ (അവനെ) മുഹമ്മദ്(സ)യുടെ നാവിലൂടെ അല്ലാഹു ശപിച്ചിരിക്കുന്നു. (ദ,തു)', 'أَبِي مِجْلَزٍ لَاحِقِ بْنِ حُمَيْدٍ', 'അബൂ മിജ്‌ലസിൻ ലാഹിഖുബ്നു ഹുമൈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ وَالنَّاسُ مَعَهُ، إِذْ أَقْبَلَ ثَلَاثَةُ نَفَرٍ، فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَ وَاحِدٌ، فَلَمَّا وَقَفَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَلَّمَا، فَأَمَّا أَحَدُهُمَا فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ فِيهَا، وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ، وَأَمَّا الْآخَرُ فَأَدْبَرَ ذَاهِبًا، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلَاثَةِ: أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ فَأَوَاهُ اللَّهُ، وَأَمَّا الْآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ، وَأَمَّا الْآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂവാഖിദില്ലൈസി(റ): ജനങ്ങളോടൊത്ത് റസൂൽ(സ) പള്ളിയിലിരിക്കുമ്പോൾ മൂന്ന്പേർ കടന്നുവരികയും അവരിൽ രണ്ടുപേർ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് വരികയും ഒരാൾ പോവുകയും ചെയ്തു. അവരിരുവരും റസൂൽ(സ)യുടെ അടുക്കലിരുന്നപ്പോൾ സലാം ചൊല്ലി. അവരിലൊരാൾ വട്ടമിട്ടിരിക്കുന്ന ആ സദസ്സിൽ ഒരൊഴിവ് കണ്ട് അവിടെയിരുന്നു. മറ്റെയാൾ അവർക്ക് പിന്നിലുമിരുന്നു. മൂന്നാമൻ പിന്തിരിഞ്ഞ് പോകുകയും ചെയ്തു. അങ്ങനെ, റസൂൽ(സ) വിരമിച്ചപ്പോൾ അവിടന്നരുളി: "ഞാൻ നിങ്ങൾക്ക് മൂന്നംഗസംഘത്തെക്കുറിച്ച് പറഞ്ഞുതരട്ടെയോ? അവരിലൊരാൾ അല്ലാഹുവിലേക്ക് അഭയം തേടിവന്നു. അപ്പോൾ അവന് അല്ലാഹു അഭയം നൽകി. മറ്റവൻ ലജ്ജ കാണിച്ചു. അപ്പോൾ അല്ലാഹു അവനോടും ലജ്ജ കാണിച്ചു. മൂന്നാമൻ പിന്തിരിഞ്ഞു. അല്ലാഹു അവനിൽ നിന്നും പിന്തിരിയുകയുണ്ടായി." (ബു,മു,തു)', 'أَبِي وَاقِدٍ اللَّيْثِيِّ', 'അബൂവാഖിദില്ലൈസി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالْجُلُوسَ بِالطُّرُقَاتِ". قَالُوا: يَا رَسُولَ اللَّهِ، مَا بُدَّ لَنَا مِنْ مَجَالِسِنَا نَتَحَدَّثُ فِيهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ أَبَيْتُمْ فَأَعْطُوا الطَّرِيقَ حَقَّهُ". قَالُوا: وَمَا حَقُّ الطَّرِيقِ يَا رَسُولَ اللَّهِ؟ قَالَ: "غَضُّ الْبَصَرِ، وَكَفُّ الْأَذَى، وَرَدُّ السَّلَامِ، وَالْأَمْرُ بِالْمَعْرُوفِ، وَالنَّهْيُ عَنِ الْمُنْكَرِ". (ق,د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "വഴിയോരങ്ങളിൽ ഇരിക്കൽ നിങ്ങൾ സൂക്ഷിക്കുക." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ സംസാരിച്ചിരിക്കുന്ന സംഗമസ്ഥലങ്ങൾ അത്യാവശ്യമായി വരുമല്ലോ?. അപ്പോൾ അവിടന്നരുളി: "നിങ്ങൾക്ക് സമ്മതമില്ലെങ്കിൽ പിന്നെ വഴിയുടെ കടമകൾ നിങ്ങൾ വകവെച്ച് നൽകുക." അവർ ചോദിച്ചു: എന്തൊക്കെയാണ് വഴിയിൽ സൂക്ഷിക്കേണ്ട കടമകൾ. അവിടന്ന് പറഞ്ഞു: "കണ്ണ് താഴ്ത്തുക, ബുദ്ധിമുട്ടകറ്റുക, സലാം മടക്കുക, നന്മ കൽപ്പിക്കുക, തിന്മ നിരോധിക്കുക." (ബു,മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 454, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذِهِ الْقِصَّةِ، قَالَ: "وَإِرْشَادُ السَّبِيلِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇതേ ഉദ്ധരണിയിൽ അവിടന്ന് പറഞ്ഞു: "വഴി കാണിച്ചുകൊടുക്കുക." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي هَذِهِ الْقِصَّةِ، قَالَ: "وَتُغِيثُوا الْمَلْهُوفَ، وَتَهْدُوا الضَّالَّ". (د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): ഇതേ ഉദ്ധരണിയിൽ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്സഹായനെ സഹായിക്കുക, നഷ്ടപ്പെട്ടവനെ (വഴിമാറിപ്പോയവനെ) നേർവഴി കാട്ടുകയും ചെയ്യുക." (ദ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ لِي إِلَيْكَ حَاجَةً. فَقَالَ لَهَا: "يَا أُمَّ فُلَانٍ، اجْلِسِي فِي أَيِّ نَوَاحِي السِّكَكِ شِئْتِ حَتَّى أَجْلِسَ إِلَيْكِ". قَالَ: فَجَلَسَتْ، فَجَلَسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهَا حَتَّى قَضَتْ حَاجَتَهَا. وفي رواية: أَنَّ امْرَأَةً كَانَ فِي عَقْلِهَا شَيْءٌ بِمَعْنَاهُ. (م,د)', 'അനസ്(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെയടുത്തേക്ക് വന്നു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എനിക്ക് അങ്ങയോട് ഒരു ആവശ്യമുണർത്താനുണ്ട്. അവിടന്ന് പറഞ്ഞു: "ഓ ഇന്നയാളുടെ മാതാവേ, ആ തെരുവുകളിൽ നിങ്ങളുദ്ദേശിക്കുന്ന ഭാഗത്ത് ഞാൻ നിങ്ങളിലേക്ക് (തിരിഞ്ഞ്) ഇരിക്കും വരെ ഇരിക്കുക." നിവേദകൻ പറഞ്ഞു: അങ്ങനെ അവർ ഇരുന്നു. നബി(സ) അവരിലേക്ക് തിരിഞ്ഞിരുന്നു. അങ്ങനെ അവരുടെ കാര്യം നിർവ്വഹിച്ചു. മറ്റൊരു നിവേദനത്തിൽ: തന്റെ ബുദ്ധിക്കെന്തോ പ്രശ്നം ഉണ്ടായിരുന്ന ഒരു സ്ത്രീ.... അതേ ആശയത്തിൽ. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=215), 1, 'وَفِي رِوَايَةٍ: أَنَّ امْرَأَةً كَانَ فِي عَقْلِهَا شَيْءٌ بِمَعْنَاهُ. (م,د)', 'മറ്റൊരു നിവേദനത്തിൽ: തന്റെ ബുദ്ധിക്കെന്തോ പ്രശ്നം ഉണ്ടായിരുന്ന ഒരു സ്ത്രീ.... അതേ ആശയത്തിൽ. (മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِنَاسٍ مِنَ الْأَنْصَارِ وَهُمْ جُلُوسٌ فِي الطَّرِيقِ، فَقَالَ: "إِنْ كُنْتُمْ لَا بُدَّ فَاعِلِينَ فَرُدُّوا السَّلَامَ، وَأَعِينُوا الْمَظْلُومَ، وَاهْدُوا السَّبِيلَ". حَسَنٌ. (ت)', 'ബറാഅ്(റ): വഴിയിലിരിക്കുകയായിരുന്ന, അൻസാരികളിൽ ചിലർക്കരികിലൂടെ റസൂൽ(സ) നടന്നു അപ്പോൾ അവിടന്ന് പറഞ്ഞു: നിങ്ങൾക്ക് (ഇങ്ങനെ ഇരിക്കൽ) അനിവാര്യമാണെങ്കിൽ പിന്നെ നിങ്ങൾ സലാം മടക്കുകയും, അക്രമിക്കപ്പെട്ടവനെ സഹായിക്കുകയും വഴി കാണിച്ചു കൊടുക്കുകയും ചെയ്യുക." (തു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَافَرْتُمْ فِي الْخِصْبِ فَأَعْطُوا الْإِبِلَ حَظَّهَا مِنَ الْأَرْضِ، وَإِذَا سَافَرْتُمْ فِي السَّنَةِ فَبَادِرُوا بِهَا نِقْيَهَا. وَإِذَا عَرَّسْتُمْ فَاجْتَنِبُوا الطَّرِيقَ، فَإِنَّهَا طُرُقُ الدَّوَابِّ وَمَأْوَى الْهَوَامِّ بِاللَّيْلِ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഫലഭൂയിഷ്ടിയുള്ള ഭൂമിയിലൂടെ യാത്രചെയ്യുമ്പോൾ ഒട്ടകത്തിന് ഭൂമിയിൽ നിന്നുള്ള അതിന്റെ അവകാശം നൽകണം. നിങ്ങൾ വരൾച്ചയുള്ള നാട്ടിലൂടെ യാത്ര ചെയ്യുന്നുവെങ്കിൽ നിങ്ങളുടെ യാത്രാമൃഗവുമായി അവിടത്തെ മണൽക്കുന്നിലൂടെ പെട്ടെന്ന് പോകുക. നിങ്ങൾ യാത്രാമധ്യേ വിശ്രമിക്കുന്നുവെങ്കിൽ യാത്രാവഴി ഒഴിവാക്കുക. കാരണമത് മൃഗങ്ങളുടെ വഴികളും രാത്രിയിൽ സിംഹങ്ങളുടെ അഭയകേന്ദ്രവുമാണ്." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا لَقِيَ الرَّجُلَ فَكَلَّمَهُ، لَمْ يَصْرِفْ وَجْهَهُ عَنْهُ حَتَّى يَكُونَ هُوَ الَّذِي يَنْصَرِفُ، وَإِذَا صَافَحَهُ لَمْ يَنْزِعْ يَدَهُ مِنْ يَدِهِ حَتَّى يَكُونَ هُوَ الَّذِي يَنْزِعُهَا، وَلَمْ يُرَ مُتَقَدِّمًا بِرُكْبَتَيْهِ جَلِيسًا لَهُ قَطُّ. [ز: في سنده ضعيف] (ت,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ആരെയെങ്കിലും കണ്ടുമുട്ടി സംസാരിച്ചാൽ, അയാൾ തിരിഞ്ഞ് പോരുന്നത്വരെ അവിടന്ന് മുഖം തിരിച്ചുകളയാറില്ലായിരുന്നു. അവിടന്ന് ആരെയെങ്കിലും ഹസ്തദാനം ചെയ്താൽ, അയാൾ തന്റെ കൈ വലിക്കുന്നത്വരെ അവിടന്ന് കൈ വലിക്കാറില്ലായിരുന്നു. അവിടന്ന് തന്റെ കാൽമുട്ടുകൾ നിവർത്തി തന്റെ കൂട്ടുകാരന് അഭിമുഖമായിരിക്കുന്നത് ഒരിക്കലും കാണപ്പെട്ടിട്ടില്ല. (പരമ്പരയിൽ ഭംഗമുള്ളവരുണ്ട്.) (തു,ജ)', 'أَنَسِ ابْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'ز: في سنده ضعيف', null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: مَرَّ بِهَا سَائِلٌ فَأَعْطَتْهُ كِسْرَةً، وَمَرَّ بِهَا رَجُلٌ عَلَيْهِ ثِيَابٌ وَهَيْئَةٌ فَأَقْعَدَتْهُ فَأَكَلَ، فَقِيلَ لَهَا فِي ذَلِكَ، فَقَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنْزِلُوا النَّاسَ مَنَازِلَهُمْ". (د)', 'ആഇശ(റ): ഒരു യാചകൻ മഹതിയുടെ അരികിലൂടെ നടന്നു വന്നപ്പോൾ മഹതി അയാൾക്ക് ഒരു റൊട്ടിക്കഷ്ണം കൊടുത്തു. പിന്നീട് വസ്ത്രങ്ങൾ ധരിച്ച നല്ല രൂപഭാവമുള്ള ഒരാൾ മഹതിയുടെ അരികിലൂടെനടന്നു വന്നു. അപ്പോൾ മഹതി അയാളെ ഇരുത്തി. അയാൾ ഭക്ഷിച്ചു. ഇതിനെക്കുറിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടപ്പോൾ പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നിങ്ങൾ ജനങ്ങളെ അവരവരുടെ സ്ഥാനങ്ങളിൽ വെക്കുക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ إِجْلَالِ اللَّهِ إِكْرَامَ ذِي الشَّيْبَةِ الْمُسْلِمِ، وَحَامِلِ الْقُرْآنِ غَيْرِ الْغَالِي فِيهِ وَالْجَافِي عَنْهُ، وَإِكْرَامَ ذِي السُّلْطَانِ الْمُقْسِطِ". (د,ت)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, അതിർ ലംഘിക്കാത്തവനും ഒഴിഞ്ഞ് നിൽക്കാത്തവനുമായ ഖുർആൻ വാഹകനെയും മുസ്ലിം വൃദ്ധരെയും വന്ദിക്കലും നീതിമാനായ അധികാരിയെ മാനിക്കലും അല്ലാഹു ബഹുമാനിക്കുന്നതിൽ പെട്ടതാണ്." (ദ,തു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 456, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَاكُمْ كَرِيمُ قَوْمٍ فَأَكْرِمُوهُ". [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സമൂഹത്തിന്റെ നേതാവ് നിങ്ങളുടെ അടുക്കൽ വന്നാൽ നിങ്ങളയാളെ വന്ദിക്കുക." (പരമ്പരയിൽ ഭംഗമുള്ള ഒരാളുണ്ട്.) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَكْرَمَ شَابٌّ شَيْخًا لِسِنِّهِ إِلَّا قَيَّضَ اللَّهُ لَهُ مَنْ يُكْرِمُهُ عِنْدَ سِنِّهِ". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു യുവാവ് ഒരു വൃദ്ധനെ അയാളുടെ പ്രായം പരിഗണിച്ച് ബഹുമാനിച്ചാൽ അവന്റെ വാർദ്ധക്യത്തിൽ അവനെ വന്ദിക്കാൻ അല്ലാഹു ഒരാളെ നിശ്ചയിച്ച്വെക്കും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنِ الْعَلَاءِ بْنِ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ: كَانَ عَامِلَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْبَحْرَيْنِ، فَكَانَ إِذَا كَتَبَ إِلَيْهِ بَدَأَ بِنَفْسِهِ. وفي رواية: أَنَّهُ كَتَبَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَبَدَأَ بِاسْمِهِ. (د)', 'അലാഉബ്നുൽ ഹള്റമീ(റ): അദ്ദേഹം നബി(സ)യുടെ കാലത്ത് ബഹ്റൈൻ ഗവർണറായിരുന്നു. അദ്ദേഹം നബി(സ)ക്ക് കത്തെഴുതുമ്പോൾ സ്വന്തത്തെക്കൊണ്ട് തുടങ്ങുമായിരുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=223), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ كَتَبَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَبَدَأَ بِاسْمِهِ. (د)', 'മറ്റൊരു നിവേദനം: സ്വന്തം പേരിൽ തുടങ്ങിക്കൊണ്ട് അദ്ദേഹം തിരുമേനി(സ)ക്ക് കത്തെഴുതി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ قَبْلَ مَوْتِهِ إِلَى كِسْرَى وَإِلَى قَيْصَرَ وَإِلَى النَّجَاشِيِّ وَإِلَى كُلِّ جَبَّارٍ، يَدْعُوهُمْ إِلَى اللَّهِ، وَلَيْسَ بِالنَّجَاشِيِّ الَّذِي صَلَّى عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. حَسَنٌ صَحِيحٌ. (م)', 'അനസ്(റ): റസൂൽ(സ) വഫാത്തിന് മുമ്പ് കിസ്റക്കും കൈസറിനും നജ്ജാശിക്കും എല്ലാ സ്വേച്ഛാധിപതികൾക്കും അല്ലാഹുവിലേക്ക് ക്ഷണിച്ച് കൊണ്ട് കത്തെഴുതി. ഈ നജ്ജാശി റസൂൽ(സ) മയ്യിത് നിസ്കരിച്ച നജ്ജാശിയല്ല. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَا سُفْيَانَ بْنَ حَرْبٍ أَخْبَرَهُ: أَنَّ هِرَقْلَ أَرْسَلَ إِلَيْهِ فِي نَفَرٍ مِنْ قُرَيْشٍ، وَكَانُوا تِجَارًا بِالشَّامِ، فَأَتَوْهُ... فَذَكَرَ الْحَدِيثَ، قَالَ: ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُرِئَ، فَإِذَا فِيهِ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ عَبْدِ اللَّهِ وَرَسُولِهِ، إِلَى هِرَقْل عَظِيمِ الرُّومِ، السَّلَامُ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ.". حَسَنٌ صَحِيحٌ. (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അബൂസുഫ്‌യാനുബ്നു ഹർബ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: ശാമിലെ കച്ചവടക്കാരായിരുന്ന ഒരു സംഘം ഖുറൈശികളുടെ പക്കൽ ഹിറഖൽരാജാവിനുള്ള ഒരു കത്ത് കൊടുത്തയച്ചു. അവർ അദ്ദേഹത്തിന്റെയടുത്ത് ചെന്നു............ ശേഷം നിവേദകൻ ഹദീസിന്റെ ബാക്കി പറഞ്ഞു. നിവേദകൻ പറയുന്നു: പിന്നെ റസൂലിന്റെ കത്ത് കൊണ്ടുവരാനാവശ്യപ്പെടുകയും അത് വായിക്കപ്പെടുകയും ചെയ്തു. അപ്പോൾ അതിലിപ്രകാരമുണ്ട്: "കാരുണ്യവാനും കരുണാവാരിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ. അല്ലാഹുവിന്റെ ദൂതനും അവന്റെ അടിമയുമായ മുഹമ്മദിൽനിന്ന് റോം രാജാവ് ഹിറഖലിന്. സന്മാർഗ്ഗം പിൻപറ്റിയവന് രക്ഷയുണ്ട്. ശേഷം... (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 457, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى هِرَقْل: "مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ، إِلَى هِرَقْل عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى". وفي رواية: عَنِ ابْنِ عَبَّاسٍ: أَنَّ أَبَا سُفْيَانَ رَضِيَ اللهُ عَنْهُم– قَالَ: فَدَخَلْنَا عَلَى هِرَقْل فَأَجْلَسَنَا بَيْنَ يَدَيْهِ، ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَإِذَا فِيهِ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ..." (ق,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഹിറഖലിന് എഴുതി: "അല്ലാഹുവിന്റെ ദൂതനായ മുഹമ്മദിൽ നിന്ന് റോമിന്റെ ഭരണാധിപൻ ഹിർഖലിന്. സന്മാർഗ്ഗം പിൻപറ്റിയവന്റെ മേൽ രക്ഷയുണ്ട്." മറ്റൊരു ദിവേദനത്തിൽ: ഇബ്നുഅബ്ബാസ്(റ): അബൂ സുഫ്‌യാൻ(റ) പറഞ്ഞു: ഞങ്ങൾ ഹിറഖലിന്റെ അടുത്തേക്ക് ചെന്നു. അദ്ദേഹം ഞങ്ങളെ അഭിമുഖമായി ഇരുത്തി. എന്നിട്ട് റസൂലിന്റെ കത്ത് കൊണ്ടുവരാൻ പറഞ്ഞു. അതിലുണ്ട്: "റഹ്മാനും റഹീമുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ: അല്ലാഹുവിന്റെ ദൂതൻ മുഹമ്മദിൽ നിന്ന് റോമൻരാജാവ് ഹിറഖലിന്. സന്മാർഗ്ഗം പിൻപറ്റിയവനാണ് രക്ഷ. ശേഷം....." (ബു,മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=226), 1, 'وَفِي رِوَايَةٍ: عَنِ ابْنِ عَبَّاسٍ: أَنَّ أَبَا سُفْيَانَ رَضِيَ اللهُ عَنْهُم– قَالَ: فَدَخَلْنَا عَلَى هِرَقْل فَأَجْلَسَنَا بَيْنَ يَدَيْهِ، ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَإِذَا فِيهِ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ..." (ق,د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَرَادَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الْعَجَمِ قِيلَ لَهُ: إِنَّ الْعَجَمَ لَا يَقْبَلُونَ إِلَّا كِتَابًا عَلَيْهِ خَاتَمٌ. فَاصْطَنَعَ خَاتَمًا، قَالَ: فَكَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي كَفِّهِ. حَسَنٌ صَحِيحٌ. (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അനറബികൾക്ക് കത്തയക്കാൻ ഉദ്ദേശിച്ചപ്പോൾ അവിടത്തോട് പറയപ്പെട്ടു: സീലില്ലാത്ത കത്ത് അനറബികൾ സ്വീകരിക്കുകയില്ല. അപ്പോൾ അവിടന്ന് ഒരു മോതിരമുണ്ടാക്കി. തിരുമേനി(സ)യുടെ കയ്യിലുള്ള ആ മോതിരത്തിന്റെ വെളുപ്പിലേക്ക് ഞാൻ നോക്കുന്നതുപോലെയുണ്ട്. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَرِّبُوا صُحُفَكُمْ أَنْجَحُ لَهَا، إِنَّ التُّرَابَ مُبَارَكٌ". [ز: ضَعِيفٌ] (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ഏടുകൾ മണ്ണുകൊണ്ട് മറക്കൂ. അത് അവക്ക് കൂടുതൽ സുരക്ഷ നൽകുന്നതാണ്. തീർച്ചയായും മണ്ണ് പരിശുദ്ധമാണ്." (സനദിൽ ബലഹീനനുണ്ട്) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضَعِيفٌ', null, 458, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كَتَبَ أَحَدُكُمْ كِتَابًا فَلْيُتَرِّبْهُ، فَإِنَّهُ أَنْجَحُ لِلْحَاجَةِ". (ت,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ നിന്ന് ആരെങ്കിലും കത്തെഴുതുകയാണെങ്കിൽ നിങ്ങൾ അതിൽ മണ്ണ് പുരട്ടുക. തീർച്ചയായും ആവശ്യങ്ങൾ പെട്ടെന്ന് നിറവേറ്റപ്പെടാൻ അത് ഉപകരിക്കും." (തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 459, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ يَدَيْهِ كَاتِبٌ، فَسَمِعْتُهُ يَقُولُ: "ضَعِ الْقَلَمَ عَلَى أُذُنِكَ، فَإِنَّهُ أَذْكَرُ لِلْمُمْلِي". (ت)', 'സൈദുബ്നു സാബിത്(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ കടന്നുചെന്നു. തിരുമേനി(സ)യുടെ മുമ്പിൽ ഒരു എഴുത്തുകാരനുണ്ടായിരുന്നു. അപ്പോൾ അവിടന്ന് ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ആ പേന നിന്റെ ചെവിയുടെ മുകളിൽ വെക്കുക, കാരണം അത് (എഴുതാൻ) പറഞ്ഞ് കൊടുക്കുന്നവന് കൂടുതൽ ഓർമ്മ നൽകുന്നതാണ്." (തു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 459, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ عَمْرِو بْنِ الْفَغْوَاءِ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَعَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ أَرَادَ أَنْ يَبْعَثَنِي بِمَالٍ إِلَى أَبِي سُفْيَانَ يَقْسِمُهُ فِي قُرَيْشٍ بِمَكَّةَ بَعْدَ الْفَتْحِ، فَقَالَ: "الْتَمِسْ صَاحِبًا". قَالَ: فَجَاءَنِي عَمْرُو بْنُ أُمَيَّةَ الضَّمْرِيُّ فَقَالَ: بَلَغَنِي أَنَّكَ تُرِيدُ الْخُرُوجَ وَتَلْتَمِسُ صَاحِبًا؟ قَالَ: قُلْتُ: أَجَلْ، قَالَ: فَأَنَا لَكَ صَاحِبٌ. قَالَ: فَجِئْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: قَدْ وَجَدْتُ صَاحِبًا، قَالَ: فَقَالَ: "مَنْ". قُلْتُ: عَمْرُو بْنُ أُمَيَّةَ الضَّمْرِيُّ، قَالَ: "إِذَا هَبَطْتَ بِلَادَ قَوْمِهِ فَاحْذَرْهُ، فَإِنَّهُ قَدْ قَالَ الْقَائِلُ: أَخُوكَ الْبِكْرِيُّ وَلَا تَأْمَنْهُ". فَخَرَجْنَا حَتَّى إِذَا كُنْتُ بِالْأَبْوَاءِ قَالَ: إِنِّي أُرِيدُ حَاجَةً إِلَى قَوْمِي بِوَدَّانَ، فَتَلَبَّثْ لِي. قُلْتُ: رَاشِدًا، فَلَمَّا وَلَّى ذَكَرْتُ قَوْلَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشَدَدْتُ عَلَى بَعِيرِي حَتَّى خَرَجْتُ أُوضِعُهُ، حَتَّى إِذَا كُنْتُ بِالْأَصَافِرِ إِذَا هُوَ يُعَارِضُنِي فِي رَهْطٍ، قَالَ: وَأَوْضَعْتُ، فَسَبَقْتُهُ، فَلَمَّا رَآنِي قَدْ فُتُّهُ انْصَرَفُوا، وَجَاءَنِي فَقَالَ: كَانَتْ لِي إِلَى قَوْمِي حَاجَةٌ، قَالَ: قُلْتُ: أَجَلْ، وَمَضَيْنَا حَتَّى قَدِمْنَا مَكَّةَ فَدَفَعْتُ الْمَالَ إِلَى أَبِي سُفْيَانَ. (د)', 'അംറുബ്നുൽ ഫഗ്‌വാഇൽ ഖുസാഈ(റ): റസൂൽ(സ) എന്നെ വിളിച്ചു. മക്കാവിജയശേഷം മക്കയിലുള്ള ഖുറൈശികൾക്ക് വീതിച്ച് നൽകാനുള്ള സമ്പത്തുമായി അബൂസുഫ്‌യാൻ(റ)വിന്റെ അടുത്തേക്ക് എന്നെ അയക്കാൻ അവിടന്ന് ഉദ്ദേശിച്ചിരുന്നു. അവിടന്ന് പറഞ്ഞു: "താങ്കൾ ഒരു കൂട്ടുകാരനെ തിരഞ്ഞുപിടിക്കൂ." അദ്ദേഹം പറയുന്നു: അപ്പോൾ അംറുബ്നു ഉമയ്യത്തുള്ളംരി എന്റെയടുക്കൽ വന്നു. എന്നിട്ട് പറഞ്ഞു: താങ്കൾ യാത്രപുറപ്പെടുകയാണെന്നും ഒരു കൂട്ടുകാരനെ അന്വേഷിക്കുകയാണെന്നും ഞാൻ അറിഞ്ഞു. നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: എന്നാൽ ഞാൻ നിങ്ങളുടെ കൂടെ വരാം. നിവേദകൻ പറഞ്ഞു: അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: നിശ്ചയം ഞാനൊരു കൂട്ടുകാരനെ കണ്ടെത്തിയിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "ആരാണത്?" ഞാൻ പറഞ്ഞു: അംറുബ്നു ഉമയ്യത്തുള്ളംരീ. അവിടന്നരുളി: "താങ്കൾ അയാളുടെ ആളുകളുടെ നാട്ടിലേക്കിറങ്ങിച്ചെല്ലുമ്പോൾ അയാളെ സൂക്ഷിക്കണം. കാരണം മുമ്പ് ആരോ പറഞ്ഞിട്ടുണ്ട്: നിന്റെ സഹോദരൻ ബക്‌രിയിൽ നിന്ന് പോലും നീ നിർഭയനാകരുത് എന്ന്." അങ്ങനെ ഞങ്ങൾ പുറപ്പെട്ടു. അബവാഇലെത്തിയപ്പോൾ അയാൾ പറഞ്ഞു: വദ്ദാനിലെ എന്റെ ആളുകളിൽ എനിക്ക് ചില ആവശ്യങ്ങൾ ഉണ്ട്. അതിനാൽ (ഞാൻ തിരിച്ച് വരും വരെ ഇവിടെ) നിങ്ങൾ എന്നെ കാത്തിരിക്കുക. ഞാൻ പറഞ്ഞു: (വഴിപിഴക്കാതെ) പോവുക. അവൻ തിരിഞ്ഞ് പോയപ്പോൾ ഞാൻ നബി(സ) പറഞ്ഞ വാക്ക് ഓർത്തു. അങ്ങനെ പെട്ടെന്ന് ഒട്ടകപ്പുറത്ത് കയറി ഞാൻ അതിനെ വേഗത്തിൽ ഓടിച്ചു. അങ്ങനെ ഞാൻ അസ്വാഫിറിൽ എത്തിയപ്പോൾ അയാളതാ ഒരു പറ്റം ആളുകൾക്ക് കൂടെ (എന്റെ എതിർവശത്തുകൂടെ) വരുന്നു. ഞാൻ സാമാന്യം വേഗത്തിൽ നടന്നു. അങ്ങനെ അയാളെ മുൻകടന്നു. ഞാനയാളെ കടന്നുകളഞ്ഞതായി അയാൾ മനസ്സിലാക്കിയപ്പോൾ അവർ തിരിഞ്ഞ് പോയി. അയാൾ എന്നിലേക്ക് വരികയും ചെയ്തു. അപ്പോൾ അയാൾ പറഞ്ഞു: എനിക്ക് എന്റെ ആളുകളോട് ചില ആവശ്യങ്ങളുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: ആട്ടെ, ഞങ്ങൾ മക്കയിലെത്തും വരെ മുന്നോട്ട് പോയി. അങ്ങനെ ആ സമ്പത്ത് അബൂസുഫ്‌യാൻ(റ)വിന് നൽകുകയും ചെയ്തു. (ദ)', 'عَمْرِو بْنِ الْفَغْوَاءِ الْخُزَاعِيِّ', 'അംറുബ്നുൽ ഫഗ്‌വാഇൽ ഖുസാഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 459, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يُلْدَغُ الْمُؤْمِنُ مِنْ جُحْرٍ وَاحِدٍ مَرَّتَيْنِ". (ق,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു (പൂർണ്ണ) വിശ്വാസിക്ക് ഒരേ മാളത്തിൽ നിന്ന് രണ്ട് പ്രാവശ്യം കടിയേൽക്കുകയില്ല." (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا بَعَثَ أَحَدًا مِنْ أَصْحَابِهِ فِي بَعْضِ أَمْرِهِ قَالَ: "بَشِّرُوا وَلَا تُنَفِّرُوا، وَيَسِّرُوا وَلَا تُعَسِّرُوا". (م,د)', 'അബൂമൂസ(റ): സ്വഹാബാക്കളിൽ ആരെയെങ്കിലും റസൂൽ(സ) വല്ല ആവശ്യത്തിനും അയച്ചാൽ അവിടന്ന് പറയുമായിരുന്നു: "നിങ്ങൾ സന്തോഷിപ്പിക്കുക! വെറുപ്പിക്കരുത്! നിങ്ങൾ എളുപ്പമാക്കുക! ബുദ്ധിമുട്ടാക്കരുത്." (മു,ദ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلُوا يُثْنُونَ عَلَيَّ وَيَذْكُرُونِّي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أَعْلَمُكُمْ". يَعْنِي بِهِ، قُلْتُ: صَدَقْتَ بِأَبِي أَنْتَ وَأُمِّي: كُنْتَ شَرِيكِي فَنِعْمَ الشَّرِيكُ، كُنْتَ لَا تُدَارِي وَلَا تُمَارِي. (د,جه)', 'സാഇബ്(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ പോയി. അപ്പോൾ ആളുകൾ എന്നെ പുകഴ്ത്തുകയും എന്നെക്കുറിച്ച് പരാമർശിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളെക്കാൾ കൂടുതൽ അറിയുന്നവനാണ്." അവിടന്ന് അദ്ദേഹത്തെയാണുദ്ദേശിച്ചത്. ഞാൻ പറഞ്ഞു: എന്റെ ഉമ്മയും ഉപ്പയും അവിടത്തേക്ക് ദണ്ഡമാകട്ടെ, അവിടന്ന് സത്യം പറഞ്ഞു. അവിടന്നെന്റെ കൂറുകാരനായിരുന്നു. എത്രനല്ല പങ്കാളി! അവിടന്ന് (ഒരിക്കലും) തർക്കിക്കുകയോ അടിപിടി കൂടുകയോ ചെയ്യുമായിരുന്നില്ല. (ദ,ജ)', 'السَّائِبِ', 'സാഇബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَفَخْرَهَا بِالْآبَاءِ، مُؤْمِنٌ تَقِيٌّ، وَفَاجِرٌ شَقِيٌّ، أَنْتُمْ بَنُو آدَمَ وَآدَمُ مِنْ تُرَابٍ، لَيَدَعَنَّ رِجَالٌ فَخْرَهُمْ بِأَقْوَامٍ، إِنَّمَا هُمْ فَحْمٌ مِنْ فَحْمِ جَهَنَّمَ، أَوْ لَيَكُونُنَّ أَهْوَنَ عَلَى اللَّهِ مِنَ الْجِعْلَانِ الَّتِي تَدْفَعُ بِأَنْفِهَا النَّتِنَ". (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഉന്നതനും ഗാംഭീര്യവാനുമായ അല്ലാഹു നിങ്ങളിൽ നിന്ന് അജ്ഞാനകാല ഗർവും പിതൃക്കളിലുള്ള അഭിമാനവും ഒഴിവാക്കിക്കളഞ്ഞിരിക്കുന്നു. ഭക്തിയുള്ള വിശ്വാസി, പരാജിതനായ തെമ്മാടി എന്നീ വ്യത്യാസങ്ങൾ മാത്രമാണുള്ളത്. നിങ്ങൾ ആദം സന്തതികളാണ്, ആദം മണ്ണിൽ നിന്നുമാണ്. ജനങ്ങൾ സ്വന്തം സമുദായങ്ങളിൽ പ്രൗഢി കാണിക്കൽ ഒഴിവാക്കട്ടെ. നിശ്ചയമവർ നരകത്തിലെ കരിക്കട്ടകളിലെ ഒരു കരിക്കട്ട മാത്രമാണ്. അല്ലെങ്കിൽ അല്ലാഹുവിന്റെയടുക്കൽ അവർ; തന്റെ മൂക്ക് കൊണ്ട് മ്ലേച്ഛങ്ങളെ ഉരുട്ടുന്ന വണ്ടിനേക്കാൾ നിസ്സാരക്കാരായിരിക്കും". (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ نَصَرَ قَوْمَهُ عَلَى غَيْرِ الْحَقِّ فَهُوَ كَالْبَعِيرِ الَّذِي رُدِّيَ، فَهُوَ يُنْزَعُ بِذَنَبِهِ. وفي رواية قَالَ: انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي قُبَّةٍ مِنْ أَدَمٍ، فَذَكَرَ نَحْوَهُ. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അന്യായമായി സ്വന്തം സമൂഹത്തെ ആരെങ്കിലും സഹായിച്ചാൽ അവൻ, കിണറ്റിൽ വീണ് വാലിൽ പിടിച്ച് വലിച്ചെടുക്കപ്പെടുന്ന ഒട്ടകത്തെപ്പോലെയാണ്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=236), 1, 'وَفِي رِوَايَةٍ قَالَ: انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي قُبَّةٍ مِنْ أَدَمٍ، فَذَكَرَ نَحْوَهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: തോലിൽ നിർമിച്ച കുടാരത്തിലായിരിക്കെ നബി(സ)യുടെ സമീപം ഞാൻ എത്തിപ്പെട്ടു. അപ്പോൾ അവിടന്ന് മേലുദ്ധരിച്ച പോലെ പറഞ്ഞു.....(ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا الْعَصَبِيَّةُ؟ قَالَ: "أَنْ تُعِينَ قَوْمَكَ عَلَى الظُّلْمِ". (د,جه)', 'വാസിലതുബ്നുൽ അസ്ഖഅ്(റ): ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, എന്താണ് വിഭാഗീയത? അവിടന്നരുളി: "നീ സ്വന്തം സമുദായത്തെ അക്രമത്തിന്റെ മേൽ സഹായിക്കലാണത്". (ദ,ജ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലതുബ്നുൽ അസ്ഖഅ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمِ الْمُدْلِجِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "خَيْرُكُمُ الْمُدَافِعُ عَنْ عَشِيرَتِهِ مَا لَمْ يَأْثَمْ". (د)', 'സുറാഖതുബ്നു മാലികിബ്നി ജുഅ്ശുമിൽ മുദ്ലജീ(റ): റസൂൽ(സ) പ്രസംഗിക്കുന്നതിനിടയിൽ ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങളിൽ ഏറ്റവും ഉത്തമൻ, തന്റെ കുടുംബത്തിന് വേണ്ടി പ്രതിരോധം നടത്തുന്നവനാണ്, അവൻ തെറ്റ് ചെയ്യാത്ത കാലമത്രയും." (ദ)', 'سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمِ الْمُدْلِجِيِّ', 'സുറാഖതുബ്നു മാലികിബ്നി ജുഅ്ശുമിൽ മുദ്ലജീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ مِنَّا مَنْ دَعَا إِلَى عَصَبِيَّةٍ، وَلَيْسَ مِنَّا مَنْ قَاتَلَ عَلَى عَصَبِيَّةٍ، وَلَيْسَ مِنَّا مَنْ مَاتَ عَلَى عَصَبِيَّةٍ". (م,د,ن)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) പറഞ്ഞു: "വർഗ്ഗീയതയിലേക്ക് ക്ഷണിക്കുന്നവൻ നമ്മിൽപ്പെട്ടവനല്ല. വർഗ്ഗീയതക്കായി യുദ്ധം ചെയ്തവനും നമ്മിൽപ്പെട്ടവനല്ല. വർഗ്ഗീയതക്കുവേണ്ടി ജീവത്യാഗം ചെയ്തവനും നമ്മിൽപ്പെട്ടവനല്ല." (മു,ദ,ന)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 461, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ". (د)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു കുടുംബത്തിലെ സഹോദരിപുത്രൻ അതിലെ അംഗമാണ്." (ദ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ أَبِي عُقْبَةَ رَضِيَ اللهُ عَنْهُ – وَكَانَ مَوْلًى مِنْ أَهْلِ فَارِسَ – قَالَ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُحُدًا، فَضَرَبْتُ رَجُلًا مِنَ الْمُشْرِكِينَ، فَقُلْتُ: خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْفَارِسِيُّ، فَالْتَفَتَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "فَهَلَّا قُلْتَ: خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْأَنْصَارِيُّ". (د,جه)', 'അബൂഉഖ്ബ(റ): പേർഷ്യൻ പരിചാരകനായിരുന്നു അദ്ദേഹം - ഞാൻ റസൂൽ(സ)യുടെ കൂടെ ഉഹ്ദ് യുദ്ധത്തിൽ പങ്കെടുത്തു. അപ്പോൾ ഞാൻ മുശ്രിക്കുകളിലൊരാളെ വെട്ടി. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഇതാ പിടിച്ചോ. ഞാൻ പേർഷ്യൻ അടിമയാണ്. അപ്പോൾ റസൂൽ(സ) എന്നിലേക്ക് തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "ഇത് പിടിക്കൂ, ഞാനൊരു അൻസാരി പരിചാരകനാണ് എന്ന് നിനക്ക് പറയാമായിരുന്നില്ലേ." (ദ,ജ)', 'أَبِي عُقْبَةَ', 'അബൂഉഖ്ബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَغْلِبَنَّكُمُ الْأَعْرَابُ عَلَى اسْمِ صَلَاتِكُمْ، أَلَا وَإِنَّهَا الْعِشَاءُ، وَلَكِنَّهُمْ يُعْتِمُونَ بِالْإِبِلِ". (م,د,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ നമസ്കാരത്തിന് നാമകരണം ചെയ്യുന്നതിൽ അഅ്റാബികൾ നിങ്ങളെ മറികടക്കരുത്. അറിയുക, അത് ''ഇശാഅ്'' തന്നെയാണ്. എങ്കിലും അവർ പാതിരാത്രി ഒട്ടകങ്ങളെ കറന്നു കൊണ്ടിരിക്കും." (മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ مِنْ خُزَاعَةَ: لَيْتَنِي صَلَّيْتُ فَاسْتَرَحْتُ، فَكَأَنَّهُمْ عَابُوا عَلَيْهِ ذَلِكَ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَا بِلَالُ، أَقِمِ الصَّلَاةَ. أَرِحْنَا بِهَا". (د)', 'സാലിമുബ്നു അബിൽ ജഅ്ദ്(റ): ''ഖുസാഅ'' വംശത്തിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: ഞാനൊന്ന് നിസ്കരിച്ച് വിശ്രമിച്ചിരുന്നെങ്കിൽ! അപ്പോൾ അതുപറഞ്ഞ് അവർ അദ്ദേഹത്തെ ആക്ഷേപിച്ചതു പോലെ. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ബിലാലേ, നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിക്കൂ. അത് കൊണ്ട് നമുക്ക് വിശ്രമം നൽകൂ." (ദ)', 'سَالِمِ بْنِ أَبِي الْجَعْدِ', 'സാലിമുബ്നു അബിൽ ജഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ الْحَنَفِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: انْطَلَقْتُ أَنَا وَأَبِي إِلَى صِهْرٍ لَنَا مِنَ الْأَنْصَارِ نَعُودُهُ، فَحَضَرَتِ الصَّلَاةُ، فَقَالَ لِبَعْضِ أَهْلِهِ: يَا جَارِيَةُ ائْتُونِي بِوَضُوءٍ لَعَلِّي أُصَلِّي فَأَسْتَرِيحَ، قَالَ: فَأَنْكَرْنَا ذَلِكَ عَلَيْهِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قُمْ يَا بِلَالُ، فَأَرِحْنَا بِالصَّلَاةِ". (د)', 'അബ്ദുല്ലാഹിബ്നു മുഹമ്മദിനിൽ ഹനഫിയ്യ(റ): ഞാനും എന്റെ പിതാവും അൻസാരികളിൽപ്പെട്ട ഞങ്ങളുടെ ഒരു പുതുമാരനെ (അളിയനെ) സന്ദർശിക്കാൻ പോയി. അന്നേരം നിസ്കാരത്തിന്റെ സമയമായി. അപ്പോൾ അദ്ദേഹം ഒരു ബന്ധുവിനോട് പറഞ്ഞു: മോളേ, എനിക്ക് വുളൂ ചെയ്യാനുള്ള വെള്ളം കൊണ്ടുവരൂ. ഞാനൊന്ന് നിസ്കരിച്ച് വിശ്രമിക്കട്ടെ. നിവേദകൻ പറയുന്നു: അദ്ദേഹം ആ പറഞ്ഞതിനെ ഞങ്ങൾ എതിർത്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ബിലാലേ, എഴുന്നേൽക്കുക (ഇഖാമത്ത് വിളിക്കുക), നിസ്കാരം കൊണ്ട് ഞങ്ങൾക്ക് വിശ്രമം നൽകുക." (ദ)', 'عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ الْحَنَفِيَّةِ', 'അബ്ദുല്ലാഹിബ്നു മുഹമ്മദിനിൽ ഹനഫിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 462, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْسِبُ أَحَدًا إِلَّا إِلَى الدِّينِ. (د)', 'ആഇശ(റ): റസൂൽ(സ) ഒരാളെയും ദീനിലേക്ക് ചേർത്തിവിളിക്കുന്നതല്ലാതെ ഞാൻ കേട്ടിട്ടില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ فَزَعٌ بِالْمَدِينَةِ، فَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَسًا لِأَبِي طَلْحَةَ، فَقَالَ: "مَا رَأَيْنَا شَيْئًا". أَوْ: "مَا رَأَيْنَا مِنْ فَزَعٍ، وَإِنْ وَجَدْنَاهُ لَبَحْرًا". (ق,د,ت,جه)', 'അനസ്(റ): മദീനയിൽ ഒരു ഭീതിയുണ്ടായി. അപ്പോൾ റസൂൽ(സ) അബൂത്വൽഹ(റ)വിന്റെ കുതിരപ്പുറത്ത് കയറിക്കൊണ്ട് പറഞ്ഞു: "നാമൊന്നും കണ്ടിട്ടില്ല." അല്ലെങ്കിൽ "പേടിക്കേണ്ട യാതൊരുകാര്യവും നാം കണ്ടില്ല. അതിവേഗം ഓടുന്ന കുതിരയാണിതെന്നാണ് നാം മനസ്സിലാക്കിയത്." (ബു,മു,ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَعِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ، فَنَادَى بِصَوْتٍ رَفِيعٍ، فَقَالَ: "يَا مَعْشَرَ مَنْ أَسْلَمَ بِلِسَانِهِ وَلَمْ يُفْضِ الْإِيمَانُ إِلَى قَلْبِهِ، لَا تُؤْذُوا الْمُسْلِمِينَ وَلَا تُعَيِّرُوهُمْ وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنْ تَتَبَّعَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ تَتَبَّعَ اللَّهُ عَوْرَتَهُ، وَمَنْ تَتَبَّعَ اللَّهُ عَوْرَتَهُ يَفْضَحْهُ وَلَوْ فِي جَوْفِ رَحْلِهِ". قَالَ: وَنَظَرَ ابْنُ عُمَرَ يَوْمًا إِلَى الْبَيْتِ –أَوْ إِلَى الْكَعْبَةِ– فَقَالَ: مَا أَعْظَمَكِ وَأَعْظَمَ حُرْمَتَكِ، وَالْمُؤْمِنُ أَعْظَمُ حُرْمَةً عِنْدَ اللَّهِ مِنْكِ. حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) മിമ്പറിൽ കയറി. അവിടന്ന് ഉയർന്ന ശബ്ദത്തിൽ വിളിച്ചുപറഞ്ഞു: "നാക്ക്കൊണ്ട് മാത്രം മുസ്‌ലിമായി വിശ്വാസം ഹൃദയത്തിൽ കടന്ന് വരാത്ത കൂട്ടരേ, നിങ്ങൾ (യഥാർത്ഥ) മുസ്‌ലിംകളെ ബുദ്ധിമുട്ടിക്കരുത്, അവരെ അധിക്ഷേപിക്കരുത്, അവരുടെ നഗ്നതകളെ പിന്തുടരുകയുമരുത്. കാരണം ആരെങ്കിലും തന്റെ മുസ്‌ലിം സഹോദരന്റെ നഗ്നത പിന്തുടർന്നാൽ അല്ലാഹു അവന്റെ നഗ്നത പിന്തുടരുന്നതാണ്. അല്ലാഹു ആരുടെയെങ്കിലും നഗ്നത പിൻതുടർന്നാൽ അവനെ വഷളാക്കുന്നതാണ്, അവന്റെ വീടിനകത്താണെങ്കിലും ശരി." നിവേദകൻ പറയുന്നു: ഇബ്നുഉമർ(റ) ഒരു ദിവസം കഅ്ബയെ നോക്കിക്കൊണ്ട് പറഞ്ഞു: നീ എത്ര മഹത്വമുള്ളതാണ്? നിന്റെ മഹത്വം എത്ര ഉന്നതം? എന്നാൽ യഥാർത്ഥ മുഅ്മിൻ അല്ലാഹുവിന്റെയടുക്കൽ നിന്നെക്കാൾ ഉയർന്ന സ്ഥാനീയനാണ്. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا وَعَدَ الرَّجُلُ أَخَاهُ، وَمِنْ نِيَّتِهِ أَنْ يَفِيَ لَهُ فَلَمْ يَفِ، وَلَمْ يَجِئْ لِلْمِيعَادِ، فَلَا إِثْمَ عَلَيْهِ". (د,ت)', 'സൈദുബ്നു അർഖം(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ സഹോദരനോട് പൂർത്തീകരിച്ചു കൊടുക്കണമെന്ന മനസ്സാലെ, വാഗ്ദാനം ചെയ്യുകയും അങ്ങനെ പൂർത്തീകരിക്കാതെ വരികയും വാഗ്ദത്തസ്ഥലത്ത് വരാതിരിക്കുകയും ചെയ്താൽ അവന്റെ മേൽ കുറ്റമില്ല." (ദ,തു)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي الْحَمْسَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبَيْعٍ قَبْلَ أَنْ يُبْعَثَ، وَبَقِيَتْ لَهُ بَقِيَّةٌ، فَوَعَدْتُهُ أَنْ آتِيَهُ بِهَا فِي مَكَانِهِ، فَنَسِيتُ، ثُمَّ ذَكَرْتُ بَعْدَ ثَلَاثٍ، فَجِئْتُ فَإِذَا هُوَ فِي مَكَانِهِ، فَقَالَ: "يَا فَتًى، لَقَدْ شَقَقْتَ عَلَيَّ، أَنَا هَاهُنَا مُنْذُ ثَلَاثٍ أَنْتَظِرُكَ". (د)', 'അബ്ദുല്ലാഹിബ്നു അബിൽഹംസാഅ്(റ): നബി(സ)യുടെ പ്രവാചകത്വലബ്ധിക്കു മുമ്പൊരിക്കൽ തിരുമേനി(സ)യുമായി ഞാൻ കച്ചവടം നടത്തി. അവിടത്തേക്ക് കുറച്ചുകൂടി നൽകാൻ ബാക്കിയുണ്ടായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞ സ്ഥലത്ത് സാധനമെത്തിക്കാമെന്ന് ഞാൻ വാക്ക് നൽകി. പക്ഷെ, ഞാനത് മറന്നു. മൂന്ന് ദിവസത്തിനുശേഷം എനിക്കത് ഓർമ്മവന്നു. അങ്ങനെ ഞാൻ അവിടെ ചെന്നു. അപ്പോൾ അവിടന്നതാ അതേ സ്ഥലത്ത് നിൽക്കുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഓ യുവാവേ, നിശ്ചയം താങ്കളെന്നെ ബുദ്ധിമുട്ടാക്കി. മൂന്ന് ദിവസമായി ഇവിടെ ഞാൻ താങ്കളെ പ്രതീക്ഷിച്ചിരിക്കുകയാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ أَبِي الْحَمْسَاءِ', 'അബ്ദുല്ലാഹിബ്നു അബിൽഹംസാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْيَض قَدْ شَابَ، وَكَانَ الْحَسَنُ بْنُ عَلِيٍّ – رَضِيَ اللهُ عَنْهُمَا – يُشْبِهُهُ، وَأَمَرَ لَنَا بِثَلَاثَةَ عَشَرَ قَلُوصًا، فَذَهَبْنَا نَقْبِضُهَا فَأَتَانَا مَوْتُهُ، فَلَمْ يُعْطُونَا شَيْئًا، فَلَمَّا قَامَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ كَانَتْ لَهُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِدَةٌ فَلْيَجِئْ. فَقُمْتُ إِلَيْهِ فَأَخْبَرْتُهُ، فَأَمَرَ لَنَا بِهَا. وَفِي رواية: قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ الْحَسَنُ بْنُ عَلِيٍّ – رَضِيَ اللهُ عَنْهُمَا – يُشْبِهُهُ. حَسَنٌ. (ق,ت)', 'അബൂജുഹൈഫ(റ): വെളുത്ത് നരബാധിച്ച അവസ്ഥയിൽ ഞാൻ റസൂൽ(സ)യെ കണ്ടു. അലി(റ)വിന്റെ മകൻ ഹസൻ(റ) അവിടത്തോട് സാദൃശ്യമുണ്ടായിരുന്നു. ഞങ്ങൾക്ക് പതിമൂന്ന് ഒട്ടകങ്ങളെ നൽകാൻ അവിടുന്ന് കൽപിച്ചു. അപ്പോൾ ഞങ്ങൾ അവയെ എടുക്കാൻ പോയി. അന്നേരം അവിടത്തെ വിയോഗവിവരം ഞങ്ങളറിഞ്ഞു. അവർ ഞങ്ങൾക്ക് ഒന്നും തന്നില്ല. അങ്ങനെ അബൂബക്കർ(റ) ഭരണമേറ്റെടുത്തപ്പോൾ പറഞ്ഞു: റസൂൽ(സ) ആർക്കെങ്കിലും വല്ല വാഗ്ദാനവും നൽകിയിട്ടുണ്ടെങ്കിൽ അവർ വരിക. അപ്പോൾ ഞാൻ എഴുന്നേറ്റ് നിന്ന് കാര്യം പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം ഞങ്ങൾക്കത് (നൽകാൻ) കൽപിച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=250), 1, 'وَفِي رِوَايَةٍ: قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ الْحَسَنُ بْنُ عَلِيٍّ – رَضِيَ اللهُ عَنْهُمَا – يُشْبِهُهُ. حَسَنٌ. (ق,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം പറഞ്ഞു: നബി(സ)യെ ഞാൻ കണ്ടു. അലി(റ)വിന്റെ മകൻ ഹസൻ(റ) അവിടത്തോട് കൂടുതൽ സാദൃശ്യമുള്ളവരാണ്. (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشُّؤْمُ فِي ثَلَاثَةٍ: فِي الْمَرْأَةِ، وَالْمَسْكَنِ، وَالدَّابَّةِ". صَحِيحٌ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്നെണ്ണത്തിലാണ് ദുശ്ശകുനമുള്ളത്: പെണ്ണിലും, പാർപ്പിടത്തിലും, മൃഗത്തിലും." (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 464, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ حَكِيمِ بْنِ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا شُؤْمَ، وَقَدْ يَكُونُ الْيُمْنُ فِي الدَّارِ وَالْمَرْأَةِ وَالْفَرَسِ". (ت)', 'ഹകീമുബ്നു മുആവിയ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ദുശ്ശകുനം ഇല്ല. വീട്ടിലും പെണ്ണിലും കുതിരകളിലും ചിലപ്പോൾ ശുഭലക്ഷണമുണ്ടാകും." (തു)', 'حَكِيمِ بْنِ مُعَاوِيَةَ', 'ഹകീമുബ്നു മുആവിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يُحِبُّ أَنْ يَرَى أَثَرَ نِعْمَتِهِ عَلَى عَبْدِهِ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു തന്റെ അനുഗ്രഹത്തിന്റെ പ്രകടനങ്ങൾ അടിമയിൽ കാണുന്നത് ഇഷ്ടപ്പെടുന്നു." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُبْدِعَ بِي، فَاحْمِلْنِي. قَالَ: "لَا أَجِدُ مَا أَحْمِلُكَ عَلَيْهِ، وَلَكِنِ ائْتِ فُلَانًا فَلَعَلَّهُ أَنْ يَحْمِلَكَ". فَأَتَاهُ فَحَمَلَهُ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ". (م,د,ت)', 'അബൂമസ്ഊദിൽ അൻസാരി(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ചുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ യാത്രാമൃഗം നഷ്ടപ്പെട്ടിരിക്കുന്നു. അത്കൊണ്ട് എനിക്കൊരു യാത്രാമൃഗം നൽകിയാലും. അവിടന്ന് പറഞ്ഞു: നിനക്കുതരാൻ എന്റെ പക്കൽ യാത്രാമൃഗങ്ങളൊന്നുമില്ല, എങ്കിലും നീ ഇന്നാലിന്ന ആളെ സമീപിക്കുക. അയാൾ നിനക്ക് ഒരു യാത്രാമൃഗത്തെ തന്നേക്കാം. അയാൾ അദ്ദേഹത്തെ സമീപിക്കുകയും അദ്ദേഹം അയാൾക്ക് യാത്രാമൃഗത്തെ നൽകുകയും ചെയതു. അപ്പോഴയാൾ റസൂൽ(സ)യുടെ അടുക്കൽ വന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നന്മയിലേക്ക് വഴികാണിക്കുന്നവന് ആ നന്മ ചെയ്യുന്നവന്റെ പ്രതിഫലമുണ്ടാകും." (മു,ദ,തു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദിൽ അൻസാരി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ أَبِي عُثْمَانَ النَّهْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي سَعْدُ بْنُ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ مُحَمَّدٍ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ أَنَّهُ قَالَ: "مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ – وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ – فَالْجَنَّةُ عَلَيْهِ حَرَامٌ". قَالَ: فَلَقِيتُ أَبَا بَكْرَةَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د,جه)', 'അബൂഉസ്മാനിന്നഹ്ദീ: സഅ്ദുബ്നു മാലിക്(റ) എന്നോട് പറഞ്ഞു: "ആരെങ്കിലും തന്റെ പിതാവല്ലാത്തവരെക്കുറിച്ച് - അയാൾ തന്റെ പിതാവല്ലന്നറിഞ്ഞ് കൊണ്ട് - അയാൾ തന്റെ പിതാവാണെന്ന് വാദിച്ചാൽ സ്വർഗ്ഗം അവന് നിഷിദ്ധമാണ്." എന്ന് മുഹമ്മദ്(സ) പറഞ്ഞത് എന്റെ രണ്ട് ചെവികൾ കേൾക്കുകയും എന്റെ ഹൃദയം മനഃപാഠമാക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അബൂബക്കർ(റ)വിനെ ഞാൻ കണ്ടുമുട്ടി. അപ്പോൾ ഞാനത് അദ്ദേഹത്തെ അറിയിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് എന്റെ രണ്ട് ചെവികളും മുഹമ്മദ്(സ)യിൽനിന്ന് കേൾക്കുകയും എന്റെ ഹൃദയം മനഃപാഠമാക്കുകയും ചെയ്തിരിക്കുന്നു. (ബു,മു,ദ,ജ)', 'أَبِي عُثْمَانَ النَّهْدِيِّ', 'അബൂഉസ്മാനിന്നഹ്ദീ', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 465, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَوَلَّى قَوْمًا بِغَيْرِ إِذْنِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ يَوْمَ الْقِيَامَةِ عَدْلٌ وَلَا صَرْفٌ". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ യജമാനന്മാരുടെ സമ്മതമില്ലാതെ ഒരു കൂട്ടർക്ക് തന്റെ ഉത്തരവാദിത്വമേൽപിച്ചാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും സകല ജനങ്ങളുടെയും ശാപമുണ്ടാകുന്നതാണ്. അന്ത്യനാളിൽ അവന്റെ പശ്ചാത്താപമോ പ്രായശ്ചിത്തമോ അല്ലെങ്കിൽ അവന്റെ നിർബന്ധ കർമങ്ങളോ സുന്നത് കർമങ്ങളോ സ്വീകരിക്കപ്പെടുകയില്ല." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوِ انْتَمَى إِلَى غَيْرِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ الْمُتَتَابِعَةُ إِلَى يَوْمِ الْقِيَامَةِ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും തന്റെ പിതാവല്ലാത്തവരെക്കുറിച്ച് തന്റെ പിതാവാണെന്ന് പറയുകയോ തന്റെ യജമാനനല്ലാത്തവരിലേക്ക് തന്നെ ചേർത്തുകയോ ചെയ്താൽ അവന്റെ മേൽ അന്ത്യനാൾ വരെ തുടരുന്ന ദൈവശാപമുണ്ടാകുന്നതാണ്." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُصُّ عَلَى النَّاسِ إِلَّا أَمِيرٌ أَوْ مَأْمُورٌ أَوْ مُرَاءٍ". [ز: في سنده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭരണാധിപനോ അയാളാൽ ഏൽപിക്കപ്പെട്ടയാളോ പ്രശസ്തി ആഗ്രഹിക്കുന്നവനോ അല്ലാതെ മറ്റാരും ജനങ്ങളിൽ വിളംബരങ്ങൾ നടത്തുകയില്ല." (സനദിൽ ബലഹീനനുണ്ട്.) (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ يَكُنِ الْقَصَصُ فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا زَمَنِ أَبِي بَكْرٍ، وَلَا زَمَنِ عُمَرَ. (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് വിളംബരം ചെയ്യൽ ഉണ്ടായിരുന്നില്ല. അബൂബക്കർ(റ)വിന്റെയോ ഉമർ(റ)വിന്റെയോ കാലത്തും അതുണ്ടായിരുന്നില്ല. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ خَطِيبًا خَطَبَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ رَشِدَ، وَمَنْ يَعْصِهِمَا، فَقَالَ: "قُمْ" أَوْ قَالَ: "اذْهَبْ، فَبِئْسَ الْخَطِيبُ أَنْتَ". (م,د)', 'അദിയ്യുബ്നു ഹാതിം(റ): നബി(സ)യുടെ അടുത്ത് ഒരു പ്രഭാഷകൻ ഇങ്ങനെ പ്രസംഗിച്ചു: ആരെങ്കിലും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിച്ചാൽ അവൻ സന്മാർഗിയായി, ആരെങ്കിലും എതിര് പ്രവർത്തിച്ചാൽ, അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "എഴുന്നേൽക്കുക." അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞു: "പോകുക, നീ എത്ര മോശമായ പ്രഭാഷകനാണ്." (മു,ദ)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 466, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ جَوْذَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اعْتَذَرَ إِلَى أَخِيهِ بِمَعْذِرَةٍ، فَلَمْ يَقْبَلْهَا، كَانَ عَلَيْهِ مِثْلُ خَطِيئَةِ صَاحِبِ مَكْسٍ". [ز: مُرْسَلٌ، وَمُرْسِلُهُ مَجْهُولٌ] (جه)', 'ജൗദാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ സഹോദരനോട് വല്ല ഒഴിവുകഴിവും ബോധിപ്പിക്കുകയും, അവനത് സ്വീകരിക്കാതിരിക്കുകയും ചെയ്താൽ, അനർഹമായത് പിടിച്ചുവാങ്ങുന്നവനുള്ള ശിക്ഷ അവനുണ്ട്." (ഹദീസ് മുർസലാണ്, മുർസിൽ അറിയപ്പെട്ടിട്ടില്ല.) (ജ)', 'جَوْذَانَ', 'ജൗദാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مُرْسَلٌ، وَمُرْسِلُهُ مَجْهُولٌ', null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمُسْتَشَارُ مُؤْتَمَنٌ". (جه)', 'അബൂമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉപദേശം തേടപ്പെട്ടവൻ വിശ്വസ്ഥത അർപ്പിക്കപ്പെട്ടവനാണ്." (ജ)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَشَارَ أَحَدُكُمْ أَخَاهُ فَلْيُشِرْ عَلَيْهِ". في سنده ضعيف (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും തന്റെ സഹോദരനോട് ഉപദേശം തേടുന്ന പക്ഷം അവൻ അയാൾക്ക് ഉപദേശം നൽകട്ടെ". പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتِ الْعَضْبَاءُ لَا تُسْبَقُ، فَجَاءَ أَعْرَابِيٌّ عَلَى قَعُودٍ لَهُ فَسَابَقَهَا فَسَبَقَهَا الْأَعْرَابِيُّ، فَكَأَنَّ ذَلِكَ شَقَّ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "حَقٌّ عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ لَا يَرْفَعَ شَيْئًا مِنَ الدُّنْيَا إِلَّا وَضَعَهُ". وفي رواية: "إِنَّ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ لَا يَرْتَفِعَ شَيْءٌ مِنَ الدُّنْيَا إِلَّا وَضَعَهُ". (خ,د)', 'അനസ്(റ): ചെവികീറിയ മൃഗങ്ങൾ (മത്സരത്തിൽ) പരാജയപ്പെടാറുണ്ടായിരുന്നില്ല. അപ്പോൾ ഒരു അഅ്റാബി തന്റെ ഒട്ടകക്കുട്ടിയുടെ പുറത്തിരുന്ന് വന്ന് അവയോട് മത്സരിക്കുകയും ആ അഅ്റാബി അവയെ മുൻകടക്കുകയും ചെയ്തു. അത് റസൂൽ(സ)യുടെ അനുചരർക്ക് വിഷമമുണ്ടാക്കി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ദുനിയാവിൽ താൻ ഉയർത്തിയതെല്ലാം താഴ്ത്തൽ മഹോന്നതനായ അല്ലാഹുവിന്റെ ഹഖിൽപ്പെട്ടതാണ്." മറ്റൊരു നിവേദനത്തിൽ: "ദുനിയാവിൽ ഉയർന്നതെല്ലാം താഴ്ത്തൽ മഹോന്നതനായ അല്ലാഹുവിന്റെ ഹഖാണ്." (ബു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 467, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=264), 1, 'وَفِي رِوَايَةٍ: "إِنَّ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ لَا يَرْتَفِعَ شَيْءٌ مِنَ الدُّنْيَا إِلَّا وَضَعَهُ". (خ,د)', 'മറ്റൊരു നിവേദനത്തിൽ: "ദുനിയാവിൽ ഉയർന്നതെല്ലാം താഴ്ത്തൽ മഹോന്നതനായ അല്ലാഹുവിന്റെ ഹഖാണ്." (ബു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَائِشَةَ وَأُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا، وَقَدْ سُئِلَتَا: أَيُّ الْعَمَلِ كَانَ أَحَبَّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتَا: مَا دِيمَ عَلَيْهِ، وَإِنْ قَلَّ. وفي رواية: عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ أَحَبُّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا دِيمَ عَلَيْهِ. (ت)', 'ആഇശ(റ), ഉമ്മുസലമ(റ): ഇരുവരും ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂൽ(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മം ഏതായിരുന്നു? മഹതികൾ പറഞ്ഞു: അൽപമാണെങ്കിലും സ്ഥിരമായി ചെയ്യുന്ന കർമ്മം.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=265), 1, 'وَفِي رِوَايَةٍ: عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ أَحَبُّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا دِيمَ عَلَيْهِ. (ت)', 'മറ്റൊരു നിവേദനത്തിൽ: ആഇശ(റ): റസൂൽ(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മം സ്ഥിരമായി പ്രവർത്തിക്കപ്പെടുന്നവയായിരുന്നു. (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَمِّرُوا الْآنِيَةَ، وَأَوْكِئُوا الْأَسْقِيَةَ، وَأَجِيفُوا الْأَبْوَابَ، وَأَطْفِئُوا الْمَصَابِيحَ، فَإِنَّ الْفُوَيْسِقَةَ رُبَّمَا جَرَّتِ الْفَتِيلَةَ، فَأَحْرَقَتْ أَهْلَ الْبَيْتِ". (ق,د,ت,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "പാത്രങ്ങൾ നിങ്ങൾ മൂടിവെക്കുക, വെള്ളപാത്രങ്ങൾ വായമൂടിക്കെട്ടി ബന്ധിക്കുക, വാതിലുകളടക്കുക, ദീപങ്ങൾ അണക്കുകയും ചെയ്യുക, കാരണം ചിലപ്പോൾ എലി വിളക്കിന്റെ തിരിവലിച്ചിട്ട് അത് വീട്ടുകാരെ കരിച്ചേക്കാം." (ബു,മു,ദ,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نِعِمَّا لِأَحَدِهِمْ أَنْ يُطِيعَ رَبَّهُ وَيُؤَدِّيَ حَقَّ سَيِّدِهِ". يَعْنِي الْمَمْلُوكَ. (خ,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അവരിലൊരാൾക്ക് എത്രയോ വലിയ നന്മയാണ് അല്ലാഹുവിന് വഴിപ്പെടലും തന്റെ യജമാനനോടുള്ള കടപ്പാട് വീട്ടലും." അടിമയെയാണുദ്ദേശിക്കുന്നത്. (ബു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ عَلَى كُثْبَانِ الْمِسْكِ يَوْمَ الْقِيَامَةِ: عَبْدٌ أَدَّى حَقَّ اللَّهِ وَحَقَّ مَوَالِيهِ، وَرَجُلٌ أَمَّ قَوْمًا وَهُمْ بِهِ رَاضُونَ، وَرَجُلٌ يُنَادِي بِالصَّلَوَاتِ الْخَمْسِ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ". (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് പേർ അന്ത്യനാളിൽ കസ്തൂരിക്കൂനമേൽ ആയിരിക്കും: അല്ലാഹുവിനോടും തന്റെ യജമാനരോടുമുള്ള ബാധ്യതകൾ നിർവ്വഹിച്ച അടിമ, ഒരു സമൂഹത്തെ നയിക്കുകയും അവർ തൃപ്തിപ്പെടുകയും ചെയ്തയാൾ, എല്ലാ രാപകലുകളിലും അഞ്ച് നിസ്കാരങ്ങൾക്ക് വാങ്ക് വിളിച്ചയാൾ." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 468, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَجُلٌ بِسِهَامٍ فِي الْمَسْجِدِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمْسِكْ بِنِصَالِهَا". قَالَ: نَعَمْ. (ق,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരാൾ കുറച്ച് അമ്പുകളുമായി പള്ളിയിൽ നടന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അതിന്റെ മുനയിൽ പിടിക്കൂ." അയാൾ പറഞ്ഞു: ശരി. (ബു,മു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا مَرَّ أَحَدُكُمْ فِي مَسْجِدِنَا – أَوْ: فِي سُوقِنَا – وَمَعَهُ نَبْلٌ فَلْيُمْسِكْ عَلَى نِصَالِهَا بِكَفِّهِ، أَنْ تُصِيبَ أَحَدًا مِنَ الْمُسْلِمِينَ بِشَيْءٍ. أَوْ: فَلْيَقْبِضْ عَلَى نِصَالِهَا". (ق,د,جه)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും നമ്മുടെ പള്ളിയിൽ - അല്ലെങ്കിൽ: നമ്മുടെ അങ്ങാടിയിൽ - നടക്കുകയും കയ്യിൽ ഒരു അമ്പ് ഉണ്ടായിരിക്കുകയും ചെയ്താൽ അവൻ തന്റെ മുൻകൈ കൊണ്ട് അതിന്റെ മുനപിടിക്കട്ടെ, ഒരു മുസ്‌ലിമിനെയും അത് ഏൽക്കാതിരിക്കാൻ." (ബു,മു,ദ,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ أَمَرَ رَجُلًا كَانَ يَتَصَدَّقُ بِالنَّبْلِ فِي الْمَسْجِدِ: أَنْ لَا يَمُرَّ بِهَا إِلَّا وَهُوَ آخِذٌ بِنُصُولِهَا. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): പള്ളിയിൽ വെച്ച് അമ്പ് ധർമ്മം ചെയ്യുകയായിരുന്ന ഒരാളോട് റസൂൽ(സ), അതിന്റെ മുനകൾ പിടിച്ചിട്ടല്ലാതെ നടക്കരുതെന്ന് കൽപിച്ചു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا مَرَّ أَحَدُكُمْ فِي مَجْلِسٍ أَوْ سُوقٍ وَبِيَدِهِ نَبْلٌ فَلْيَأْخُذْ بِنِصَالِهَا، ثُمَّ لِيَأْخُذْ بِنِصَالِهَا، ثُمَّ لِيَأْخُذْ بِنِصَالِهَا". قَالَ: فَقَالَ أَبُو مُوسَى: وَاللَّهِ مَا مُتْنَا حَتَّى سَدَّدْنَاهَا بَعْضُنَا فِي وُجُوهِ بَعْضٍ. (م)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും ഒരു സദസ്സിലോ അങ്ങാടിയിലോ, കൈയ്യിൽ ഒരു അമ്പുമായി നടക്കുകയാണെങ്കിൽ അതിന്റെ മുനയിൽ പിടിക്കട്ടെ, അതിന്റെ മുനയിൽ പിടിക്കട്ടെ, അതിന്റെ മുനയിൽ പിടിക്കട്ടെ." നിവേദകൻ പറയുന്നു: അപ്പോൾ അബൂമൂസ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ മരിക്കുന്നതിന് മുമ്പ് തന്നെ ചിലരുടെ അമ്പിന്റെ മുന മറ്റു ചിലരുടെ മുഖത്ത് തട്ടിയിരിക്കുന്നു. (മു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتَعَلَّمَ لَهُ كَلِمَاتٍ مِنْ كِتَابِ يَهُودَ، وَقَالَ: "إِنِّي وَاللَّهِ مَا آمَنُ يَهُودَ عَلَى كِتَابٍ". قَالَ: فَمَا مَرَّ بِي نِصْفُ شَهْرٍ حَتَّى تَعَلَّمْتُهُ لَهُ. قَالَ: فَلَمَّا تَعَلَّمْتُهُ كَانَ إِذَا كَتَبَ إِلَى يَهُودَ كَتَبْتُ إِلَيْهِمْ، وَإِذَا كَتَبُوا إِلَيْهِ قَرَأْتُ لَهُ كِتَابَهُمْ. حَسَنٌ صَحِيحٌ. (د,ت)', 'സൈദുബ്നു സാബിത്(റ): ജൂതരുടെ കത്തിലെ ചിലവാക്കുകൾ തിരുമേനി(സ)ക്ക് വേണ്ടി പഠിക്കാൻ അവിടന്ന് എന്നോട് കൽപിച്ചു. അവിടന്നരുളി: "നിശ്ചയം, അല്ലാഹുവാണ് സത്യം, ഒരു കത്തിലും ഞാൻ ജൂതരെ വിശ്വസിക്കുന്നില്ല." നിവേദകൻ പറയുന്നു: അരമാസത്തിനുള്ളിൽ ഞാനത് അവിടത്തേക്ക് വേണ്ടി പഠിച്ചു. നിവേദകൻ: ഞാനത് പഠിച്ചു, അവിടന്ന് ജൂതരിലേക്ക് കത്തയക്കുമ്പോൾ ഞാനായിരുന്നു കത്തെഴുതിയിരുന്നത്. അവർ അവിടത്തേക്കെഴുതിയാൽ ഞാനായിരിക്കുമത് തിരുമേനി(സ)ക്ക് വായിച്ചു കൊടുക്കുക. (ദ,തു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 469, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اقْتَبَسَ عِلْمًا مِنَ النُّجُومِ اقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ زَادَ مَا زَادَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ജ്യോതിശാസ്ത്രത്തിൽ നിന്ന് ഒരു ഭാഗം കരസ്ഥമാക്കിയാൽ സിഹ്റിന്റെ ഒരു ഭാഗം അവൻ കരസ്ഥമാക്കിയിരിക്കുന്നു. അവൻ എത്രമാത്രം ജ്യോതിശാസ്ത്രം പഠിക്കുന്നുവോ അത്ര സിഹ്റും പഠിക്കുന്നു." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَذْفِ قَالَ: "إِنَّهُ لَا يَصِيدُ صَيْدًا وَلَا يَنْكَأُ عَدُوًّا، وَإِنَّمَا يَفْقَأُ الْعَيْنَ وَيَكْسِرُ السِّنَّ". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): കല്ലേറ് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. അവിടന്ന് പറയുന്നു: "അത് വേട്ടമൃഗത്തെ കൊല്ലുകയോ ഒരു ശത്രുവിനെ മുറിയാക്കുകയോ ചെയ്യുകയില്ല. നേരെമറിച്ച് കണ്ണും പല്ലും പൊട്ടിക്കുക മാത്രമേ ചെയ്യുകയുള്ളൂ." (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ أُمِّ عَطِيَّةَ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً كَانَتْ تَخْتِنُ بِالْمَدِينَةِ، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُنْهِكِي، فَإِنَّ ذَلِكَ أَحْظَى لِلْمَرْأَةِ وَأَحَبُّ إِلَى الْبَعْلِ". ضَعِيفٌ (د)', 'ഉമ്മുഅതിയ്യതിൽ അൻസാരിയ്യ(റ): മദീനയിൽ ചേലാകർമ്മം ചെയ്യുന്ന ഒരു സ്ത്രീയുണ്ടായിരുന്നു. അവരോട് റസൂൽ(സ) പറഞ്ഞു: "അങ്ങനെ കൂടുതലായി മുറിക്കരുത്. കാരണം അത് ഭർത്താവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടതും പെണ്ണിന് കൂടുതൽ ആസ്വാദകരമായതുമാകുന്നു." (ഈ ഹദീസ് ബലഹീനമാണ്.) (ദ)', 'أُمِّ عَطِيَّةَ الْأَنْصَارِيَّةِ', 'ഉമ്മുഅതിയ്യതിൽ അൻസാരിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ دُكَيْنِ بْنِ سَعِيدٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْنَاهُ الطَّعَامَ، فَقَالَ: "يَا عُمَرُ، اذْهَبْ فَأَعْطِهِمْ". فَارْتَقَى بِنَا إِلَى عِلِّيَّةٍ. فَأَخَذَ الْمِفْتَاحَ مِنْ حُجْرَتِهِ فَفَتَحَ. (د)', 'ദുകൈനുബ്നു സഈദിൽ മുസ്നി(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുക്കൽ പോയി ഭക്ഷണം ചോദിച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഉമർ, താങ്കൾ പോയി അവർക്ക് ഭക്ഷണം നൽകുക." അങ്ങനെ ഉമർ(റ) ഞങ്ങളുമായി മുകളിലേക്ക് പോയി, തന്റെ അരക്കെട്ടിൽ നിന്നൊരു ചാവിയെടുത്ത് തുറന്നു. (ദ)', 'دُكَيْنِ بْنِ سَعِيدٍ الْمُزَنِيِّ', 'ദുകൈനുബ്നു സഈദിൽ മുസ്നി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَّكِئًا عَلَى وِسَادَةٍ. وفي رواية: عَلَى يَسَارِهِ. (د,ت)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) തലയിണയുടെ മേൽ ചാരിയിരിക്കുന്നത് ഞാൻ കണ്ടു. മറ്റൊരു നിവേദനത്തിൽ: അവിടത്തെ ഇടതുഭാഗത്തിന്മേൽ. (ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=278), 1, 'وَفِي رِوَايَةٍ: عَلَى يَسَارِهِ. (د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: അവിടത്തെ ഇടതുഭാഗത്തിന്മേൽ. (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِفِنَاءِ الْكَعْبَةِ مُحْتَبِيًا بِيَدِهِ، هَكَذَا. (خ)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) കഅ്ബയുടെ മുറ്റത്ത് കൈ കൊണ്ട് ഇങ്ങനെ മുട്ട്കെട്ടിയിരിക്കുന്നത് ഞാൻ കണ്ടു. (ബു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا مَشَى كَأَنَّهُ يَتَوَكَّأُ. (د)', 'അനസ്(റ): നബി(സ) നടക്കുകയാണെങ്കിൽ ചാരുന്നത് പോലെയായിരിക്കും. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ أَبِي الطُّفَيْلِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: كَيْفَ رَأَيْتَهُ؟ قَالَ: كَانَ أَبْيَضَ مَلِيحًا، إِذَا مَشَى كَأَنَّمَا يَهْوِي فِي صَبُوبٍ. (م,د)', 'അബൂഥുഫൈൽ(റ): ഞാൻ തിരുദൂതർ(സ)യെ കണ്ടു. ഞാൻ ചോദിച്ചു: അവിടത്തെ എങ്ങനെയാണ് താങ്കൾ കണ്ടത്? അദ്ദേഹം പറഞ്ഞു: അവിടന്ന് നല്ല അഴകുള്ളവരും വെള്ള നിറവുമായിരുന്നു. അവിടന്ന് നടന്നാൽ ഇറക്കമുള്ള സ്ഥലത്തിൽ നിന്നും ഇറങ്ങിവരുന്നത് പോലെയായിരിക്കും. (മു,ദ)', 'أَبِي الطُّفَيْلِ', 'അബൂഥുഫൈൽ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَنْزِلُوا عَلَى جَوَادِّ الطَّرِيقِ، وَلَا تَقْضُوا عَلَيْهَا الْحَاجَاتِ". (د,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നു: "സഞ്ചാരം കൂടുതലുള്ള വഴിയിൽ നിങ്ങൾ ഇറങ്ങരുത്. അതിൽ മലമൂത്ര വിസർജ്ജനം നടത്തുകയും ചെയ്യരുത്." (ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ يَعْلَمُ أَحَدُكُمْ مَا فِي الْوَحْدَةِ مَا سَارَ أَحَدٌ بِلَيْلٍ وَحْدَهُ". (خ,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "ഏകാന്ത സഞ്ചാരത്തിലുള്ള അപകടങ്ങൾ നിങ്ങൾ അറിയുമായിരുന്നെങ്കിൽ രാത്രിയിൽ നിങ്ങളാരും ഏകാന്തമായി നടക്കുകയില്ല." (ബു,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُؤَمُّ الرَّجُلُ فِي سُلْطَانِهِ، وَلَا يُجْلَسُ عَلَى تَكْرِمَتِهِ فِي بَيْتِهِ إِلَّا بِإِذْنِهِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളുടെ അധികാരപരിധിയിൽ അയാളുടെ സമ്മതമില്ലാതെ മറ്റൊരാൾ ഇമാം നിൽക്കുകയോ അവന്റെ വീട്ടിൽ അവന്റെ അനുവാദമില്ലാതെ ബഹുമാനപൂർവ്വം ഇരിക്കുന്ന സ്ഥലത്ത് ഇരിക്കുകയോ ചെയ്യരുത്." (മു,ദ,തു,ന,ജ)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ أَبِي بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي إِذْ جَاءَهُ رَجُلٌ وَمَعَهُ حِمَارٌ، فَقَالَ: يَا رَسُولَ اللَّهِ، ارْكَبْ. وَتَأَخَّرَ الرَّجُلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا، أَنْتَ أَحَقُّ بِصَدْرِ دَابَّتِكَ، إِلَّا أَنْ تَجْعَلَهُ لِي". قَالَ: قَدْ جَعَلْتُهُ لَكَ. قَالَ: فَرَكِبَ. حَسَنٌ. (د,ت)', 'അബൂബുറൈദ(റ): നബി(സ) നടന്നുപോകുമ്പോൾ ഒരാൾ കഴുതയുമായി വന്നു പറഞ്ഞു: തിരുദൂതരേ, അങ്ങ് ഇതിന്മേൽ കയറുക. എന്നിട്ട് അദ്ദേഹം പിന്നിലിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ല, നിന്റെ മൃഗത്തിന്റെ കടിഞ്ഞാൺ പിടിക്കാൻ ഏറ്റവും അർഹൻ നീ തന്നെ. നീയത് എനിക്ക് നൽകിയാലൊഴികെ." അദ്ദേഹം പറഞ്ഞു: ഞാനിത് അങ്ങേക്ക് നൽകിയിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ റസൂൽ(സ) അതിന്മേൽ കയറി. (ദ,തു)', 'أَبِي بُرَيْدَةَ', 'അബൂബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أُطَيِّنُ حَائِطًا لِي أَنَا وَأُمِّي، فَقَالَ: "مَا هَذَا يَا عَبْدَ اللَّهِ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، شَيْءٌ أُصْلِحُهُ. فَقَالَ: "الْأَمْرُ أَسْرَعُ مِنْ ذَلِكَ". وفي رواية: قَالَ: مَرَّ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نُعَالِجُ خُصًّا لَنَا وَهَى، فَقَالَ: "مَا هَذَا". فَقُلْنَا: خُصٌّ لَنَا وَهَى، فَنَحْنُ نُصْلِحُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَرَى الْأَمْرَ إِلَّا أَعْجَلَ مِنْ ذَلِكَ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞാനും ഉമ്മയും കൂടി ഞങ്ങളുടെ മതിലിന് മണ്ണുതേച്ചുകൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ) അതിലൂടെ നടന്നുവന്നു. അവിടന്ന് ചോദിച്ചു: "അബ്ദുല്ലാ, എന്താണിത്?" ഞാൻ പറഞ്ഞു: തിരുദൂതരേ, ഞാനിത് നന്നാക്കുകയാണ്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "മരണം അതിനേക്കാൾ പെട്ടെന്ന് വരുന്നതാണ്." മറ്റൊരു നിവേദനത്തിൽ: നിവേദകൻ പറയുന്നു: ഞങ്ങളുടെ വീഴാറായ വീട് നന്നാക്കുമ്പോൾ എന്റെ അരികിലൂടെ റസൂൽ(സ) നടന്നു പോയി. അവിടന്ന് ചോദിച്ചു: "ഇതെന്താണ്?" ഞങ്ങൾ പറഞ്ഞു: വീഴാറായ ഞങ്ങളുടെ വീടാണ്. അത് നന്നാക്കുകയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മരണം ഇതിനേക്കാൾ എളുപ്പം വരുമെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു." (ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=286), 1, 'وَفِي رِوَايَةٍ: قَالَ: مَرَّ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نُعَالِجُ خُصًّا لَنَا وَهَى، فَقَالَ: "مَا هَذَا". فَقُلْنَا: خُصٌّ لَنَا وَهَى، فَنَحْنُ نُصْلِحُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَرَى الْأَمْرَ إِلَّا أَعْجَلَ مِنْ ذَلِكَ". (د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: നിവേദകൻ പറയുന്നു: ഞങ്ങളുടെ വീഴാറായ വീട് നന്നാക്കുമ്പോൾ എന്റെ അരികിലൂടെ റസൂൽ(സ) നടന്നു പോയി. അവിടന്ന് ചോദിച്ചു: "ഇതെന്താണ്?" ഞങ്ങൾ പറഞ്ഞു: വീഴാറായ ഞങ്ങളുടെ വീടാണ്. അത് നന്നാക്കുകയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മരണം ഇതിനേക്കാൾ എളുപ്പം വരുമെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ، فَرَأَى قُبَّةً مُشْرِفَةً، فَقَالَ: "مَا هَذِهِ". قَالَ لَهُ أَصْحَابُهُ: هَذِهِ لِفُلَانٍ، رَجُلٍ مِنَ الْأَنْصَارِ، قَالَ: فَسَكَتَ وَحَمَلَهَا فِي نَفْسِهِ، حَتَّى إِذَا جَاءَ صَاحِبُهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَلِّمُ عَلَيْهِ فِي النَّاسِ أَعْرَضَ عَنْهُ، صَنَعَ ذَلِكَ مِرَارًا، حَتَّى عَرَفَ الرَّجُلُ الْغَضَبَ فِيهِ وَالْإِعْرَاضَ عَنْهُ، فَشَكَا ذَلِكَ إِلَى أَصْحَابِهِ، فَقَالَ: وَاللَّهِ إِنِّي لَأُنْكِرُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: خَرَجَ فَرَأَى قُبَّتَكَ، قَالَ: فَرَجَعَ الرَّجُلُ إِلَى قُبَّتِهِ فَهَدَمَهَا، حَتَّى سَوَّاهَا بِالْأَرْضِ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَلَمْ يَرَهَا، قَالَ: "مَا فَعَلَتِ الْقُبَّةُ". قَالُوا: شَكَا إِلَيْنَا صَاحِبُهَا إِعْرَاضَكَ عَنْهُ، فَأَخْبَرْنَاهُ، فَهَدَمَهَا، فَقَالَ: "أَمَا إِنَّ كُلَّ بِنَاءٍ وَبَالٌ عَلَى صَاحِبِهِ إِلَّا مَا لَا، إِلَّا مَا لَا" يَعْنِي: مَا لَا بُدَّ مِنْهُ. (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പുറത്തിറങ്ങി നടന്നപ്പോൾ ഉയർന്ന ഒരു കുംഭഗോപുരം കണ്ടു. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "ഇതെന്താണ്?" അവിടത്തെ അനുചരർ പറഞ്ഞു: അൻസാറുകളിൽപ്പെട്ട ഒരാളുടേതാണ്. നിവേദകൻ പറയുന്നു: അപ്പോൾ റസൂൽ(സ) മൗനം പാലിച്ചു. അദ്ദേഹത്തെ കാണുന്നത് വരെ അത് മനസ്സിൽ വെച്ചു. അങ്ങനെ അദ്ദേഹം വന്നു. നബി(സ)യോട് ജനമധ്യേ സലാം പറഞ്ഞു. എന്നാൽ റസൂൽ(സ) മുഖം തിരിച്ചു. അദ്ദേഹം പലപ്രാവശ്യം അങ്ങനെ ചെയ്തു. നബി(സ) ദേശ്യവാനാണ്. അതുകൊണ്ടാണ് മുഖം തിരിക്കുന്നതെന്നും അദ്ദേഹം മനസ്സിലാക്കി. അപ്പോൾ അദ്ദേഹം കൂട്ടുകാരോട് പരാതി പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാൻ റസൂൽ(സ)യെ ദേഷ്യം പിടിപ്പിച്ചിരിക്കുകയാണ്! അവർ പറഞ്ഞു: തിരുമേനി(സ) വരുമ്പോൾ നിന്റെ ഗോപുരം കണ്ടിരുന്നു. നിവേദകൻ തുടരുന്നു: ഉടനെ അദ്ദേഹം തിരിച്ചുപോയി തന്റെ ഗോപുരം പൊളിച്ചു നിരപ്പാക്കി. പിന്നെ ഒരു ദിവസം റസൂൽ(സ) പോയപ്പോൾ അതവിടെ കണ്ടില്ല. അവിടന്ന് ചോദിച്ചു: "ഗോപുരം എന്ത് ചെയ്തു?" അവർ പറഞ്ഞു: അങ്ങയുടെ ദേഷ്യത്തെക്കുറിച്ച് അതിന്റെ ഉമട ഞങ്ങളോട് പരാതിപ്പെട്ടപ്പോൾ ഞങ്ങൾ വിഷയം പറഞ്ഞു. ഉടനെ അദ്ദേഹം അത് പൊളിച്ച് കളഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "എല്ലാ കെട്ടിടങ്ങളും അതിന്റെ ഉടമക്ക് നാശമാണ്, അവന് ഒഴിച്ച് കൂടാൻ പറ്റാത്തതൊഴികെ." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَيْتُنِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَنَيْتُ بِيَدِي بَيْتًا يُكِنُّنِي مِنَ الْمَطَرِ، وَيُظِلُّنِي مِنَ الشَّمْسِ، مَا أَعَانَنِي عَلَيْهِ أَحَدٌ مِنْ خَلْقِ اللَّهِ. (خ)', 'ഇബ്നുഉമർ(റ): മഴയിൽ നിന്ന് മറയിടുന്ന, വെയിലുണ്ടാകുമ്പോൾ തണലിടുന്ന ഒരു വീട് എന്റെ കൈകൾ കൊണ്ട് ഞാൻ നിർമ്മിച്ച് നബി(സ)യോടു കൂടെ നിൽക്കുന്നതായി ഞാൻ സ്വപ്നം കണ്ടു. അല്ലാഹുവിന്റെ സൃഷ്ടികളിൽ ഒരാളും അതിനുവേണ്ടി എന്നെ സഹായിച്ചിട്ടില്ല. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَعِبَ بِالنَّرْدِ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ". (د,جه)', 'അബുമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും പകിട കളിച്ചാൽ അവൻ അല്ലാഹുവിനും അവന്റെ റസൂലിനും എതിര് പ്രവർത്തിച്ചിരിക്കുന്നു." (ദ,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബുമൂസൽ അശ്അരി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَعِبَ بِالنَّرْدَشِيرِ فَكَأَنَّمَا غَمَسَ يَدَهُ فِي لَحْمِ خِنْزِيرٍ وَدَمِهِ". (م,د,جه)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും പകിട കളിച്ചാൽ അയാൾ പന്നിയിറച്ചിയിലും അതിന്റെ രക്തത്തിലും തന്റെ കൈകൾ മുക്കിയതുപോലെയാണ്." (മു,ദ,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يَتْبَعُ حَمَامَةً، فَقَالَ: "شَيْطَانٌ يَتْبَعُ شَيْطَانَةً". (د,جه)', 'അബുഹുറൈറ(റ): പ്രാവിനെ പിന്തുടരുന്ന ഒരാളെ കണ്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പെൺപിശാചിനെ പിന്തുടരുന്ന ഒരു പിശാച്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَظَرَ إِلَى إِنْسَانٍ يَتْبَعُ طَائِرًا، فَقَالَ: "شَيْطَانٌ يَتْبَعُ شَيْطَانًا". (جه)', 'ആഇശ(റ): ഒരു പക്ഷിയെ പിന്തുടരുന്ന ഒരാളെ നോക്കിക്കൊണ്ട് നബി(സ) പറഞ്ഞു: "പിശാചിനെ പിന്തുടരുന്ന മറ്റൊരു പിശാച്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَلْعَبُ بِالْبَنَاتِ، فَرُبَّمَا دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي الْجَوَارِي، فَإِذَا دَخَلَ خَرَجْنَ، وَإِذَا خَرَجَ دَخَلْنَ. (ق,د,ن,جه)', 'ആഇശ(റ): ഞാൻ പെൺകുട്ടികളോടൊത്ത് കളിക്കാറുണ്ടായിരുന്നു. ചിലസമയങ്ങളിൽ റസൂൽ(സ) കയറിവരുമ്പോൾ എന്റെ കൂടെ ധാരാളം പെൺകൊച്ചുകളുണ്ടാകും. തിരുമേനി(സ) വന്നാൽ അവർ പുറത്തുപോകും. അവിടന്ന് പുറത്തേക്കിറങ്ങിയാൽ അവർ വീണ്ടും വരും. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 474, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ غَزْوَةِ تَبُوك، أَوْ خَيْبَرَ، وَفِي سَهْوَتِهَا سِتْرٌ، فَهَبَّتْ رِيحٌ فَكَشَفَتْ نَاحِيَةَ السِّتْرِ عَنْ بَنَاتٍ لِعَائِشَةَ لُعَبٍ، فَقَالَ: "مَا هَذَا يَا عَائِشَةُ". قَالَتْ: بَنَاتِي، وَرَأَى بَيْنَهُنَّ فَرَسًا لَهُ جَنَاحَانِ مِنْ رِقَاعٍ، فَقَالَ: "مَا هَذَا الَّذِي أَرَى وَسْطَهُنَّ". قَالَتْ: فَرَسٌ، قَالَ: "وَمَا هَذَا الَّذِي عَلَيْهِ". قَالَتْ: جَنَاحَانِ، قَالَ: "فَرَسٌ لَهُ جَنَاحَانِ". قَالَتْ: أَمَا سَمِعْتَ أَنَّ لِسُلَيْمَانَ خَيْلًا لَهَا أَجْنِحَةٌ؟ قَالَتْ: فَضَحِكَ حَتَّى رَأَيْتُ نَوَاجِذَهُ. (د)', 'ആഇശ(റ): നബി(സ) തബൂക് -അല്ലെങ്കിൽ ഖൈബർ- യുദ്ധം കഴിഞ്ഞ് വരികയായിരുന്നു. ആഇശ(റ)യുടെ ശെൽഫിന് (സാധനങ്ങൾ വെക്കുന്ന പലകത്തട്ട്) ഒരു വിരിയുണ്ടായിരുന്നു. അന്നേരം ഒരു കാറ്റടിച്ച് വിരി നീങ്ങിയപ്പോൾ അവരുടെ കളിത്തോഴികളായ പെൺകുട്ടികളെ അവിടന്ന് കണ്ടു. അവിടന്ന് ചോദിച്ചു: "ഇതെന്താണ് ആഇശ?" അവർ പറഞ്ഞു: ഇതെന്റെ പെൺകുട്ടികളാകുന്നു. അവരുടെ ഇടയിൽ തുന്നിച്ചേർത്ത രണ്ട് ചിറകുള്ള ഒരു കുതിരയെ കണ്ടപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അവരുടെ മധ്യത്തിൽ കാണുന്നതെന്താണ്?" അവർ പറഞ്ഞു: കുതിര. നബി(സ) ചോദിച്ചു: "അതിന്റെ മുകളിലെന്താണ്?" അവർ പറഞ്ഞു: രണ്ട് ചിറകുകൾ. നബി(സ) പറഞ്ഞു: "രണ്ട് ചിറകുള്ള കുതിരയോ?" അവർ ചോദിച്ചു: അവിടന്ന് കേട്ടിട്ടില്ലേ, സുലൈമാൻ(റ)വിന് ചിറകുകളുള്ള കുതിരയുണ്ടായിരുന്നുവെന്ന്. അവർ പറയുന്നു: അപ്പോൾ റസൂൽ(സ) അവിടത്തെ അണപ്പല്ലുകൾ പുറത്ത്കാണും വിധം ചിരിച്ചു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَدِمَ مِنْ سَفَرٍ تُلُقِّيَ بِنَا. قَالَ: فَتُلُقِّيَ بِي وَبِالْحَسَنِ أَوْ بِالْحُسَيْنِ، قَالَ: فَحَمَلَ أَحَدَنَا بَيْنَ يَدَيْهِ، وَالْآخَرَ خَلْفَهُ، حَتَّى قَدِمْنَا الْمَدِينَةَ. (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): റസൂൽ(സ) യാത്ര കഴിഞ്ഞു വരികയാണെങ്കിൽ ഞങ്ങളെ കണ്ടുമുട്ടുമായിരുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ എന്നെയും ഹസൻ(റ)വിനെയോ ഹുസൈൻ(റ)വിനെയോ കണ്ടുമുട്ടി. അപ്പോൾ ഞങ്ങളിലൊരാളെ അവിടത്തെ മുൻവശത്തും മറ്റെയാളെ പിന്നിലും വെച്ചു. അങ്ങനെ ഞങ്ങൾ മദീനയിൽ പോയി. (മു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهَا قَالَ: لَقَدْ قُدْتُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْحَسَنَ وَالْحُسَيْنَ عَلَى بَغْلَتِهِ الشَّهْبَاءِ حَتَّى أَدْخَلْتُهُ حُجْرَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، هَذَا قُدَّامُهُ وَهَذَا خَلْفَهُ. حَسَنٌ صَحِيحٌ. (م,ت)', 'സലമതുബ്നുൽ അക്വഅ്(റ): നബി(സ)യും ഹസൻ(റ)വും ഹുസൈൻ(റ)വും അവിടത്തെ ''ശഹ്ബാഅ്'' എന്ന കോവർ കഴുതപ്പുറത്തിരിക്കെ ഞാൻ അവരെ നയിച്ചുകൊണ്ടുപോയി. അങ്ങനെ അവിടത്തെ റൂമിൽ പ്രവേശിപ്പിച്ചു. അപ്പോൾ ഇദ്ദേഹം (ഹസനോ ഹുസൈനോ) മുന്നിലും അദ്ദേഹം (ഹുസൈനോ ഹസനോ) പിന്നിലുമായിരുന്നു. (മു,തു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا جَلَسَ يَتَحَدَّثُ يُكْثِرُ أَنْ يَرْفَعَ طَرْفَهُ إِلَى السَّمَاءِ. (د)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): റസൂൽ(സ) സംസാരിക്കാനായി ഇരുന്നാൽ അവിടത്തെ കണ്ണുകൾ ഇടക്കിടെ ആകാശത്തേക്ക് ഉയർത്തിക്കൊണ്ടിരിക്കും. (ദ)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ فِي كَلَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَرْتِيلٌ. أَوْ: تَرْسِيلٌ. (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ)യുടെ സംസാരത്തിൽ കാവ്യാത്മകത കലർന്നിരുന്നു. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الْأَيَّامِ، مَخَافَةَ السَّآمَةِ عَلَيْنَا. حَسَنٌ صَحِيحٌ. (ق ت)', 'അബ്ദുല്ല(റ): തിരുദൂതർ(സ) ഞങ്ങൾക്ക് മടുപ്പ് വരുമെന്ന് കരുതി ഉപദേശം നടത്തുന്ന ദിവസങ്ങളിൽ സമയം പാലിക്കാറുണ്ടായിരുന്നു. (ബു,മു,തു)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ كَلَامُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلَامًا فَصْلًا، يَفْهَمُهُ كُلُّ مَنْ سَمِعَهُ. (د)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ സംസാരം കേൾക്കുന്നവർക്കെല്ലാം മനസ്സിലാകുന്നവിധം വ്യക്തമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ كَلَامٍ لَا يُبْدَأُ فِيهِ بِالْحَمْدُ لِلَّهِ فَهُوَ أَجْذَمُ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അൽഹംദുലില്ലാഹി'' എന്നതുകൊണ്ട് തുടങ്ങാത്ത എല്ലാ സംസാരവും മുറിഞ്ഞു പോകുന്നതാകുന്നു." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ خُطْبَةٍ لَيْسَ فِيهَا تَشَهُّدٌ فَهِيَ كَالْيَدِ الْجَذْمَاءِ". (د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സാക്ഷ്യവചനം പറയപ്പെടാത്ത എല്ലാ പ്രസംഗങ്ങളും മുറിഞ്ഞുപോയ കയ്യിനെ പോലെയാകുന്നു." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ سُفْيَانَ بْنِ أَسِيدٍ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كَبُرَتْ خِيَانَةً أَنْ تُحَدِّثَ أَخَاكَ حَدِيثًا: هُوَ لَكَ بِهِ مُصَدِّقٌ، وَأَنْتَ لَهُ بِهِ كَاذِبٌ". (د)', 'സുഫ്യാനുബ്നു അസീദിൽ ഹള്റമി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സത്യമാണെന്ന വിശ്വാസത്തോടെ നിന്റെ സംസാരം ശ്രവിക്കുന്ന സഹോദരനോട് നീ കളവ് പറഞ്ഞാൽ അവനോട് നീ ചെയ്യുന്ന കടുത്ത വഞ്ചനയാണത്." (ദ)', 'سُفْيَانَ بْنِ أَسِيدٍ الْحَضْرَمِيِّ', 'സുഫ്യാനുബ്നു അസീദിൽ ഹള്റമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 476, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي قِلَابَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو مَسْعُودٍ لِأَبِي عَبْدِ اللَّهِ، أَوْ: قَالَ أَبُو عَبْدِ اللَّهِ لِأَبِي مَسْعُودٍ، رَضِيَ اللهُ عَنْهُمَا: مَا سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي زَعَمُوا؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "بِئْسَ مَطِيَّةُ الرَّجُلِ زَعَمُوا". قَالَ أَبُو دَاود: أَبُو عَبْدِ اللَّهِ هَذَا حُذَيْفَةُ رَضِيَ اللهُ عَنْهُ. (د)', 'അബുഖിലാബ(റ): അബുമസ്ഊദ്(റ) അബൂഅബ്ദില്ലാ(റ)വിനോട് അല്ലെങ്കിൽ അബൂഅബ്ദുല്ല(റ) അബുമസ്ഊദ്(റ)വിനോട് പറഞ്ഞു:അവരിങ്ങനെ പറയുന്നു അല്ലെങ്കിൽ അവർ വാദിക്കുന്നു എന്നു പറയുന്നതിനെക്കുറിച്ച് റസൂൽ(സ) എന്ത് പറയുന്നതാണ് താങ്കൾ കേട്ടിട്ടുള്ളത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അവർ പറയുന്നു എന്നത് ഒരാളുടെ സംസാരത്തിന്റെ മാധ്യമമാക്കുന്നത് എത്രമോശമാണ്." അബൂദാവൂദ്(റ) പറയുന്നു: ഹുദൈഫ(റ)വാണ് ഈ അബുഅബ്ദില്ല(റ). (ദ)', 'أَبِي قِلَابَةَ', 'അബുഖിലാബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 477, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ يَزِيدَ بْنِ حَيَّانَ رَضِيَ اللهُ عَنْهُ: عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَهُمْ فَقَالَ: "أَمَّا بَعْدُ". (م,د)', 'സൈദുബ്നു അർഖം(റ)വിൽ നിന്ന് യസീദുബ്നു ഹയ്യാൻ(റ): നബി(സ) അനുചരരോട് പ്രസംഗിച്ചപ്പോൾ "അമ്മാ ബഅ്ദ് (ഹംദ്, സ്വലാത്ത് തുടങ്ങിയവക്ക് ശേഷം)" എന്ന് പറഞ്ഞിരുന്നു. (മു,ദ)', 'يَزِيدَ بْنِ حَيَّانَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 477, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُولَنَّ أَحَدُكُمُ الْكَرْمَ، فَإِنَّ الْكَرْمَ الرَّجُلُ الْمُسْلِمُ. وَلَكِنْ قُولُوا: حَدَائِقَ الْأَعْنَابِ". (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "മുന്തിരി വള്ളിയെ നിങ്ങളാരും ''കർമ്'' എന്ന് വിളിക്കരുത്. കാരണം ''കർമ്'' എന്നത് മുസ്ലിമായ മനുഷ്യനാണ്. മറിച്ച് നിങ്ങൾ പറയുക: മുന്തിരിത്തോട്ടങ്ങൾ എന്ന്." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 477, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُولَنَّ أَحَدُكُمْ: عَبْدِي وَأَمَتِي، وَلَا يَقُولَنَّ الْمَمْلُوكُ: رَبِّي وَرَبَّتِي، وَلْيَقُلِ الْمَالِكُ: فَتَايَ وَفَتَاتِي، وَلْيَقُلِ الْمَمْلُوكُ: سَيِّدِي وَسَيِّدَتِي، فَإِنَّكُمُ الْمَمْلُوكُونَ وَالرَّبُّ اللَّهُ عَزَّ وَجَلَّ". وفي رواية: "وَلْيَقُلْ: سَيِّدِي وَمَوْلَايَ". (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരും ''എന്റെ അടിമ'' എന്നും അടിമ ''എന്റെ രക്ഷിതാവ്'' എന്നും പറയരുത്. യജമാനൻ പറയുക: എന്റെ യുവാവ്, എന്റെ യുവതി. അടിമ പറയട്ടെ: എന്റെ യജമാനൻ, എന്റെ യജമാനത്തി. കാരണം നിങ്ങൾ അടിമകളും നിങ്ങളുടെ രക്ഷിതാവ് അന്തസ്സുള്ളവനും ഉന്നതനും പരിശുദ്ധനുമായ അല്ലാഹുവുമാണ്." മറ്റൊരു നിവേദനത്തിൽ: "എന്റെ യജമാനൻ, എന്റെ നേതാവ് എന്ന് പറയട്ടെ." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=307), 1, 'وَفِي رِوَايَةٍ: "وَلْيَقُلْ: سَيِّدِي وَمَوْلَايَ". (ق,د)', 'മറ്റൊരു നിവേദനത്തിൽ: "എന്റെ യജമാനൻ, എന്റെ നേതാവ് എന്ന് പറയട്ടെ." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُولُوا لِلْمُنَافِقِ: سَيِّدٌ، فَإِنَّهُ إِنْ يَكُ سَيِّدًا فَقَدْ أَسْخَطْتُمْ رَبَّكُمْ عَزَّ وَجَلَّ". (د)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "കപടവിശ്വാസികളെ ''നേതാവ്'' എന്ന് നിങ്ങൾ വിളിക്കരുത്, അവൻ നേതാവായാൽ നിങ്ങൾ നിങ്ങളുടെ രക്ഷിതാവിനെ ദേഷ്യം പിടിപ്പിച്ചിരിക്കുന്നു." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُولَنَّ أَحَدُكُمْ: خَبُثَتْ -وفي رواية: جَاشَتْ- نَفْسِي، وَلْيَقُلْ لَقِسَتْ نَفْسِي". (ق,د)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): റസൂൽ(സ) പറയുന്നു: "എന്റെ ശരീരം മോശമായി. മറ്റൊരു - നിവേദനത്തിൽ: വളരെ ബുദ്ധിമുട്ടി - എന്ന് നിങ്ങളാരും പറയരുത്. മറിച്ച് എന്റെ ശരീരം വേദനിച്ചു എന്ന് പറയുക." (ബു,മു,ദ)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=309), 1, 'وَفِي رِوَايَةٍ: جَاشَتْ- نَفْسِي، وَلْيَقُلْ لَقِسَتْ نَفْسِي". (ق,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُولُوا: مَا شَاءَ اللَّهُ وَشَاءَ فُلَانٌ، وَلَكِنْ قُولُوا: مَا شَاءَ اللَّهُ ثُمَّ شَاءَ فُلَانٌ". (د)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരും ''മാശാഅല്ലാഹു വശാഅ ഫുലാനുൻ'' (അല്ലാഹു ഉദ്ദേശിച്ചു അപ്രകാരം തന്നെ മറ്റൊരുത്തനും ഉദ്ദേശിച്ചു) എന്ന് പറയരുത്, മറിച്ച് നിങ്ങൾ ''മാശാഅല്ലാഹു സുമ്മ ശാഅ ഫുലാനുൻ'' (അല്ലാഹു ഉദ്ദേശിച്ചു, അപ്പോൾ അതിന് ശേഷം മറ്റൊരുത്തനും ഉദ്ദേശിച്ചു) എന്ന് പറയുക." (ദ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ أَبِي الْمَلِيحِ بْنِ أُسَامَةَ الْهُذَلِي، عَنْ رَجُلٍ قَالَ: كُنْتُ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَثَرَتْ دَابَّتُهُ. فَقُلْتُ: تَعِسَ الشَّيْطَانُ، فَقَالَ: "لَا تَقُلْ: تَعِسَ الشَّيْطَانُ، فَإِنَّكَ إِذَا قُلْتَ ذَلِكَ تَعَاظَمَ حَتَّى يَكُونَ مِثْلَ الْبَيْتِ، وَيَقُولُ: بِقُوَّتِي، وَلَكِنْ قُلْ: بِسْمِ اللَّهِ، فَإِنَّكَ إِذَا قُلْتَ ذَلِكَ تَصَاغَرَ حَتَّى يَكُونَ مِثْلَ الذُّبَابِ". (د)', 'അബുൽമലീഹുബ്നു ഉസാമതിൽ ഹുദലി(റ): മറ്റൊരാളിൽ നിന്ന് അദ്ദേഹം നിവേദനം ചെയ്യുന്നു: ഞാൻ റസൂൽ(സ)യുടെ വാഹനത്തിന്റെ പിന്നിലിരിക്കുകയായിരുന്നു. അപ്പോൾ അവിടത്തെ വാഹനം വഴുതി വീണു. ഉടനെ ഞാൻ പറഞ്ഞു: ''പിശാച് നശിക്കട്ടെ'' അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "പിശാച് നശിക്കട്ടെ എന്ന് നിങ്ങൾ പറയരുത്. കാരണം നിങ്ങൾ അങ്ങനെ പറഞ്ഞാൽ അവൻ വളർന്ന് ഒരു വീട് പോലെയാകും, എന്നിട്ടവൻ പറയും: എന്റെ ശക്തി കൊണ്ടാണത്. മറിച്ച് നിങ്ങൾ ബിസ്മില്ലാഹി എന്ന് പറയുക. കാരണം അങ്ങനെ നിങ്ങൾ പറഞ്ഞാൽ അവൻ ചെറുതായി ഒരു ഈച്ചയോളമാകും." (ദ)', 'أَبِي الْمَلِيحِ بْنِ أُسَامَةَ الْهُذَلِي، عَنْ رَجُلٍ قَالَ', 'അബുൽമലീഹുബ്നു ഉസാമതിൽ ഹുദലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ الرَّجُلُ هَلَكَ النَّاسُ فَهُوَ أَهْلَكُهُمْ". (م,د)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَدَّثَ الرَّجُلُ بِالْحَدِيثِ ثُمَّ الْتَفَتَ فَهِيَ أَمَانَةٌ". (د,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ഒരു കാര്യം പറഞ്ഞ് പിന്തിരിഞ്ഞ് പോയാൽ ആ പറഞ്ഞത് ഒരു സൂക്ഷിപ്പ് സ്വത്താണ്." (ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَجَالِسُ بِالْأَمَانَةِ إِلَّا ثَلَاثَةَ مَجَالِسَ: سَفْكُ دَمٍ حَرَامٍ، أَوْ فَرْجٌ حَرَامٌ، أَوِ اقْتِطَاعُ مَالٍ بِغَيْرِ حَقٍّ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: മൂന്ന് സദസ്സുകളൊഴികെ എല്ലാ സദസ്സുകളും സംരക്ഷണത്തിലാണ്: നിഷിദ്ധമായ രക്തം ചിന്തൽ, വ്യപിചാരം, അവകാശമില്ലാതെ മുതൽ കൊള്ളയടിക്കൽ എന്നിവക്ക് വേണ്ടിയുള്ള സദസ്സ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَعْظَمَ الْأَمَانَةِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ: الرَّجُلُ يُفْضِي إِلَى امْرَأَتِهِ وَتُفْضِي إِلَيْهِ، ثُمَّ يَنْشُرُ سِرَّهَا". (م,د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹു സൂക്ഷിക്കൽ ഏറ്റവും ഗൗരവമായിക്കാണുന്ന കാര്യമാണ്; ഒരുത്തൻ തന്റെ ഭാര്യയോടും ഭാര്യ അയാളോടും രഹസ്യങ്ങൾ പറയുകയും പിന്നീടവൻ തന്റെ ഭാര്യയുടെ രഹസ്യങ്ങൾ വെളിപ്പെടുത്തുകയും ചെയ്യുക എന്നത്." (മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يُبْغِضُ الْبَلِيغَ مِنَ الرِّجَالِ، الَّذِي يَتَخَلَّلُ بِلِسَانِهِ تَخَلُّلَ الْبَاقِرَةِ بِلِسَانِهَا". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നു: "ഉച്ചാരണം നന്നാക്കാൻ വേണ്ടി, നാവ് കൊണ്ട് പശു അയവിറക്കുന്നത് പോലെ ചെയ്ത് സംസാരത്തിൽ ശക്തികൂട്ടുന്നവരെ അല്ലാഹു ദേശ്യപ്പെട്ടിരിക്കുന്നു." (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 479, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَلَّمَ صَرْفَ الْكَلَامِ لِيَسْبِيَ بِهِ قُلُوبَ الرِّجَالِ -أَوِ النَّاسِ- لَمْ يَقْبَلِ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ صَرْفًا وَلَا عَدْلًا". (د)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും ജനങ്ങളുടെ ഹൃദയം കീഴടക്കാൻ വേണ്ടി അലങ്കാരവാചകങ്ങൾ പഠിച്ചാൽ അവനിൽ നിന്ന് അല്ലാഹു പാശ്ചാത്തപമോ പ്രായശ്ചിത്തമോ അല്ലെങ്കിൽ നിർബന്ധ, സുന്നത് കർമങ്ങൾ സ്വീകരിക്കുകയില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قَدِمَ رَجُلَانِ مِنَ الْمَشْرِقِ، فَخَطَبَا، فَعَجِبَ النَّاسُ -يَعْنِي لِبَيَانِهِمَا- فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْبَيَانِ لَسِحْرًا". أَوْ: "إِنَّ بَعْضَ الْبَيَانِ لَسِحْرٌ". (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): കിഴക്കിൽ നിന്ന് രണ്ട് പേർ വന്ന് പ്രസംഗിച്ചപ്പോൾ അവരുടെ വിവരണം കാരണം ജനങ്ങൾ അത്ഭുതപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം വിവരണത്തിൽ മാരണവുമുണ്ട്." അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്: "ചിലവിവരണങ്ങൾ മാരണമാകുന്നു." (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ عَمْرِو ابْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ يَوْمًا -وَقَامَ رَجُلٌ فَأَكْثَرَ الْقَوْلَ- فَقَالَ عَمْرٌو: لَوْ قَصَدَ فِي قَوْلِهِ لَكَانَ خَيْرًا لَهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَقَدْ رَأَيْتُ -أَوْ أُمِرْتُ- أَنْ أَتَجَوَّزَ فِي الْقَوْلِ، فَإِنَّ الْجَوَازَ هُوَ خَيْرٌ". (د)', 'അംറുബ്നുൽ ആസ്(റ): ഒരു ദിവസം ഒരു വ്യക്തി എഴുന്നേറ്റ് നിന്ന് ധാരാളം സംസാരിച്ചു: അപ്പോൾ അംറ്(റ) പറഞ്ഞു: അദ്ദേഹം തന്റെ സംസാരത്തിന് ഒന്ന് മിതവ്യയം കാട്ടിയിരുന്നെങ്കിൽ അദ്ദേഹത്തിന് നന്നാകുമായിരുന്നു. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "സംസാരത്തിൽ മിതവ്യയം കാണിക്കാൻ ഞാൻ കൽപ്പിക്കപ്പെട്ടു. മിതവ്യയമാണ് ഏറ്റവും ഉത്തമം." (ദ)', 'عَمْرِو ابْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ، وَمَنْ تَرَكَ شَيْئًا مِنْهُنَّ خِيفَةً فَلَيْسَ مِنَّا". (د)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അവരോട് യുദ്ധം തുടങ്ങിയതുമുതൽ പിന്നെ നാം സന്ധിയിലേർപ്പെടാറില്ല. ഭയം കാരണം ആരെങ്കിലുമതിനെ വെറുതെ വിട്ടാൽ അവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْتُلُوا الْحَيَّاتِ كُلَّهُنَّ، فَمَنْ خَافَ ثَأْرَهُنَّ فَلَيْسَ مِنِّي". (د)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഴുവൻ സർപ്പങ്ങളെയും നിങ്ങൾ കൊല്ലുക. അതിന്റെ പ്രതികാരത്തെ ഭയപ്പെടുന്നവൻ എന്നിൽപ്പെട്ടവനല്ല." (ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّا نُرِيدُ أَنْ نَكْنُسَ زَمْزَمَ، وَإِنَّ فِيهَا مِنْ هَذِهِ الْجِنَّانِ؟ يَعْنِي الْحَيَّاتِ الصِّغَارَ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِهِنَّ. (د)', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്വലിബ്(റ): അദ്ദേഹം റസൂൽ(സ)യോട് പറഞ്ഞു: ഞങ്ങൾ സംസം അടിച്ചു വാരാൻ ഉദ്ദേശിക്കുന്നു, കാരണം അതിൽ കുറച്ച് ചെറിയപാമ്പുകളുണ്ട്. അപ്പോൾ നബി(സ) അവയെ കൊല്ലാൻ ആജ്ഞാപിച്ചു. (ദ)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്വലിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 480, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اقْتُلُوا الْحَيَّاتِ، وَذَا الطُّفْيَتَيْنِ، وَالْأَبْتَرَ، فَإِنَّهُمَا يَلْتَمِسَانِ الْبَصَرَ، وَيُسْقِطَانِ الْحَبَلَ".
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ أَبِي لُبَابَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَتْلِ الْجِنَّانِ الَّتِي تَكُونُ فِي الْبُيُوتِ، إِلَّا أَنْ يَكُونَ ذَا الطُّفْيَتَيْنِ، وَالْأَبْتَرَ، فَإِنَّهُمَا يَخْطِفَانِ الْبَصَرَ وَيَطْرَحَانِ مَا فِي بُطُونِ النِّسَاءِ. وفي رواية: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا وَجَدَ بَعْدَ ذَلِكَ - يَعْنِي بَعْدَ مَا حَدَّثَهُ أَبُو لُبَابَةَ - حَيَّةً فِي دَارِهِ، فَأَمَرَ بِهَا فَأُخْرِجَتْ، يَعْنِي إِلَى الْبَقِيعِ. وفي رواية: قَالَ نَافِعٌ: ثُمَّ رَأَيْتُهَا بَعْدُ فِي بَيْتِهِ. (ق,د)', 'അബൂലുബാബ(റ): റസൂൽ(സ) വീടുകളിലെ പാമ്പുകളെ കൊല്ലൽ നിരോധിച്ചിരിക്കുന്നു. പുറത്ത് രണ്ട് വരകളുള്ളതും ചെറിയ വാലുള്ളതുമായത് ഒഴികെ. കാരണം അവ കാഴ്ച നഷ്ടപ്പെടുത്തുകയും സ്ത്രീകളുടെ ഗർഭത്തിലുള്ളതിനെ പുറത്തേക്കെറിയുകയും ചെയ്യും.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=324), 1, 'وَفِي رِوَايَةٍ: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا وَجَدَ بَعْدَ ذَلِكَ - يَعْنِي بَعْدَ مَا حَدَّثَهُ أَبُو لُبَابَةَ - حَيَّةً فِي دَارِهِ، فَأَمَرَ بِهَا فَأُخْرِجَتْ، يَعْنِي إِلَى الْبَقِيعِ.', 'മറ്റൊരു നിവേദനം: അബൂലുബാബ(റ)വിന്റെ ഈ ഹദീസ് കേട്ടതിന്ശേഷം ഇബ്നുഉമർ(റ) വീട്ടിൽ പാമ്പിനെ കണ്ടപ്പോൾ അതിനെ പറമ്പിൽ കൊണ്ടുപോയി ഇടാൻ കൽപിക്കുകയും അത് പറമ്പിൽ ഉപേക്ഷിക്കപ്പെടുകയും ചെയ്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=324), 2, 'وَفِي رِوَايَةٍ: قَالَ نَافِعٌ: ثُمَّ رَأَيْتُهَا بَعْدُ فِي بَيْتِهِ. (ق,د)', 'മറ്റൊരു നിവേദനം: നാഫിഅ്(റ) പറയുന്നു: അതിന്ശേഷം അതിനെ ഞാൻ അദ്ദേഹത്തിന്റെ വീട്ടിൽവെച്ച് കണ്ടു. (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْهَوَامَّ مِنَ الْجِنِّ، فَمَنْ رَأَى فِي بَيْتِهِ شَيْئًا فَلْيُحَرِّجْ عَلَيْهِ ثَلَاثَ مَرَّاتٍ، فَإِنْ عَادَ فَلْيَقْتُلْهُ، فَإِنَّهُ شَيْطَانٌ". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറയുന്നു: "കൊല്ലുന്ന വിഷമുള്ള ജീവികൾ ജിന്നുകളിൽ പെട്ടതാണ്. അവയെ തന്റെ വീട്ടിൽ കണ്ടാൽ മൂന്ന് പ്രാവശ്യം പോകാൻ പറയുക. എന്നിട്ടും മടങ്ങിവന്നാൽ കൊല്ലുക. കാരണം അത് പിശാചാകുന്നു." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ أَبِي السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ، فَبَيْنَا أَنَا جَالِسٌ عِنْدَهُ سَمِعْتُ تَحْتَ سَرِيرِهِ تَحْرِيكَ شَيْءٍ، فَنَظَرْتُ فَإِذَا حَيَّةٌ، فَقُمْتُ، فَقَالَ أَبُو سَعِيدٍ: مَا لَكَ؟ قُلْتُ: حَيَّةٌ هَاهُنَا، قَالَ: فَتُرِيدُ مَاذَا؟ قُلْتُ: أَقْتُلُهَا، فَأَشَارَ إِلَى بَيْتٍ فِي دَارِهِ تِلْقَاءَ بَيْتِهِ، فَقَالَ: إِنَّ ابْنَ عَمٍّ لِي كَانَ فِي هَذَا الْبَيْتِ، فَلَمَّا كَانَ يَوْمُ الْأَحْزَابِ اسْتَأْذَنَ إِلَى أَهْلِهِ، وَكَانَ حَدِيثَ عَهْدٍ بِعُرْسٍ، فَأَذِنَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَرَهُ أَنْ يَذْهَبَ بِسِلَاحِهِ، فَأَتَى دَارَهُ فَوَجَدَ امْرَأَتَهُ قَائِمَةً عَلَى بَابٌ الْبَيْتِ، فَأَشَارَ إِلَيْهَا بِالرُّمْحِ، فَقَالَتْ: لَا تَعْجَلْ حَتَّى تَنْظُرَ مَا أَخْرَجَنِي، فَدَخَلَ الْبَيْتَ فَإِذَا حَيَّةٌ مُنْكَرَةٌ، فَطَعَنَهَا بِالرُّمْحِ ثُمَّ خَرَجَ بِهَا فِي الرُّمْحِ تَرْتَكِضُ، قَالَ: فَلَا أَدْرِي أَيُّهُمَا كَانَ أَسْرَعَ مَوْتًا الرَّجُلُ أَوِ الْحَيَّةُ، فَأَتَى قَوْمُهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: ادْعُ اللَّهَ أَنْ يَرُدَّ صَاحِبَنَا، فَقَالَ: "اسْتَغْفِرُوا لِصَاحِبِكُمْ". ثُمَّ قَالَ: "إِنَّ نَفَرًا مِنَ الْجِنِّ أَسْلَمُوا بِالْمَدِينَةِ، فَإِذَا رَأَيْتُمْ أَحَدًا مِنْهُمْ فَحَذِّرُوهُ ثَلَاثَ مَرَّاتٍ، ثُمَّ إِنْ بَدَا لَكُمْ بَعْدُ أَنْ تَقْتُلُوهُ فَاقْتُلُوهُ بَعْدَ الثَّلَاثِ". وفي رواية: "فَلْيُؤْذِنْهُ ثَلَاثًا، فَإِنْ بَدَا لَهُ بَعْدُ فَلْيَقْتُلْهُ فَإِنَّهُ شَيْطَانٌ". وفي الرواية: "فَآذِنُوهُ ثَلَاثَةَ أَيَّامٍ، فَإِنْ بَدَا لَكُمْ بَعْدَ ذَلِكَ فَاقْتُلُوهُ، فَإِنَّمَا هُوَ شَيْطَانٌ". (د)', 'അബുസ്സാഇബ്(റ): ഞാൻ അബൂസഈദിൽ ഖുദ്രി(റ)വിന്റെ അടുത്ത് പോയി. ഞാനവിടെ ഇരിക്കുമ്പോൾ കട്ടിലിന്റെ ചുവട്ടിൽ എന്തോ ചലിക്കുന്ന ശബ്ദം കേട്ടു. നോക്കുമ്പോൾ അതൊരു പാമ്പായിരുന്നു. പെട്ടെന്ന് ഞാനെണീറ്റു. അബൂസഈദ്(റ) ചോദിച്ചു: എന്ത് പറ്റി? ഞാൻ പറഞ്ഞു: ഇതാ ഒരു പാമ്പ്: അദ്ദേഹം ചോദിച്ചു: താങ്കൾ എന്ത് ചെയ്യാനുദ്ദേശിക്കുന്നു? ഞാൻ പറഞ്ഞു: ഞാൻ അതിനെ കൊല്ലാം. അപ്പോൾ അദ്ദേഹം തന്റെ റൂമിന്റെ മുന്നിലുള്ള ഒരു റൂം സൂചിപ്പിച്ച് കൊണ്ട് പറഞ്ഞു: എന്റെ പിതൃവ്യപുത്രൻ ഈ റൂമിൽ താമസിച്ചിരുന്നു. ഒരിക്കലൊരു യുദ്ധദിവസം തന്റെ ഭാര്യയുടെ അടുത്തേക്ക് പോകാൻ അദ്ദേഹം അനുവാദം തേടി, വളരെയടുത്ത് വിവാഹിതനായ ഒരാളായിരുന്നു ആദ്ദേഹം. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തിന് സമ്മതം നൽകുകയും ആയുധമെടുത്ത് പോകാൻ പറയുകയും ചെയ്തു. തന്റെ വീട്ടിനടുത്തെത്തിയപ്പോൾ വാതിലിൽ തന്റെ ഭാര്യ നിൽക്കുന്നത് കണ്ടു. അപ്പോൾ അവൾക്ക് നേരെ കുന്തം പിടിച്ചു. അപ്പോൾ അവൾ പറഞ്ഞു: എന്നെ ഇവിടെ നിർത്തിയത് എന്താണെന്ന് നോക്കുന്നത് വരെ നിങ്ങൾ ധൃതി കൂട്ടരുത്. അങ്ങനെയദ്ദേഹം വീട്ടിൽ കേറി നോക്കിയപ്പോൾ അവിടെയതാ ഒരു പാമ്പ്! അദ്ദേഹം കുന്തം കൊണ്ട് അതിനെ കുത്തി കുന്തത്തിലേറ്റി പുറത്ത് വന്നു. പാമ്പ് പിടയുന്നുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: അവരിൽ നിന്ന് പാമ്പോ അതോ അബൂസഈദോ(റ) ആരാണ് പെട്ടെന്ന് മരിച്ചതെന്ന് പറയാൻ എനിക്കറിയില്ല. അദ്ദേഹത്തിന്റെ സമുദായും റസൂൽ(സ)യുടെ അടുത്ത് പോയി പറഞ്ഞു: ഞങ്ങളുടെ കൂട്ടുകാരൻ തിരിച്ചുവരാൻ ദുആ ചെയ്താലും. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളുടെ കൂട്ടുകാരന് വേണ്ടി പൊറുക്കലിനെ തേടുക" പിന്നെ അവിടന്ന് പറഞ്ഞു: "ജിന്നുകളിൽ പെട്ട ഒരു കൂട്ടം മദീനയിൽ വെച്ച് മുസ്ലിംകളായിട്ടുണ്ട്. നിങ്ങൾ ആരെങ്കിലും അവരിൽനിന്നൊരാളെ കണ്ടാൽ മൂന്ന് പ്രാവശ്യം പോകൻ പറഞ്ഞ് മുന്നറിയിപ്പ് നൽകുകയും ശേഷം വധിക്കണമെന്ന് തോന്നിയാൽ മൂന്നാമത്തേതിന് ശേഷം വധിച്ച് കളയുകയും ചെയ്യുക." മറ്റൊരു നിവേദനത്തിൽ: "അതിന് മൂന്ന് പ്രാവശ്യം താക്കീത് നൽകുക, ശേഷം കണ്ടാൽ കൊന്നുകളയുക കാരണം അത് പിശാചാകുന്നു." മറ്റൊരു നിവേദനം: മൂന്ന് ദിവസം നിങ്ങൾ അതിന് താക്കീത് നൽകുക. ശേഷം കണ്ടാൽ കൊന്ന് കളയുക, അത് പിശാച് മാത്രമാണ്." (ദ)', 'أَبِي السَّائِبِ', 'അബുസ്സാഇബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 481, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=326), 1, 'وَفِي رِوَايَةٍ: "فَلْيُؤْذِنْهُ ثَلَاثًا، فَإِنْ بَدَا لَهُ بَعْدُ فَلْيَقْتُلْهُ فَإِنَّهُ شَيْطَانٌ". وفي الرواية: "فَآذِنُوهُ ثَلَاثَةَ أَيَّامٍ، فَإِنْ بَدَا لَكُمْ بَعْدَ ذَلِكَ فَاقْتُلُوهُ، فَإِنَّمَا هُوَ شَيْطَانٌ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "അതിന് മൂന്ന് പ്രാവശ്യം താക്കീത് നൽകുക, ശേഷം കണ്ടാൽ കൊന്നുകളയുക കാരണം അത് പിശാചാകുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=326), 2, null, 'മറ്റൊരു നിവേദനം: മൂന്ന് ദിവസം നിങ്ങൾ അതിന് താക്കീത് നൽകുക. ശേഷം കണ്ടാൽ കൊന്ന് കളയുക, അത് പിശാച് മാത്രമാണ്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ أَبِي لَيْلَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ حَيَّاتِ الْبُيُوتِ، فَقَالَ: "إِذَا رَأَيْتُمْ مِنْهُنَّ شَيْئًا فِي مَسَاكِنِكُمْ فَقُولُوا: أَنْشُدُكُنَّ الْعَهْدَ الَّذِي أَخَذَ عَلَيْكُنَّ نُوحٌ أَنْشُدُكُنَّ الْعَهْدَ الَّذِي أَخَذَ عَلَيْكُنَّ سُلَيْمَانُ: أَنْ لَا تُؤْذُونَا، فَإِنْ عُدْنَ فَاقْتُلُوهُنَّ". (د,ت)', 'അബൂലൈലതുൽ അൻസാരി(റ): വീട്ടിലെ പാമ്പുകളെക്കുറിച്ച് റസൂൽ(സ) ചോദിക്കപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവയിൽനിന്ന് വല്ലതും നിങ്ങളുടെ താമസസ്ഥലത്ത് കണ്ടാൽ നിങ്ങൾ പറയുക: നിങ്ങൾ ഞങ്ങളെ ബുദ്ധിമുട്ടാക്കുകയില്ല എന്ന് സുലൈമാൻ നബി(അ) നിങ്ങളിൽനിന്ന് സ്വീകരിച്ച കരാറിനെയും നൂഹ്നബി(അ) നിങ്ങളിൽനിന്ന് സ്വീകരിച്ച കരാറിനെയും നിങ്ങളെ ഞാൻ ഓർമിപ്പിക്കുന്നു. ശേഷം അത് മടങ്ങിവന്നാൽ അവയെ കൊന്നുകളയുക." (ദ,തു)', 'أَبِي لَيْلَى', 'അബൂലൈലതുൽ അൻസാരി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 482, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: اقْتُلُوا الْحَيَّاتِ كُلَّهَا إِلَّا الْجَانَّ الْأَبْيَضَ الَّذِي كَأَنَّهُ قَضِيبُ فِضَّةٍ. (د)', 'ഇബ്നുമസ്ഊദ്(റ): വെള്ളികൊണ്ടുള്ള വടിക്കഷ്ണം പോലെയുള്ള വെളുത്ത പാമ്പുകളല്ലാത്ത എല്ലാ പാമ്പിനെയും കൊന്നുകളയുക." (ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْوَزَغِ، وَسَمَّاهُ فُوَيْسِقًا. (م,د)', 'സഅ്ദ്(റ): റസൂൽ(സ) വലിയ പല്ലികളെ കൊല്ലാൻ കൽപിച്ചു അതിന് ''ഫുവൈസിഖ്'' (കൊച്ചു തെമ്മാടി) എന്ന പേര് വിളിക്കുകയും ചെയ്തു. (മു,ദ)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ وَزَغَةً فِي أَوَّلِ ضَرْبَةٍ فَلَهُ كَذَا وَكَذَا حَسَنَةً، وَمَنْ قَتَلَهَا فِي الضَّرْبَةِ الثَّانِيَةِ فَلَهُ كَذَا وَكَذَا حَسَنَةً، أَدْنَى مِنَ الْأُولَى، وَمَنْ قَتَلَهَا فِي الضَّرْبَةِ الثَّالِثَةِ فَلَهُ كَذَا وَكَذَا حَسَنَةً، أَدْنَى مِنَ الثَّانِيَةِ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പല്ലിയെ ആദ്യത്തെ അടിക്ക്തന്നെ കൊന്നവന് ഇത്രയിത്ര നന്മകളുണ്ട്. രണ്ടാമത്തെ അടിക്ക് കൊന്നവന് ആദ്യത്തെ അടിക്ക് കൊന്നവനേക്കാൾ ചുരുങ്ങിയ രീതിയിൽ ഇത്രയിത്ര നന്മകളുണ്ട്, മൂന്നാമത്തെ അടിക്ക് കൊന്നവന് രണ്ടാമത്തെ അടിക്ക് കൊന്നയാളെക്കാളും കുറഞ്ഞതായ നന്മകളുമുണ്ട്." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "فِي أَوَّلِ ضَرْبَةٍ سَبْعِينَ حَسَنَةً". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒന്നാമത്തെയടിക്ക് എഴുപത് നന്മയുണ്ട്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَزَلَ نَبِيٌّ مِنَ الْأَنْبِيَاءِ تَحْتَ شَجَرَةٍ فَلَدَغَتْهُ نَمْلَةٌ، فَأَمَرَ بِجِهَازِهِ فَأُخْرِجَ مِنْ تَحْتِهَا، ثُمَّ أَمَرَ بِهَا فَأُحْرِقَتْ، فَأَوْحَى اللَّهُ إِلَيْهِ: فَهَلَّا نَمْلَةً وَاحِدَةً". (م,د)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പ്രവാചകൻമാരിൽപ്പെട്ട ഒരു പ്രവാചകൻ ഒരു മരച്ചുവട്ടിൽ ഇറങ്ങിനിന്നപ്പോൾ അദ്ദേഹത്തെ ഒരു ഉറുമ്പ് കടിച്ചു. മരത്തിന്റെ ചുവട്ടിൽ നിന്ന് യാത്രാസാമഗ്രികളെടുക്കാൻ പറയുകയും ശേഷം അതിനെ കരിക്കാൻ കൽപ്പിക്കുകയും ചെയ്തു. അത് കരിക്കപ്പെടുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു വഹ്യ് ഇറക്കി: ''അത് ഒരു ഉറുമ്പായിരുന്നില്ലേ.'' (എന്നിട്ടും എന്ത് കൊണ്ട് അപ്രകാരം പ്രവർത്തിച്ചു?) (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ نَمْلَةً قَرَصَتْ نَبِيًّا مِنَ الْأَنْبِيَاءِ، فَأَمَرَ بِقَرْيَةِ النَّمْلِ فَأُحْرِقَتْ، فَأَوْحَى اللَّهُ إِلَيْهِ: أَفِي أَنْ قَرَصَتْكَ نَمْلَةٌ أَهْلَكْتَ أُمَّةً مِنَ الْأُمَمِ تُسَبِّحُ". (ق,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകൻമാരിൽ ഒരാളെ ഒരു ഉറുമ്പ് കടിച്ചപ്പോൾ ഉറുമ്പിൻ കൂട്ടത്തെ മുഴുവൻ കരിച്ച് കളയാൻ അദ്ദേഹം കൽപിച്ചു. അങ്ങനെ അവ കരിക്കപ്പെടുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു വഹ്യിറക്കി: ഒരു ഉറുമ്പ് താങ്കളെ കടിച്ചതിനാണോ തസ്ബീഹ് ചെയ്യുന്ന ഒരു സമുദായത്തെ താങ്കൾ നശിപ്പിച്ച് കളഞ്ഞത്?'' (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَتْلِ أَرْبَعٍ مِنَ الدَّوَابِّ: النَّمْلَةُ، وَالنَّحْلَةُ، وَالْهُدْهُدُ، وَالصُّرَدُ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) നാലിനം ജീവികളെ കൊല്ലുന്നത് നരോധിച്ചിരിക്കുന്നു: ഉറുമ്പ്, തേനീച്ച, ഹുദ്ഹുദ്, പച്ച മരംകൊത്തി." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَانْطَلَقَ لِحَاجَتِهِ، فَرَأَيْنَا حُمَّرَةً مَعَهَا فَرْخَانِ فَأَخَذْنَا فَرْخَيْهَا، فَجَاءَتِ الْحُمَرَةُ، فَجَعَلَتْ تُعَرِّشُ، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَنْ فَجَعَ هَذِهِ بِوَلَدِهَا؟ رُدُّوا وَلَدَهَا إِلَيْهَا". وَرَأَى قَرْيَةَ نَمْلٍ قَدْ حَرَّقْنَاهَا، فَقَالَ: "مَنْ حَرَّقَ هَذِهِ". قُلْنَا: نَحْنُ، قَالَ: "إِنَّهُ لَا يَنْبَغِي أَنْ يُعَذِّبَ بِالنَّارِ إِلَّا رَبُّ النَّارِ". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ യാത്ര ചെയ്യുകയായിരുന്നു. അങ്ങനെ തിരുമേനി(സ) അവിടത്തെ ആവശ്യങ്ങൾക്ക് വേണ്ടി പുറത്ത് പോയപ്പോൾ ഞങ്ങൾ ഒരു അടക്കാക്കിളിയെ അതിന്റെ രണ്ട് കുട്ടികളുടെ കൂടെ കണ്ടു. ആ കുട്ടികളെ ഞങ്ങൾ പിടിച്ചു. ഉടനെ ആ പക്ഷിവന്ന് ചിറക് വിടർത്തി മുകളിൽ പറന്നുകൊണ്ടിരുന്നു. അപ്പോൾ നബി(സ) വന്നു ചോദിച്ചു: "തന്റെ കുട്ടികളെ പിടിച്ച് ആരാണതിനെ വേദനിപ്പിച്ചത്? അതിന്റെ കുട്ടിയെ അതിനുതന്നെ തിരിച്ചു കൊടുക്കുക." ഞങ്ങൾ കരിച്ച ഒരു കൂട്ടം ഉറുമ്പിനെ കണ്ടപ്പോൾ അവിടന്ന് ചോദിച്ചു: "ആരാണ് ഇതിനെ കരിച്ചത്?" ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങളാണ്. അവിടന്ന് പറഞ്ഞു: "തീ കൊണ്ട് ശിക്ഷിക്കാൻ തീയുടെ രക്ഷിതാവിനല്ലാതെ അവകാശമില്ല." (ദ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ طَبِيبًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ضِفْدَعٍ يَجْعَلُهَا فِي دَوَاءٍ، فَنَهَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا. (د,ن)', 'അബ്ദുർറഹ്മാനുബ്നു ഉസ്മാൻ(റ): തവളയെ മരുന്നിൽ പെടുത്തുന്നതിനെക്കുറിച്ച് ഒരു ഡോക്ടർ നബി(സ)യോട് ചോദിച്ചു. അപ്പോൾ നബി(സ) അയാളോട് അതിനെ കൊല്ലൽ വിലക്കി. (ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ', 'അബ്ദുർറഹ്മാനുബ്നു ഉസ്മാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَطَعَ سِدْرَةً صَوَّبَ اللَّهُ رَأْسَهُ فِي النَّارِ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും സിദ്റ് മരം മുറിച്ചാൽ അല്ലാഹു അവന്റെ ശിരസ്സിനെ നരകത്തിലിടുന്നതാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 484, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ حَسَّانَ بْنِ إِبْرَاهِيمَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ هِشَامَ بْنَ عُرْوَةَ عَنْ قَطْعِ السِّدْرِ، وَهُوَ مُسْتَنِدٌ إِلَى قَصْرِ عُرْوَةَ، فَقَالَ: أَتَرَى هَذِهِ الْأَبْوَابَ وَالْمَصَارِيعَ، إِنَّمَا هِيَ مِنْ سِدْرِ عُرْوَةَ، كَانَ عُرْوَةُ يَقْطَعُهُ مِنْ أَرْضِهِ، وَقَالَ: لَا بَأْسَ بِهِ. فَقَالَ: هِيَ يَا عِرَاقِيُّ، جِئْتَنِي بِبِدْعَةٍ قَالَ: قُلْتُ إِنَّمَا الْبِدْعَةُ مِنْ قِبَلِكُمْ سَمِعْتُ مَنْ يَقُولُ بِمَكَّةَ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قَطَعَ السِّدْرَ ثُمَّ سَاقَ مَعْنَاهُ (د)', 'ഹസ്സാനുബ്നു ഇബ്റാഹീം(റ): സിദ്റ് മരം മുറിക്കുന്നതിനെക്കുറിച്ച് ഞാൻ ഹിശാമുബ്നു ഉർവ(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം ഉർവ്വ(റ)വിന്റെ കോട്ടയോട് ചാരിയിരിക്കുകയായിരുന്നു. ഹിശാം(റ) പറഞ്ഞു: നീ ഈ വാതിലുകളും വാതിൽ പൊളികളും കാണുന്നില്ലെയോ? ഇതെല്ലാം ഉർവ്വയുടെ സിദ്റ് മരങ്ങൾ കൊണ്ടുണ്ടാക്കിയതാണ്. ഉർവ(റ) തന്റെ ഭൂമിയിലുള്ള സിദ്റ് മരം മുറിക്കുകയും അതിൽ തെറ്റില്ല എന്ന് പറയുകയും ചെയ്യുമായിരുന്നു. ശേഷം ഹിശാം(റ) പറഞ്ഞു: അല്ലയോ ഇറാഖീ, നീ എന്നോട് പറഞ്ഞത് പുതിയ കാര്യമാണ്. അപ്പോൾ ഞാൻ പറഞ്ഞു: നിങ്ങൾ എന്നോട് പറഞ്ഞതാണ് പുതിയ കാര്യം. മക്കയിൽ വെച്ച് ഒരാൾ പറയുന്നത് ഞാൻ കേട്ടു. സിദ്റ് മരം മുറിക്കുന്നവരെ റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. ശേഷം അവർ ഇതിന്റെ ആശയം പറഞ്ഞു. (ദ)', 'حَسَّانَ بْنِ إِبْرَاهِيمَ', 'ഹസ്സാനുബ്നു ഇബ്റാഹീം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، عَوْرَاتُنَا، مَا نَأْتِي مِنْهَا وَمَا نَذَرُ؟ قَالَ: "احْفَظْ عَوْرَتَكَ إِلَّا مِنْ زَوْجَتِكَ، أَوْ مَا مَلَكَتْ يَمِينُكَ". فَقَالَ: الرَّجُلُ يَكُونُ مَعَ الرَّجُلِ؟ قَالَ: "إِنِ اسْتَطَعْتَ أَنْ لَا يَرَاهَا أَحَدٌ فَافْعَلْ". قُلْتُ: وَالرَّجُلُ يَكُونُ خَالِيًا؟ قَالَ: "فَاللَّهُ أَحَقُّ أَنْ يُسْتَحْيَا مِنْهُ". حَسَنٌ. (د,ت,جه)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, ഞങ്ങളുടെ ഔറത്തിൽ ഏതാണ് മറക്കേണ്ടതും മറക്കേണ്ടാത്തതും? അവിടന്ന് പറഞ്ഞു: "തന്റെ ഭാര്യയും താങ്കൾ ഉടമപ്പെടുത്തിയവരുമൊഴികെ എല്ലാവരിൽ നിന്നും ഔറത്ത് മറക്കുക." അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: പുരുഷൻ പുരുഷനോടൊപ്പമാണെങ്കിൽ? തിരുമേനി(സ) പറഞ്ഞു: "ഔറത്ത് ആരും കാണാതിരിക്കാൻ കഴിയുമെങ്കിൽ നിങ്ങൾ അപ്രകാരം ചെയ്യുക." ഞാൻ ചോദിച്ചു: ഒരാൾ തനിയെ ആണെങ്കിലോ? അവിടന്ന് പറഞ്ഞു: "അന്നേരം അവനിൽനിന്ന് ലജ്ജിക്കാൻ ഏറ്റവും അർഹൻ അല്ലാഹുവാണ്." (ദ,തു,ജ)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: حَمَلْتُ حَجَرًا ثَقِيلًا، فَبَيْنَا أَمْشِي فَسَقَطَ عَنِّي ثَوْبِي، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خُذْ عَلَيْكَ ثَوْبَكَ، وَلَا تَمْشُوا عُرَاةً". (م,د)', 'മിസ്വറുബ്നു മഖ്റമ(റ): ഞാൻ ഭാരമുള്ള ഒരു കല്ല് ചുമന്ന് പോകുകയായിരുന്നു. അതിനിടയിൽ എന്റെ തുണിയഴിഞ്ഞു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നിങ്ങൾ തുണിയെടുക്കുക, നഗ്നരായി നടക്കരുത്." (മു,ദ)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ يَعْلَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يَغْتَسِلُ بِالْبَرَازِ بِلَا إِزَارٍ، فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ حَيِيٌّ سِتِّيرٌ يُحِبُّ الْحَيَاءَ وَالسَّتْرَ، فَإِذَا اغْتَسَلَ أَحَدُكُمْ فَلْيَسْتَتِرْ". (د,ن)', 'യഅ്ല(റ): തുണിയില്ലാതെ, വിശാലമായ/വിസർജ്ജനസ്ഥലത്ത് കുളിക്കുന്ന ഒരാളെ റസൂൽ(സ) കണ്ടു. ഉടനെ മിമ്പറിൽ കേറി അല്ലാഹുവിനെ സ്തുതിച്ചു. എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു ലജ്ജിക്കുന്നവനും മറച്ചുവെക്കുന്നവനുമാകുന്നു, ലജ്ജയും മറയും അവൻ ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നു. അത് കൊണ്ട് നിങ്ങൾ കുളിക്കുകയാണെങ്കിൽ മറപാലിക്കുക." (ദ,ന)', 'يَعْلَى', 'യഅ്ല(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 485, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ جَرْهَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجَرْهَدٍ فِي الْمَسْجِدِ وَقَدِ انْكَشَفَ فَخِذُهُ، وفي رواية: مَرَّ بِهِ وَهُوَ كَاشِفٌ عَنْ فَخِذِهِ، فَقَالَ: "إِنَّ الْفَخِذَ عَوْرَةٌ". وفي رواية: "الْفَخِذُ عَوْرَةٌ". وفي رواية: "غَطٍّ فَخِذَكَ، فَإِنَّهَا مِنَ الْعَوْرَةِ". حَسَنٌ. (ت)', 'ജർഹദ്(റ): നബി(സ) പള്ളിയിലൂടെ ജർഹദ്(റ)വിന്റെ അരികിലൂടെ നടന്നു പോയി. അദ്ദേഹത്തിന്റെ തുട വെളിവായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം തന്റെ തുട വെളിവാക്കിയിരിക്കെ നബി(സ) അദ്ദേഹത്തിന്റെ അരികിലൂടെ നടന്നു പോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തുട തീർച്ചയായും ഔറത്താകുന്നു." മറ്റൊരു നിവേദനം: "തുട ഔറത്താകുന്നു." മറ്റൊരു റിപ്പോർട്ടിൽ: "താങ്കളുടെ തുട മറക്കുക, കാരണമത് ഔറത്തിൽ പെട്ടതാകുന്നു." (തു)', 'جَرْهَدٍ', 'ജർഹദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=342), 1, 'وَفِي رِوَايَةٍ: مَرَّ بِهِ وَهُوَ كَاشِفٌ عَنْ فَخِذِهِ، فَقَالَ: "إِنَّ الْفَخِذَ عَوْرَةٌ".', 'മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം തന്റെ തുട വെളിവാക്കിയിരിക്കെ നബി(സ) അദ്ദേഹത്തിന്റെ അരികിലൂടെ നടന്നു പോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തുട തീർച്ചയായും ഔറത്താകുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=342), 2, 'وَفِي رِوَايَةٍ: "الْفَخِذُ عَوْرَةٌ".', 'മറ്റൊരു നിവേദനം: "തുട ഔറത്താകുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=342), 3, 'وَفِي رِوَايَةٍ: "غَطٍّ فَخِذَكَ، فَإِنَّهَا مِنَ الْعَوْرَةِ". حَسَنٌ. (ت)', 'മറ്റൊരു നിവേദനിൽ: "താങ്കളുടെ തുട മറക്കുക, കാരണമത് ഔറത്തിൽ പെട്ടതാകുന്നു." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ جَرْهَدٍ رَضِيَ اللهُ عَنْهُ -وَكَانَ مِنْ أَصْحَابِ الصُّفَّةِ- قَالَ: جَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَنَا وَفَخِذِي مُنْكَشِفَةٌ، فَقَالَ: "أَمَا عَلِمْتَ أَنَّ الْفَخِذَ عَوْرَةٌ". (د)', 'ജർഹദ്(റ): (അസ്ഹാബുസ്സുഫ്ഫയിൽ പെട്ടവരാണ് അദ്ദേഹം.) ഞങ്ങളുടെയടുത്ത് റസൂൽ(സ) ഇരുന്നു. എന്റെ തുട വെളിവായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "തുട ഔറത്താണെന്നത് താങ്കൾ അറിഞ്ഞിട്ടില്ലേ." (ദ)', 'جَرْهَدٍ', 'ജർഹദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكْشِفْ فَخِذَكَ، وَلَا تَنْظُرْ إِلَى فَخِذِ حَيٍّ وَلَا مَيِّتٍ". (د,جه)', 'അലിയ്യ്(റ): റസൂൽ(സ) പറയുന്നു: "താങ്കളുടെ തുട കാണിക്കരുത്, ജീവിച്ചിരിക്കുന്നവന്റെയോ മരിച്ചവന്റെ തുട നിങ്ങൾ നോക്കുകയുമരുത്." (ദ,ജ)', 'عَلِيٍّ', 'അലിയ്യ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَيْمُونَةُ، قَالَتْ: فَبَيْنَا نَحْنُ عِنْدَهُ أَقْبَلَ ابْنُ أُمِّ مَكْتُومٍ فَدَخَلَ عَلَيْهِ، وَذَلِكَ بَعْدَ مَا أُمِرْنَا بِالْحِجَابِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "احْتَجِبَا مِنْهُ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَلَيْسَ هُوَ أَعْمَى لَا يُبْصِرُنَا وَلَا يَعْرِفُنَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفَعَمْيَاوَانِ أَنْتُمَا؟ أَلَسْتُمَا تُبْصِرَانِهِ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ഉമ്മുസലമ(റ): അവരും മൈമൂന(റ)യും റസൂൽ(സ)യുടെ അടുത്തായിരുന്നു. അവർ പറയുന്നു: അങ്ങനെയിരിക്കുമ്പോൾ ഉമ്മുമക്തൂം(റ) കയറിവന്നു. അത് ഞങ്ങൾ ഹിജാബ് കൊണ്ട് കൽപ്പിക്കപ്പെട്ടതിന് ശേഷമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹത്തെ തൊട്ട് നിങ്ങൾ മറ സ്വീകരിക്കുക." അപ്പോൾ ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, അവർ കണ്ണ് കാണാത്തവരല്ലേ, ഞങ്ങളെ അറിയുകയോ കാണുകയോ ഇല്ലല്ലോ! അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ രണ്ട്പേരും അന്ധരാണോ, നിങ്ങൾ അദ്ദേഹത്തെ കാണുന്നില്ലയോ?" (ദ,തു,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 486, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُبَاشِرُ الْمَرْأَةُ، الْمَرْأَةَ حَتَّى تَصِفَهَا لِزَوْجِهَا كَأَنَّمَا يَنْظُرُ إِلَيْهَا". حَسَنٌ صَحِيحٌ. (خ,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നു: "ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയുമായി തൊലി കൂട്ടിച്ചേർക്കരുത്, എന്നിട്ട് തന്റെ ഭർത്താവ് അവളെ കാണുന്നത് പോലെയാകുംവിധം തന്റെ ഭർത്താവിനോട് അവളെക്കുറിച്ച് (അവളുടെ ശരീരസവിശേഷത) പറഞ്ഞു കൊടുക്കുന്നു." (ബു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْظُرُ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ، وَلَا تَنْظُرُ الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ، وَلَا يُفْضِي الرَّجُلُ إِلَى الرَّجُلِ فِي الثَّوْبِ الْوَاحِدِ، وَلَا تُفْضِي الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ الْوَاحِدِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറയുന്നു: "പുരുഷൻ മറ്റൊരു പുരുഷന്റെ ഔറത്തിലേക്കോ, സ്ത്രീ മറ്റൊരു സ്ത്രീയുടെ ഔറത്തിലേക്കോ നോക്കരുത്. ഔറ്റവസ്ത്രത്തിൽ പുരുഷൻ മറ്റൊരുത്തനുമായോ, സ്ത്രീ മറ്റൊരു സ്ത്രീയുമായോ ചേരരുത്." (മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُفْضِيَنَّ رَجُلٌ إِلَى رَجُلٍ، وَلَا امْرَأَةٌ إِلَى امْرَأَةٍ، إِلَّا وَلَدًا أَوْ وَالِدًا". (د)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഒരു പുരുഷൻ മറ്റൊരു പുരുഷനിലേക്കോ ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയിലേക്കോ ചേരരുത്, സന്താനവും മാതാപിതാക്കളുമല്ലെങ്കിൽ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالتَّعَرِّيَ، فَإِنَّ مَعَكُمْ مَنْ لَا يُفَارِقُكُمْ إِلَّا عِنْدَ الْغَائِطِ، وَحِينَ يُفْضِي الرَّجُلُ إِلَى أَهْلِهِ، فَاسْتَحْيُوهُمْ وَأَكْرِمُوهُمْ". (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "നഗ്നത നിങ്ങൾ സൂക്ഷിക്കുക, കാരണം വിസർജ്ജനസമയത്തും, ഒരാൾ തന്റെ ഭാര്യയിലേക്ക് ചേരുമ്പോഴും അല്ലാതെ നിങ്ങളെ വിട്ട് പിരിയാത്ത ആളുകൾ നിങ്ങളുടെ കൂടെയുണ്ട്, അത് കൊണ്ട് അവരെ ബഹുമാനിക്കുക, അവരോട് ലജ്ജ കാണിക്കുക." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ أَبِي أُسَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَهُوَ خَارِجٌ مِنَ الْمَسْجِدِ، فَاخْتَلَطَ الرِّجَالُ مَعَ النِّسَاءِ فِي الطَّرِيقِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلنِّسَاءِ: "اسْتَأْخِرْنَ، فَإِنَّهُ لَيْسَ لَكُنَّ أَنْ تَحْقُقْنَ الطَّرِيقَ، عَلَيْكُنَّ بِحَافَاتِ الطَّرِيقِ". فَكَانَتِ الْمَرْأَةُ تَلْتَصِقُ بِالْجِدَارِ، حَتَّى إِنَّ ثَوْبَهَا لَيَتَعَلَّقُ بِالْجِدَارِ مِنْ لُصُوقِهَا بِهِ. (د)', 'അബൂഉസൈദിൽ അൻസാരി(റ): റസൂൽ(സ) പള്ളിയിൽ നിന്ന് പുറത്ത് പോകുമ്പോൾ പറയുന്നത് കേട്ടു. അപ്പോൾ വഴിയിൽ പുരുഷൻമാരും സ്ത്രീകളും കൂടിക്കലർന്നിരുന്നു. റസൂൽ(സ) സ്ത്രീകളോട് പറഞ്ഞു: "നിങ്ങൾ പിന്തിനിൽക്കുക, കാരണം വഴിയുടെ മധ്യഭാഗത്ത് കൂടെ നിങ്ങൾ നടക്കരുത്, നിങ്ങൾ വഴിയുടെ ഓരംചേർന്നു നടക്കുക." ശേഷം സ്ത്രീകൾ ചുമരിനോടടുത്ത് നടക്കുമായിരുന്നു. ചുമരിനോട് ചേർന്ന് നടന്നതിനാൽ അവരുടെ വസ്ത്രങ്ങൾ അതിനോട് ഉരസുമായിരുന്നു. (ദ)', 'أَبِي أُسَيْدٍ الْأَنْصَارِيِّ', 'അബൂഉസൈദിൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَمْشِيَ -يَعْنِي الرَّجُلَ- بَيْنَ الْمَرْأَتَيْنِ. (د)', 'ഇബ്നുഉമർ(റ): പുരുഷൻ രണ്ട് സ്ത്രീകൾക്കിടയിൽ നടക്കന്നത് റസൂൽ(സ) വിലക്കിയിരിക്കുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ، مَوْلَى عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ: أَنَّ عَمْرَو بْنَ الْعَاصِ رَضِيَ اللهُ عَنْهُ أَرْسَلَهُ إِلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ ،يَسْتَأْذِنُهُ عَلَى أَسْمَاء بِنْتِ عُمَيْسٍ، فَأُذِنَ لَهُ، حَتَّى إِذَا فَرَغَ مِنْ حَاجَتِهِ سَأَلَ الْمَوْلَى عَمْرَو بْنَ الْعَاصِ عَنْ ذَلِكَ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَانَا أَوْ نَهَى أَنْ نَدْخُلَ عَلَى النِّسَاءِ بِغَيْرِ إِذْنِ أَزْوَاجِهِنَّ. حَسَنٌ صَحِيحٌ. (ت)', 'അംറുബ്നുൽ ആസ്(റ)വിന്റെ അടിമയായ അബ്ദുർറഹ്മാനുബ്നു സാബിത്(റ): അംറുബ്നുൽ ആസ്(റ) അദ്ദേഹത്തെ അലി(റ)വിന്റെ അടുത്തേക്ക് അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)യുടെ അടുത്ത് പോകാൻ സമ്മതം ചോദിക്കാൻ വേണ്ടി പറഞ്ഞയച്ചു. അങ്ങനെ അദ്ദേഹത്തിന് സമ്മതം നൽകപ്പെട്ടു. തിരിച്ച് പോരുമ്പോൾ അടിമ അംറുബ്നുൽ ആസ്(റ)വിനോട് അതിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: സ്ത്രീകളുടെ ഭർത്താക്കന്മാരുടെ സമ്മതമില്ലാതെ അവരുടെയടുത്ത് പോകുന്നത് റസൂൽ(സ) ഞങ്ങളോട് നിരോധിച്ചിരിക്കുന്നു. (തു)', 'عَبْدِ الرَّحْمَنِ بْنِ ثَابِتٍ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَزْوَاجَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنَّ يَخْرُجْنَ بِاللَّيْلِ إِذَا تَبَرَّزْنَ إِلَى الْمَنَاصِعِ، وَهُوَ صَعِيدٌ أَفْيَحُ، وَكَانَ عُمَرُ بْنُ الْخَطَّاب يَقُولُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْجُبْ نِسَاءَكَ، فَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ، فَخَرَجَتْ سَوْدَةُ بِنْتُ زَمْعَةَ -زَوْجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- لَيْلَةً مِنَ اللَّيَالِي عِشَاءً، وَكَانَتِ امْرَأَةً طَوِيلَةً، فَنَادَاهَا عُمَرُ رَضِيَ اللهُ عَنْهُ: أَلَا قَدْ عَرَفْنَاكِ يَا سَوْدَةُ. حِرْصًا عَلَى أَنْ يُنْزَلَ الْحِجَابُ، قَالَتْ عَائِشَةُ: فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ الْحِجَابَ. (م)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ ഭാര്യമാർ രാത്രിയിൽ വിശാലമായ തുറന്ന സ്ഥലത്തേക്ക് (ബുദ്ധിമുട്ടുകളില്ലാത്ത വിസർജ്ജനസ്ഥലത്തേക്ക്) പോകാറുണ്ടായിരുന്നു. ഉമറുബ്നുൽ ഖത്വാബ്(റ) റസൂൽ(സ)യോട് അവിടത്തെ സ്ത്രീകളെ ഹിജാബ് ധരിപ്പിക്കാൻ പറയാറുണ്ടായിരുന്നു. പക്ഷെ, റസൂൽ(സ) അത് ചെയ്യാറില്ല. അങ്ങനെ സൗദ ബിൻത് സംഅ(റ) -നബി(സ)യുടെ ഭാര്യ- ഒരു രാത്രി പുറപ്പെട്ടു. അവർ നീളം കൂടിയ ഒരു സ്ത്രീയായിരുന്നു. അപ്പോൾ ഹിജാബിലിറങ്ങാൻ അതിയായി ആഗ്രഹിച്ചു കൊണ്ട് ഉമർ(റ) അവരെ വിളിച്ചു പറഞ്ഞു: സൗദാ, ഞാൻ നിങ്ങളെ തിരിച്ചറിഞ്ഞിരിക്കുന്നു, ആഇശ(റ) പറഞ്ഞു: അപ്പോൾ അല്ലാഹു ഹിജാബിന്റെ സൂക്തമിറക്കി. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 488, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجَتْ سَوْدَةُ بَعْدَ مَا ضُرِبَ عَلَيْهَا الْحِجَابُ لِتَقْضِيَ حَاجَتَهَا، وَكَانَتِ امْرَأَةً جَسِيمَةً تَفْرَعُ النِّسَاء جِسْمًا، لَا تَخْفَى عَلَى مَنْ يَعْرِفُهَا، فَرَآهَا عُمَرُ بْنُ الْخَطَّاب فَقَالَ: يَا سَوْدَةُ، وَاللَّهِ مَا تَخْفَيْنَ عَلَيْنَا فَانْظُرِي كَيْفَ تَخْرُجِينَ. قَالَتْ: فَانْكَفَأَتْ رَاجِعَةً، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي وَإِنَّهُ لَيَتَعَشَّى وَفِي يَدِهِ عَرْقٌ، فَدَخَلَتْ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي خَرَجْتُ، فَقَالَ لِي عُمَرُ: كَذَا وَكَذَا. قَالَتْ: فَأُوحِيَ إِلَيْهِ، ثُمَّ رُفِعَ عَنْهُ وَإِنَّ الْعَرْقَ فِي يَدِهِ مَا وَضَعَهُ، فَقَالَ: "إِنَّهُ قَدْ أُذِنَ لَكُنَّ أَنْ تَخْرُجْنَ لِحَاجَتِكُنَّ". (م)', 'ആഇശ(റ): ഞങ്ങൾക്ക് ഹിജാബ് നിർബന്ധമാക്കപ്പെട്ടതിന് ശേഷം സൗദ(റ) പ്രാഥമികാവശ്യങ്ങൾക്ക് വേണ്ടി പുറത്തിറങ്ങി. മറ്റു ഭാര്യമാരിൽ നിന്ന് വ്യത്യാസമാകും വിധം തടിയുള്ളവരായിരുന്നു അവർ. അവരെ അറിയുന്നവർക്ക് മനസ്സിലാകാതിരിക്കുകയില്ല. അങ്ങനെ അവരെ ഉമറുബ്നുൽഖത്താബ്(റ) കണ്ടപ്പോൾ പറഞ്ഞു: ഓ സൗദാ, നിങ്ങളെ ഞങ്ങൾക്ക് മനസ്സിലാവാതിരിക്കുകയില്ല. അതിനാൽ നിങ്ങൾ എങ്ങനെയാണ് പുറത്തിറങ്ങിയതെന്ന് നോക്കുക. ആഇശ(റ) പറയുന്നു: സൗദ(റ) പെട്ടെന്ന് തിരിച്ച് പോന്നു. റസൂൽ(സ) എന്റെ വീട്ടിൽ രാത്രി ഭക്ഷണം കഴിച്ച് കൊണ്ടിരിക്കുകയുമായിരുന്നു. അവിടന്ന് തിരുകയ്യിൽ എല്ലിന്റെ കഷ്ണമുണ്ടായിരുന്നു. അപ്പോൾ സൗദ(റ) കടന്നു വന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ പുറത്തുപോയപ്പോൾ ഉമർ(റ) എന്നോട് ഇങ്ങനെയെല്ലാം പറഞ്ഞു. ആഇശ(റ) പറയുന്നു: അപ്പോൾ നബി(സ) തങ്ങൾക്ക് വഹ്യിറങ്ങി, വഹ്യ് അവസാനിച്ചപ്പോൾ എല്ലിന്റെ കഷ്ണം അവിടത്തെ ഒരു കയ്യിൽ അങ്ങനെത്തന്നെയുണ്ട്. എന്നിട്ട് പറഞ്ഞു: നിങ്ങളുടെ ആവശ്യങ്ങൾക്ക് വേണ്ടി പുറത്തിറങ്ങാൻ അനുവദിക്കപ്പെട്ടിരിക്കുന്നു." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي الزُّبَيْرُ، وَمَا لَهُ فِي الْأَرْضِ مِنْ مَالٍ وَلَا مَمْلُوكٍ وَلَا شَيْءٍ غَيْرَ فَرَسِهِ، قَالَتْ: فَكُنْتُ أَعْلِفُ فَرَسَهُ وَأَكْفِيهِ مَئُونَتَهُ وَأَسُوسُهُ، وَأَدُقُّ النَّوَى لِنَاضِحِهِ، وَأَعْلِفُهُ، وَأَسْتَقِي الْمَاءَ وَأَخْرُزُ غَرْبَهُ وَأَعْجِنُ، وَلَمْ أَكُنْ أُحْسِنُ أَخْبِزُ، وَكَانَ يَخْبِزُ لِي جَارَاتٌ مِنَ الْأَنْصَارِ، وَكُنَّ نِسْوَةَ صِدْقٍ، قَالَتْ: وَكُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ الزُّبَيْرِ الَّتِي أَقْطَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَأْسِي، وَهِيَ عَلَى ثُلُثَيْ فَرْسَخٍ، قَالَتْ: فَجِئْتُ يَوْمًا وَالنَّوَى عَلَى رَأْسِي، فَلَقِيتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ، فَدَعَانِي ثُمَّ قَالَ: "إِخْ إِخْ". لِيَحْمِلَنِي خَلْفَهُ، قَالَتْ: فَاسْتَحْيَيْتُ وَعَرَفْتُ غَيْرَتَكَ، فَقَالَ: وَاللَّهِ لَحَمْلُكِ النَّوَى عَلَى رَأْسِكِ أَشَدُّ مِنْ رُكُوبِكِ مَعَهُ. قَالَتْ: حَتَّى أَرْسَلَ إِلَيَّ أَبُو بَكْرٍ بَعْدَ ذَلِكَ بِخَادِمٍ، فَكَفَتْنِي سِيَاسَةَ الْفَرَسِ، فَكَأَنَّمَا أَعْتَقَتْنِي. (م)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): അവർ പറഞ്ഞു: എന്നെ സുബൈർ(റ) വിവാഹം കഴിക്കുമ്പോൾ അദ്ദേഹത്തിനു ഭൂമിയിൽ കൃഷിക്ക് വെള്ളം വലിക്കാൻ ഉപയോഗിക്കുന്ന ഒരു കുതിരയല്ലാതെ ധനമോ അടിമയോ മറ്റുവല്ലതുമോ ഉണ്ടായിരുന്നില്ല. മഹതി പറഞ്ഞു: ഞാൻ അദ്ദേഹത്തിന്റെ കുതിരക്കു പുല്ലു തീറ്റുകയും ആവശ്യമുള്ള വിഭവങ്ങൾ നൽകുകയും പരിപാലിക്കുകുയം ചെയ്തിരുന്നു. കുതിരക്കു വേണ്ടി ഞാൻ ഈത്തപ്പഴക്കുരു പൊടിക്കും. അതിനെ പുല്ലുതീറ്റും. വെള്ളം കാട്ടും. തോൽപ്പാത്രം തുന്നുകയും മാവ് കുഴക്കുകയും ചെയ്യും. എനിക്ക് പത്തിരി ചുടാൻ അറിയുമായിരുന്നില്ല. അൻസാരികളായ ചില അയൽക്കാർ എനിക്ക് പത്തിരി ചുട്ടുതരുമായിരുന്നു. അവർ സത്യസന്ധരായ സ്ത്രീകളായിരുന്നു. മഹതി പറയുന്നു: റസൂൽ(സ) സുബൈർ(റ)വിന് വീതിച്ച നൽകിയ രണ്ട് മൈൽ ദൂരത്തുള്ള ഭൂമിയിൽ നിന്ന് ഞാൻ ഈത്തപ്പഴക്കുരു തലയിൽ ചുമന്ന് കൊണ്ടുവരാറാണ് പതിവ്. മഹതി പറയുന്നു: അങ്ങനെ ഒരു ദിവസം ഈത്തപ്പഴക്കുരു ചുമന്ന് വരുമ്പോൾ ഞാൻ റസൂൽ(സ)യെ കണ്ടു. കൂടെ ഒരു സംഘം സ്വഹാബാക്കളുമുണ്ടായിരുന്നു. "ഇഖ്, ഇഖ്" എന്ന് പറഞ്ഞ് തന്റെ ഒട്ടകത്തെ മുട്ടുകുത്തിച്ച് റസൂൽ(സ) എന്നോട് അവിടത്തെ പിറകിൽ കേറാൻ പറഞ്ഞു. മഹതി പറയുന്നു: നിങ്ങളുടെ (സുബൈർ(റ)വിന്റെ) അഭിമാന രോഷം മനസ്സിലാക്കിയതിനാൽ എനിക്കു ലജ്ജ തോന്നി. അപ്പോൾ സുബൈർ(റ) പറഞ്ഞു: നീ തലയിൽ ഈത്തപ്പഴക്കുരു ചുമന്ന് കൊണ്ടുപോകുന്നതാണ് റസൂൽ(സ)യോടൊപ്പം നീ വാഹനത്തിൽ കേറുന്നതിനേക്കാൾ എനിക്ക് അസഹ്യമായത്. മഹതി പറയുന്നു: ഈ സംഭവശേഷം അബുബക്കർ(റ) ഒരു ഭൃത്യനെ എനിക്കയച്ചു തന്നു. പിന്നെയെനിക്ക് കുതിരയെ പരിപാലിക്കേണ്ടി വന്നില്ല. അപ്പോൾ എനിക്ക് മോചനം ലഭിച്ച പോലെ തോന്നി. (മു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 489, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُعْتَكِفًا، فَأَتَيْتُهُ أَزُورُهُ لَيْلًا، فَحَدَّثْتُهُ، ثُمَّ قُمْتُ لِأَنْقَلِبَ فَقَامَ مَعِي لِيَقْلِبَنِي -وَكَانَ مَسْكَنُهَا فِي دَارِ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا- فَمَرَّ رَجُلَانِ مِنَ الْأَنْصَارِ، فَلَمَّا رَأَيَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْرَعَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَى رِسْلِكُمَا، إِنَّهَا صَفِيَّةُ بِنْتُ حُيَيٍّ". فَقَالَا: سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ! قَالَ: "إِنَّ الشَّيْطَانَ يَجْرِي مِنَ الْإِنْسَانِ مَجْرَى الدَّمِ، وَإِنِّي خَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا شَرًّا". أَوْ قَالَ: "شَيْئًا" (م)', 'സ്വഫിയ്യ ബിൻത് ഹുയയ്യ്(റ): നബി(സ) ഇഅ്തികാഫ് ഇരിക്കുകയായിരുന്നു. അപ്പോൾ രാത്രി ഞാൻ അവിടത്തെ സന്ദർശിച്ചു. സംസാരം കഴിഞ്ഞ് തിരിച്ച് പോകാൻ എഴുന്നേറ്റു. അപ്പോൾ എന്നെ പറഞ്ഞയക്കാനായി അവിടന്ന് എന്റെ കൂടെ വന്നു. മഹതിയുടെ താമസം ഉസാമതുബ്നു സൈദ്(റ)വിന്റെ വീട്ടിലായിരുന്നു. അപ്പോൾ അൻസാരികളിൽ പെട്ട രണ്ട് പേർ അതിലൂടെ കടന്നുവന്നു. അവർ റസൂൽ(സ)യെ കണ്ടപ്പോൾ വേഗം നടന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "സാവധാനം, അത് സ്വഫിയ്യ ബിൻത് ഹുയയ്യാണ്." അപ്പോൾ അവർ രണ്ടുപേരും പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്, യാ റസൂലല്ലാഹ്! അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിശ്ചയം പിശാച് മനുഷ്യരക്തത്തിന്റെ സഞ്ചാര പദത്തിലൂടെ സഞ്ചരിക്കുന്നു, അത് കൊണ്ട് നിങ്ങളുടെ ഹൃദയങ്ങളിൽ വല്ല തിന്മയും -അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്, ''വല്ലതും'' എന്നാണ് - അവൻ ഇട്ടുതരുന്നത് ഞാൻ ഭയക്കുന്നു." (മു)', 'صَفِيَّةَ بِنْتِ حُيَيٍّ', 'സ്വഫിയ്യ ബിൻത് ഹുയയ്യ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 490, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا لَا يَبِيتَنَّ رَجُلٌ عِنْدَ امْرَأَةٍ ثَيِّبٍ إِلَّا أَنْ يَكُونَ نَاكِحًا أَوْ ذَا مَحْرَمٍ". (م)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നു: "അറിയുക, ഭർത്താവോ വിവാഹബന്ധം നിഷിദ്ധമായവനോ അല്ലാത്ത ഒരു പുരുഷനും വിവാഹിതയായ (കന്യാചർമ്മം നീങ്ങിയ) സ്ത്രീയുടെ അടുത്ത് അന്തിയുറങ്ങരുത്." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ". فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللَّهِ، أَفَرَأَيْتَ الْحَمْوَ؟ قَالَ: "الْحَمْوُ الْمَوْتُ". قَالَ: اللَّيْثُ بْنَ سَعْدٍ: الْحَمْوُ أَخُ الزَّوْجِ وَمَا أَشْبَهَهُ مِنْ أَقَارِبِ الزَّوْجِ، ابْنِ الْعَمِّ وَنَحْوِهِ. (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറയുന്നു: "സ്ത്രീകളുടെ അടുത്ത് പോകുന്നത് നിങ്ങൾ സൂക്ഷിക്കുക." അപ്പോൾ അൻസാരികളിൽ പെട്ട ഒരാൾ ചോദിച്ചു: തിരുദൂതരേ, അപ്പോൾ ഭർത്താവിന്റെ സഹോദരനോ? അവിടന്ന് പറഞ്ഞു: "ഭർതൃസഹോദരൻ മരണമാകുന്നു." ലൈസുബ്നു സഅ്ദ്(റ) പറഞ്ഞു: ''ഹംവ്'' എന്നാൽ ഭർതൃസഹോദരനും ഭർത്താവിന്റെ കുടുംബത്തിലെ അതുപോലുള്ളവരും, പിതൃവ്യപുത്രന്മാർ പോലോത്തവരുമാണ്. (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ نَفَرًا مِنْ بَنِي هَاشِمٍ دَخَلُوا عَلَى أَسْمَاءَ بِنْتِ عُمَيْسٍ، فَدَخَلَ أَبُو بَكْرٍ الصِّدِّيقُ -وَهِيَ تَحْتَهُ يَوْمَئِذٍ- فَرَآهُمْ فَكَرِهَ ذَلِكَ، فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: لَمْ أَرَ إِلَّا خَيْرًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ قَدْ بَرَّأَهَا مِنْ ذَلِكَ". ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَقَالَ: "لَا يَدْخُلَنَّ رَجُلٌ بَعْدَ يَوْمِي هَذَا عَلَى مُغِيبَةٍ إِلَّا وَمَعَهُ رَجُلٌ أَوِ اثْنَانِ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നിൽ ആസ്(റ): ബനൂ ഹാശിമിൽ പെട്ട ഒരു സംഘം ആളുകൾ അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ അബൂബകർ സിദ്ദീഖ്(റ) കടന്നുവന്നു, അസ്മാഅ്(റ) സിദ്ദീഖ്(റ)വിന്റെ ഭാര്യയായിരുന്നു, അദ്ദേഹം അവരെ കണ്ടപ്പോൾ അത് ഇഷ്ടപ്പെട്ടില്ല. അങ്ങനെ അതിനെക്കുറിച്ച് റസൂൽ(സ)യോട് പറയുകയും ചെയ്തു. നല്ലത് മാത്രമേ കണ്ടിട്ടുള്ളൂ എന്നും പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും അല്ലാഹു അവരെ അതിൽ നിന്ന് മുക്തമാക്കിയിരിക്കുന്നു." ശേഷം തിരുമേനി(സ) മിമ്പറിൽ കയറി പറഞ്ഞു: "ഈ ദിവസത്തിന് ശേഷം ഭർത്താവ് സ്ഥലത്തില്ലാത്ത ഒരു സ്ത്രീയുടെ അടുത്തും ഒന്നോ രണ്ടോ ആളുകളില്ലാതെ ആരും പോകരുത്." (മു)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നിൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 491, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ يَدْخُلُ عَلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُخَنَّثٌ، فَكَانُوا يَعُدُّونَهُ مِنْ غَيْرِ أُولِي الْإِرْبَةِ، قَالَ: فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا وَهُوَ عِنْدَ بَعْضِ نِسَائِهِ وَهُوَ يَنْعَتُ امْرَأَةً، قَالَ: إِذَا أَقْبَلَتْ أَقْبَلَتْ بِأَرْبَعٍ، وَإِذَا أَدْبَرَتْ أَدْبَرَتْ بِثَمَانٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أَرَى هَذَا يَعْرِفُ مَا هَاهُنَا؟ لَا يَدْخُلَنَّ عَلَيْكُنَّ". قَالَتْ: فَحَجَبُوهُ. (م)', 'ആഇശ(റ): നബി(സ)യുടെ ഭാര്യമാരുടെ അടുത്ത് ഒരു നപുംസകം വരാറുണ്ടായിരുന്നു. അവർ ആ നപുംസകത്തെ നിർവികാരനായി കണക്കാക്കുകയും ചെയ്തിരുന്നു. അങ്ങനെ ഒരു ദിവസം നബി(സ) ഭാര്യമാരുടെ അടുക്കൽ പോയപ്പോൾ ആ നപുംസകം അവിടെയിരുന്ന് ഒരു സ്ത്രീയെ വർണ്ണിക്കുകയായിരുന്നു. അദ്ദേഹം പറയുന്നു: അവൾ നാലെണ്ണവുമായി മുന്നിട്ടുവരികയും എട്ടെണ്ണവുമായി തിരിച്ച് പോകുകയും ചെയ്യും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവിടെ എന്താണെന്ന് ഇവനറിഞ്ഞുകൂടേ? ഇനി അവൻ നിങ്ങളുടെയടുത്ത് വരരുത്." ആഇശ(റ) പറയുന്നു: പിന്നീടവർ അവനെ തടഞ്ഞു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ وَسَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ رَضِيَ اللهُ عَنْهُمْ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا تَرَكْتُ بَعْدِي فِي النَّاسِ فِتْنَةً أَضَرَّ عَلَى الرِّجَالِ مِنَ النِّسَاءِ". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'ഉസാമതുബ്നുസൈദ്(റ), സഈദുബ്നു സൈദ്(റ): നബി(സ) പറയുന്നു: "ജനങ്ങൾക്കിടയിൽ പുരുഷൻമാർക്ക് സ്ത്രീകളേക്കാൾ ദ്രോഹപരമായ ഒരു വിപത്തിനെയും എനിക്ക് ശേഷം ഞാൻ ഉപേക്ഷിച്ചിട്ടില്ല." (ബു,മു,തു,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ وَسَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ', 'ഉസാമതുബ്നുസൈദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَاهُمْ أَنْ يَطْرُقُوا النِّسَاءَ لَيْلًا. حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ജാബിർ(റ): ഭാര്യമാരുടെ അടുത്തേക്ക് രാത്രിയിൽ യാത്ര കഴിഞ്ഞ് അപ്രതീക്ഷിതമായി കേറി വരുന്നത് നബി(സ) അവരോട് വിലക്കി. (ബു,മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: احْتَرَقَ بَيْتٌ عَلَى أَهْلِهِ بِالْمَدِينَةِ مِنَ اللَّيْلِ، فَلَمَّا حُدِّثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَأْنِهِمْ، قَالَ: "إِنَّ هَذِهِ النَّارَ إِنَّمَا هِيَ عَدُوٌّ لَكُمْ، فَإِذَا نِمْتُمْ فَأَطْفِئُوهَا عَنْكُمْ". (ق,جه)', 'അബൂമൂസാ(റ): രാത്രിയിൽ മദീനയിലെ ഒരു വീട് കത്തി നശിച്ചു. ഇതേക്കുറിച്ച് റസൂൽ(സ)യോട് പറഞ്ഞപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം തീ നിങ്ങളുടെ ശത്രുവാണ്, നിങ്ങൾ ഉറങ്ങുമ്പോൾ അത് അണക്കുക." (ബു,മു,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَتْرُكُوا النَّارَ فِي بُيُوتِكُمْ حِينَ تَنَامُونَ". (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറയുന്നു: "നിങ്ങൾ ഉറങ്ങുമ്പോൾ വീട്ടിൽ തീ ഉപേക്ഷിച്ചിടരുത്." (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَتْ فَأْرَةٌ فَأَخَذَتْ تَجُرُّ الْفَتِيلَةَ، فَجَاءَتْ بِهَا فَأَلْقَتْهَا بَيْنَ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْخُمْرَةِ الَّتِي كَانَ قَاعِدًا عَلَيْهَا، فَأَحْرَقَتْ مِنْهَا مِثْلَ مَوْضِعِ الدِّرْهَمِ، فَقَالَ: "إِذَا نِمْتُمْ فَأَطْفِئُوا سُرُجَكُمْ، فَإِنَّ الشَّيْطَانَ يَدُلُّ مِثْلَ هَذِهِ عَلَى هَذَا فَتُحْرِقَكُمْ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു എലി വന്നു വിളക്കന്റെ തിരി വലിക്കാൻ തുടങ്ങി, എന്നിട്ടത് റസൂൽ(സ)യുടെ മുന്നിൽ റസൂൽ(സ) ഇരിക്കാറുള്ള ഒരു ചെറിയ പായയിൽ കൊണ്ടുവന്നിട്ടു, ഒരു ദിർഹമിന്റെ വട്ടത്തിൽ കരിഞ്ഞുപോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഉറങ്ങുകയാണെങ്കിൽ വിളക്കുകൾ അണക്കുക, കാരണം പിശാച് ഇവയെ പോലെയുള്ളതിന് (എലിക്ക്) ഇങ്ങനെയുള്ള പ്രവർത്തനങ്ങൾ അറിയിച്ച് കൊടുക്കുകയും അങ്ങനെ നിങ്ങളെ കരിച്ച് കളയുകയും ചെയ്യും." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَهَانَا، فَأَمَرَنَا أَنْ نُطْفِئَ سِرَاجَنَا. (جه)', 'ജാബിർ(റ): റസൂൽ(സ) ഞങ്ങളോട് കൽപ്പിക്കുകയും നിരോധിക്കുകയും ചെയ്തിട്ടുണ്ട്. വിളക്കുകൾ അണക്കാൻ അവിടന്ന് ഞങ്ങളോട് കൽപ്പിച്ചു. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّكَ تَبْعَثُنَا، فَنَنْزِلُ بِقَوْمٍ فَلَا يَقْرُونَنَا، فَمَا تَرَى؟ فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ نَزَلْتُمْ بِقَوْمٍ فَأَمَرُوا لَكُمْ بِمَا يَنْبَغِي لِلضَّيْفِ فَاقْبَلُوا، فَإِنْ لَمْ يَفْعَلُوا فَخُذُوا مِنْهُمْ حَقَّ الضَّيْفِ الَّذِي يَنْبَغِي لَهُمْ". (م,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, അവിടന്ന് ഞങ്ങളെ പറഞ്ഞയക്കുകയും ഞങ്ങൾ ഒരു സമൂഹത്തിന്റെയടുത്ത് വസിക്കുകയും ചെയ്യുന്നു. പക്ഷെ, അവർ ഞങ്ങൾക്ക് ആതിഥ്യം നൽകുന്നില്ല. എങ്കിൽ അവിടന്ന് എന്ത് പറയുന്നു? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു സമൂഹത്തിന്റെയടുത്തിറങ്ങിയാൽ അതിഥിക്കാവശ്യമായത് അവർ തയ്യാർചെയ്തുതന്നാൽ നിങ്ങൾ സ്വീകരിക്കുക. അവർ അങ്ങനെ ചെയ്തില്ലെങ്കിൽ അതിഥിയുടെ അവകാശം നിങ്ങൾ പിടിച്ചെടുക്കുക." (മു,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 493, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنْ أَبِي شُرَيْحٍ الْعَدَوِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَبْصَرَتْ عَيْنَايَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَسَمِعَتْهُ أُذُنَايَ حِينَ تَكَلَّمَ بِهِ، قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ جَائِزَتَهُ". قَالُوا: وَمَا جَائِزَتُهُ؟ قَالَ: "يَوْمٌ وَلَيْلَةٌ، وَالضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، وَمَا كَانَ بَعْدَ ذَلِكَ فَهُوَ صَدَقَةٌ. وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ". حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബൂശുറൈഹിൽ അദവി(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് എന്റെ രണ്ട് കണ്ണുകൾ കാണുകയും രണ്ട് ചെവികൾ കേൾക്കുകയും ചെയ്തു: അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിലും അവസാന നാളിലും വിശ്വസിക്കുന്നവൻ തന്റെ അതിഥിയെ അവന്റെ ''ജാഇസ'' സൽക്കരിക്കട്ടെ." അവർ ചോദിച്ചു: അവന്റെ ജാഇസത്തെന്നാലെന്താകുന്നു? അവിടന്ന് പറഞ്ഞു: "ഒരു രാത്രിയും പകലും. ആതിഥ്യം മൂന്ന് ദിവസവുമാണ്. അതിന് ശേഷമുള്ളത് ദാനമാണ്. അല്ലാഹുവിലും അവസാനനാളിലും വിശ്വസിക്കുന്നവൻ നല്ലത് പറയട്ടെ. അല്ലെങ്കിൽ മൗനം പാലിക്കട്ടെ." (ബു,മു,ദ,തു,ജ)', 'أَبِي شُرَيْحٍ الْعَدَوِيِّ', 'അബൂശുറൈഹിൽ അദവി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، وَجَائِزَتُهُ يَوْمٌ وَلَيْلَةٌ، وَلَا يَحِلُّ لَهُ أَنْ يَثْوِيَ عِنْدَ صَاحِبِهِ حَتَّى يُحْرِجَهُ. الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، وَمَا أَنْفَقَ عَلَيْهِ بَعْدَ ثَلَاثَةِ أَيَّامٍ فَهُوَ صَدَقَةٌ". (جه)', 'അബൂ ശുറൈഹിൽ ഖുസാഈ(റ): നബി(സ) പറയുന്നു: "അല്ലാഹുവിലും അവസാന നാളിലും വിശ്വസിക്കുന്നവൻ തന്റെ അതിഥിയെ ബഹുമാനിക്കട്ടെ, അവന് നന്നായി ഭക്ഷണം നൽകലും അവനോട് അധികമായി നന്മ ചെയ്യലും ഒരു പകലും രാത്രിയുമാണ്. ഒരാളുടെ അടുത്ത് അവന് ബുദ്ധിമുട്ടാകുന്നത് വരെ താമസിക്കൽ അനുവദനീയമല്ല. ആതിഥ്യം മൂന്ന് ദിവസമാകുന്നു. അതിനേക്കാൾ കൂടുതൽ ചിലവഴിക്കുന്നത് ദാനവുമാകുന്നു." (ജ)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'അബൂ ശുറൈഹിൽ ഖുസാഈ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، وَجَائِزَتُهُ يَوْمٌ وَلَيْلَةٌ، وَلَا يَحِلُّ لِرَجُلٍ مُسْلِمٍ أَنْ يُقِيمَ عِنْدَ أَخِيهِ حَتَّى يُؤْثِمَهُ". قَالُوا: يَا رَسُولَ اللَّهِ، وَكَيْفَ يُؤْثِمُهُ؟ قَالَ: "يُقِيمُ عِنْدَهُ وَلَا شَيْءَ لَهُ يَقْرِيهِ بِهِ". (م)', 'ആബൂശുറൈഹിൽ ഖുസാഈ(റ): റസൂൽ(സ) പറയുന്നു: "ആതിഥ്യം മൂന്ന് ദിവസവും അവന് നന്നായി ഭക്ഷണം നലൽകേണ്ടതും അധികമായി നന്മ ചെയ്യേണ്ടതും ഒരു പകലും രാത്രിയുമാണ്. മുസ്ലിമായ ഒരു മനുഷ്യനും തന്റെ സഹോദരന്റെയടുത്ത് അവനെ കുറ്റക്കാരനാക്കുന്നത് വരെ താമസിക്കൽ അനുവദനീയമല്ല." അവർ ചോദിച്ചു: തിരുദൂതരേ, എങ്ങനെയാണ് അവനെ കുറ്റക്കാരനാക്കുന്നത്? അവിടന്ന് പറഞ്ഞു: "അവന്റെയടുത്ത് സൽകരിക്കാൻ ഒന്നുമില്ലാതെതന്നെ അവന്റെയടുക്കൽ താമസിക്കലാകുന്നു." (മു)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'ആബൂശുറൈഹിൽ ഖുസാഈ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنِ الْمِقْدَامِ أَبِي كَرِيمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْلَةُ الضَّيْفِ وَاجِبَةٌ، فَإِنْ أَصْبَحَ بِفِنَائِهِ فَهُوَ دَيْنٌ عَلَيْهِ، فَإِنْ شَاءَ اقْتَضَى وَإِنْ شَاءَ تَرَكَ". (د,جه)', 'അൽമിഖ്ദാം അബൂകരീമ(റ): റസൂൽ(സ) പറയുന്നു: "അതിഥിയുടെ രാത്രി (അവനെ സൽക്കരിക്കാൻ) നിർബന്ധവും പ്രഭാതത്തിൽ അവൻ വീട്ടിലുണ്ടെങ്കിൽ അത് കടവുമാണ്. അവൻ (ആതിഥേയൻ) ഉദ്ദേശിക്കുന്നെങ്കിൽ വീട്ടാം, അല്ലെങ്കിൽ ഒഴിവാക്കാം." (ദ,ജ)', 'الْمِقْدَامِ أَبِي كَرِيمَةَ', 'അൽമിഖ്ദാം അബൂകരീമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 494, 494, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ فِي سَفَرٍ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ رَجُلٌ عَلَى رَاحِلَةٍ لَهُ، قَالَ: فَجَعَلَ يَصْرِفُ بَصَرَهُ يَمِينًا وَشِمَالًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ مَعَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا ظَهْرَ لَهُ، وَمَنْ كَانَ لَهُ فَضْلٌ مِنْ زَادٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا زَادَ لَهُ". قَالَ: فَذَكَرَ مِنْ أَصْنَافِ الْمَالِ مَا ذَكَرَ، حَتَّى رَأَيْنَا أَنَّهُ لَا حَقَّ لِأَحَدٍ مِنَّا فِي فَضْلٍ. (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ യാത്ര ചെയ്യുമ്പോൾ ഒരാൾ തന്റെ വാഹനവുമായി വന്നു. നിവേദകൻ പറയുന്നു: അദ്ദേഹം ഇടതു വശത്തേക്കും വലതു വശത്തേക്കും നോക്കിക്കൊണ്ടിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആരുടെയെങ്കിലും വാഹനത്തിൽ സ്ഥലം ബാക്കിയുണ്ടെങ്കിൽ സ്ഥലം ഇല്ലാത്തവർക്ക് അതൊരുക്കിക്കൊടുക്കട്ടെ, പാഥേയം ബാക്കിയുള്ളവർ ഇല്ലാത്തവർക്ക് നൽകട്ടെ." നിവേദകൻ പറയുന്നു: ധനത്തിന്റെ നിരവധി ഇനങ്ങൾ നബി(സ) പറഞ്ഞു, ബാക്കിയുള്ളതിൽ ഞങ്ങൾക്ക് ഒരവകാശവുമില്ലെന്ന് തോന്നും വിധം. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 495, 495, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=171 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنْ إِيَاسِ بْنِ سَلَمَةَ رَضِيَ اللهُ عَنْهُ عَنْ أَبِيهِ، قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، فَأَصَابَنَا جَهْدٌ، حَتَّى هَمَمْنَا أَنْ نَنْحَرَ بَعْضَ ظَهْرِنَا، فَأَمَرَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَمَعْنَا مَزَاوِدَنَا فَبَسَطْنَا لَهُ نطَعًا، فَاجْتَمَعَ زَادُ الْقَوْمِ عَلَى النِّطَعِ، قَالَ: فَتَطَاوَلْتُ لِأَحْزُرَهُ كَمْ هُوَ؟ فَحَزَرْتُهُ كَرَبْضَةِ الْعَنْزِ، وَنَحْنُ أَرْبَعَ عَشْرَةَ مِائَةً، قَالَ: فَأَكَلْنَا حَتَّى شَبِعْنَا جَمِيعًا، ثُمَّ حَشَوْنَا جُرُبَنَا، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَهَلْ مِنْ وَضُوءٍ". قَالَ: فَجَاءَ رَجُلٌ بِإِدَاوَةٍ [لَهُ] فِيهَا نُطْفَةٌ، فَأَفْرَغَهَا فِي قَدَحٍ، فَتَوَضَّأْنَا كُلُّنَا نُدَغْفِقُهُ دَغْفَقَةً، أَرْبَعَ عَشْرَةَ مِائَةً، قَالَ: ثُمَّ جَاءَ بَعْدَ ذَلِكَ ثَمَانِيَةٌ، فَقَالُوا: هَلْ مِنْ طَهُورٍ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَرِغَ الْوَضُوءُ". (م)', 'ഇയാസുബ്നു സലമ(റ): തന്റെ പിതാവ് പറഞ്ഞു: റസൂൽ(സ)യുടെ കൂടെ ഞങ്ങൾ ഒരു യുദ്ധത്തിന് പുറപ്പെട്ടു. ഞങ്ങൾക്ക് ശക്തമായ ക്ഷീണം അനുഭവപ്പെട്ടപ്പോൾ ഞങ്ങളുടെ ചില വാഹനങ്ങളെ അറുക്കാൻ പോലും ഞങ്ങൾ ഉദ്ദേശിച്ചു. അപ്പോൾ നബി(സ) ഞങ്ങളുടെ പാഥേയപാത്രങ്ങൾ ഒരുമിച്ച് കൂട്ടാൻ കൽപ്പിച്ചു. അതിന് വേണ്ടി ഞങ്ങൾ ഒരു തോൽവിരിപ്പ് വിരിച്ചു. എല്ലാവരുടെയും പാഥേയം തോൽവിരിപ്പിൽ ഒരുമിച്ച് കൂടി. നിവേദകൻ പറയുന്നു: അത് എത്രയുണ്ടെന്ന് നോക്കി ശേഖരിക്കാൻ ഞാൻ നീളമുള്ളവനായി അഭിനയിച്ചു. ഒരു കുന്തത്തിന്റെ അളവിൽ ഞാനത് ഒരുമിച്ചു കൂട്ടി. ഞങ്ങൾ 1400 പേരുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ വയറു നിറയെ ഭക്ഷിച്ചു. ശേഷം ഞങ്ങളുടെ പാഥേയപാത്രങ്ങൾ നിറച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: ആരുടെയെങ്കിലും പക്കൽ വുളൂഅ് എടുക്കാൻ ഉള്ള വെള്ളം ഉണ്ടോ? അപ്പോൾ വളരെ കുറച്ച് മാത്രം വെള്ളമുള്ള ഒരു തോൽപാത്രവുമായി ഒരാൾ വന്നു. അത് ഒരു പാത്രത്തിലേക്ക് റസൂൽ(സ) മാറ്റി. ഞങ്ങൾ ആയിരത്തി നാനൂറ് പേരും വുളൂഅ് ചെയ്തു. നന്നായികോരിയൊഴിക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അതിന് ശേഷം എട്ട് പേർ വന്നു, ചോദിച്ചു: (അതിൽ) വുളൂഅ് എടുക്കാനുള്ള വെള്ളമുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "വെള്ളം കഴിഞ്ഞു" (മു)', 'إِيَاسِ بْنِ سَلَمَةَ', 'ഇയാസുബ്നു സലമ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَهُ', null, 495, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَدْخُلِ الْحَمَّامَ بِغَيْرِ إِزَارٍ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُدْخِلْ حَلِيلَتَهُ الْحَمَّامَ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَجْلِسْ عَلَى مَائِدَةٍ يُدَارُ عَلَيْهَا بِالْخَمْرِ". حَسَنٌ. (ت)', 'ജാബിർ(റ): നബി(സ) പറയുന്നു: "അല്ലാഹുവിലും അവസാന നാളിലും വിശ്വസിക്കുന്നവൻ തുണിയില്ലാതെ പൊതുകുളിസ്ഥലത്ത് പ്രവേശിക്കരുത്, അല്ലാഹുവിലും അന്ത്യനാളിയും വിശ്വസിക്കുന്നവൻ തന്റെ ഭാര്യയെ പൊതുകുളിസ്ഥലത്ത് പ്രവേശിപ്പിക്കരുത്, അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നവൻ മദ്യം വിളമ്പുന്ന സുപ്രക്ക് ചുറ്റും ഇരിക്കരുത്." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 375, 'عَنْ أَبِي عُذْرَةَ رَضِيَ اللهُ عَنْهُ -وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى الرِّجَالَ وَالنِّسَاءَ عَنِ الْحَمَّامَاتِ، ثُمَّ رَخَّصَ لِلرِّجَالِ فِي الْمَيَازِرِ. (د,ت,جه)', 'ആഇശ(റ)യിൽ നിന്ന് അബൂഉദ്റ(റ) (അദ്ദേഹം റസൂൽ(സ)യെ കണ്ടുമുട്ടിയ വ്യക്തിയാണ്): പൊതുകുളിസ്ഥലത്ത് പുരുഷൻമാരും സ്ത്രീകളും ഒരുമിച്ച്കൂടൽ നബി(സ) നിരോധിച്ചിരിക്കുന്നു. പിന്നെ പുരുഷൻമാർക്ക് തുണിയിൽ ഇളവ് നൽകി. (ദ,തു,ജ)', 'أَبِي عُذْرَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 376, 'عَنْ أَبِي الْمَلِيحِ الْهُذَلِيِّ: أَنَّ نِسَاءً مِنْ أَهْلِ حِمْصَ -أَوْ مِنْ أَهْلِ الشَّامِ- دَخَلْنَ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَقَالَتْ: أَنْتُنَّ اللَّاتِي يَدْخُلْنَ نِسَاؤُكُنَّ الْحَمَّامَاتِ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنِ امْرَأَةٍ تَضَعُ ثِيَابَهَا فِي غَيْرِ بَيْتِ زَوْجِهَا إِلَّا هَتَكَتِ السِّتْرَ بَيْنَهَا وَبَيْنَ رَبِّهَا". حَسَنٌ. (د,ت,جه)', 'അബുൽ മലീഹിൽ ഹുദലി(റ): ഹിംസിൽ നിന്നോ അല്ലെങ്കിൽ ശാമിൽ നിന്നോ കുറച്ച് സ്ത്രീകൾ ആഇശ(റ)യുടെ അടുത്ത് വന്നു. അപ്പോൾ ആഇശ(റ) ചോദിച്ചു: നിങ്ങൾ സ്ത്രീകൾ പൊതുകുളിസ്ഥലത്ത് പ്രവേശിക്കുന്നവരല്ലെയോ? റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "തന്റെ ഭർത്താവിന്റെ വീട്ടിലല്ലാതെ വസ്ത്രം അഴിച്ച് വെക്കുന്നവൾ തന്റെയും തന്റെ രക്ഷിതാവിന്റെയും ഇടക്കുള്ള മറ പൊളിച്ചിരിക്കുന്നു." (ദ,തു,ജ)', 'أَبِي الْمَلِيحِ الْهُذَلِيِّ', 'അബുൽ മലീഹിൽ ഹുദലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 377, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تُفْتَحُ لَكُمْ أَرْضُ الْأَعَاجِمِ، وَسَتَجِدُونَ فِيهَا بُيُوتًا يُقَالُ لَهَا الْحَمَّامَاتُ، فَلَا يَدْخُلْهَا الرِّجَالُ إِلَّا بِإِزَارٍ، وَامْنَعُوا النِّسَاءَ أَنْ يَدْخُلْنَهَا، إِلَّا مَرِيضَةً أَوْ نُفَسَاءَ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നു: "അനറബി ദേശങ്ങൾ നിങ്ങൾക്ക് കീഴടങ്ങും. അവിടെ ബാത്റൂം (പൊതുകുളിസ്ഥലം) എന്ന് പറയുന്ന ചിലവീടുകളുണ്ടാവും. അതിൽ തുണിയില്ലാതെ പുരുഷൻമാർ പ്രവേശിക്കരുത്. രോഗികളോ പ്രസവരക്തം സ്രവിക്കുന്നവരോ അല്ലാത്ത സ്ത്രീകൾ അതിൽ പ്രവേശിക്കുന്നത് നിങ്ങൾ തടയുകയും ചെയ്യുക." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 378, 'عَنْ يَعِيشَ بْنِ طَخْفَةَ بْنِ قَيْسٍ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَبِي مِنْ أَصْحَابِ الصُّفَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "انْطَلِقُوا بِنَا إِلَى بَيْتِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا". فَانْطَلَقْنَا، فَقَالَ: "يَا عَائِشَةُ أَطْعِمِينَا". فَجَاءَتْ بِجَشِيشَةٍ فَأَكَلْنَا، ثُمَّ قَالَ: "يَا عَائِشَةُ، أَطْعِمِينَا". فَجَاءَتْ بِحَيْسَةٍ مِثْلِ الْقَطَاةِ فَأَكَلْنَا، ثُمَّ قَالَ: "يَا عَائِشَةُ، اسْقِينَا". فَجَاءَتْ بِعُسٍّ مِنْ لَبَنٍ فَشَرِبْنَا، ثُمَّ قَالَ: "يَا عَائِشَةُ اسْقِينَا". فَجَاءَتْ بِقَدَحٍ صَغِيرٍ فَشَرِبْنَا، ثُمَّ قَالَ: "إِنْ شِئْتُمْ بِتُّمْ، وَإِنْ شِئْتُمُ انْطَلَقْتُمْ إِلَى الْمَسْجِدِ". قَالَ: فَبَيْنَمَا أَنَا مُضْطَجِعٌ فِي الْمَسْجِدِ مِنَ السَّحَرِ عَلَى بَطْنِي إِذَا رَجُلٌ يُحَرِّكُنِي بِرِجْلِهِ، فَقَالَ: "إِنَّ هَذِهِ ضِجْعَةٌ يُبْغِضُهَا اللَّهُ". قَالَ: فَنَظَرْتُ فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ (د,جه)', 'യഈശുബ്നു ത്വിഖ്ഫത് ബിൻ ഖൈസിൽ ഗിഫാരീ(റ): എന്റെ പിതാവ് അസ്ഹാബുസ്സുഫ്ഫ (മദീന പള്ളിയുടെ ചെരുവിൽ താമസിച്ചിരുന്ന സ്വഹാബികൾ)യിൽ പെട്ടയാളായിരുന്നു. ഒരിക്കൽ റസൂൽ(സ) പറഞ്ഞു: "നമുക്ക് ആഇശ(റ)യുടെ വീട്ടിലേക്കു പോകാം." അങ്ങനെ ഞങ്ങൾ പോയി. റസൂൽ(സ) ആഇശ(റ)യോട് പറഞ്ഞു: "ആഇശാ! നീ ഞങ്ങളെ ഭക്ഷിപ്പിക്കുക." അപ്പോൾ ആഇശ(റ) ജശീശ (ഗോതമ്പും മാംസവും കൂട്ടിയുണ്ടാക്കുന്ന ഭക്ഷണം) കൊണ്ട് വരികയും ഞങ്ങളത് ഭക്ഷിക്കുകയും ചെയ്തു. റസൂൽ(സ) വീണ്ടും പറഞ്ഞു: "ആഇശാ, നീ ഞങ്ങളെ ഭക്ഷിപ്പിക്കുക". അപ്പോൾ ആഇശ(റ) ഹൈസ (പാൽകട്ടിയും ഈത്തപ്പഴവും ചേർത്തുണ്ടാക്കുന്ന പായസം) കൊണ്ട് വന്നു. അത് ഒരു പ്രാവിന്റെ മാംസത്തിന്റെയത്രയേ ഉണ്ടായിരുന്നുള്ളൂ. ഞങ്ങളത് ഭക്ഷിച്ചു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, നീ ഞങ്ങളെ കുടിപ്പിക്കുക. അപ്പോൾ അവർ ഒരു പാത്രം പാൽ കൊണ്ടുവരികയും ഞങ്ങൾ അത് കുടിക്കുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, നീ ഞങ്ങളെ കുടിപ്പിക്കുക." അപ്പോൾ അവർ ഒരു ചെറിയ പാത്രവുമായി വരികയും ഞങ്ങൾ അതിൽ നിന്ന് കുടിക്കുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്കു വേണമെങ്കിൽ ഉറങ്ങാം, അല്ലെങ്കിൽ പള്ളിയിലേക്ക് പോകാം." നിവേദകൻ പറഞ്ഞു: അങ്ങനെ ഞാൻ അത്താഴസമയത്ത് പള്ളിയിൽ കമിഴ്ന്നു കിടക്കുമ്പോൾ ഒരാൾ വന്ന് തന്റെ കാല് കൊണ്ട് എന്നെ ഇളക്കിക്കൊണ്ട് പറയുന്നു: "ഇത് അല്ലാഹുവിന് കോപമുണ്ടാക്കുന്ന കിടത്തമാണ്." ഞാൻ നോക്കുമ്പോൾ അത് റസൂൽ(സ)യായിരുന്നു. (ദ,ജ)', 'يَعِيشَ بْنِ طَخْفَةَ بْنِ قَيْسٍ الْغِفَارِيِّ', 'യഈശുബ്നു ത്വിഖ്ഫത് ബിൻ ഖൈസിൽ ഗിഫാരീ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 379, 'عَنْ طِخْفَةَ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَصَابَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَائِمًا فِي الْمَسْجِدِ عَلَى بَطْنِي، فَرَكَضَنِي بِرِجْلِهِ وَقَالَ: "مَا لَكَ وَلِهَذَا النَّوْمِ، هَذِهِ نَوْمَةٌ يَكْرَهُهَا اللَّهُ. أَوْ: يُبْغِضُهَا اللَّهُ". (جه)', 'ത്വിഖ്ഫതുൽ ഗിഫാരീ(റ): ഞാൻ പള്ളിയിൽ കമിഴ്ന്നു കിടന്നുറങ്ങുന്നത് റസൂൽ(സ) കണ്ടു. അപ്പോൾ തന്റെ കാല് കൊണ്ട് റസൂൽ(സ) എന്നെ തട്ടി. എന്നിട്ട് പറഞ്ഞു: "നീയെന്താണ് ഇപ്രകാരമുറങ്ങുന്നത്, ഇത് അല്ലാഹു വെറുക്കുന്ന ഉറക്കമാണ്. അല്ലെങ്കിൽ അല്ലാഹു ദേശ്യപ്പെടുന്ന ഉറക്കമാണ്." (ജ)', 'طِخْفَةَ الْغِفَارِيِّ', 'ത്വിഖ്ഫതുൽ ഗിഫാരീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 380, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ بِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مُضْطَجِعٌ عَلَى بَطْنِي، فَرَكَضَنِي بِرِجْلِهِ، وَقَالَ: "يَا جُنَيْدِبُ، إِنَّمَا هَذِهِ ضِجْعَةُ أَهْلِ النَّارِ". (جه)', 'അബുദർറ്(റ): ഞാൻ കമിഴ്ന്ന് കിടന്ന് കൊണ്ടിരിക്കുമ്പോൾ നബി(സ) എന്റെയടുത്ത് കൂടെ നടന്നു പോയി. തിരുമേനി(സ) തന്റെ കാല് കൊണ്ട് എന്നെ ചവിട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ജുനൈദിബേ, (അബൂദർറേ), ഇത് നരകവാസികളുടെ കിടത്തമാണ്." (ജ)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 497, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 381, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مُضْطَجِعًا عَلَى بَطْنِهِ، فَقَالَ: "إِنَّ هَذِهِ ضِجْعَةٌ لَا يُحِبُّهَا اللَّهُ". (ت)', 'അബൂഹുറൈറ(റ): ഒരാൾ കമിഴ്ന്നു കിടക്കുന്നത് റസൂൽ(സ) കണ്ടു. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു ഇഷ്ടപ്പെടാത്ത കിടത്തമാണിത്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 382, 'عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَلْقِيًا فِي الْمَسْجِدِ، وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസ്വിം(റ): നബി(സ) പള്ളിയിൽ ഒരു കാൽ മറ്റേ കാലിനു മുകളിൽ വെച്ച് മലർന്നു കിടക്കുന്നത് അവർ കണ്ടു. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസ്വിം(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 383, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ وَعُثْمَانَ بْنَ عَفَّانَ -رَضِيَ اللهُ عَنْهُمَا- كَانَا يَفْعَلَانِ ذَلِكَ. (خ,د)', 'സഈദുബ്നു മുസയ്യബ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ)വും ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വും അപ്രകാം ചെയ്യാറുണ്ടായിരുന്നു. (ബു,ദ)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 384, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ اشْتِمَالِ الصَّمَّاءِ، وَالِاحْتِبَاءِ فِي ثَوْبٍ وَاحِدٍ، وَأَنْ يَرْفَعَ الرَّجُلُ إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى وَهُوَ مُسْتَلْقٍ عَلَى ظَهْرِهِ. حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'ജാബിർ(റ): ദേഹമാകെ മൂടുന്ന വസ്ത്രം ധരിക്കലും ഒരു വസ്ത്രത്തിൽ മുട്ട് കെട്ടിയിരിക്കലും, മലർന്നു കിടന്ന് ഒരുകാൽ മറ്റേ കാലിൻമേൽ കയറ്റിവെക്കുന്നതും റസൂൽ(സ) നിരോധിച്ചു. (മു,ദ,തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 385, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَلْقَى أَحَدُكُمْ عَلَى ظَهْرِهِ فَلَا يَضَعْ إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى". (ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും മലർന്നു കിടക്കുന്നെങ്കിൽ തന്റെ ഒരു കാൽ മറ്റേ കാലിനു മുകളിൽ വെക്കരുത്." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 386, 'عَنْ جَابِرٍ [بْنِ عَبْدِ اللَّهِ] رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَسْتَلْقِيَنَّ أَحَدُكُمْ، ثُمَّ يَضَعُ إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى". (م)', 'ജാബിർ ബിൻ അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളും ഒരു കാലിനു മേൽ മറ്റേകാൽ കയറ്റിവെച്ച് മലർന്നു കിടക്കരുത്." (മു)', 'جَابِرٍ [بْنِ عَبْدِ اللَّهِ]', 'ജാബിർ ബിൻ അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'بْنِ عَبْدِ اللَّهِ', null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 387, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ نَائِمٍ فِي الْمَسْجِدِ، مُنْبَطِحٍ عَلَى وَجْهِهِ، فَضَرَبَهُ بِرِجْلِهِ وَقَالَ: "قُمْ وَاقْعُدْ، فَإِنَّهَا نَوْمَةٌ جَهَنَّمِيَّةٌ". [ز: مُخْتَلَفٌ فِي رِجَالِ سَنَدِهِ] (جه)', 'അബൂഉമാമ(റ): പള്ളിയിൽ മുഖം കമിഴ്ത്തി കിടന്നുറങ്ങുന്ന ഒരാളുടെ അടുത്ത് കൂടെ നബി(സ) നടന്നു പോയി. അവിടന്ന് തന്റെ കാൽ കൊണ്ട് ആ മനുഷ്യനെ ചവിട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു. "നീ എഴുന്നേറ്റിരിക്കുക, ഇത് നരകത്തിലെ ഉറക്കമാണ്." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مُخْتَلَفٌ فِي رِجَالِ سَنَدِهِ', null, 498, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 388, 'عَنْ عَلِيِّ بْنِ شَيْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ بَاتَ عَلَى ظَهْرِ بَيْتٍ لَيْسَ لَهُ حِجَارٌ فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ". (د)', 'അലിയ്യുബ്നു ശൈബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ചുറ്റും തടവില്ലാത്ത തട്ടിൻ പുറത്ത് ഒരാൾ ഉറങ്ങുന്നുവെങ്കിൽ അവനിൽ ആർക്കും ഉത്തരവാദിത്വമില്ല." (ദ)', 'عَلِيِّ بْنِ شَيْبَانَ', 'അലിയ്യുബ്നു ശൈബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=178 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 389, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَنَامَ الرَّجُلُ عَلَى سَطْحٍ لَيْسَ بِمَحْجُورٍ عَلَيْهِ. (ت)', 'ജാബിർ(റ): മറക്കപ്പെടാത്ത മേൽക്കൂരയിൽ കിടന്നുറങ്ങുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=178 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 390, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ يَبِيتُ عَلَى ذِكْرٍ طَاهِرًا، فَيَتَعَارُّ مِنَ اللَّيْلِ، فَيَسْأَلُ اللَّهَ خَيْرًا مِنَ الدُّنْيَا وَالْآخِرَةِ إِلَّا أَعْطَاهُ إِيَّاهُ". (د,جه)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) പറഞ്ഞു: "ശുദ്ധിയോട് കൂടെ ദിക്റ് ചൊല്ലി കിടന്നുറങ്ങുകയും എന്നിട്ട് രാത്രി ഉണർന്ന് അല്ലാഹുവിനോട് ഐഹികമോ പാരത്രികമോ ആയ വല്ല നന്മയെയും ചോദിക്കുകയും ചെയ്യുന്ന മുസ്ലിമിന് അല്ലാഹു അത് നൽകുക തന്നെ ചെയ്യും." (ദ,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=179 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 391, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ مِنَ اللَّيْلِ فَقَضَى حَاجَتَهُ، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ ثُمَّ نَامَ. (ق,د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) രാത്രി എഴുന്നേൽക്കുകയും ആവശ്യ നിർവ്വഹണത്തിനു ശേഷം മുഖവും കൈകളും കഴുകി ഉറങ്ങുകയും ചെയ്തു. (ബു,മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=179 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 392, 'عَنْ أَبِي قِلَابَةَ عَنْ بَعْضِ آلِ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: كَانَ فِرَاشُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَحْوًا مِمَّا يُوضَعُ الْإِنْسَانُ فِي قَبْرِهِ، وَكَانَ الْمَسْجِدُ عِنْدَ رَأْسِهِ. (د)', 'ഉമ്മുസലമ(റ)യുടെ കുടുംബത്തിലെ ഒരാളിൽ നിന്ന് അബൂഖിലാബ്(റ): ഒരു മനുഷ്യനെ ഖബ്റിൽ കിടത്തുന്നത് പോലെയായിരുന്നു നബി(സ)യുടെ വിരിപ്പ്. പള്ളി നബി(സ)യുടെ തലഭാഗത്തായിരുന്നു. (ദ)', 'أَبِي قِلَابَةَ عَنْ بَعْضِ آلِ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=180 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 393, 'عَنْ حَفْصَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ أَنْ يَرْقُدَ وَضَعَ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ، ثُمَّ يَقُولُ: "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ" ثَلَاثَ مِرَارٍ. (د,ن)', 'നബി(സ)യുടെ പത്നി ഹഫ്സ(റ): ഉറങ്ങാനുദ്ധേശിച്ചാൽ റസൂൽ(സ) തന്റെ വലതു കൈ കവിളിനു താഴെ വെക്കുകയും ശേഷം ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം ചൊല്ലുകയും ചെയ്യുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ അടിമകളെ പുനർജീവിപ്പിക്കുന്ന ദിവസം നിന്റെ ശിക്ഷയിൽ നിന്നെന്നെ സംരക്ഷിക്കണേ." (ദ,ന)', 'حَفْصَةَ', 'നബി(സ)യുടെ പത്നി ഹഫ്സ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 394, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَيْتَ مَضْجَعَكَ فَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الْأَيْمَنِ، وَقُلِ: اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَهْبَةً وَرَغْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ". قَالَ: "فَإِنْ مِتَّ مِتَّ عَلَى الْفِطْرَةِ. وَاجْعَلْهُنَّ آخِرَ مَا تَقُولُ". قَالَ الْبَرَاءُ: فَقُلْتُ أَسْتَذْكِرُهُنَّ، فَقُلْتُ: وَبِرَسُولِكَ الَّذِي أَرْسَلْتَ، قَالَ: "لَا، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=394), 1, 'وَفِي رِوَايَةٍ: "إِذَا أَوَيْتَ إِلَى فِرَاشِكَ وَأَنْتَ طَاهِرٌ فَتَوَسَّدْ يَمِينَكَ" ثُمَّ ذَكَرَ نَحْوَهُ.', 'മറ്റൊരു നിവേദനം: "നീ ശുദ്ധവാനായി നിന്റെ കിടപ്പറയിലേക്ക് ചെന്നാൽ നിന്റെ വലതുഭാഗം ചേർന്നു കിടക്കുക". ശേഷം മുമ്പ് പറഞ്ഞതു പോലെ പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=394), 2, 'وَفِي رِوَايَةٍ: "إِذَا أَتَيْتَ فِرَاشَكَ طَاهِرًا". (ق,د,ت)', 'മറ്റൊരു നിവേദനം: "നീ ശുദ്ധിയുള്ളവനായി നിന്റെ കിടപ്പറയിൽ വന്നാൽ." (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 395, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا نَامَ قَالَ: "اللَّهُمَّ بِاسْمِكَ أَحْيَا وَأَمُوتُ". وَإِذَا اسْتَيْقَظَ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ". (خ,د,ت,جه)', 'ഹുദൈഫ(റ): നബി(സ) ഉറങ്ങാൻ കിടന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ നാമത്തിൽ ഞാൻ ജീവിക്കുകയും മരിക്കുകുയം ചെയ്യുന്നു." ഉണർന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "നമ്മെ മരിപ്പിച്ച ശേഷം ജീവിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും, അവനിലേക്കാണ് പുനർജന്മവും." (ബു,ദ,തു,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 500, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 396, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِهِ، لِأَنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ، ثُمَّ لِيَضْطَجِعْ عَلَى شِقِّهِ الْأَيْمَنِ، ثُمَّ لِيَقُلْ: بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ". (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും തന്റെ കിടപ്പറ പ്രാപിച്ചാൽ തന്റെ തുണിക്കോന്തലകൊണ്ട് അവിടം തട്ടിക്കൊള്ളട്ടെ, കാരണം താൻ പോയ ശേഷം അവിടെയെന്തുണ്ടായി എന്ന് അവനറിയില്ല. ശേഷം തന്റെ വലതു ഭാഗത്തേക്ക് തിരിഞ്ഞ് കിടന്ന് കൊണ്ട് അവൻ ഇപ്രകാരം പറഞ്ഞു കൊള്ളട്ടെ: ''എന്റെ നാഥാ, നിന്റെ നാമത്തിൽ ഞാൻ എന്റെ ഭാഗത്തെ (ശരീരത്തെ) കിടത്തി, നിന്നെക്കൊണ്ട് തന്നെ ഞാനത് ഉയർത്തുകയും ചെയ്യും. എന്റെ ആത്മാവിനെ നീ പിടിച്ചാൽ നീ അതിനോട് കരുണ ചെയ്യുക. നീ അതിനെ വിട്ടയക്കുന്നെങ്കിൽ നിന്റെ സജ്ജനങ്ങളെ സംരക്ഷിക്കും വിധം നീയതിനെ സംരക്ഷിക്കുക." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 397, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَّهُ كَانَ يَقُولُ إِذَا أَوَى إِلَى فِرَاشِهِ: "اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، مُنَزِّلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنَ الْفَقْرِ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) തന്റെ കിടപ്പറയിലേക്ക് ചെന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "ആകാശഭുമികളുടെയും സർവ്വ വസ്തുക്കളുടെയും രക്ഷിതാവും, വിത്തുകളെയും ധാന്യങ്ങളെയും പൊട്ടി മുളപ്പിച്ചവനും തൗറാത്തിനെയും ഇഞ്ചീലിനെയും ഖുർആനിനെയും ഇറക്കിയവനുമായ അല്ലാഹുവേ, നിന്റെ നിയന്ത്രണത്തിലുള്ള തിന്മചെയ്യുന്ന സർവ്വ വസ്തുക്കളുടെയും തിന്മയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. നീയാണ് ആദ്യം, നിനക്കു മുന്നെയൊന്നുമില്ല. നീയാണ് അന്ത്യം നിനക്കുശേഷം ഒന്നുമില്ല, നീയാണ് പ്രത്യക്ഷൻ, നിന്റെ മുകളിൽ ഒന്നുമില്ല, നീയാണ് പരോക്ഷൻ, നിന്റെ അടിയിൽ ഒന്നുമില്ല. നീ എന്റെ കടം വീട്ടുകയും, ദാരിദ്രമകറ്റുകയും ചെയ്യേണമേ." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 398, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يَقُولُ عِنْدَ مَضْجَعِهِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِوَجْهِكَ الْكَرِيمِ، وَكَلِمَاتِكَ التَّامَّةِ، مِنْ شَرِّ مَا أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ تَكْشِفُ الْمَغْرَمَ وَالْمَأْثَمَ، اللَّهُمَّ لَا يُهْزَمُ جُنْدُكَ، وَلَا يُخْلَفُ وَعْدُكَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ، سُبْحَانَكَ وَبِحَمْدِكَ". (د)', 'അലി(റ): ഉറങ്ങാൻ കിടക്കുമ്പോൾ റസൂൽ(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ തിരുമുഖം കൊണ്ടും പരിപൂർണ്ണ വചനങ്ങളെക്കൊണ്ടും, നിന്റെ നിയന്ത്രണത്തിലായ മുഴുവൻ തിന്മകളിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, കടക്കാരന്റെയും പാപിയുടെയും ബുദ്ധിമുട്ടകറ്റുന്നവൻ നീയാണ്. അല്ലാഹുവേ, നിന്റെ സൈന്യം പരാജയപ്പെടുകയില്ല, നിന്റെ കരാർ ലംഘിക്കപ്പെടുകയില്ല, ഐശ്വര്യമുള്ളവന് നിന്റെയടുത്ത് തന്റെ ഐശ്വര്യം ഉപകാരപ്പെടുകയില്ല. നിന്നെ സ്തുതിക്കുന്നതോടൊപ്പം ഞാൻ നിന്റെ പരിശുദ്ധിയെ വാഴ്ത്തുന്നു." (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 399, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ". (م,د,ت)', 'അനസ്(റ): റസൂൽ(സ) തന്റെ കിടപ്പറയിലേക്ക് വന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു. "ഞങ്ങൾക്ക് ഭക്ഷണവും പാനീയവും നൽകുകയും മതിയാക്കിത്തരികയും അഭയം നൽകുകയും ചെയ്ത അല്ലാഹുവിന് സ്തുതി. മതിയാക്കിത്തരുന്നവനും അഭയം നൽകുന്നവനും ഇല്ലാത്ത എത്ര എത്ര ആളുകളുണ്ട്." (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 501, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 400, 'عَنْ أَبِي الْأَزْهَرِ الْأَنْمَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَخَذَ مَضْجَعَهُ مِنَ اللَّيْلِ قَالَ: "بِسْمِ اللَّهِ وَضَعْتُ جَنْبِي، اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، وَأَخْسِئْ شَيْطَانِي، وَفُكَّ رِهَانِي، وَاجْعَلْنِي فِي النَّدِيِّ الْأَعْلَى". (د)', 'അബുൽ അസ്ഹറുൽ അൻമാരീ(റ): റസൂൽ(സ) രാത്രി ഉറങ്ങാൻ കിടക്കുമ്പോൾ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ ഞാനെന്റെ ശരീരത്തെ കിടത്തുന്നു. അല്ലാഹുവേ, നീ എന്റെ പാപം പൊറുക്കണേ, എന്റെ പിശാചിനെ അകറ്റണേ, സർവ്വ ബാധ്യതകളിൽ നിന്നും എന്നെ രക്ഷിക്കണേ, ഏറ്റവും ഉയർന്ന സംഘത്തിൽ എന്നെ നീ ചേർക്കണേ." (ദ)', 'أَبِي الْأَزْهَرِ الْأَنْمَارِيِّ', 'അബുൽ അസ്ഹറുൽ അൻമാരീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 401, 'عَنْ نَوْفَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "اقْرَأْ {قُلْ يَا أَيُّهَا الْكَافِرُونَ} ثُمَّ نَمْ عَلَى خَاتِمَتِهَا، فَإِنَّهَا بَرَاءَةٌ مِنَ الشِّرْكِ". (د,ت,ن)', 'നൗഫൽ(റ): നബി(സ) അവരോട് പറഞ്ഞു: "നീ കാഫിറൂൻ സൂറത്ത് ഓതുക, അതിന്റെ അന്ത്യത്തിൽ നീ ഉറങ്ങുകയും ചെയ്യുക. നിശ്ചയമത് ശിർക് (ബഹുദൈവാരാധന)യിൽ നിന്നുള്ള മോചനമാണ്." (ദ,തു,ന)', 'نَوْفَلٍ', 'നൗഫൽ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 402, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ جَمَعَ كَفَّيْهِ، ثُمَّ نَفَثَ فِيهِمَا وَقَرَأَ فِيهِمَا: {قُلْ هُوَ اللَّهُ أَحَدٌ} وَ {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ: يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ. (ق,د,ت,ن)', 'ആഇശ(റ): നബി(സ) ദിവസവും കിടപ്പറയിലേക്ക് വന്നാൽ തന്റെ ഇരുകൈകളും ഒരുമിച്ച് പിടിക്കുകയും അവയിൽ ഊതുകയും അവയിൽ ഇഖ്ലാസ്, മുഅവ്വിദതൈനി സൂറത്തുകൾ ഓതുകയും ചെയ്യും. ശേഷം അവകൊണ്ട് തന്റെ ശരീരം കഴിയും വിധം തടവും. ആദ്യം തലയും മുഖവും ശരീരത്തിന്റെ മുൻഭാഗവുമാണ് തടവുക. അപ്രകാരം മൂന്ന് പ്രാവശ്യം ചെയ്യും. (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 403, 'عَنْ عِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ الْمُسَبِّحَاتِ قَبْلَ أَنْ يَرْقُدَ، وَقَالَ: "إِنَّ فِيهِنَّ آيَةً أَفْضَلُ مِنْ أَلْفِ آيَةٍ". (د,ت,ن)', 'ഇർബാളുബ്നു സാരിയ(റ): റസൂൽ(സ) ഉറങ്ങുന്നതിന് മുമ്പ് മുസബ്ബിഹാത് സൂറത്തുകളെ (സബ്ബഹ, യുസബ്ബിഹു എന്നീ വാക്കുകൾ കൊണ്ട് തുടങ്ങുന്ന സൂറത്തുകൾ) ഓതാറുണ്ടായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ആയിരം സൂക്തങ്ങളേക്കാൾ ശ്രേഷ്ഠമായ സൂക്തമുണ്ട് അവയിൽ." (ദ,തു,ന)', 'عِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 404, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ إِذَا أَخَذَ مَضْجَعَهُ: "الْحَمْدُ لِلَّهِ الَّذِي كَفَانِي وَآوَانِي، وَأَطْعَمَنِي وَسَقَانِي، وَالَّذِي مَنَّ عَلَيَّ فَأَفْضَلَ، وَالَّذِي أَعْطَانِي فَأَجْزَلَ، الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، اللَّهُمَّ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ وَإِلَهَ كُلِّ شَيْءٍ، أَعُوذُ بِكَ مِنَ النَّارِ". (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) തന്റെ കിടപ്പറയിലേക്ക് ചെന്നാൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "എനിക്ക് അഭയം നൽകുകയും മതിയാക്കിത്തരികയും ഭക്ഷണം നൽകുകയും പാനീയം നൽകുകയും ചെയ്ത, എനിക്ക് ഒരുപാട് അനുഗ്രഹങ്ങൾ ചെയ്തുതരികയും കോരിച്ചോരി നൽകുകയും ചെയ്ത, അല്ലാഹുവിനാണ് സ്തുതി. സർവ്വ അവസ്ഥകളിലും അല്ലാഹുവിനാണ് സ്തുതി. സർവ്വ വസ്തുക്കളുടെയും ആരാധ്യനും ഉടമസ്ഥനും രക്ഷിതാവുമായ അല്ലാഹുവേ നരകത്തിൽ നിന്നു ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 502, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 405, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اضْطَجَعَ مَضْجَعًا لَمْ يَذْكُرِ اللَّهَ تَعَالَى فِيهِ إِلَّا كَانَ عَلَيْهِ تِرَةً يَوْمَ الْقِيَامَةِ، وَمَنْ قَعَدَ مَقْعَدًا لَمْ يَذْكُرِ اللَّهَ عَزَّ وَجَلَّ فِيهِ إِلَّا كَانَ عَلَيْهِ تِرَةً يَوْمَ الْقِيَامَةِ". (د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ സ്മരിക്കപ്പെടാത്ത ഒരു കിടപ്പറയിൽ ആരെങ്കിൽ കിടന്നുറങ്ങിയാൽ അന്ത്യനാളിൽ അവനതു ദുഃഖ ഹേതുവായി മാറുന്നതാണ്. അല്ലാഹുവിനെ സ്മരിക്കപ്പെടാത്ത ഒരു ഇരിപ്പിടത്തിൽ ആരെങ്കിൽ ഇരുന്നാൽ അന്ത്യനാളിൽ അവനതു ദുഃഖഹേതുവായി മാറുന്നതാണ്." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 406, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: شَكَتْ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا تَلْقَى فِي يَدِهَا مِنَ الرَّحَى، فَأُتِيَ بِسَبْيٍ، فَأَتَتْهُ تَسْأَلُهُ فَلَمْ تَرَهُ، فَأَخْبَرَتْ بِذَلِكَ عَائِشَةَ، فَلَمَّا جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ، فَأَتَانَا وَقَدْ أَخَذْنَا مَضَاجِعَنَا، فَذَهَبْنَا لِنَقُومَ، فَقَالَ: "عَلَى مَكَانِكُمَا". فَجَاءَ فَقَعَدَ بَيْنَنَا حَتَّى وَجَدْتُ بَرْدَ قَدَمَيْهِ عَلَى صَدْرِي، فَقَالَ: "أَلَا أَدُلُّكُمَا عَلَى خَيْرٍ مِمَّا سَأَلْتُمَا؟ إِذَا أَخَذْتُمَا مَضَاجِعَكُمَا فَسَبِّحَا ثَلَاثًا وَثَلَاثِينَ، وَاحْمَدَا ثَلَاثًا وَثَلَاثِينَ، وَكَبِّرَا أَرْبَعًا وَثَلَاثِينَ، فَهُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ". (ق,د)', 'അലി(റ): ആസുകല്ല് ആട്ടിയതു കാരണത്താൽ താനനുഭവിച്ച ബുദ്ധിമുട്ടിനെക്കുറിച്ച് ഫാത്വിമ(റ) നബി(സ)യോട് പരാതിപ്പെട്ടു. അങ്ങനെ നബി(സ)യുടെ അടുത്ത് ഒരു ബന്ധിയെ കൊണ്ട് വരപ്പെട്ടപ്പോൾ ഫാത്വിമ(റ) അതിനെ ആവശ്യപ്പെടാൻ വേണ്ടി നബി(സ)യുടെ അടുത്ത് പോയി. പക്ഷെ മഹതി നബി(സ)യെ കണ്ടില്ല. അപ്പോൾ അവർ വിവരം ആഇശ(റ)യോട് പറഞ്ഞു കൊടുത്തു. നബി(സ) വന്നപ്പോൾ ആഇശ(റ) വിവരം നബി(സ)യോട് പറഞ്ഞു. അങ്ങനെ ഞങ്ങൾ കിടപ്പറയിലേക്ക് പോയ സമയത്ത് നബി(സ) ഞങ്ങളുടെയടുത്ത് വന്നു. ഞങ്ങൾ എഴുന്നേൽക്കാൻ തയ്യാറെടുത്തപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളവിടെ കിടക്കുക." അങ്ങനെ നബി(സ) വന്ന് ഞങ്ങളുടെ ഇടയിലിരുന്നു. നബി(സ)യുടെ കാലിലെ തണുപ്പ് എന്റെ നെഞ്ചിൽ ഞാൻ അനുഭവിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ആവശ്യപ്പെട്ട കാര്യത്തേക്കാൾ ഉത്തമമായ ഒരു കാര്യം ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ? നിങ്ങൾ കിടപ്പറയിലേക്ക് ചെന്നാൽ മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തസ്ബീഹ് ചൊല്ലുക, മുപ്പത്തിമൂന്ന് പ്രാവശ്യം ഹംദ് ചൊല്ലുക, മുപ്പത്തിനാല് പ്രാവശ്യം തക്ബീർ ചൊല്ലുക. ഇത് ഒരു സേവകനേക്കാൾ നിങ്ങൾക്കുത്തമമാണ്." (ബു,മു,ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 407, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ لِابْنِ أَعْبُدَ: أَلَا أُحَدِّثُكَ عَنِّي وَعَنْ فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَتْ أَحَبَّ أَهْلِهِ إِلَيْهِ، وَكَانَتْ عِنْدِي، فَجَرَّتْ بِالرَّحَى حَتَّى أَثَّرَتْ بِيَدِهَا، وَاسْتَقَتْ بِالْقِرْبَةِ حَتَّى أَثَّرَتْ فِي نَحْرِهَا، وَقَمَّتِ الْبَيْتَ حَتَّى اغْبَرَّتْ ثِيَابُهَا، وَأَوْقَدَتِ الْقِدْرَ حَتَّى دَكِنَتْ ثِيَابُهَا، وَأَصَابَهَا مِنْ ذَلِكَ ضُرٌّ، فَسَمِعْنَا أَنَّ رَقِيقًا أُتِيَ بِهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: لَوْ أَتَيْتِ أَبَاكِ فَسَأَلْتِيهِ خَادِمًا يَكْفِيكِ. فَأَتَتْهُ، فَوَجَدَتْ عِنْدَهُ حُدَّاثًا، فَاسْتَحْيَتْ فَرَجَعَتْ، فَغَدَا عَلَيْنَا وَنَحْنُ فِي لِفَاعِنَا، فَجَلَسَ عِنْدَ رَأْسِهَا، فَأَدْخَلَتْ رَأْسَهَا فِي اللِّفَاعِ حَيَاءً مِنْ أَبِيهَا، فَقَالَ: "مَا كَانَ حَاجَتُكِ أَمْسِ إِلَى آلِ مُحَمَّدٍ". فَسَكَتَتْ، مَرَّتَيْنِ، فَقُلْتُ: أَنَا وَاللَّهِ أُحَدِّثُكَ يَا رَسُولَ اللَّهِ، إِنَّ هَذِهِ جَرَّتْ عِنْدِي بِالرَّحَى حَتَّى أَثَّرَتْ فِي يَدِهَا، وَاسْتَقَتْ بِالْقِرْبَةِ حَتَّى أَثَّرَتْ فِي نَحْرِهَا، وَكَسَحَتِ الْبَيْتَ حَتَّى اغْبَرَّتْ ثِيَابُهَا، وَأَوْقَدَتِ الْقِدْرَ حَتَّى دَكِنَتْ ثِيَابُهَا، وَبَلَغَنَا أَنَّهُ قَدْ أَتَاكَ رَقِيقٌ، أَوْ خَدَمٌ، فَقُلْتُ لَهَا: سَلِيهِ خَادِمًا، ... فَذَكَرَ مَعْنَى الْحَدِيثِ. (د)', 'അലി(റ): അലി(റ) ഇബ്നുഅഅ്ബുദിനോട് പറഞ്ഞു: എന്നെക്കുറിച്ചും റസൂൽ(സ)യുടെ പുത്രിയായ ഫാത്വിമ(റ)യെക്കുറിച്ചും ഞാൻ നിനക്ക് പറഞ്ഞു തരട്ടെയോ. തന്റെ കുടുംബത്തിൽ നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടം ഫാത്വിമ(റ)യോടായിരുന്നു, മഹതി എന്റെ ഭാര്യയായിരുന്നു. ആസുകല്ല് ആട്ടി അവരുടെ കയ്യിൽ അടയാളം വീണിരുന്നു. തോൽപാത്രത്തിൽ വെള്ളം കൊണ്ടുവന്ന് പിരടിയിലും അടയാളം വീണിരുന്നു. വീട് അടിച്ചുവാരി വസ്ത്രം പൊടി പുരണ്ടിരുന്നു. അടുപ്പ് കത്തിച്ച് തന്റെ വസ്ത്രം ഇരുണ്ട് പോയിരുന്നു. ഇവ കാരണത്താലെല്ലാം മഹതി ബുദ്ധിമുട്ട് അനുഭവിച്ചിരുന്നു. അങ്ങനെയിരിക്കെ നബി(സ)യുടെ അടുത്ത് കുറേ അടിമകൾ എത്തിയിട്ടുണ്ടെന്ന് ഞങ്ങൾ കേട്ടു. ഞാൻ മഹതിയോട് പറഞ്ഞു: നീ നിന്റെ പിതാവിന്റെയടുത്ത് പോയി ഒരു സേവകനെ ആവശ്യപ്പെട്ടാൽ നിനക്കത് മതിയാകും. അങ്ങനെ മഹതി നബി(സ)യുടെ അടുത്ത് പോയി. അവിടെ മഹതി കുറേയാളുകൾ സംസാരിക്കുന്നത് കാണുകയും ലജ്ജ തോന്നി അവിടെ നിന്ന് മടങ്ങിവരികയും ചെയ്തു. അങ്ങനെ ഞങ്ങൾ പുതപ്പിലായിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു, എന്നിട്ട് ഫാത്വിമ(റ)യുടെ തലയുടെ ഭാഗത്തിരുന്നു. വാപ്പയെ കണ്ട് ലജ്ജിച്ച മഹതി തന്റെ തല പുതപ്പിലേക്ക് പ്രവേശിപ്പിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിൽ വരാൻ ഇന്നലെ നിനക്ക് എന്ത് ആവശ്യമാണുണ്ടായിരുന്നത്." അപ്പോൾ മഹതി മൗനമവലംബിച്ചു. ഇപ്രകാരം രണ്ടു പ്രാവശ്യം ചോദിച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, ഞാൻ പറഞ്ഞു തരാം റസുലേ, ഫാത്വിമ(റ) എന്റെയടുത്ത് ആസുകല്ല് ആട്ടി അവരുടെ കയ്യിൽ അടയാളം വീണിരിക്കുന്നു, തോൽ പാത്രത്തിൽ വെള്ളം കൊണ്ടുവന്ന് പിരടിയിലും അടയാളം വീണിരിക്കുന്നു, വീട് അടിച്ചുവാരി തന്റെ വസ്ത്രം പൊടിപുരണ്ടിരിക്കുന്നു, അടുപ്പ് കത്തിച്ച് തന്റെ വസ്ത്രം കറുത്ത് പോയിരിക്കുന്നു. അങ്ങയുടെ അടുത്ത് കുറേ അടിമകൾ അല്ലെങ്കിൽ സേവകൻമാർ എത്തിയിട്ടുണ്ടെന്ന് ഞങ്ങൾക്ക് വിവരം കിട്ടി. അപ്പോൾ ഞാൻ മഹതിയോട് പറഞ്ഞു: നീ നബി(സ)യോട് ഒരു സേവകനെ ചോദിക്കുക........... ശേഷം അവർ ഹദീസിന്റെ ആശയം പറഞ്ഞു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 503, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 408, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِهَذَا الْخَبَرِ، قَالَ فِيهِ عَلِيٌّ: فَمَا تَرَكْتُهُنَّ مُنْذُ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا لَيْلَةَ صِفِّينَ، فَإِنِّي ذَكَرْتُهَا مِنْ آخِرِ اللَّيْلِ فَقُلْتُهَا. (د,ن)', 'അലി(റ): നബി(സ)യിൽ നിന്ന് ഉദ്ധരിച്ച ഈ ഹദീസിൽ അലി(റ) പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് അത് കേട്ടതു മുതൽ സ്വഫ്ഫീൻ യുദ്ധത്തിന്റെ രാത്രിയിലല്ലാതെ ഞാനവയെ ഉപേക്ഷിച്ചിട്ടില്ല. അന്ന് രാത്രിയുടെ അവസാന സമയം ഞാനത് ഓർമ്മിക്കുകയും അത് ചൊല്ലുകയും ചെയ്തു. (ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 409, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَصْلَتَانِ -أَوْ خَلَّتَانِ- لَا يُحَافِظُ عَلَيْهِمَا عَبْدٌ مُسْلِمٌ إِلَّا دَخَلَ الْجَنَّةَ، هُمَا يَسِيرٌ، وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ: يُسَبِّحُ فِي دُبُرِ كُلِّ صَلَاةٍ عَشْرًا، وَيَحْمَدُ عَشْرًا، وَيُكَبِّرُ عَشْرًا، فَذَلِكَ خَمْسُونَ وَمِائَةٌ بِاللِّسَانِ، وَأَلْفٌ وَخَمْسُ مِائَةٍ فِي الْمِيزَانِ. وَيُكَبِّرُ أَرْبَعًا وَثَلَاثِينَ إِذَا أَخَذَ مَضْجَعَهُ، وَيَحْمَدُ ثَلَاثًا وَثَلَاثِينَ، وَيُسَبِّحُ ثَلَاثًا وَثَلَاثِينَ، فَذَلِكَ مِائَةٌ بِاللِّسَانِ، وَأَلْفٌ فِي الْمِيزَانِ". فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُهَا بِيَدِهِ، قَالُوا: يَا رَسُولَ اللَّهِ، كَيْفَ هُمَا يَسِيرٌ، وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ؟ قَالَ: "يَأْتِي أَحَدَكُمْ -يَعْنِي الشَّيْطَانَ- فِي مَنَامِهِ فَيُنَوِّمُهُ قَبْلَ أَنْ يَقُولَهُ، وَيَأْتِيهِ فِي صَلَاتِهِ فَيُذَكِّرُهُ حَاجَةً قَبْلَ أَنْ يَقُولَهَا". (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് കാര്യങ്ങൾ കൃത്യമായി സൂക്ഷിക്കുന്ന മുസ്ലിമായ ഒരു അടിമയും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാതിരിക്കയില്ല. ആ രണ്ടു കാര്യങ്ങൾ വളരെ ലളിതമാകുന്നു. അത് പ്രവർത്തിക്കുന്നവർ വളരെ വിരളവും. എല്ലാ നിസ്കാരത്തിന് ശേഷവും പത്തു പ്രാവശ്യം തസ്ബീഹ് ചൊല്ലുക, പത്തു പ്രാവശ്യം ഹംദ് ചൊല്ലുക, പത്തുപ്രാവശ്യം തക്ബീർ ചൊല്ലുക. അത് മൊത്തം നാവുകൊണ്ടുള്ള നൂറ്റിഅമ്പത് ദിക്റുകളാണ്, തുലാസിൽ (നന്മതിന്മകൾ തൂക്കുന്ന മീസാനിൽ) ആയിരത്തി അഞ്ഞൂറും. കിടപ്പറയിലേക്ക് ചെന്നാൽ മുപ്പത്തിനാല് പ്രാവശ്യം തക്ബീർ ചൊല്ലുക, മുപ്പത്തി മൂന്ന് പ്രാവശ്യം ഹംദ് ചൊല്ലുക, മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തസ്ബീഹ് ചൊല്ലുക. അത് മൊത്തം നാവ് കൊണ്ടുള്ള നൂറ് ദിക്റുകളും മീസാനിൽ ആയിരവുമായിരിക്കും." റസൂൽ(സ) അത് തന്റെ കൈകൊണ്ട് എണ്ണുന്നത് ഞാൻ കണ്ടു. അവർ ചോദിച്ചു: റസൂലേ, രണ്ടും ലളിതവും, അവ പ്രവർത്തിക്കുന്നവർ വളരെ വിരളവുമായതെങ്ങനെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരുത്തൻ ഉറങ്ങുന്ന സമയത്ത് പിശാച് വരികയും അത് ചൊല്ലുന്നതിനു മുമ്പ് അവനെ ഉറക്കിക്കളയുകയും ചെയ്യും. നിസ്കാരത്തിൽ പിശാച് വന്ന് ഇവ ചൊല്ലും മുമ്പ് വല്ല ആവശ്യത്തിനും പോകണമെന്ന് അവന് തോന്നിക്കും." (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 504, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 410, 'عَنْ أُمِّ الْحَكَمِ أَوْ ضُبَاعَةَ ابْنَتَيِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ -رَضِيَ اللهُ عَنْهُم- أَنَّهَا قَالَتْ: أَصَابَ رَسُولُ اللَّهِ سَبْيًا، فَذَهَبْتُ أَنَا وَأُخْتِي فَاطِمَةُ بِنْتُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشَكَوْنَا إِلَيْهِ مَا نَحْنُ فِيهِ، وَسَأَلْنَاهُ أَنْ يَأْمُرَ لَنَا بِشَيْءٍ مِنَ السَّبْيِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَبَقَكُنَّ يَتَامَى بَدْرٍ". ثُمَّ ذَكَرَ قِصَّةَ التَّسْبِيحِ، قَالَ: "عَلَى أَثَرِ كُلِّ صَلَاةٍ". لَمْ يَذْكُرِ النَّوْمَ. (د)', 'സുബൈറുബ്നു അബ്ദുൽ മുത്വലിബ്(റ)ന്റെ മക്കളായ ളുബാഅ(റ) അല്ലെങ്കിൽ ഉമ്മുൽ ഹകം(റ): റസൂൽ(സ)ക്ക് കുറേ ബന്ധികളെ ലഭിച്ചു. അപ്പോൾ ഞാനും എന്റെ സഹോദരിയായ നബി(സ)യുടെ മകൾ ഫാത്വിമ(റ)യും നബി(സ)യുടെ അടുത്ത് ചെന്നു. ഞങ്ങൾ അനുഭവിക്കുന്ന ബുദ്ധമുട്ടുകൾ അവടിത്തോടവതരിപ്പിച്ചു. ബന്ധികളിൽ നിന്ന് ഞങ്ങൾക്കും വീതിച്ചു തരാൻ നബി(സ)യോട് ആവശ്യപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ബദ്റിലെ യതീമുകൾ (യുദ്ധത്തിൽ രക്സാക്ഷികളായവരുടെ മക്കൾ) നിങ്ങളെ മുൻകടന്നിരിക്കുന്നു." ശേഷം നിവേദകൻ തസ്ബീഹിന്റെ സംഭവം പറഞ്ഞു: ഈ ഹദീസിൽ നബി(സ) "എല്ലാ നിസ്കാരത്തിന്റെ ശേഷവും" എന്ന് പറയുകയും ഉറക്കിന്റെ കാര്യം ഒഴിവാക്കുകയും ചെയ്തു. (ദ)', 'أُمِّ الْحَكَمِ أَوْ ضُبَاعَةَ ابْنَتَيِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ -', 'സുബൈറുബ്നു അബ്ദുൽ മുത്വലിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 411, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَارَّ مِنَ اللَّيْلِ، فَقَالَ حِينَ يَسْتَيْقِظُ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. ثُمَّ دَعَا: رَبِّ اغْفِرْ لِي -أَوْ قَالَ: دَعَا- اسْتُجِيبَ لَهُ، فَإِنْ قَامَ فَتَوَضَّأَ ثُمَّ صَلَّى قُبِلَتْ صَلَاتُهُ". (خ,د,ت,ن,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും രാത്രി ഉണരുമ്പോൾ ''അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവനു പങ്കുകാരനില്ല, അവന്നാണ് അധികാരവും സ്തുതിയും, അവൻ സർവ്വത്തിനും കഴിവുള്ളവനാണ്, അല്ലാഹു ഏറ്റവും പരിശുദ്ധനാണ്, അവന്നാണ് സർവ്വ സ്തുതിയും, അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവനാണ് ഏറ്റവും വലിയവൻ, അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവുമില്ല'' എന്ന് ചൊല്ലുകയും ശേഷം ''രക്ഷിതാവേ, എനിക്ക് പൊറുത്ത് തരണേ എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്താൽ അവന് ഉത്തരം നൽകപ്പെടുന്നതാണ്. അവൻ എഴുന്നേറ്റ് വുളൂ ചെയ്യുകയും നമസ്കരിക്കുകയും ചെയ്താൽ അവന്റെ നിസ്കാരം സ്വീകരിക്കപ്പെടും." (ബു,ദ,തു,ന,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 505, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=182 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 412, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اسْتَيْقَظَ مِنَ اللَّيْلِ قَالَ: "لَا إِلَهَ إِلَّا أَنْتَ، سُبْحَانَكَ، اللَّهُمَّ أَسْتَغْفِرُكَ لِذَنْبِي وَأَسْأَلُكَ رَحْمَتَكَ، اللَّهُمَّ زِدْنِي عِلْمًا، وَلَا تُزِغْ قَلْبِي بَعْدَ إِذْ هَدَيْتَنِي، وَهَبْ لِي مِنْ لَدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ". (د)', 'ആഇശ(റ): റസൂൽ(സ) രാത്രി ഉണർന്നാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "നീയല്ലാതെ ആരാധ്യനില്ല, നിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവേ, എന്റെ പാപത്തിന് ഞാൻ പൊറുക്കലിനെ തേടുന്നു. നിന്റെ കരുണ ചോദിക്കുന്നു. അല്ലാഹുവേ, എനിക്ക് നീ അറിവ് അധികരിപ്പിച്ചു തരണേ, സന്മാർഗ്ഗത്തിലാക്കിയ ശേഷം എന്റെ ഹൃദയത്തെ നീ തെറ്റിക്കരുത്. എനിക്ക് നിന്റെ ഭാഗത്തു നിന്നുള്ള അനുഗ്രഹം നൽകണേ, നിശ്ചയം നീ അധികമായി നൽകുന്നവനാണ്." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=182 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 413, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا بَكْرٍ الصِّدِّيقَ رَضِيَ اللهُ عَنْهُ قَالَ: يَا رَسُولَ اللَّهِ، مُرْنِي بِكَلِمَاتٍ أَقُولُهُنَّ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ، قَالَ: "قُلِ اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ". قَالَ: "قُلْهَا إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ، وَإِذَا أَخَذْتَ مَضْجَعَكَ". (د,ت)', 'അബൂഹുറൈറ(റ): അബൂബക്കർ സിദ്ദീഖ്(റ) പറഞ്ഞു: റസൂലേ, നേരം പുലരുമ്പോഴും വൈകുന്നേര സമയവും എനിക്ക് ചൊല്ലാൻ ചില വചനങ്ങൾ പറഞ്ഞുതരിക. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇപ്രകാരം ചൊല്ലുക: ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവും ദൃശ്യാദൃശ്യ കാര്യങ്ങളെ അറിയുന്നവനും സർവ്വ വസ്തുക്കളുടെയും ഉടമയും രക്ഷിതാവുമായ അല്ലാഹുവേ, നീയല്ലാതെ ഒരു ആരാധ്യനില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. എന്റെ ശരീരത്തിന്റെ തിന്മയിൽ നിന്നും പിശാചിന്റെ തിന്മയിൽ നിന്നും പിശാചിന്റെ ശിർകിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലർന്നാലും, വൈകുന്നേരവും കിടപ്പറയിലേക്ക് ചെന്നാലും നിങ്ങൾ ഇതു ചൊല്ലുക." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 414, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ إِذَا أَصْبَحَ: "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ". وَإِذَا أَمْسَى قَالَ: "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നേരം പുലരുമ്പോൾ നബി(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്നെക്കൊണ്ടാണ് ഞങ്ങൾ നേരം പുലരുന്നതും പ്രദോഷത്തിലാകുന്നതും, നിന്നെക്കൊണ്ടാണ് ഞങ്ങൾ ജീവിക്കുന്നതും മരിക്കുന്നതും, നിന്നിലേക്കാണ് മടക്കവും." പ്രദോഷമായാൽ ഇപ്രകാരവും പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്നെക്കൊണ്ടാണ് ഞങ്ങൾ പ്രദോഷത്തിലാകുന്നത്. നിന്നെക്കൊണ്ടാണ് ഞങ്ങൾ ജീവിക്കുന്നതും മരിക്കുന്നതും. നിന്നിലേക്കാണ് മടക്കവും." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 415, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ أَوْ يُمْسِي: اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ: أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ. أَعْتَقَ اللَّهُ رُبُعَهُ مِنَ النَّارِ، فَمَنْ قَالَهَا مَرَّتَيْنِ أَعْتَقَ اللَّهُ نِصْفَهُ، وَمَنْ قَالَهَا ثَلَاثًا أَعْتَقَ اللَّهُ ثَلَاثَةَ أَرْبَاعِهِ، فَإِنْ قَالَهَا أَرْبَعًا أَعْتَقَهُ اللَّهُ مِنَ النَّارِ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലരുമ്പോഴോ പ്രദോഷസമയത്തോ ആരെങ്കിലും, നിശ്ചയം നീ അല്ലാഹുവാണ് നീയല്ലാതെ ഒരു ആരാധ്യനില്ല, മുഹമ്മദ്(സ) നിന്റെ അടിമയും പ്രവാചകനുമാണ് എന്ന് നിന്നെയും നിന്റെ അർശിനെ ചുമക്കുന്നവരെയും നിന്റെ മലക്കുകളെയും നിന്റെ സർവ്വ സൃഷ്ടികളെയും സാക്ഷ്യപ്പെടുത്തിക്കൊണ്ട് അല്ലാഹുവേ ഞാൻ നേരം പുലരുന്നു, എന്ന് ഒരുത്തൻ ചൊല്ലിയാൽ അല്ലാഹു അവന്റെ നാലിലൊരു ഭാഗത്തെ നരകത്തിൽ നിന്ന് മോചിപ്പിക്കുന്നതാണ്. ആരെങ്കിലും അത് രണ്ട് പ്രാവശ്യം ചൊല്ലിയാൽ അവന്റെ പകുതി ഭാഗത്തെ അല്ലാഹു മോചിപ്പിക്കും. ആരെങ്കിലും അത് മൂന്ന് പ്രാവശ്യം ചൊല്ലിയാൽ അവന്റെ നാലിൽ മൂന്ന് ഭാഗത്തെയും അല്ലാഹു മോചിപ്പിക്കും. ആരെങ്കിലുമത് നാല് പ്രാവശ്യം ചൊല്ലിയാൽ അവനെ പൂർണ്ണമായും അല്ലാഹു നരകത്തിൽ നിന്ന് മോചിപ്പിക്കും." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 506, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 416, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ أَوْ حِينَ يُمْسِي: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ بِنِعْمَتِكَ وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. فَمَاتَ مِنْ يَوْمِهِ -أَوْ: مِنْ لَيْلَتِهِ- دَخَلَ الْجَنَّةَ". (د,جه)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നേരം പുലരുമ്പോഴോ പ്രദോഷത്തിലോ ''അല്ലാഹുവേ, നീ എന്റെ രക്ഷിതാവാണ്, നീയല്ലാതെ ഒരു ആരാധ്യനില്ല, നീ എന്നെ സൃഷ്ടിച്ചു, ഞാൻ നിന്റെ അടിമയാണ്, ഞാൻ കഴിയും വിധം നിന്നോടുള്ള കരാറും വാഗ്ദാനവും നിറവേറ്റുന്നു, ഞാൻ ചെയ്ത് കൂട്ടിയവയുടെ തിൻമകളെ തൊട്ട് ഞാൻ നിന്നോട് രക്ഷ ചോദിക്കുന്നു. ഞാൻ നിന്റെ അനുഗ്രഹത്തെ അംഗീകരിക്കുകുയം എന്റെ പാപങ്ങളെ സമ്മതിക്കുകയും ചെയ്യുന്നു, അത് കൊണ്ട് നീ എനിക്ക് പൊറുത്ത് തരണേ, നിശ്ചയം നീയല്ലാതെ ആരും പാപം പൊറുക്കുകയില്ല, എന്ന് ചൊല്ലുകയും അന്ന് പകലോ രാത്രിയോ അവൻ മരിക്കുകയും ചെയ്താൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്." (ദ,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 417, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ إِذَا أَمْسَى: "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا. رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَمِنْ سُوءِ الْكِبَرِ، أَوْ: الْكُفْرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ وَعَذَابِ الْقَبْرِ". وَإِذَا أَصْبَحَ قَالَ ذَلِكَ أَيْضًا: "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ ...". (م,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രദോഷമായാൽ നബി(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "ഞങ്ങളും അധികാരവും അല്ലാഹുവിന്റേതായിട്ട് പ്രദോഷത്തിലായി. അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല, അവൻ ഏകനാണ്, അവനു പങ്കാളിയില്ല. അധികാരവും സ്തുതിയും അല്ലാഹുവിനാണ്. അവൻ സർവ്വത്തിനും ശക്തിയുള്ളവനാണ്. രക്ഷിതാവേ, ഈ രാത്രിയിലും അതിന്റെ ശേഷവുമുള്ള നന്മകളെ ഞാൻ നിന്നോട് ചോദിക്കുകയും ഈ രാത്രിയിലും അതിന്റെ ശേഷവുമുള്ള തിന്മകളിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുകയും ചെയ്യുന്നു. രക്ഷിതാവേ, അലസതയിൽ നിന്നും വാർദ്ധക്യത്തിന്റെയും ദൈവ നിഷേധത്തിന്റെയും ബുദ്ധിമുട്ടിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. രക്ഷിതാവേ ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും നരക ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു." നേരം പുലരുമ്പോൾ "ഞങ്ങളും അധികാരവും അല്ലാഹുവിന്റേതായിട്ട് നേരം പുലർന്നു......" എന്ന് തുടങ്ങി നബി(സ) ഈ ദിക്റ് ചൊല്ലാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 507, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 418, 'عَنْ أَبِي سَلَّام مَمْطُور الْحَبَشِي رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ فِي مَسْجِدِ حِمْص فَمَرَّ بِهِ رَجُلٌ، فَقَالُوا: هَذَا خَدَمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَامَ إِلَيْهِ فَقَالَ: حَدِّثْنِي بِحَدِيثٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَتَدَاوَلْهُ بَيْنَكَ وَبَيْنَهُ الرِّجَالُ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَالَ إِذَا أَصْبَحَ وَإِذَا أَمْسَى: رَضِينَا بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ رَسُولًا، إِلَّا كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ". (د)', 'അബൂസല്ലാം മംതൂറുൽ ഹബഷീ(റ): അവർ ഹിംസിലെ പള്ളിയിലിരിക്കുമ്പോൾ അടുത്ത് കൂടെ ഒരാൾ നടന്നു പോയി. ജനങ്ങൾ അയാളോട് പറഞ്ഞു: ഇദ്ദേഹം നബി(സ)യുടെ സേവകനാണ്. അപ്പോൾ അദ്ദേഹം അബൂസല്ലാം(റ)വിനടുത്ത് ചെന്നു, എന്നിട്ട് പറഞ്ഞു: നിങ്ങൾക്കും റസൂലിനുമിടയിൽ മറ്റൊരു നിവേദകനില്ലാത്ത, നിങ്ങൾ നേരിട്ട് റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ഒരു ഹദീസ് പറഞ്ഞു തരിക. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "നേരം പുലരുമ്പോഴും പ്രദോഷമാകുമ്പോഴും ഒരാൾ ഞങ്ങൾ അല്ലാഹുവിനെ രക്ഷിതാവായും ഇസ്‌ലാമിനെ മതമായും മുഹമ്മദ് നബി(സ)യെ റസൂലായും തൃപ്തിപ്പെട്ടു എന്ന് ചൊല്ലിയാൽ അവനെ തൃപ്തിപ്പെടുത്തൽ അല്ലാഹുവിന്റെ ബാധ്യതയാണ്." (ദ)', 'أَبِي سَلَّام مَمْطُور الْحَبَشِي', 'അബൂസല്ലാം മംതൂറുൽ ഹബഷീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 419, 'عَنْ عَبْدِ اللَّهِ بْنِ غَنَّامِ الْبَيَاضِي رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ: اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ. فَقَدْ أَدَّى شُكْرَ يَوْمِهِ، وَمَنْ قَالَ: مِثْلَ ذَلِكَ حِينَ يُمْسِي فَقَدْ أَدَّى شُكْرَ لَيْلَتِهِ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഗന്നാമുൽ ബയാളി(റ): റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലരുമ്പോൾ ''അല്ലാഹുവേ എനിക്ക് ഈ പ്രഭാതത്തിൽ വല്ല അനുഗ്രഹവും ലഭിച്ചിട്ടുണ്ടെങ്കിൽ അത് നിന്നിൽ നിന്നുള്ളത് മാത്രമാണ്, നിനക്ക് പങ്കാളിയില്ല. അതിനാൽ സർവ്വസ്തുതിയും നന്ദിയും നിനക്കാണ്.'' എന്ന് ആരെങ്കിലും ചൊല്ലിയാൽ അവൻ തന്റെ ആ ദിനത്തിന്റെ നന്ദി ചെയ്തിരിക്കുന്നു. ആരെങ്കിലും വൈകുന്നേരമത് ചൊല്ലിയാൽ അവൻ തന്റെ ആ രാത്രിയുടെ നന്ദി ചെയ്തിരിക്കുന്നു." (ദ)', 'عَبْدِ اللَّهِ بْنِ غَنَّامِ الْبَيَاضِي', 'അബ്ദുല്ലാഹിബ്നു ഗന്നാമുൽ ബയാളി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 420, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ حِينَ يُمْسِي وَحِينَ يُصْبِحُ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي -وفي رواية: عَوْرَاتِي- وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي". (د)', 'ഇബ്നുഉമർ(റ): പ്രഭാതത്തിലും പ്രദോഷത്തിലും റസൂൽ(സ) "അല്ലാഹുവേ, ഇഹപരലോകങ്ങളിലുള്ള നല്ല ആരോഗ്യത്തെ ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, എന്റെ കുടുംബത്തിന്റെയും മുതലിന്റെയും ദുൻയാവിന്റെയും മതത്തിന്റെയും കാര്യത്തിൽ മാപ്പ് തരണമെന്നും ആരോഗ്യം നൽകണമെന്നും ഞാൻ നിന്നോട് ആവശ്യപ്പെടുന്നു. നീ എന്റെ മോശത്തരങ്ങളെ മറച്ചുവെക്കുകയും പേടികളെ അകറ്റുകയും ചെയ്യണേ. അല്ലാഹുവേ, എന്റെ മുൻ വശത്തുകൂടെയും, പിൻവശത്തുകൂടെയും, ഇടതുവശത്തുകൂടെയും, വലതുവശത്തുകൂടെയും, മുകൾ ഭാഗത്തുകൂടെയും നീ എനിക്ക് സംരക്ഷണം നൽകണേ. എന്റെ താഴ്ഭാഗത്തുനിന്ന് വരുന്ന പെട്ടെന്നുള്ള നാശത്തിൽ നിന്ന് ഞാൻ നിന്റെ മഹത്വത്തിൽ അഭയം പ്രാപിക്കുന്നു." എന്ന പ്രാർത്ഥനകൾ ഉപേക്ഷിക്കാറുണ്ടായിരുന്നില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=420), 1, 'وَفِي رِوَايَةٍ: عَوْرَاتِي- وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 421, 'عَنْ عَبْدِ الْحَمِيدِ مَوْلَى بَنِي هَاشِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُمَّهُ حَدَّثَتْهُ، وَكَانَتْ تَخْدُمُ بَعْضَ بَنَاتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ ابْنَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَتْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهَا فَيَقُولُ: "قُولِي حِينَ تُصْبِحِينَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، لَا قُوَّةَ إِلَّا بِاللَّهِ، مَا شَاءَ اللَّهُ كَانَ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، أَعْلَمُ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا. فَإِنَّهُ مَنْ قَالَهُنَّ حِينَ يُصْبِحُ حُفِظَ حَتَّى يُمْسِيَ، وَمَنْ قَالَهُنَّ حِينَ يُمْسِي حُفِظَ حَتَّى يُصْبِحَ". (د)', 'നബി(സ)യുടെ ചില പെൺമക്കൾക്ക് സേവനം ചെയ്തിരുന്ന തന്റെ ഉമ്മയോട് നബി(സ)യുടെ മകൾ പറഞ്ഞു കൊടുത്തതായി ബനു ഹാഷിമിന്റെ അടിമയായ അബ്ദുൽ ഹമീദ്(റ): നബി(സ) അവർക്ക് ഇപ്രകാരം പഠിപ്പിച്ച് കൊടുക്കാറുണ്ടായിരുന്നു: "നേരം പുലരുമ്പോൾ നീ ഇപ്രകാരം ചൊല്ലുക: ''അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം ഞാനവന്റെ പരിശുദ്ധിയെ വാഴ്ത്തുന്നു. അല്ലാഹുവിനല്ലാതെ ഒരു ശക്തിയുമില്ല. അവനുദ്ദേശിച്ചത് സംഭവിക്കും, അവനുദ്ദേശിക്കാത്തത് ഉണ്ടാവുകയില്ല. അല്ലാഹു എല്ലാ കാര്യത്തിനും കഴിവുള്ളവനാണെന്നും അവൻ എല്ലാത്തിനെക്കുറിച്ചും അറിയുമെന്നും ഞാൻ വിശ്വസിക്കുന്നു.'' നേരം പുലരുമ്പോൾ ആരെങ്കിലും ഇത് ചൊല്ലിയാൽ വൈകുന്നേരമാകുവോളം അവൻ സംരക്ഷിക്കപ്പെടും. വൈകുന്നേരത്ത് ആരെങ്കിലും ഇത് ചൊല്ലിയാൽ നേരം പുലരുവോളം അവൻ സംരക്ഷിക്കപ്പെടും." (ദ)', 'عَبْدِ الْحَمِيدِ مَوْلَى بَنِي هَاشِمٍ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 508, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 422, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ: {فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ. وَلَهُ الْحَمْدُ فِي السَّمَوَاتِ وَالْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ} إِلَى {وَكَذَلِكَ تُخْرَجُونَ} أَدْرَكَ مَا فَاتَهُ فِي يَوْمِهِ ذَلِكَ، وَمَنْ قَالَهُنَّ حِينَ يُمْسِي أَدْرَكَ مَا فَاتَهُ فِي لَيْلَتِهِ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലരുമ്പോൾ ആരെങ്കിലും ''നിങ്ങൾ നേരം പുലരുമ്പോഴും പ്രദോഷത്തിലാകുമ്പോഴും അല്ലാഹുവാണ് പരിശുദ്ധൻ. മധ്യാഹ്ന സമയത്തും വൈകുന്നരവും ആകാശ ഭുമികളിലെ സർവ്വസ്തുതിയും അവനുള്ളതാണ്.'' എന്നത് മുതൽ ''അപ്രകാരം തന്നെ നിങ്ങൾ പുറപ്പെടീക്കപ്പെടും'' എന്നത് വരെയുള്ള സൂക്തമോതിയാൽ ആ പകലിൽ അവന് നഷ്ടമായ സർവ്വതും അവനു വീണ്ടുകിട്ടും. വൈകുന്നേരം ആരെങ്കിലും അത് ഓതിയാൽ ആ രാത്രിയിൽ അവന് നഷ്ടമായ സർവ്വതും അവനു വീണ്ടുകിട്ടും." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 423, 'عَنْ أَبِي عَيَّاشٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَال إِذَا أَصْبَحَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. كَانَ لَهُ عِدْلَ رَقَبَةٍ مِنْ وَلَدِ إِسْمَعِيلَ، وَكُتِبَ لَهُ عَشْرُ حَسَنَاتٍ، وَحُطَّ عَنْهُ عَشْرُ سَيِّئَاتٍ، وَرُفِعَ لَهُ عَشْرُ دَرَجَاتٍ، وَكَانَ فِي حِرْزٍ مِنَ الشَّيْطَانِ حَتَّى يُمْسِيَ، وَإِنْ قَالَهَا إِذَا أَمْسَى كَانَ لَهُ مِثْلُ ذَلِكَ حَتَّى يُصْبِحَ". (د,جه)', 'അബൂഅയ്യാശ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലരുമ്പോൾ ''അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല തന്നെ, അവന് ഒരു പങ്കാളിയുമില്ല, അധികാരവും സർവ്വസ്തുതിയും അവന്നാണ് അവൻ സർവ്വ കാര്യങ്ങൾക്കും കഴിവുള്ളവനാണ്'' എന്ന് ആരെങ്കിലും ചൊല്ലിയാൽ അത് അവന് ഇസ്മാഈലീ സന്തതികളിൽ പെട്ട ഒരു അടിമയെ മോചിപ്പിച്ചതിനു തുല്യമാണ്. അത് കാരണത്താൽ അവന് പത്ത് നന്മകൾ എഴുതപ്പെടുകയും പത്ത് തിന്മകൾ മായ്ക്കപ്പെടുകയും പത്ത് പദവികൾ ഉയർത്തപ്പെടുകയും ചെയ്യും. നേരം വൈകുവോളം അവൻ പിശാചിനെത്തൊട്ടുള്ള കാവലിലാകും. ആരെങ്കിലും വൈകുന്നേരസമയത്ത് അത് ചൊല്ലിയാൽ നേരം പുലവുരോളം അവനു മുമ്പ് പറഞ്ഞ ഗുണങ്ങളെല്ലാം ലഭിക്കും." (ദ,ജ)', 'أَبِي عَيَّاشٍ', 'അബൂഅയ്യാശ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 424, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ حِينَ يُصْبِحُ: "اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ: أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ، وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ. إِلَّا غُفِرَ لَهُ مَا أَصَابَ فِي يَوْمِهِ ذَلِكَ مِنْ ذَنْبٍ، وَإِنْ قَالَهَا حِينَ يُمْسِي غُفِرَ لَهُ مَا أَصَابَ تِلْكَ اللَّيْلَةَ". (د,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നേരം പുലരുമ്പോൾ ആരെങ്കിലും ''നിശ്ചയം നീ അല്ലാഹുവാണ്, നീയല്ലാതെ ഒരു ആരാധ്യനില്ല, നിനക്ക് പങ്കുകാരനില്ല, മുഹമ്മദ്(സ) നിന്റെ അടിമയും പ്രവാചകനുമാണ് എന്ന് നിന്നെയും നിന്റെ മലക്കുകളെയും നിന്റെ സർവ്വ സൃഷ്ടികളെയും സാക്ഷ്യപ്പെടുത്തിക്കൊണ്ട് അല്ലാഹുവേ ഞാൻ നേരം പുലരുന്നു'' എന്ന് ചൊല്ലിയാൽ ആ പകലിൽ അവൻ ചെയ്ത ദോഷങ്ങളെല്ലാം പൊറുക്കപ്പെടുന്നതാണ്. വൈകുന്നേരം ആരെങ്കിലുമത് ചൊല്ലിയാൽ ആ രാത്രിയിൽ അവൻ ചെയ്ത ദോഷങ്ങളെല്ലാം പൊറുക്കപ്പെടുന്നതാണ്." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 509, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 425, 'عَنْ مُسْلِمِ بْنِ الْحَارِثِ التَّمِيمِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ أَسَرَّ إِلَيْهِ فَقَالَ: "إِذَا انْصَرَفْتَ مِنْ صَلَاةِ الْمَغْرِبِ فَقُلْ: اللَّهُمَّ أَجِرْنِي مِنَ النَّارِ، سَبْعَ مَرَّاتٍ، فَإِنَّكَ إِذَا قُلْتَ ذَلِكَ ثُمَّ مِتَّ فِي لَيْلَتِكَ كُتِبَ لَكَ جِوَارٌ مِنْهَا. وَإِذَا صَلَّيْتَ الصُّبْحَ فَقُلْ كَذَلِكَ، فَإِنَّكَ إِنْ مِتَّ فِي يَوْمِكَ كُتِبَ لَكَ جِوَارٌ مِنْهَا". (د)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=425), 1, 'وَفِي رِوَايَةٍ: "قَبْلَ أَنْ تُكَلِّمَ أَحَدًا". وفيها: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ، فَلَمَّا بَلَغْنَا الْمُغَارَ اسْتَحْثَثْتُ فَرَسِي فَسَبَقْتُ أَصْحَابِي، وَتَلَقَّانِي الْحَيُّ بِالرَّنِينِ، فَقُلْتُ لَهُمْ قُولُوا لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ تُحْرَزُوا، فَقَالُوهَا، فَلَامَنِي أَصْحَابِي، وَقَالُوا: حَرَمْتَنَا الْغَنِيمَةَ، فَلَمَّا قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرُوهُ بِالَّذِي صَنَعْتُ، فَدَعَانِي، فَحَسَّنَ لِي مَا صَنَعْتُ، وَقَالَ: "أَمَا إِنَّ اللَّهَ قَدْ كَتَبَ لَكَ مِنْ كُلِّ إِنْسَانٍ مِنْهُمْ كَذَا وَكَذَا". قَالَ الرَّاوِي: فَأَنَا نَسِيتُ الثَّوَابَ. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا إِنِّي سَأَكْتُبُ لَكَ بِالْوَصَاةِ بَعْدِي". قَالَ: فَفَعَلَ وَخَتَمَ عَلَيْهِ، فَدَفَعَهُ إِلَيَّ، وَقَالَ لِي ... ثُمَّ ذَكَرَ مَعْنَاهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഒരാളോടും സംസാരിക്കുന്നതിന് മുമ്പ്" എന്നുണ്ട്. ആ നിവേദനത്തിൽ ഇപ്രകാരം കൂടിയുണ്ട്: ഒരു സൈന്യത്തോടൊപ്പം റസൂൽ(സ) ഞങ്ങളെ പറഞ്ഞയച്ചു. ശത്രുക്കളെ അക്രമിക്കേണ്ട സ്ഥലത്തെത്തിയപ്പോൾ ഞാനെന്റെ കുതിരയുടെ വേഗത കൂട്ടുകയും ഞാൻ മുന്നിലെത്തുകയും ചെയ്തു. ആ ഗോത്രക്കാർ ശബ്ദ കോലാഹലങ്ങളോടെയാണ് എന്നെ വരവേറ്റത്. ഞാനവരോട് പറഞ്ഞു: അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല എന്ന് പറയുക, എങ്കിൽ നിങ്ങൾക്ക് രക്ഷ ലഭിക്കും. അപ്പോൾ അവർ അപ്രകാരം പറഞ്ഞു. അന്നേരം എന്റെയാളുകൾ എന്നെയാക്ഷേപിച്ചു. അവർ പറഞ്ഞു: നീ ഞങ്ങളുടെ യുദ്ധമുതൽ തടഞ്ഞു വെച്ചു. ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്തെത്തിയപ്പോൾ ഞാൻ ചെയ്തതെല്ലാം അവർ റസൂൽ(സ)യോട് അവതരിപ്പിച്ചു. അപ്പോൾ റസൂൽ(സ) എന്നെ വിളിക്കുകയും ഞാൻ ചെയ്തതിനെ പുകഴ്ത്തുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "നിശ്ചയം അല്ലാഹു അവരിൽ ഓരോരുത്തർക്കു പകരമായും നിനക്ക് ഇന്നാലിന്ന പ്രതിഫലം നിശ്ചയിച്ചിരിക്കുന്നു." നിവേദകൻ പറഞ്ഞു: പ്രതിഫലം എത്രയാണെന്നത് ഞാൻ മറന്നുപോയി. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശേഷം ഞാൻ നിനക്ക് വസിയ്യത് എഴുതി വെക്കും." നിവേദകൻ പറഞ്ഞു: നബി(സ) അപ്രകാരം ചെയ്യുകയും അതിന്മേൽ സീല് വെക്കുകയും അത് എനിക്ക് നൽകുകയും ചെയ്തു. എന്നിട്ട് എന്നോട് പറഞ്ഞു: ...... ശേഷം നിവേദകൻ ഈ ഹദീസിന്റെ ആശയം പറഞ്ഞു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 426, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَنْ قَالَ إِذَا أَمْسَى: حَسْبِيَ اللَّهُ، لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ مَا أَهَمَّهُ، صَادِقًا كَانَ بِهَا أَوْ كَاذِبًا. (د)', 'അബുദ്ദർദാഅ്(റ): വൈകുന്നേരമാകുമ്പോൾ ആരെങ്കിലും ''എനിക്ക് അല്ലാഹു മതി, അവനല്ലാതെ ഒരു ആരാധ്യനുമില്ല, അവന്റെ മേൽ ഞാൻ ഭരമേൽപ്പിക്കുന്നു, അവൻ മഹത്തായ അർശിന്റെ രക്ഷിതാവാണ്'' എന്ന് ഏഴു പ്രാവശ്യം ചൊല്ലിയാൽ അവന്റെ വിഷമങ്ങളെ, അവൻ സത്യം പറയുന്നെങ്കിലും കളവു പറയുന്നെങ്കിലും അല്ലാഹു തീർത്തു കൊടുക്കുന്നതാണ്. (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 511, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 427, 'عَنْ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا فِي لَيْلَةِ مَطَرٍ وَظُلْمَةٍ شَدِيدَةٍ نَطْلُبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ لَنَا، فَأَدْرَكْنَاهُ، فَقَالَ: "أَصَلَّيْتُمْ". فَلَمْ أَقُلْ شَيْئًا، فَقَالَ: "قُلْ". فَلَمْ أَقُلْ شَيْئًا، ثُمَّ قَالَ: "قُلْ". فَلَمْ أَقُلْ شَيْئًا، ثُمَّ قَالَ: "قُلْ". فَقُلْتُ: يَا رَسُولَ اللَّهِ مَا أَقُولُ؟ قَالَ: "قُلْ: {قُلْ هُوَ اللَّهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَحِينَ تُصْبِحُ، ثَلَاثَ مَرَّاتٍ، تَكْفِيكَ مِنْ كُلِّ شَيْءٍ". (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ): മഴയും ശക്തമായ ഇരുട്ടുമുള്ള ഒരു രാത്രിയിൽ ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുവാൻ വേണ്ടി റസൂൽ(സ)യെ തേടി ഞങ്ങൾ പുറപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യെ കണ്ടുമുട്ടി. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ നമസ്കരിച്ചുവോ?" ഞാൻ ഒന്നും പ്രതിവചിച്ചില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ ഓതുക". അപ്പോഴും ഞാൻ ഒന്നും പ്രതിവചിച്ചില്ല. വീണ്ടും റസൂൽ(സ) പറഞ്ഞു: "നീ ഓതുക". അപ്പോഴും ഞാൻ ഒന്നും പ്രതിവചിച്ചില്ല. വീണ്ടും റസൂൽ(സ) പറഞ്ഞു: "നീ ഓതുക." ഞാൻ ചോദിച്ചു: റസൂലേ, ഞാൻ എന്താണ് ഓതേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "വൈകുന്നേരവും നേരം പുലരുമ്പോഴും നീ സുറതുൽ ഇഖ്‌ലാസും മുഅവ്വിദതൈനിയും മൂന്ന് പ്രാവശ്യം ഓതുക, എന്നാൽ എല്ലാ പ്രശ്നങ്ങൾക്കും പരിഹാരമായി നിനക്കതുമതി." (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ خُبَيْبٍ', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 511, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 428, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِي رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، حَدِّثْنَا بِكَلِمَةٍ نَقُولُهَا إِذَا أَصْبَحْنَا وَأَمْسَيْنَا وَاضْطَجَعْنَا؟ فَأَمَرَهُمْ أَنْ يَقُولُوا: "اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ رَبُّ كُلِّ شَيْءٍ، وَالْمَلَائِكَةُ يَشْهَدُونَ أَنَّكَ لَا إِلَهَ إِلَّا أَنْتَ، فَإِنَّا نَعُوذُ بِكَ مِنْ شَرِّ أَنْفُسِنَا، وَمِنْ شَرِّ الشَّيْطَانِ الرَّجِيمِ وَشِرْكِهِ، وَأَنْ نَقْتَرِفَ سُوءًا عَلَى أَنْفُسِنَا أَوْ نَجُرَّهُ إِلَى مُسْلِمٍ". (د) قَالَ أَبُو دَاوُد: وَبِهَذَا الْإِسْنَادِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَصْبَحَ أَحَدُكُمْ فَلْيَقُلْ: أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ: فَتْحَهُ وَنَصْرَهُ وَنُورَهُ وَبَرَكَتَهُ وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ. ثُمَّ إِذَا أَمْسَى فَلْيَقُلْ مِثْلَ ذَلِكَ". (د)', 'അബൂമാലികിനിൽ അശ്അരി(റ): സ്വഹാബികൾ ചോദിച്ചു: റസൂലേ, നേരം പുലരുമ്പോഴും വൈകുന്നേരവും കിടപ്പറയിലേക്ക് ചെന്നാലും ഞങ്ങൾക്കു ചൊല്ലാൻ പറ്റുന്ന ഒരു വാക്യം പറഞ്ഞു തരിക. അപ്പോൾ റസൂൽ(സ) അവരോട് ഇപ്രകാരം ചൊല്ലാൻ കൽപ്പിച്ചു: "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവും രഹസ്യപരസ്യങ്ങളെ അറിയുന്നവനുമായ അല്ലാഹുവേ, നീ സർവ്വ വസ്തുക്കളുടെയും രക്ഷിതാവാണ്. നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ലെന്ന് മലക്കുകൾ സാക്ഷ്യം വഹിക്കുന്നു. ഞങ്ങളുടെ ശരീരങ്ങളുടെ തിന്മയിൽ നിന്നും ആട്ടിയോടിക്കപ്പെട്ട പിശാചിന്റെ തിന്മയിൽ നിന്നും അവന്റെ ശിർകിൽ നിന്നും, ഞങ്ങൾ ഞങ്ങളുടെ ശരീരത്തോട് തിന്മ ചെയ്യുന്നതിൽ നിന്നും അല്ലെങ്കിൽ ഒരു മുസ്‌ലിമിലേക്കത് വലിച്ചിഴക്കുന്നതിൽ നിന്നും ഞങ്ങൾ നിന്നിൽ അഭയം പ്രാപിക്കുന്നു." (ദ)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 429, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، سُئِلَتْ: بِمَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ؟ فَقَالَتْ لِلسَّائِلِ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ. كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمَّدَ عَشْرًا، وَقَالَ: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ" عَشْرًا، وَقَالَ: "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ" عَشْرًا، وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا وَضِيقِ يَوْمِ الْقِيَامَةِ" عَشْرًا، ثُمَّ يَفْتَتِحُ الصَّلَاةَ. (د,ن)', 'ആഇശ(റ): രാത്രി ഉണർന്നാൽ റസൂൽ(സ) എന്താണ് ചൊല്ലിത്തുടങ്ങിയിരുന്നത് എന്ന് അവരോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ മഹതി ചോദ്യക്കാരനോട് പറഞ്ഞു: മുമ്പ് ഒരാളും എന്നോട് ചോദിച്ചിട്ടില്ലാത്ത ഒരു ചോദ്യമാണ് നീ എന്നോട് ചോദിച്ചിരിക്കുന്നത്, രാത്രി ഉണർന്നാൽ നബി(സ) പത്തു പ്രാവശ്യം തക്ബീർ ചൊല്ലും, പത്ത് പ്രാവശ്യം തഹ്മീദ് ചൊല്ലും, ''അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം അവന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു'' എന്ന് പത്ത് പ്രാവശ്യം ചൊല്ലും, ''പരിശുദ്ധവാനും സർവ്വാധികാരിയുമായ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു'' എന്ന് പത്ത് പ്രാവശ്യം ചൊല്ലും, പത്ത് തവണ പൊറക്കലിനെ തേടും, പത്ത് പ്രാവശ്യം തഹ്ലീൽ ചൊല്ലും, ശേഷം ഇപ്രകാരം പത്ത് പ്രാവശ്യം പറയും: "അല്ലാഹുവേ, ഐഹിക ലോകത്തിന്റെയും അന്ത്യദിനത്തിന്റെയും പ്രയാസങ്ങളിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." ശേഷം നബി(സ) നമസ്കരിക്കാൻ തുടങ്ങും. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 430, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ فِي سَفَرٍ فَأَسْحَرَ يَقُولُ: "سَمِعَ سَامِعٌ بِحَمْدِ اللَّهِ وَنِعْمَتِهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا، اللَّهُمَّ صَاحِبْنَا فَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللَّهِ مِنَ النَّارِ". (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) യാത്ര ചെയ്യുകയും അങ്ങനെ അത്താഴ സമയമാവുകയും ചെയ്താൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവിനെ സ്തുതിക്കുന്നതും അവന്റെ അനുഗ്രഹവും അവൻ നമുക്ക് ചെയ്ത ഗുണങ്ങളും എടുത്ത് പറയുന്നത് കേൾക്കുന്നയാൾ (അല്ലാഹു) കേട്ടിരിക്കുന്നു. അല്ലാഹുവേ, നീ ഞങ്ങളുടെ കൂടെയുണ്ടാവുകയും ഞങ്ങൾക്ക് നിന്റെ ഔദാര്യമേകുകയും ചെയ്യേണമേ. നരകത്തിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 431, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَنْ قَالَ حِينَ يُصْبِحُ: اللَّهُمَّ مَا حَلَفْتُ مِنْ حَلِفٍ أَوْ قُلْتُ مِنْ قَوْلٍ أَوْ نَذَرْتُ مِنْ نَذْرٍ فَمَشِيئَتُكَ بَيْنَ يَدَيْ ذَلِكَ كُلِّهِ: مَا شِئْتَ كَانَ وَمَا لَمْ تَشَأْ لَمْ يَكُنْ، اللَّهُمَّ اغْفِرْ لِي وَتَجَاوَزْ لِي عَنْهُ، اللَّهُمَّ فَمَنْ صَلَّيْتَ عَلَيْهِ فَعَلَيْهِ صَلَاتِي، وَمَنْ لَعَنْتَ فَعَلَيْهِ لَعْنَتِي. كَانَ فِي اسْتِثْنَاء يَوْمَهُ ذَلِكَ، أَوْ قَالَ: ذَلِكَ الْيَوْمَ. (د)', 'അബൂദർറ്(റ): നേരം പുലരുമ്പോൾ ആരെങ്കിലും ''അല്ലാഹുവേ, നിന്റെ തീരുമാനമുണ്ടായിട്ടല്ലാതെ ഞാൻ വല്ല സത്യവും ചെയ്യുകയോ വല്ല നേർച്ചയും നേരുകയോ വല്ലതും പറയുകയോ ചെയ്തിട്ടില്ല. നീ ഉദ്ധേശിച്ചത് സംഭവിക്കും, ഉദ്ധേശിക്കാത്തത് സംഭവിക്കില്ല. അല്ലാഹുവേ, നീ എന്റെ പാപം പൊറുക്കുകയും അവ എനിക്ക് വിട്ടുവീഴ്ച ചെയ്തു തരികയും ചെയ്യേണമേ. അല്ലാഹുവേ, നീയാരെയെങ്കിലും തൃപ്തിപ്പെട്ടാൽ അവന്റെ മേൽ എന്റെ തൃപ്തിയുമുണ്ട്. നീ ആരെയെങ്കിലും ശപിച്ചാൽ അവന്റെ മേൽ എന്റെ ശാപവുമുണ്ട്. എന്ന് പറഞ്ഞാൽ ആ ദിനത്തിൽ അവൻ സംരക്ഷണത്തിലായിരിക്കും. (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 512, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 432, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَالَ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ، ثَلَاثَ مَرَّاتٍ، لَمْ تُصِبْهُ فَجْأَةُ بَلَاءٍ حَتَّى يُصْبِحَ، وَمَنْ قَالَهَا حِينَ يُصْبِحُ ثَلَاثُ مَرَّاتٍ لَمْ تُصِبْهُ فَجْأَةُ بَلَاء حَتَّى يُمْسِيَ". (د,ت,جه)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ നാമത്തിൽ ഞാൻ തുടങ്ങുന്നു, അവന്റെ നാമമുണ്ടെങ്കിൽ ആകാശത്തിലേയോ ഭൂമിയിലേയോ ഒരു വസ്തുവും ബുദ്ധിമുട്ടേൽപ്പിക്കുകയില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും സർവ്വം അറിയുന്നവനുമാണ്'' എന്ന് ആരെങ്കിലും മൂന്ന് പ്രാവശ്യം ചൊല്ലിയാൽ നേരം പുലരുവോളം പെട്ടന്നുണ്ടാകുന്ന ഒരു വിപത്തും അവന് ഏൽക്കുകയില്ല. നേരം പുലരുമ്പോൾ ആരെങ്കിലും അത് മൂന്ന് പ്രാവശ്യം ചൊല്ലിയാൽ വൈകുവോളം പെട്ടെന്നുണ്ടാകുന്ന ഒരു വിപത്തും അവന് ഏൽക്കുകയില്ല." (ദ,തു,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 433, 'عَنْ عَبْدِ الرَّحْمَنِ بْن أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ لِأَبِيهِ: يَا أَبَةِ، إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. وَفِيهِ: وَتَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ. تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي؟ فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "دَعَوَاتُ الْمَكْرُوبِ: اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ". (د)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ): അവർ തന്റെ പിതാവിനോട് ചോദിച്ചു: എല്ലാ പ്രഭാതത്തിലും അങ്ങ് ''അല്ലാഹുവേ എന്റെ ശരീരത്തിലും എന്റെ കേൾവിയിലും, കാഴ്ചയിലും നീ എനിക്ക് സൗഖ്യം നൽകണേ. നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല.'' എന്ന് ചൊല്ലുന്നല്ലോ? ആ നിവേദനത്തിൽ ഇപ്രകാരം കൂടിയുണ്ട്: ''അല്ലാഹുവേ, ദൈവ നിഷേധത്തിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നും ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല.'' എന്നും നിങ്ങൾ ചൊല്ലുന്നല്ലോ? വൈകുന്നേരവും പ്രഭാതത്തിലും അങ്ങ് അത് മൂന്ന് പ്രാവശ്യം ചൊല്ലുന്നു. അപ്പോൾ അവരുടെ പിതാവ് പറഞ്ഞു: റസൂൽ(സ) അവ പ്രാർത്ഥിക്കുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. റസൂൽ(സ)യുടെ ചര്യയെ പിന്തുടരാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. റസൂൽ(സ) ഇത് കൂടി പറഞ്ഞിട്ടുണ്ട്: "ബുദ്ധിമുട്ടുന്നവന്റെ പ്രാർത്ഥനകൾ ഇവയാണ്: ''അല്ലാഹുവേ, നിന്റെ അനുഗ്രഹത്തെ ഞാൻ ആഗ്രഹിക്കുന്നു, അതിനാൽ എന്നിലേക്ക് ഒരു കൺപോളയുടെ നിയന്ത്രണം പോലും നീ ഏൽപ്പിക്കരുത്, എന്റെ കാര്യങ്ങളെയെല്ലാം നീ എനിക്ക് നന്നാക്കിത്തരണേ, നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല." (ദ)', 'عَبْدِ الرَّحْمَنِ بْن أَبِي بَكْرَةَ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 434, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ حِينَ يُصْبِحُ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ، مِائَةَ مَرَّةٍ. وَإِذَا أَمْسَى كَذَلِكَ، لَمْ يُوَافِ أَحَدٌ مِنَ الْخَلَائِقِ بِمِثْلِ مَا وَافَى". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മഹത്വമേറിയ അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം ഞാൻ അവന്റെ പരിശുദ്ധിയെ വാഴ്ത്തുന്നു എന്ന് നേരം പുലരുമ്പോഴും വൈകുന്നേരവും ആരെങ്കിലും നൂറ് പ്രാവശ്യം വീതം ചൊല്ലിയാൽ അവൻ ചെയ്തത് പോലെയുള്ള ഒരു പ്രവർത്തനം സൃഷ്ടികളിൽ നിന്നുള്ള ഒരാളും പൂർത്തീകരിച്ചിട്ടുണ്ടാവില്ല." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 435, 'عَنْ قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ بَلَغَهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى الْهِلَالَ قَالَ: "هِلَالُ خَيْرٍ وَرُشْدٍ، هِلَالُ خَيْرٍ وَرُشْدٍ، آمَنْتُ بِالَّذِي خَلَقَكَ" ثَلَاثَ مَرَّاتٍ، ثُمَّ يَقُولُ: "الْحَمْدُ لِلَّهِ الَّذِي ذَهَبَ بِشَهْرِ كَذَا وَجَاءَ بِشَهْرِ كَذَا". (مرسلٌ) (د)', 'ഖതാദ(റ): നബി(സ) ചന്ദ്രനെ ദർശിച്ചാൽ "സൻമാർഗ്ഗത്തിന്റെയും നന്മയുടെയും ചന്ദ്രൻ, സൻമാർഗ്ഗത്തിന്റെയും നന്മയുടെയും ചന്ദ്രൻ, നിന്നെ സൃഷ്ടിച്ചവനിൽ ഞാൻ വിശ്വസിച്ചിരിക്കുന്നു." എന്ന് മൂന്ന് പ്രാവശ്യം ചൊല്ലും. എന്നിട്ട് പറയും: "ഇന്ന മാസത്തെ കൊണ്ടുവരികയും ഇന്ന മാസം കൊണ്ടുപോകുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും." (ഹദീസ് മുർസലാണ്) (ദ)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=184 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 436, 'عَنْ قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى الْهِلَالَ صَرَفَ وَجْهَهُ عَنْهُ. (مُرْسَلٌ). قَالَ أَبُو دَاود: لَيْسَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْبَابِ حَدِيثٌ مُسْنَدٌ صَحِيحٌ. (د)', 'ഖതാദ(റ): നബി(സ) ചന്ദ്രനെ ദർശിച്ചാൽ അതിൽ നിന്നും മുഖം തിരിച്ച് കളയുമായിരുന്നു. (ഹദീസ് മുർസലാകുന്നു). അബൂദാവുദ്(റ) പറയുന്നു: തിരുനബി(സ)യെക്കുറിച്ച് ''മുസ്നദും സ്വഹീഹു''മായ ഒരു ഹദീസും ഈ വിഷയത്തിലില്ല. (ദ)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=184 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 437, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ بَيْتِي قَطُّ إِلَّا رَفَعَ طَرْفَهُ إِلَى السَّمَاءِ فَقَالَ: "اللَّهُمَّ أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ". (د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) തന്റെ കണ്ണ് ആകാശത്തേക്കുയർത്തി ഇപ്രകാരം പറഞ്ഞിട്ടല്ലാതെ എന്റെ വീട്ടിൽ നിന്നിറങ്ങിയിട്ടേയില്ല: "അല്ലാഹുവേ, വഴി പിഴച്ച് പോകുന്നതിൽ നിന്നും വഴി പിഴപ്പിക്കപ്പെടുന്നതിൽ നിന്നും, വഴുതിപ്പോകുന്നതിൽ നിന്നും, വഴുതിക്കളയുന്നതിൽ നിന്നും, അക്രമിക്കുകയോ അക്രമിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും അധർമ്മം ചെയ്യുകയോ ചെയ്യപ്പടുകയോ ചെയ്യുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 438, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَقَالَ: بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. يُقَالُ حِينَئِذٍ: هُدِيتَ وَكُفِيتَ وَوُقِيتَ. فَتَتَنَحَّى لَهُ الشَّيَاطِينُ، فَيَقُولُ لَهُ شَيْطَانٌ آخَرُ: كَيْفَ لَكَ بِرَجُلٍ قَدْ هُدِيَ وَكُفِيَ وَوُقِيَ". (د,ت)', 'അനസുബ്നു മാലിക്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ഒരുത്തൻ തന്റെ വീട്ടിൽ നിന്നിറങ്ങുമ്പോൾ ''അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിൽ ഞാൻ ഭരമേൽപ്പിച്ചു, കഴിവും ശക്തിയും അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഇല്ല'' എന്ന് പറഞ്ഞാൽ ആ സമയത്ത് ഇപ്രകാരം പറയപ്പെടും: നീ സന്മാർഗ്ഗത്തിലാക്കപ്പെടുകയും, നിന്റെ ആവശ്യങ്ങൾ തീർക്കപ്പെടുകയും നീ സംരക്ഷിക്കപ്പെടുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ പിശാചുക്കൾ അവനിൽ നിന്ന് അകന്ന് പോകും. ഈ പിശാചിനോട് മറ്റൊരു പിശാച് പറയും: സന്മാർഗ്ഗത്തിലാക്കപ്പെടുകയും ആവശ്യങ്ങൾ തീർക്കപ്പെടുകയും സംരക്ഷിക്കപ്പെടുകയും ചെയ്ത ഒരുത്തനെ നിനക്കെന്ത് ചെയ്യാൻ കഴിയും." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 439, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَلَجَ الرَّجُلُ بَيْتَهُ فَلْيَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلَجِ وَخَيْرَ الْمَخْرَجِ، بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا، ثُمَّ لِيُسَلِّمْ عَلَى أَهْلِهِ". (د)', 'അബൂമാലികുൽ അശ്അരി(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ വീട്ടിൽ പ്രവേശിച്ചാൽ അല്ലാഹുവേ, ഏറ്റവും നല്ല പ്രവേശനസ്ഥലവും, ഏറ്റവും നല്ല പുറപ്പെടുന്ന സ്ഥലവും നിന്നോട് ഞാൻ ചോദിക്കുന്നു, അല്ലാഹുവിന്റെ നാമത്തിൽ ഞങ്ങൾ പ്രവേശിച്ചു, അല്ലാഹുവിന്റെ നാമത്തിൽ ഞങ്ങൾ പുറപ്പെട്ടു, ഞങ്ങളുടെ റബ്ബായ അല്ലാഹുവിൽ ഞങ്ങൾ ഭരമേൽപ്പിച്ചു, എന്ന് പറയുകയും ശേഷം അവന്റെ വീട്ടുകാർക്ക് സലാം പറയുകയും ചെയ്യട്ടെ." (ദ)', 'أَبِي مَالِكٍ الْأَشْعَرِيِّ', 'അബൂമാലികുൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=186 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 440, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الرِّيحُ مِنْ رَوْحِ اللَّهِ، فَرَوْحُ اللَّهِ تَأْتِي بِالرَّحْمَةِ وَتَأْتِي بِالْعَذَابِ، فَإِذَا رَأَيْتُمُوهَا فَلَا تَسُبُّوهَا، وَسَلُوا اللَّهَ خَيْرَهَا، وَاسْتَعِيذُوا بِاللَّهِ مِنْ شَرِّهَا". (د,جه)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ ശ്രവിച്ചു: "കാറ്റ് അല്ലാഹുവിന്റെ വിഭവങ്ങളിൽ പെട്ടതാണ്, അല്ലാഹുവിന്റെ വിഭവം അനുഗ്രഹവും കൊണ്ടുവരും, ശിക്ഷയും കൊണ്ടുവരും, അതിനെ നിങ്ങൾ ദർശിച്ചാൽ നിങ്ങൾ അതിനെ ചീത്ത വിളിക്കരുത്, അതിലെ നന്മയെ നിങ്ങൾ അല്ലാഹുവിനോട് ചോദിക്കുക, അതിന്റെ തിന്മയിൽ നിന്നും അല്ലാഹുവിൽ അഭയം തേടുകയും ചെയ്യുക." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=187 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 441, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا -زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- أَنَّهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطُّ مُسْتَجْمِعًا ضَاحِكًا حَتَّى أَرَى مِنْهُ لَهَوَاتِهِ، إِنَّمَا كَانَ يَتَبَسَّمُ، وَكَانَ إِذَا رَأَى غَيْمًا أَوْ رِيحًا عُرِفَ ذَلِكَ فِي وَجْهِهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، النَّاسُ إِذَا رَأَوُا الْغَيْمَ فَرِحُوا رَجَاء أَنْ يَكُونَ فِيهِ الْمَطَرُ، وَأَرَاكَ إِذَا رَأَيْتَهُ عُرِفَتْ فِي وَجْهِكَ الْكَرَاهِيَةُ؟ فَقَالَ: "يَا عَائِشَةُ، مَا يُؤَمِّنُنِي أَنْ يَكُونَ فِيهِ عَذَابٌ؟ قَدْ عُذِّبَ قَوْمٌ بِالرِّيحِ، وَقَدْ رَأَى قَوْمٌ الْعَذَابَ فَقَالُوا: {هَذَا عَارِضٌ مُمْطِرُنَا} [الأحقاف:٢٨]. (ق)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ മോണ കാണുമാറ് പൊട്ടിച്ചിരിക്കുന്നതായി ഇതു വരെ ഞാൻ കണ്ടിട്ടില്ല. അവിടന്ന് പുഞ്ചിരിക്കുക മാത്രമാണ് ചെയ്തിരുന്നത്. മേഘമോ, കാറ്റോ ദർശിച്ചാൽ അത് അവിടത്തെ മുഖത്ത് പ്രകടമാകും. അപ്പോൾ ഞാൻ ചോദിക്കും: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ജനങ്ങൾ മേഘം കണ്ടാൽ അതിൽ മഴയുണ്ടാകുമെന്ന് കരുതി സന്തോഷിക്കും. അങ്ങത് കണ്ടാൽ അങ്ങയുടെ മുഖത്ത് അനിഷ്ടമാണല്ലോ ഞാൻ കാണുന്നത്? അവിടന്ന് പറഞ്ഞു: "ആഇശാ, അതിൽ ശിക്ഷയില്ലെന്ന് എങ്ങനെ വിശ്വസിക്കും. ചില സമുദായങ്ങൾ ശിക്ഷിക്കപ്പെട്ടത് കാറ്റ് കൊണ്ടാണ്, ഒരു സമുദായം അവർക്കുള്ള ശിക്ഷ കണ്ടപ്പോൾ പറഞ്ഞത്: ''ഇത് മഴപെയ്യിക്കുന്ന മേഘമാണ്'' (അഹ്ഖാഫ്: 28) എന്നായിരുന്നു." (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'الأحقاف:٢٨', null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=187 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 442, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى نَاشِئًا فِي أُفُقِ السَّمَاءِ تَرَكَ الْعَمَلَ وَإِنْ كَانَ فِي صَلَاةٍ، ثُمَّ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّهَا". فَإِنْ مُطِرَ قَالَ: "اللَّهُمَّ صَيِّبًا هَنِيئًا". (د,جه)', 'ആഇശ(റ): റസൂൽ(സ) ചക്രവാളത്തിൽ വല്ല പുതുമേഘത്തെയും ദർശിച്ചാൽ, നിസ്കാരത്തിലാണെങ്കിൽ പോലും എല്ലാ പ്രവർത്തികളും ഉപേക്ഷിക്കും, എന്നിട്ട് പറയും: "അല്ലാഹുവേ, അതിന്റെ ശർറിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ തേടുന്നു." മഴപെയ്താൽ അവിടന്ന് പറയും: "അല്ലാഹുവേ, ആവശ്യത്തിനുള്ള തരത്തിൽ ഉപകാരപ്രദമായി വർഷിപ്പിക്കണേ." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 515, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=187 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 443, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَصَابَنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَطَرٌ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَسَرَ ثَوْبَهُ عَنْهُ حَتَّى أَصَابَهُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، لِمَ صَنَعْتَ هَذَا؟ قَالَ: "لِأَنَّهُ حَدِيثُ عَهْدٍ بِرَبِّهِ". (م,د)', 'അനസ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെയായിരിക്കുമ്പോൾ മഴപെയ്തു. അപ്പോൾ അവിടന്ന് മഴയിലേക്കിറങ്ങി തന്റെ ശരീരത്തിൽ മഴയേൽക്കും വിധം വസ്ത്രമഴിച്ചു. ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങെന്തിനാണ് ഇത് ചെയ്തത്? അവിടന്ന് മറുപടി പറഞ്ഞു: "കാരണം അത് എന്റെ റബ്ബിനോട് അടുത്ത കാലക്കാരനാണ്." (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=188 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 444, 'عَنْ زَيْدِ بْنِ خَالِدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسُبُّوا الدِّيكَ، فَإِنَّهُ يُوقِظُ لِلصَّلَاةِ". (د,ن)', 'സൈദുബ്നു ഖാലിദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പൂവൻകോഴിയെ ചീത്ത പറയരുത്, കാരണം, അത് നിസ്കാരത്തിന് ഉണർത്തുന്നതാണ്." (ദ,ന)', 'زَيْدِ بْنِ خَالِدٍ', 'സൈദുബ്നു ഖാലിദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=189 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 445, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَسَلُوا اللَّهَ تَعَالَى مِنْ فَضْلِهِ، فَإِنَّهَا رَأَتْ مَلَكًا. وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيْطَانِ، فَإِنَّهَا رَأَتْ شَيْطَانًا". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പൂവൻകോഴിയുടെ കൂവൽ കേട്ടാൽ അല്ലാഹുവിന്റെ ഔദാര്യം ചോദിക്കുക, കാരണം, അത് മലകിനെ കണ്ടിരിക്കുന്നു, കഴുതയുടെ ശബ്ദം കേട്ടാൽ നിങ്ങൾ പിശാചിൽ നിന്ന് അല്ലാഹുവിൽ അഭയം പ്രാപിക്കുക, കാരണം, അത് പിശാചിനെയാണ് കണ്ടിരിക്കുന്നത്." (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=189 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 446, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا سَمِعْتُمْ نُبَاحَ الْكِلَابِ وَنَهِيقَ الْحُمُرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ، فَإِنَّهُنَّ يَرَيْنَ مَا لَا تَرَوْنَ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ രാത്രിയിൽ നായകളുടെ കുരയും, കഴുതകളുടെ കരച്ചിലും കേട്ടാൽ അല്ലാഹുവിൽ അഭയം പ്രാപിക്കുക, കാരണം നിങ്ങൾ കാണാത്തതാണ് അവ കാണുന്നത്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=189 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 447, 'عَنْ عَلِيِّ بْنِ عُمَرَ بْنِ حُسَيْنِ بْنِ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَقِلُّوا الْخُرُوجَ بَعْدَ هَدْأَةِ الرِّجْلِ، فَإِنَّ لِلَّهِ تَعَالَى دَوَابَّ -وفي رواية: خَلْقًا- يَبُثُّهُنَّ فِي الْأَرْضِ فِي تِلْكَ السَّاعَةِ". ثُمَّ ذَكَرَ نُبَاحَ الْكَلْبِ وَالْحَمِيرِ... نَحْوَهُ. (د)', 'അലിയ്യുബ്നു ഉമറുബ്നു ഹുസൈനുബ്നു അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "പാദ ചലനങ്ങൾ ശാന്തമായതിന് ശേഷം (രാത്രിയിൽ) പുറത്ത് പോകുന്നത് നിങ്ങൾ കുറക്കുക, കാരണം അല്ലാഹുവിന് കുറെ മൃഗങ്ങളുണ്ട് - മറ്റൊരു നിവേദനത്തിൽ: സൃഷ്ടികളുണ്ട് - ആ സമയത്ത് അവനവയെ ഭൂമിയിൽ വ്യാപിപ്പിക്കും." പിന്നെ പട്ടിയുടെയും കഴുതയുടെയും അത് പോലുള്ളവയുടെയും ശബ്ദത്തെക്കുറിച്ച് അവിടന്ന് പറഞ്ഞു. (ദ)', 'عَلِيِّ بْنِ عُمَرَ بْنِ حُسَيْنِ بْنِ عَلِيٍّ', 'അലിയ്യുബ്നു ഉമറുബ്നു ഹുസൈനുബ്നു അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=189 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=447), 1, 'وَفِي رِوَايَةٍ: خَلْقًا- يَبُثُّهُنَّ فِي الْأَرْضِ فِي تِلْكَ السَّاعَةِ". ثُمَّ ذَكَرَ نُبَاحَ الْكَلْبِ وَالْحَمِيرِ... نَحْوَهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: സൃഷ്ടികളുണ്ട് - ആ സമയത്ത് അവനവയെ ഭൂമിയിൽ വ്യാപിപ്പിക്കും." പിന്നെ പട്ടിയുടെയും കഴുതയുടെയും അത് പോലുള്ളവയുടെയും ശബ്ദത്തെക്കുറിച്ച് അവിടന്ന് പറഞ്ഞു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 448, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَذَّنَ فِي أُذُنِ الْحَسَنِ بْنِ عَلِيٍّ -رَضِيَ اللَّهُ عَنْهُمَا- حِينَ وَلَدَتْهُ فَاطِمَةُ بِالصَّلَاةِ. (د,ت)', 'അബൂറാഫിഅ്(റ): ഫാത്വിമ(റ) ഹസൻ(റ)വിനെ പ്രസവിച്ചപ്പോൾ, ഹസൻ(റ)വിന്റെ കാതിൽ നബി(സ) നിസ്കാരത്തിനുള്ള ബാങ്ക് വിളിക്കുന്നതായി ഞാൻ കണ്ടു. (ദ,തു)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=190 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 449, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُؤْتَى بِالصِّبْيَانِ فَيَدْعُو لَهُمْ بِالْبَرَكَةِ، وَيُحَنِّكُهُمْ. (د)', 'ആഇശ(റ): തിരുദൂതർ(സ)യുടെ അടുക്കൽ കുട്ടികളെ കൊണ്ടുവരുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) അവർക്ക് ബറക്കതിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും അവർക്ക് മധുരം നൽകുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=190 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 450, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ رُئِيَ فِيكُمُ الْمُغَرِّبُونَ". قُلْتُ: وَمَا الْمُغَرِّبُونَ؟ قَالَ: "الَّذِينَ يَشْتَرِكُ فِيهِمُ الْجِنُّ". (د)', 'ആഇശ(റ): റസൂൽ(സ) എന്നോട് ചോദിച്ചു: "നിങ്ങളിൽ ''മുഗർറബു''കൾ കാണപ്പെട്ടിട്ടുണ്ടോ? ഞാൻ ചോദിച്ചു: എന്താണ് ''മുഗർറബുകൾ''? റസൂൽ(സ) പറഞ്ഞു: "ജിന്ന് പങ്കാളികളായുള്ളവരാണ് മുഗർറബുകൾ." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=190 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 451, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اسْتَعَاذَ بِاللَّهِ فَأَعِيذُوهُ، وَمَنْ سَأَلَكُمْ بِوَجْهِ اللَّهِ فَأَعْطُوهُ". (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനെക്കൊണ്ട് അഭയം തേടിയാൽ നിങ്ങൾ അവന് അഭയം നൽകുക, ആരെങ്കിലും അല്ലാഹുവിന്റെ പേരിൽ നിങ്ങളോട് ചോദിച്ചാൽ നിങ്ങൾ അവന് നൽകുക." (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=191 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 452, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَعَاذَكُمْ بِاللَّهِ فَأَعِيذُوهُ، وَمَنْ سَأَلَكُمْ بِاللَّهِ فَأَعْطُوهُ، وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ، وَمَنْ آتَى إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ، فَإِنْ لَمْ تَجِدُوا فَادْعُوا اللَّهَ لَهُ حَتَّى تَعْلَمُوا أَنْ قَدْ كَافَأْتُمُوهُ". (د,ن)', 'ഇബ്നുഉമർ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളോട് ആരെങ്കിലും അല്ലാഹുവിനെക്കൊണ്ട് അഭയം തേടിയാൽ നിങ്ങളവന് അഭയം നൽകുക, നിങ്ങളോടാരെങ്കിലും അല്ലാഹുവിനെക്കൊണ്ട് ചോദിച്ചാൽ നിങ്ങളവന് നൽകുക, നിങ്ങളെ ആരെങ്കിലും ക്ഷണിച്ചാൽ നിങ്ങളവന് ഉത്തരം നൽകുക, നിങ്ങൾക്കാരെങ്കിലും നന്മചെയ്താൽ നിങ്ങളവന് നന്മ കൊണ്ട് പ്രതിഫലം നൽകുക, അതിന് സാധ്യമായില്ലെങ്കിൽ നന്മകൊണ്ട് പകരമായെന്ന് നിങ്ങൾക്ക് ബോധ്യമാകും വിധം അവനു വേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുക." (ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 517, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=191 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 453, 'عَنْ أَبِي زُمَيْلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: مَا شَيْءٌ أَجِدُهُ فِي صَدْرِي؟ قَالَ: مَا هُوَ؟ قُلْتُ: وَاللَّهِ مَا أَتَكَلَّمُ بِهِ، قَالَ: فَقَالَ لِي: أَشَيْءٌ مِنْ شَكٍّ؟ قَالَ: وَضَحِكَ، قَالَ: مَا نَجَا مِنْ ذَلِكَ أَحَدٌ، قَالَ: حَتَّى أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {فَإِنْ كُنْتَ فِي شَكٍّ مِمَّا أَنْزَلْنَا إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَابَ مِنْ قَبْلِكَ} الْآيَةَ، قَالَ: فَقَالَ لِي: إِذَا وَجَدْتَ فِي نَفْسِكَ شَيْئًا فَقُلْ: {هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ} [الحديد:٣] (د)', 'അബൂസുമൈൽ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: എന്റെ ഹൃദയത്തിൽ എനിക്കീ തോന്നുന്നതെന്താണ്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെന്താണ്? ഞാൻ പറഞ്ഞു: അല്ലാഹുവിനെ തന്നെയാണ് സത്യം. അത് ഞാൻ പറയില്ല. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) എന്നോട് ചോദിച്ചു: വല്ല സംശയവുമുണ്ടോ? എന്നിട്ട് അദ്ദേഹം ചിരിക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: അതിൽ നിന്ന് ഒരാളും രക്ഷപ്പെട്ടിട്ടില്ല. എത്രത്തോളമെന്നാൽ അല്ലാഹു തആല ഇറക്കി: ''നാം അങ്ങേക്ക് ഇറക്കിയതിൽ അങ്ങ് സംശയാലുവാണെങ്കിൽ നിങ്ങൾക്കു മുമ്പേ ഗ്രന്ഥം പാരായണം ചെയ്യുന്നവരോട് നിങ്ങൾ ചോദിക്കുക.'' എന്നിട്ട് ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നിങ്ങൾക്കു വല്ലതും തോന്നുന്നുവെങ്കിൽ ''അവനാണ് ആദ്യത്തവനും ശേഷിക്കുന്നവനും പ്രകടമായവനും ഗോപ്യമായവനും. അവൻ എല്ലാ കാര്യങ്ങളും നന്നായറിയുന്നവനാണ്'' (ഹദീദ്: 3) എന്ന സൂക്തം നീ ചൊല്ലുക. (ദ)', 'أَبِي زُمَيْلٍ', 'അബൂസുമൈൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الحديد:٣', null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=192 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 454, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَهُ نَاسٌ مِنْ أَصْحَابِهِ فَقَالُوا: يَا رَسُولَ اللَّهِ، نَجِدُ فِي أَنْفُسِنَا الشَّيْءَ نُعْظِمُ أَنْ نَتَكَلَّمَ بِهِ، أَوِ الْكَلَامَ بِهِ، مَا نُحِبُّ أَنَّ لَنَا وَأَنَّا تَكَلَّمْنَا بِهِ؟ قَالَ: "أَوَقَدْ وَجَدْتُمُوهُ". قَالُوا: نَعَمْ، قَالَ: "ذَاكَ صَرِيحُ الْإِيمَانِ". (م,د)', 'അബൂഹുറൈറ(റ): സ്വഹാബാക്കളിൽ നിന്ന് ചിലർ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ സംസാരിക്കാൻ ധൈര്യപ്പെടാത്ത ഗുരുതരമായ ചിലത് ഞങ്ങൾക്ക് തോന്നുന്നു. അവ ഞങ്ങളിലുണ്ടാകുന്നതോ അവയെ സംബന്ധിച്ച് സംസാരിക്കുന്നതോ ഞങ്ങളിഷ്ടപ്പെടുന്നില്ല? റസൂൽ(സ) ചോദിച്ചു: "അങ്ങനെ നിങ്ങൾക്കു തോന്നിയോ?" അവർ പറഞ്ഞു: അതെ, റസൂൽ(സ) പറഞ്ഞു: "അതാണ് ശരിയായ വിശ്വാസം" (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=192 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 455, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أَحَدَنَا يَجِدُ فِي نَفْسِهِ، يُعَرِّضُ بِالشَّيْءِ، لَأَنْ يَكُونَ حُمَمَةً أَحَبُّ إِلَيْهِ مِنْ أَنْ يَتَكَلَّمَ بِهِ. فَقَالَ: "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، الْحَمْدُ لِلَّهِ الَّذِي رَدَّ كَيْدَهُ إِلَى الْوَسْوَسَةِ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ അടുക്കൽ ഒരാൾ വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, തീർച്ചയായും ഞങ്ങളിൽ നിന്നൊരാൾക്ക് സംശയവുമും, മോശമായ പല ചിന്തകളും ഉണ്ടാകുന്നു, ഒരു കൽക്കരിയായിത്തീരലാണ് അയാൾക്കത് സംബന്ധമായി സംസാരിക്കുന്നതിനേക്കാൾ ഇഷ്ടം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ! അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ, അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ, പിശാചിന്റെ കുതന്ത്രത്തെ വസ്‌വാസ് മാത്രമാക്കി മാറ്റിയ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും" (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 518, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=192 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 456, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളുടെ ഉൾഭാഗം ചീഞ്ചലം കൊണ്ട് നിറയുന്നതാണ്, കവിതകൾ കൊണ്ട് നിറയുന്നതിനേക്കാൾ ഉത്തമം" (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 457, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنَ الشِّعْرِ حِكْمَةً". (خ,د,ت,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം കവിതയിൽ തന്ത്രമുണ്ട്." (ബു,ദ,തു,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 458, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يَتَكَلَّمُ بِكَلَامٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْبَيَانِ سِحْرًا، وَإِنَّ مِنَ الشِّعْرِ حُكْمًا". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു അഅ്റാബി നബി(സ)യുടെ അടുത്ത് വന്ന് ചില കാര്യങ്ങൾ സംസാരിക്കാൻ തുടങ്ങി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ബയാനിൽ (വിശദീകരണത്തിൽ) മാരണശക്തിയുണ്ട്. നിശ്ചയം കവിതയിൽ തന്ത്രങ്ങളുമുണ്ട്." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 459, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ مِنَ الْبَيَانِ سِحْرًا، وَإِنَّ مِنَ الْعِلْمِ جَهْلًا، وَإِنَّ مِنَ الشِّعْرِ حُكْمًا، وَإِنَّ مِنَ الْقَوْلِ عِيَالًا". (د,ت)', 'ബുറൈദ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയമായും വിശദീകരണത്തിൽ മാരണമുണ്ട്, നിശ്ചയമായും വിജ്ഞാനത്തിൽ അജ്ഞതയുണ്ട്, നിശ്ചയമായും കവിതയിൽ തന്ത്രമുണ്ട്, നിശ്ചയമായും വാക്കിൽ ഭാരമുണ്ട്." (അനർഹരോട് പറയുമ്പോൾ) (ദ,തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 460, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَصْدَقُ كَلِمَةٍ قَالَهَا الشَّاعِرُ كَلِمَةُ لَبِيدٍ: أَلَا كُلُّ شَيْءٍ مَا خَلَا اللَّهَ بَاطِلُ. وَكَادَ أُمَيَّةُ بْنُ أَبِي الصَّلْتِ أَنْ يُسْلِمَ". (ق,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു കവി പറഞ്ഞതിലേറ്റവും സത്യസന്ധമായത് ''അറിയുക, അല്ലാഹു അല്ലാത്തതെല്ലാം ബാതിലാണ്'' എന്ന ലബീദിന്റെ വാക്കാണ്. ഉമയ്യതുബ്നു അബിസ്സൽത്ത് മുസ്‌ലിമാകാനടുത്തിരിക്കുന്നു." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 461, 'عَنِ الشَّرِيدِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنْشَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِائَةَ قَافِيَةٍ مِنْ شِعْرِ أُمَيَّةَ بْنِ أَبِي الصَّلْتِ، يَقُولُ بَيْنَ كُلِّ قَافِيَةٍ: "هِيهْ". وَقَالَ: "كَادَ أَنْ يُسْلِمَ". (م,جه)', 'ശരീദ്(റ): തിരുദൂതർ(സ)ക്ക് ഉമയ്യതുബ്നു അബിസ്സൽതിന്റെ കവിതയിൽ നിന്ന് നൂറ് ഖാഫിയകൾ ഞാൻ ചൊല്ലിക്കേൾപ്പിച്ചു. ഓരോ ഖാഫിയക്കിടയിലും റസൂൽ(സ) "ഹീ" എന്ന് പറയും. എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹം മുസ്‌ലിമാകാനടുത്തിരിക്കുന്നു." (മു,ജ)', 'الشَّرِيدِ', 'ശരീദ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 462, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَعْظَمَ النَّاسِ فِرْيَةً لَرَجُلٌ هَاجَى رَجُلًا، فَهَجَا الْقَبِيلَةَ بِأَسْرِهَا. وَرَجُلٌ انْتَفَى مِنْ أَبِيهِ وَزَنَّى أُمَّهُ". (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിലേറ്റവും വലിയ അപവാദം പരത്തുന്നവൻ, ഒരാളെ പരിഹസിക്കലിലൂടെ ഗോത്രത്തെ മുഴുവൻ പരിഹസിച്ചവനും, തന്റെ പിതാവിന്റെ മകനാണെന്നതിനെ നിഷേധിക്കുകയും ഉമ്മക്കെതിരെ വ്യഭിചാരാരോപണം നടത്തുകയും ചെയ്തവനാണ്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 519, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 463, 'عَنْ سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ عُمَرُ بِحَسَّانَ وَهُوَ يُنْشِدُ فِي الْمَسْجِدِ، فَلَحَظَ إِلَيْهِ، فَقَالَ: قَدْ كُنْتُ أُنْشِدُ وَفِيهِ مَنْ هُوَ خَيْرٌ مِنْكَ. (د,ن)', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ): ഹസ്സാൻ(റ) പള്ളിയിൽ പാടിക്കൊണ്ടിരിക്കെ അതിലൂടെ ഉമർ(റ) കടന്നുപോയി, അപ്പോൾ ഉമർ(റ) ഹസ്സാൻ(റ)വിനെ ഇടംകണ്ണിട്ട് നോക്കി. ഹസ്സാൻ(റ) പറഞ്ഞു: നിങ്ങളേക്കാൾ ഉത്തമനുണ്ടായിരുന്ന വേദിയിൽ ഞാൻ പാടിയിരുന്നു. (ദ,ന)', 'سَعِيدٍ', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 464, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، بِمَعْنَاهُ، زَادَ: فَخَشِيَ أَنْ يَرْمِيَهُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَجَازَهُ. (ق,د,ن)', 'അബൂഹുറൈറ(റ): മേൽപറഞ്ഞ ഹദീസ് തന്നെ റിപ്പോർട്ട് ചെയ്തിട്ടുണ്ട്. അതിൽ ഇതുകൂടി പറഞ്ഞു. അപ്പോൾ പക്ഷെ, ഉമർ(റ) റസൂൽ(സ)യെ കൊണ്ട് (അനുവാദം നൽകിയെന്ന് പറഞ്ഞ്) ഹസ്സാൻ(റ) തന്നെ പ്രതിരോധിക്കുമെന്ന് ഭയന്നു. അപ്പോൾ അതിന് അനുവാദം നൽകി. (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 465, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: {وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ} [الشعراء: ٢٢٤] فَنُسِخَ مِنْ ذَلِكَ وَاسْتُثْنِيَ فَقَالَ: {إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَذَكَرُوا اللَّهَ كَثِيرًا} [الشعراء: ٢٢٦]. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''കവികളെ വഴിപിഴച്ചവർ പിന്തുടരും'' (ശുഅറാഅ്: 224), അതിൽ നിന്ന് ''അല്ലാഹുവിനെ ധാരാളമായി സ്മരിക്കുകയും സൽകർമ്മങ്ങൾ ചെയ്യുകയും വിശ്വസിക്കുകയും ചെയ്തവരൊഴികെ'' എന്ന് നസ്ഖ് ചെയ്യപ്പെടുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الشعراء: ٢٢٦', null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 466, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضَعُ لِحَسَّانَ رَضِيَ اللَّهُ عَنْهُ مِنْبَرًا فِي الْمَسْجِدِ يَقُومُ عَلَيْهِ قَائِمًا، يُفَاخِرُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَالَ: يُنَافِحُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَيَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يُؤَيِّدُ حَسَّانَ بِرُوحِ الْقُدُسِ، مَا يُفَاخِرُ -أَوْ يُنَافِحُ- عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ". حَسَنٌ صَحِيحٌ. (د,ت)', 'ആഇശ(റ): റസൂൽ(സ) ഹസ്സാൻ(റ)വിന് വേണ്ടി പള്ളിയിൽ ഒരു പീഠം വെക്കുമായിരുന്നു, ഹസ്സാൻ(റ) അതിൻമേൽ എഴുന്നേറ്റ് നിന്ന് റസൂൽ(സ)യെക്കുറിച്ച് അഭിമാനം കൊള്ളും. അല്ലെങ്കിൽ റസൂൽ(സ)യെക്കുറിച്ച് തർക്കിച്ചുകൊണ്ടിരിക്കും. എന്നിട്ട് റസൂൽ(സ) പറയും: "ഹസ്സാൻ(റ), റസൂൽ(സ)യെ പ്രശംസിച്ചുകൊണ്ടിരിക്കുന്ന അല്ലെങ്കിൽ റസൂൽ(സ)യെക്കുറിച്ച് തർക്കിച്ച് കൊണ്ടിരിക്കുന്ന കാലത്തോളം അദ്ദേഹത്തെ അല്ലാഹു പരിശുദ്ധാത്മാവ് കൊണ്ട് ശക്തിപ്പെടുത്തും." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 467, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ فِي عُمْرَةِ الْقَضَاءِ، وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ – رَضِيَ اللَّهُ عَنْهُ– بَيْنَ يَدَيْهِ يَمْشِي وَهُوَ يَقُولُ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 468, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَ: قِيلَ لَهَا: هَلْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَمَثَّلُ بِشَيْءٍ مِنَ الشِّعْرِ؟ قَالَتْ: كَانَ يَتَمَثَّلُ بِشِعْرِ ابْنِ رَوَاحَةَ – رَضِيَ اللَّهُ عَنْهُ– وَيَتَمَثَّلُ وَيَقُولُ: "وَيَأْتِيكَ بِالْأَخْبَارِ مَنْ لَمْ تُزَوِّدِ". حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): മഹതിയോട് ചോദിക്കപ്പെട്ടു: റസൂൽ(സ) ആരുടെയെങ്കിലും കവിത അനുകരിക്കാറുണ്ടോ? റസൂൽ(സ) മഹതി പറഞ്ഞു: തിരുദൂതർ(സ) ഇബ്നു റവാഹയുടെ കവിത അനുകരിക്കാറുണ്ട്. തിരുദൂതർ(സ) അനുകരിക്കും, എന്നിട്ട് പറയും: "നീ ഭക്ഷണ സാധനങ്ങൾ കൊടുക്കാത്തവൻ, നിനക്ക് വിവരങ്ങൾ കൊണ്ടുവന്ന് തരും." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 469, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ يَبْغُضُ الْبَلِيغَ مِنَ الرِّجَالِ، الَّذِي يَتَخَلَّلُ بِلِسَانِهِ كَمَا تَتَخَلَّلُ الْبَقَرَةُ". حَسَنٌ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "പശുക്കൾ അയവിറക്കിക്കൊണ്ടിരിക്കുന്നത് പോലെ തുടർച്ചയായി നാക്കിട്ട് സംസാരിക്കുന്ന വായാടികളായ ആളുകളോട് നിശ്ചയമായും അല്ലാഹു ദേശ്യപ്പെടും." (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 470, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَالَسْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ مِنْ مِائَةِ مَرَّةٍ، فَكَانَ أَصْحَابُهُ يَتَنَاشَدُونَ الشِّعْرَ، وَيَتَذَاكَرُونَ أَشْيَاءَ مِنْ أَمْرِ الْجَاهِلِيَّةِ، وَهُوَ سَاكِتٌ، فَرُبَّمَا تَبَسَّمَ مَعَهُمْ. حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിറുബ്നു സമുറ(റ): ഞാൻ തിരുദൂതർ(സ)യോടു കൂടെ നൂറിലേറെ പ്രാവശ്യം ഇരുന്നിട്ടുണ്ട്, തന്റെ സഹാബാക്കൾ കവിതകൾ ആലപിക്കുകയും ജാഹിലിയ്യത്തിലെ ഓരോ കാര്യങ്ങൾ അയവിറക്കുകയും ചെയ്യും, റസൂൽ(സ) നിശബ്ദനായിരിക്കും, ചിലപ്പോൾ അവരോട് കൂടെ പുഞ്ചിരിക്കും. (തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=193 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 471, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ رَضِيَ اللَّهُ عَنْهُ قَالَتْ: جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ عَلَيَّ صَبِيحَةَ بُنِيَ بِي، فَجَلَسَ عَلَى فِرَاشِي كَمَجْلِسِكَ مِنِّي، فَجَعَلَتْ جُوَيْرِيَاتٌ يَضْرِبْنَ بِدُفٍّ لَهُنَّ، وَيَنْدُبْنَ مَنْ قُتِلَ مِنْ آبَائِي يَوْمَ بَدْرٍ، إِلَى أَنْ قَالَتْ إِحْدَاهُنَّ: وَفِينَا نَبِيٌّ يَعْلَمُ مَا فِي الْغَدِ، فَقَالَ: "دَعِي هَذِهِ، وَقُولِي الَّذِي كُنْتِ تَقُولِينَ". (خ,د,ت,جه)', 'റുബയ്യിഅ് ബിൻത് മുഅവ്വിദ്(റ): ഞാൻ വീട് കൂട്ടപ്പെട്ട ദിവസം രാവിലെ റസൂൽ(സ) എന്റെ അടുത്തേക്ക് വന്നു. അങ്ങനെ നീ എന്റെ അടുത്തിരിക്കുന്ന പോലെ റസൂൽ(സ) എന്റെ വിരിപ്പിലിരുന്നു. അപ്പോൾ ചില യുവതികൾ ദഫ്ഫ് കൊട്ടാൻ തുടങ്ങി, ബദ്‌റിൽ കൊല്ലപ്പെട്ട എന്റെ പിതാമഹൻമാരെ സ്തുതിച്ച് പാടാൻ തുടങ്ങി. അവരിലൊരാൾ പറഞ്ഞു: നാളെയുണ്ടാകുന്ന കാര്യങ്ങൾ അറിയുന്ന ഒരു നബി ഞങ്ങളിലുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇതൊഴിവാക്കുക, മുമ്പ് പറഞ്ഞിരുന്നത് തന്നെ പറയുക." (ബു,ദ,തു,ജ)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ', 'റുബയ്യിഅ് ബിൻത് മുഅവ്വിദ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 521, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=194 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 472, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ لَعِبَتِ الْحَبَشَةُ لِقُدُومِهِ فَرَحًا بِذَلِكَ، لَعِبُوا بِحِرَابِهِمْ. (د)', 'അനസ്(റ): തിരുദൂതർ(സ) മദീനയിൽ വന്നപ്പോൾ അബ്സീനിയക്കാർ സന്തോഷം കാരണം, അവരുടെ കുന്തങ്ങൾ കൊണ്ട് കളിച്ചു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=194 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 473, 'عَنْ نَافِعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعَ ابْنُ عُمَرَ مِزْمَارًا، قَالَ: فَوَضَعَ إِصْبَعَيْهِ عَلَى أُذُنَيْهِ وَنَأَى عَنِ الطَّرِيقِ، وَقَالَ لِي: يَا نَافِعُ هَلْ تَسْمَعُ شَيْئًا؟ قَالَ: فَقُلْتُ: لَا، قَالَ: فَرَفَعَ إِصْبَعَيْهِ مِنْ أُذُنَيْهِ، وَقَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمِعَ مِثْلَ هَذَا. فَصَنَعَ مِثْلَ هَذَا. وفي رواية: قَالَ: كُنْتُ رِدْفَ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، إِذْ مَرَّ بِرَاعٍ يَزْمُرُ. فَذَكَرَ نَحْوَهُ. وفي رواية: قَالَ: كُنَّا مَعَ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا فَسَمِعَ صَوْتَ زَامِرٍ. فَذَكَرَ نَحْوَهُ. (د)', 'നാഫിഅ്(റ): ഇബ്നുഉമർ(റ) വീണ വായിക്കുന്നത് കേട്ടപ്പോൾ തന്റെ രണ്ട് ചെവിയിലും വിരലുകൾ വെക്കുകയും ആ വഴിയിൽ നിന്ന് ദൂരെപ്പോകുകയും ചെയ്തു. എന്നിട്ടെന്നോട് പറഞ്ഞു: നാഫിഅ്! നീ വല്ലതും കേൾക്കുന്നുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല, അങ്ങനെ ഇബ്നുഉമർ(റ) തന്റെ ചെവിയിൽ നിന്നും വിരലെടുത്ത് പറഞ്ഞു: ഞാൻ തിരുദൂതർ(സ)യുടെ കൂടെയുള്ളപ്പോൾ ഇതുപോലെ കേട്ടു. അപ്പോൾ അവിടന്ന് ഇങ്ങനെ ചെയ്തു. മറ്റൊരു നിവേദനം: നാഫിഅ്(റ) പറഞ്ഞു: ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ പിന്നിലിരിക്കുകയായിരുന്നു, അങ്ങനെ സംഗീതം വായിക്കുന്നൊരു ഇടയന്റെ അടുത്ത് കൂടെ നടന്നപ്പോൾ ഇത് പോലെ പറഞ്ഞു. മറ്റൊരു നിവേദനം: ഞങ്ങൾ ഇബ്നുഉമർ(റ)വിനോട് കൂടെയായിരുന്നപ്പോൾ സംഗീതജ്ഞന്റെ ശബ്ദം കേട്ടു. അപ്പോൾ ഇബ്നുഉമർ(റ) ഇത് പോലെ പറഞ്ഞു. (ദ)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=194 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=473), 1, 'وَفِي رِوَايَةٍ: قَالَ: كُنْتُ رِدْفَ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، إِذْ مَرَّ بِرَاعٍ يَزْمُرُ. فَذَكَرَ نَحْوَهُ.', 'മറ്റൊരു നിവേദനം: നാഫിഅ്(റ) പറഞ്ഞു: ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ പിന്നിലിരിക്കുകയായിരുന്നു, അങ്ങനെ സംഗീതം വായിക്കുന്നൊരു ഇടയന്റെ അടുത്ത് കൂടെ നടന്നപ്പോൾ ഇത് പോലെ പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=5 and h.hadith_no=473), 2, 'وَفِي رِوَايَةٍ: قَالَ: كُنَّا مَعَ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا فَسَمِعَ صَوْتَ زَامِرٍ. فَذَكَرَ نَحْوَهُ. (د)', 'മറ്റൊരു നിവേദനം: ഞങ്ങൾ ഇബ്നുഉമർ(റ)വിനോട് കൂടെയായിരുന്നപ്പോൾ സംഗീതജ്ഞന്റെ ശബ്ദം കേട്ടു. അപ്പോൾ ഇബ്നുഉമർ(റ) ഇത് പോലെ പറഞ്ഞു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 474, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْغِنَاءُ يُنْبِتُ النِّفَاقَ فِي الْقَلْبِ". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സംഗീതം ഹൃദയത്തിൽ കാപട്യം വളർത്തും." (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=194 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 475, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلَيْنِ قَدِمَا فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَطَبَا، فَعَجِبَ النَّاسُ مِنْ كَلَامِهِمَا، فَالْتَفَتَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ مِنَ الْبَيَانِ سِحْرًا. أَوْ: إِنَّ بَعْضَ الْبَيَانِ سِحْرٌ". حَسَنٌ صَحِيحٌ. (خ,د,ت)', 'ഇബ്നുഉമർ(റ): തിരുദൂതർ(സ)യുടെ കാലത്ത് രണ്ടാളുകൾ വന്നു പ്രസംഗിച്ചു, അവരുടെ സംസാരം ജനങ്ങളെ ആശ്ചര്യപ്പെടുത്തി. അപ്പോൾ തിരദൂതർ(സ) ഞങ്ങളിലേക്ക് തിരിഞ്ഞ് പറഞ്ഞു: "നിശ്ചയമായും പ്രഭാഷണത്തിൽ മാരണമുണ്ട്." അല്ലെങ്കിൽ "ചില പ്രഭാഷണങ്ങൾ മാരണമാണ്." (ബു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=195 where b.volume_id=2 and b.book_no=5 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
